#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Define GPIO pins for SPI communication
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11
#define CE0_PIN 8

// Global variable for SPI handle
int spi_handle = -1;

// Function prototypes
int read_mcp3008(int channel);
void log_data(int adc_value);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud;
    int flags;
} spi_config_t;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to log data to the console
void log_data(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - ADC Value: %d\n", timestamp, adc_value);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down gracefully...\n", signal);

    // Close SPI connection if open
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as output (not strictly necessary for SPI, but good practice)
    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);
    gpioSetMode(CE0_PIN, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(0); // Read from channel 0
        if (adc_value >= 0) {
            log_data(adc_value);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        sleep(1); // Sample once per second
    }

    return 0;
}

