#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_SINGLE_ENDED_AIN0 0x4003 // Single-ended AIN0, 4.096V gain, 128 SPS
#define CONFIG_SINGLE_SHOT 0x8000    // Single-shot mode

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to write a 16-bit value to the ADS1115 configuration register
int write_ads1115_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115 conversion register
int16_t read_ads1115_conversion(int handle) {
    char buf[1];
    buf[0] = ADS1115_REG_CONVERT;

    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %d\n", result);
        return -1;
    }

    return (int16_t)((read_buf[0] << 8) | read_buf[1]); // Combine MSB and LSB
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read conversion result
        int16_t conversion_result = read_ads1115_conversion(i2c_handle);

        if (conversion_result >= 0) {
            // Convert to current (assuming 4.096V gain and 16-bit resolution)
            float current = (float)conversion_result * 4.096 / 32768.0; // 16-bit resolution

            // Log the current value
            printf("Current: %.2f A\n", current);
        } else {
            fprintf(stderr, "Error reading conversion result\n");
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

