#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CE_PIN 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define temperature conversion parameters
#define VREF 3.3 // Reference voltage
#define TEMP_RESISTOR 10000.0 // Resistor value in ohms
#define TEMP_VOLTAGE 0.1 // Voltage drop across the temperature sensor

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_flame_sensor();
int read_mcp3008(int channel);
float convert_to_temperature(int adc_value);
void log_data(time_t timestamp, int flame_detected, float temperature);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int flame_pin;
    int ce_pin;
    int spi_channel;
    int spi_speed;
    float vref;
    float temp_resistor;
    float temp_voltage;
} Config;

Config config = {
    FLAME_SENSOR_PIN,
    MCP3008_CE_PIN,
    SPI_CHANNEL,
    SPI_SPEED,
    VREF,
    TEMP_RESISTOR,
    TEMP_VOLTAGE
};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Get current timestamp
        time_t now = time(NULL);

        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read MCP3008 ADC
        int adc_value = read_mcp3008(0);

        // Convert ADC value to temperature
        float temperature = convert_to_temperature(adc_value);

        // Log data
        log_data(now, flame_detected, temperature);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();
    if (fp != NULL) {
        fclose(fp);
    }

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize the pigpio library and SPI interface
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(config.flame_pin, PI_INPUT);
    gpioSetMode(config.ce_pin, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("flame_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open flame_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Flame_Detected,Temperature_C\n");
    }

    return 0;
}

// Read the flame sensor
int read_flame_sensor() {
    return gpioRead(config.flame_pin);
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    // Construct SPI message
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to temperature (Celsius)
float convert_to_temperature(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * config.vref;
    float temperature = (voltage - config.temp_voltage) / config.temp_resistor;
    return temperature;
}

// Log data to CSV file
void log_data(time_t timestamp, int flame_detected, float temperature) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp_str, flame_detected, temperature);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

