#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <wiringPiI2C.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define MCP3008_CHANNEL 0
#define FAN_GPIO 18
#define CURRENT_THRESHOLD 10.0 // Amperes
#define VREF 3.3 // Reference voltage for MCP3008
#define SENSOR_SENSITIVITY 0.1 // V/A (Example value, check datasheet)
#define SENSOR_ZERO_OFFSET 1.65 // V (Example value, check datasheet)
#define LOG_FILE "current_log.txt"
#define I2C_ADDR 0x48 // Example I2C address for temperature sensor

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure for sensor data
typedef struct {
    float current;
    float temperature;
} SensorData;

// Function prototypes
int spi_init(void);
int spi_read_adc(int channel);
float adc_to_current(int adc_value);
float i2c_read_temperature(void);
void log_data(float current, float temperature);
void control_fan(float current);
void signal_handler(int signal);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI max speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI read ADC function
int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to current conversion function
float adc_to_current(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float current = (voltage - SENSOR_ZERO_OFFSET) / SENSOR_SENSITIVITY;
    return current;
}

// I2C read temperature function (Placeholder - implement actual I2C read)
float i2c_read_temperature(void) {
    // This is a placeholder.  Replace with actual I2C read code.
    // For example, using wiringPiI2CReadReg16.
    // Assuming the temperature sensor returns a 16-bit value.
    // The returned value is just a dummy value.
    // Refer to the temperature sensor's datasheet for the correct I2C read command.
    // Example:
    // int data = wiringPiI2CReadReg16(i2c_fd, 0x00); // Read from register 0x00
    // float temperature = (float)data * 0.01; // Convert to Celsius
    // return temperature;

    // For now, return a dummy value.
    return 25.0; // Dummy temperature
}

// Data logging function
void log_data(float current, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, current, temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fan control function
void control_fan(float current) {
    if (current > CURRENT_THRESHOLD) {
        digitalWrite(FAN_GPIO, HIGH); // Turn fan ON
    } else {
        digitalWrite(FAN_GPIO, LOW);  // Turn fan OFF
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Turn off the fan
    digitalWrite(FAN_GPIO, LOW);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Reset GPIO pins (optional, but good practice)
    // wiringPiSetupGpio(); // Reinitialize wiringPi to reset pins
    // pinMode(FAN_GPIO, INPUT); // Set to input to avoid leaving it HIGH

    printf("Cleanup complete. Exiting.\n");
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (spi_init() == -1) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Configure FAN_GPIO as output
    pinMode(FAN_GPIO, OUTPUT);
    digitalWrite(FAN_GPIO, LOW); // Ensure fan is initially OFF

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read ADC value
        int adc_value = spi_read_adc(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value.\n");
            log_data(-1.0, -1.0); // Log error
        } else {
            // Convert ADC value to current
            float current = adc_to_current(adc_value);

            // Read temperature
            float temperature = i2c_read_temperature();

            // Log data
            log_data(current, temperature);

            // Control fan
            control_fan(current);

            printf("Current: %.2f A, Temperature: %.2f °C\n", current, temperature);
        }

        // Wait for 1 second
        sleep(1);
    }

    cleanup();
    return 0;
}

