    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure ADS1115 for single-ended input, 4.096V range, 128 SPS
    char config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x83; // Single-ended A0, 4.096V, 128 SPS
    config[2] = 0x83; // Single-ended A1, 4.096V, 128 SPS

    int result = i2cWriteDevice(i2c_handle, config, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to configure ADS1115: %d\n", result);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

