    // Main loop
    while (!terminate) {
        int raw_value = read_adc(i2c_handle);
        if (raw_value >= 0) {
            float ppm_value = convert_to_ppm(raw_value);
            log_ppm(ppm_value);
            printf("CO concentration: %.2f ppm\n", ppm_value);
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", SLEEP_SECONDS);
        }

        sleep(SLEEP_SECONDS);
    }

