#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8
#define MCP3008_SCLK_PIN 11
#define MCP3008_MOSI_PIN 10
#define MCP3008_MISO_PIN 9

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define temperature range
#define MIN_TEMP 20.0
#define MAX_TEMP 40.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_flame_sensor();
int read_mcp3008(int channel);
float convert_adc_to_temperature(int adc_value);
int log_data(int flame_present, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library and configures GPIO pins
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);
    gpioSetMode(MCP3008_SCLK_PIN, PI_OUTPUT);
    gpioSetMode(MCP3008_MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MCP3008_MISO_PIN, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Reads the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Reads the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    gpioWrite(MCP3008_CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, spi_data, spi_data, 3);
    gpioWrite(MCP3008_CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Converts the ADC value to temperature (Celsius)
float convert_adc_to_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range\n");
        return -999.0;
    }

    // Linear interpolation
    float temperature = MIN_TEMP + (float)(adc_value - 0) * (MAX_TEMP - MIN_TEMP) / 1023.0;
    return temperature;
}

// Logs the data to a CSV file
int log_data(int flame_present, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_present, temperature);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flame_Presence,Temperature_C\n");
    }

    printf("Flame sensor and temperature logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read MCP3008, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float temperature = convert_adc_to_temperature(adc_value);

        if (temperature < -999.0) {
            fprintf(stderr, "Invalid temperature reading, skipping log.\n");
        } else {
            log_data(flame_detected, temperature);
        }

        gpioDelay(1000); // Log data every 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

