#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MICS_4514_ADDR 0x49
#define CO_ALERT_THRESHOLD 25.0
#define CO_LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *ox, uint16_t *red);
float convert_to_ppm(uint16_t ox);
int log_data(float co_ppm);
int check_alert(float co_ppm);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    uint16_t ox;
    uint16_t red;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MICS_4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *ox, uint16_t *red) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *ox = (buf[0] << 8) | buf[1];
    *red = (buf[2] << 8) | buf[3];

    return 0;
}

// Function to convert OX value to CO concentration in ppm
float convert_to_ppm(uint16_t ox) {
    // Assuming a linear relationship for simplicity.
    // You'll need to calibrate this based on the sensor's datasheet.
    // This is a placeholder.
    return (float)ox * 0.1; // Example conversion
}

// Function to log CO data to a file
int log_data(float co_ppm) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CO_LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f ppm\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);

    fclose(fp);
    return 0;
}

// Function to check for alert condition
int check_alert(float co_ppm) {
    if (co_ppm >= CO_ALERT_THRESHOLD) {
        FILE *fp = fopen(ALERT_LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening alert log file: %s\n", ALERT_LOG_FILE);
            return -1;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Alert: CO concentration exceeds threshold (%.2f ppm)\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, CO_ALERT_THRESHOLD);

        fclose(fp);
