        int mic2_level = read_mic_level(MIC2_GPIO);

        // Check for errors during reading
        if (mic1_level == -1 || mic2_level == -1) {
            fprintf(stderr, "Error reading microphone levels. Logging -999.0 dB.\n");
            float level1 = -999.0; // Error value
            float level2 = -999.0; // Error value
            float average_level = calculate_average_level(level1, level2);
            log_data(average_level);
        } else {
            // Calculate average level
            float average_level = calculate_average_level(mic1_level, mic2_level);

            // Log the data
            log_data(average_level);
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

