#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define MIC1_CE 8
#define MIC2_CE 9
#define LED_PIN 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define RMS threshold
#define RMS_THRESHOLD 500.0

// Define sampling window
#define SAMPLING_WINDOW_MS 100
#define SAMPLE_RATE_MS 1

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
float calculate_rms(int *samples, int num_samples);
void log_data(float mic1_rms, float mic2_rms);
void control_led(float mic1_rms, float mic2_rms);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    int ce_pin;
    int miso_pin;
    int mosi_pin;
    int sclk_pin;
} spi_config_t;

spi_config_t spi_config = {MIC1_CE, 9, 10, 11};

int main() {
    int mic1_samples[SAMPLING_WINDOW_MS];
    int mic2_samples[SAMPLING_WINDOW_MS];
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    // Sampling loop
    for (i = 0; i < SAMPLING_WINDOW_MS * SAMPLE_RATE_MS; i++) {
        // Read samples from microphones
        int mic1_sample = read_mcp3008(0);
        int mic2_sample = read_mcp3008(1);

        // Store samples in arrays
        mic1_samples[i] = mic1_sample;
        mic2_samples[i] = mic2_sample;

        // Calculate RMS levels
        float mic1_rms = calculate_rms(mic1_samples, SAMPLING_WINDOW_MS);
        float mic2_rms = calculate_rms(mic2_samples, SAMPLING_WINDOW_MS);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Control LED
        control_led(mic1_rms, mic2_rms);

        // Delay for 1 ms
        gpioDelay(SAMPLE_RATE_MS);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MIC1_CE, PI_OUTPUT);
    gpioSetMode(MIC2_CE, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    gpioWrite(MIC1_CE, 1); // Deselect both channels initially
    gpioWrite(MIC2_CE, 1); // Deselect both channels initially
    gpioWrite(LED_PIN, 0); // Turn off LED

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    uint8_t tx_buffer[3];
    uint8_t rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Calculate RMS level
float calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Log data to file
void log_data(float mic1_rms, float mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED based on RMS levels
void control_led(float mic1_rms, float mic2_rms) {
    if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn on LED
        gpioDelay(500);         // Wait 500 ms
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Cleaning up...\n");
    terminate = 1;
}

