#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define ALERT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define LED_GPIO 17
#define SAMPLE_RATE 10 // Hz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int config_ads1115();
int16_t read_ads1115();
float convert_to_current(int16_t raw_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Circular buffer functions
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

int is_buffer_full(CircularBuffer *cb) {
    return cb->count == BUFFER_SIZE;
}

int add_to_buffer(CircularBuffer *cb, float value) {
    if (is_buffer_full(cb)) {
        // Overwrite the oldest value
        cb->buffer[cb->head] = value;
        cb->head = (cb->head + 1) % BUFFER_SIZE;
        return 0; // Success, but buffer is full
    }

    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    cb->count++;
    return 0; // Success
}

float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0; // Avoid division by zero
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// I2C functions
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int config_ads1115() {
    char config[3];
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // Single-ended A0, 4.096V, 128 SPS, Disable comparator
    config[2] = 0x83; // 128 SPS, Disable comparator

    int result = i2cWriteI2CBlockData(i2c_handle, config[0], config + 1, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to write config register: %d\n", result);
        return -1;
    }

    return 0;
}

int16_t read_ads1115() {
    char reg = CONVERSION_REG;
    int result = i2cWriteI2CBlockData(i2c_handle, reg, NULL, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to write conversion register: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for conversion (at least 8ms for 128 SPS)

    char data[2];
    result = i2cReadI2CBlockData(i2c_handle, reg, data, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read conversion register: %d\n", result);
        return -1;
    }

    return (int16_t)((data[0] << 8) | data[1]);
}

// Current conversion function
float convert_to_current(int16_t raw_value) {
    // Assuming a linear relationship between raw value and current
    // Adjust the scaling factor as needed based on your sensor's datasheet
    float current = (float)raw_value * 0.1; // Example scaling
    return current;
}

// LED control function
void control_led(float average_current) {
    if (average_current > ALERT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Configure ADS1115
    if (config_ads1115() < 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer current_buffer;
    init_circular_buffer(&current_buffer);

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read raw value from ADS1115
        int16_t raw_value = read_ads1115();
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read sensor value. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to current
        float current = convert_to_current(raw_value);

        // Add to circular buffer
        add_to_buffer(&current_buffer, current);

        // Calculate average current
        float average_current = calculate_average(&current_buffer);

        // Control LED
        control_led(average_current);

        // Print current and average current (for debugging)
        printf("Raw: %d, Current: %.2f A, Average: %.2f A\n", raw_value, current, average_current);

        // Sleep for a short period
        gpioDelay(1000); // 1 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

