#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A
#define TCS34725_ID 0x12

// Enable register values
#define TCS34725_ENABLE_AIEN 0x10  // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN 0x08   // Wait enable - writing 1 activates the wait timer
#define TCS34725_ENABLE_AEN 0x02   // ALS Enable
#define TCS34725_ENABLE_PON 0x01   // Power on

// Integration time values
#define TCS34725_INTEGRATIONTIME_2_4MS 0xFF // 2.4ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init(int i2c_handle);
int tcs34725_read_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(FILE *fp, const char *timestamp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int i2c_handle) {
    int status;

    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
    }
    if (sensor_id != 0x44) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Enable power and ALS
    status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON);
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register (PON): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(3); // Wait for power-on

    status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN);
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register (PON | AEN): %s\n", strerror(errno));
        return -1;
    }

    // Set integration time
    status = i2cWriteByteData(i2c_handle, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_2_4MS);
    if (status < 0) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return -1;
    }

    // Set gain (optional, default is 1x)
    // status = i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x00); // 1x gain
    // if (status < 0) {
    //     fprintf(stderr, "Error writing to CONTROL register: %s\n", strerror(errno));
    //     return -1;
    // }

    return 0;
}

// Function to read color data from the sensor
int tcs34725_read_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int status;

    status = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading clear data: %s\n", strerror(errno));
        return -1;
    }
    *clear = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading red data: %s\n", strerror(errno));
        return -1;
    }
    *red = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading green data: %s\n", strerror(errno));
        return -1;
    }
    *green = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_BDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading blue data: %s\n", strerror(errno));
        return -1;
    }
    *blue = (uint16_t)status;

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, const char *timestamp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    if (fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    int status;
    uint16_t clear, red, green, blue;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int consecutive_failures = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Read color data
        status = tcs34725_read_data(i2c_handle, &clear, &red, &green, &blue);
        if (status != 0) {
            fprintf(stderr, "Error reading color data, retrying in 1 second...\n");
            consecutive_failures = 0; // Reset failure count
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Log data to file
        if (log_data(log_file, timestamp, clear, red, green, blue) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for 1 second without blocking
        gpioDelay(1000); // Delay for 1 second (1000 ms)
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

