        }
        if (moisture1 < 0) {
            fprintf(stderr, "Failed to read sensor 1 after %d retries. Skipping.\n", MAX_RETRIES);
            moisture1 = -1; // Indicate error
        }

        // Retry mechanism for sensor 2
        retries = 0;
