#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define PRESSURE_REG 0x00 // Example register address for pressure
#define TEMPERATURE_REG 0x01 // Example register address for temperature
#define WARNING_LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0 // kPa
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_kPa;
    float temperature_C;
} SensorData;

// Function prototypes
int init_i2c();
int read_ads1115(int reg_addr, int16_t *data);
SensorData read_sensor_data();
void process_sensor_data(int16_t raw_pressure, int16_t raw_temperature, SensorData *data);
void control_warning_led(float pressure_kPa);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115 ADC
int read_ads1115(int reg_addr, int16_t *data) {
    char buf[2];
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        buf[0] = reg_addr;
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error writing register address: %d\n", i2c_handle);
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
            *data = (int16_t)((buf[0] << 8) | buf[1]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading data: %d\n", i2c_handle);
            retries++;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Read raw sensor data and convert to kPa and °C
SensorData read_sensor_data() {
    SensorData data;
    int16_t raw_pressure, raw_temperature;

    if (read_ads1115(PRESSURE_REG, &raw_pressure) != 0) {
        data.pressure_kPa = -1.0; // Indicate error
        data.temperature_C = -1.0;
        fprintf(stderr, "Error reading pressure data.\n");
        return data;
    }

    if (read_ads1115(TEMPERATURE_REG, &raw_temperature) != 0) {
        data.pressure_kPa = -1.0; // Indicate error
        data.temperature_C = -1.0;
        fprintf(stderr, "Error reading temperature data.\n");
        return data;
    }

    process_sensor_data(raw_pressure, raw_temperature, &data);
    return data;
}

// Convert raw sensor data to kPa and °C
void process_sensor_data(int16_t raw_pressure, int16_t raw_temperature, SensorData *data) {
    // Example conversion formulas (replace with actual datasheet values)
    data->pressure_kPa = (float)raw_pressure * 0.1; // kPa
    data->temperature_C = (float)raw_temperature * 0.01 - 40.0; // °C
}

// Control the warning LED based on pressure
void control_warning_led(float pressure_kPa) {
    if (pressure_kPa > PRESSURE_THRESHOLD) {
        gpioWrite(WARNING_LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(WARNING_LED_GPIO, 0); // Turn LED off
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(WARNING_LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for the warning LED
    gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT);
    gpioWrite(WARNING_LED_GPIO, 0); // Initially off

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        SensorData sensor_data = read_sensor_data();

        if (sensor_data.pressure_kPa != -1.0 && sensor_data.temperature_C != -1.0) {
            printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", sensor_data.pressure_kPa, sensor_data.temperature_C);
            control_warning_led(sensor_data.pressure_kPa);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping.\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

