#define MCP3208_CS 8      // GPIO8 (BCM)
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with your email

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int initialize();
int read_mcp3208(int channel);
SensorData convert_adc_to_humidity_temperature(int adc_value);
int log_data(SensorData data);
int send_email_alert(float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MCP3208_CS, PI_OUTPUT);
    gpioWrite(MCP3208_CS, 1); // Ensure CS is initially high

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read data from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 3) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    gpioWrite(MCP3208_CS, 0); // Select the MCP3208
    int result = spiXfer(spi_handle, spi_data, spi_data, 3);
    gpioWrite(MCP3208_CS, 1); // Deselect the MCP3208

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Convert ADC value to humidity and temperature
SensorData convert_adc_to_humidity_temperature(int adc_value) {
    SensorData data;
    // These are placeholder formulas.  Refer to the HIH-4602-A datasheet for accurate formulas.
    // The datasheet provides a transfer function for humidity and temperature.
    // This example uses a simple linear approximation for demonstration purposes.

    // Example formulas (replace with actual formulas from datasheet):
    float humidity = (float)adc_value * 0.1; // Example: 0-1023 -> 0-10%
    float temperature = (float)adc_value * 0.01 - 40.0; // Example: 0-1023 -> -40 to 125C

    data.humidity = humidity;
    data.temperature = temperature;

    return data;
}

// Log data to file
int log_data(SensorData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.humidity, data.temperature);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Send email alert
int send_email_alert(float humidity) {
    char command[256];
    char body[256];
    char filename[64];
    FILE *mail_file;

    snprintf(filename, sizeof(filename), LOG_FILE);
    mail_file = popen("ssmtp -t -f recipient@example.com -i < %s", "r");
    if (mail_file == NULL) {
        fprintf(stderr, "Failed to execute ssmtp\n");
        return 1;
    }

    fprintf(mail_file, "To: recipient@example.com\n");
    fprintf(mail_file, "From: sender@example.com\n");
    fprintf(mail_file, "Subject: Humidity Alert\n\n");
    fprintf(mail_file, "High humidity detected! Humidity: %.2f%%\n", humidity);

    int status = pclose(mail_file);
    if (status != 0) {
        fprintf(stderr, "ssmtp exited with status %d\n", status);
        return 1;
    }

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3208(0); // Read from channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        SensorData data = convert_adc_to_humidity_temperature(adc_value);
        log_data(data);

        if (data.humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(data.humidity);
        }

        sleep(5); // Read every 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

