#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CE_PIN 8 // GPIO8 (BCM)
#define MCP3208_SCLK_PIN 11 // GPIO11 (BCM)
#define MCP3208_MOSI_PIN 10 // GPIO10 (BCM)
#define MCP3208_MISO_PIN 9 // GPIO9 (BCM)
#define VREF 3.3
#define TMP36_MIN_VOLTAGE 0.75
#define TMP36_MAX_VOLTAGE 1.75
#define TMP36_MIN_TEMPERATURE -40.0
#define TMP36_MAX_TEMPERATURE 125.0

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int spi_transfer(int fd, uint8_t channel, uint8_t *data);
float adc_to_temperature(int adc_value);
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int ret = ioctl(fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_RD_MODE, &mode);
    if (ret == -1) {
        perror("Error getting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error getting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error getting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t channel, uint8_t *data) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    memcpy(data, rx_buf, 3);
    return 0;
}

// Temperature conversion function
float adc_to_temperature(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float temperature = (voltage - TMP36_MIN_VOLTAGE) / (TMP36_MAX_VOLTAGE - TMP36_MIN_VOLTAGE) * (TMP36_MAX_TEMPERATURE - TMP36_MIN_TEMPERATURE) + TMP36_MIN_TEMPERATURE;
    return temperature;
}

// Temperature logging function
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("temperature_log.csv", "a");
        if (log_file == NULL) {
            perror("Error opening temperature_log.csv");
            return -1;
