#define SPI_MODE 0
#define IMPACT_THRESHOLD 500
#define LOG_FILE "impact_log.txt"

// ADXL335 Sensitivity (mg/LSB) - Adjust based on your setup
#define ADXL335_SENSITIVITY 0.3 // Example value, check datasheet

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} accelerometer_data_t;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
accelerometer_data_t read_accelerometer();
int detect_impact(accelerometer_data_t data);
int log_data(accelerometer_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library and SPI interface
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioCfgClock(5, 1, 0); // 5us sample rate

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads data from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Reads accelerometer data from the MCP3008
accelerometer_data_t read_accelerometer() {
    accelerometer_data_t data;
    data.x = read_mcp3008(0);
    data.y = read_mcp3008(1);
    data.z = read_mcp3008(2);
    return data;
}

// Detects impact based on the magnitude of the acceleration vector
int detect_impact(accelerometer_data_t data) {
    int magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    return (magnitude > IMPACT_THRESHOLD) ? 1 : 0;
}

// Logs the accelerometer data to a file
int log_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("Accelerometer data logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        accelerometer_data_t data = read_accelerometer();
        if (data.x < 0 || data.x > 1023 || data.y < 0 || data.y > 1023 || data.z < 0 || data.z > 1023) {
            fprintf(stderr, "Invalid ADC value read. Skipping.\n");
            gpioDelay(10); // Small delay to prevent busy-waiting
            continue;
        }

        if (detect_impact(data)) {
            fprintf(log_file, "IMPACT DETECTED\n");
            fflush(log_file);
        }

        log_data(data);
        gpioDelay(10); // Sample at approximately 100 Hz
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

