#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 channel assignments
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

// Define gain control values
#define GAIN_1 1.0
#define GAIN_2 2.0
#define GAIN_3 4.0

// Define noise cancellation parameters
#define ALPHA 0.5

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t mic1;
    int16_t mic2;
} MicrophoneData;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
MicrophoneData apply_noise_cancellation(int16_t mic1_sample, int16_t mic2_sample, float gain);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    int result = spiXfer(spi_handle, spi_data, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Apply noise cancellation algorithm
MicrophoneData apply_noise_cancellation(int16_t mic1_sample, int16_t mic2_sample, float gain) {
    MicrophoneData output;
    float mic1_filtered = (mic1_sample * gain) - (mic2_sample * ALPHA);
    output.mic1 = (int16_t)(mic1_filtered * 10000); // Scale to 0-10000 range
    output.mic2 = (int16_t)(mic2_sample * gain); // Pass through mic2
    return output;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments for gain
    float gain = GAIN_1;
    if (argc > 1) {
        if (strcmp(argv[1], "--gain1") == 0) {
            gain = GAIN_1;
        } else if (strcmp(argv[1], "--gain2") == 0) {
            gain = GAIN_2;
        } else if (strcmp(argv[1], "--gain3") == 0) {
            gain = GAIN_3;
        } else {
            fprintf(stderr, "Invalid gain argument. Using default gain: %f\n", GAIN_1);
        }
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read microphone data
        int mic1_value = read_mcp3008(MIC1_CHANNEL);
        int mic2_value = read_mcp3008(MIC2_CHANNEL);

        if (mic1_value == -1 || mic2_value == -1) {
            fprintf(stderr, "Error reading microphone data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Apply noise cancellation
        MicrophoneData noise_canceled_data = apply_noise_cancellation((int16_t)mic1_value, (int16_t)mic2_value, gain);

        // Print data to terminal
        printf("%d,%d\n", noise_canceled_data.mic1, noise_canceled_data.mic2);

        // Delay for a short period
        gpioDelay(10); // 10 ms delay
    }

    // Clean up resources
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

