#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define MAX_RETRIES 3
#define DEFAULT_AMBIENT_TEMP 25.0

// Global variables
int spi_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float temperature_compensation(float voltage, float ambient_temp);
int log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0;
    }

    return (float)adc_value * 3.3 / 1024.0;
}

// Function to perform temperature compensation
float temperature_compensation(float voltage, float ambient_temp) {
    // Simple linear compensation (replace with a more accurate model if needed)
    float compensated_voltage = voltage + (ambient_temp - 25.0) * 0.01; // Example: 0.01V/degree
    return compensated_voltage;
}

// Function to log data to file
int log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen("error_log.txt", "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open error log file\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    fprintf(stderr, "Flame sensor monitoring started...\n");

    while (!terminate) {
        int raw_adc = -1;
        int retries = 0;
        float voltage = -1.0;
        float compensated_voltage = -1.0;
        float temperature = -1.0;
        int flame_detected = 0;

        while (retries < MAX_RETRIES) {
            raw_adc = read_mcp3008(0);
            if (raw_adc < 0) {
                fprintf(stderr, "Error: Failed to read MCP3008, retrying...\n");
                fprintf(error_log_file, "Error: Failed to read MCP3008, retrying...\n");
                gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
                gpioDelay(100); // Small delay before retrying
                retries++;
                continue;
            }

            if (raw_adc < 0 || raw_adc > 1023) {
                fprintf(stderr, "Error: ADC value out of range, retrying...\n");
                fprintf(error_log_file, "Error: ADC value out of range, retrying...\n");
                gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
                gpioDelay(100); // Small delay before retrying
                retries++;
                continue;
            }

            voltage = adc_to_voltage(raw_adc);
            if (voltage < 0) {
                fprintf(stderr, "Error: Failed to convert ADC to voltage, retrying...\n");
                fprintf(error_log_file, "Error: Failed to convert ADC to voltage, retrying...\n");
                gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
                gpioDelay(100); // Small delay before retrying
                retries++;
                continue;
            }

            compensated_voltage = temperature_compensation(voltage, DEFAULT_AMBIENT_TEMP);
            temperature = DEFAULT_AMBIENT_TEMP; // Default temperature if file is missing or invalid

            if (temperature == DEFAULT_AMBIENT_TEMP) {
                fprintf(stderr, "Warning: Ambient temperature file not found or invalid, using default temperature: %.2f\n", DEFAULT_AMBIENT_TEMP);
                fprintf(error_log_file, "Warning: Ambient temperature file not found or invalid, using default temperature: %.2f\n", DEFAULT_AMBIENT_TEMP);
            }

            if (temperature == DEFAULT_AMBIENT_TEMP) {
                flame_detected = 0; // Flame not detected if temperature is invalid
            } else {
                flame_detected = (compensated_voltage > 2.5) ? 1 : 0; // Flame detected if voltage is high
            }

            log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected);

            gpioWrite(BUZZER_GPIO, flame_detected); // Control buzzer
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Error: Max retries reached, skipping this iteration.\n");
            fprintf(error_log_file, "Error: Max retries reached, skipping this iteration.\n");
        }

        gpioDelay(500); // Sample every 500ms
    }

    cleanup();
    return 0;
}

