#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define LED_GPIO 17
#define MCP3008_CHANNEL 0
#define SLEEP_DURATION 5 // seconds

// Global variables
int spi_handle;
FILE *water_levels_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_water_level(int adc_value);
void control_led(float water_level);
void log_data(float water_level);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn the LED off

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    water_levels_file = fopen("water_levels.json", "a");
    if (water_levels_file == NULL) {
        fprintf(stderr, "Failed to open water_levels.json\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write opening bracket if the file is newly created
    fseek(water_levels_file, 0, SEEK_END);
    long file_size = ftell(water_levels_file);
    if (file_size == 0) {
        fprintf(water_levels_file, "[");
        fflush(water_levels_file);
    }

    return 0;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate water level percentage
float calculate_water_level(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the LED based on water level
void control_led(float water_level) {
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH && gpioRead(LED_GPIO) == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW && gpioRead(LED_GPIO) == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Function to log data to file
void log_data(float water_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(water_levels_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, water_level);
    fflush(water_levels_file);

    // Check if the file is empty and write the opening bracket if needed
    fseek(water_levels_file, 0, SEEK_END);
    long file_size = ftell(water_levels_file);
    if (file_size == 0) {
        fprintf(water_levels_file, "[");
        fflush(water_levels_file);
    }
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    spiClose(spi_handle);
    fclose(water_levels_file);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
