void control_led(float water_level) {
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH && gpioRead(LED_GPIO) == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW && gpioRead(LED_GPIO) == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
