    fseek(logFile, 0, SEEK_END);
    long file_size = ftell(logFile);
    if (file_size == 0) {
        fprintf(logFile, "Timestamp,Airflow (LPM)\n");
    }
    rewind(logFile);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (keepRunning) {
        // Read ADC value
        int adc_value = read_adc(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 100ms.\n");
            delay(100);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to airflow
        float airflow = voltage_to_airflow(voltage);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log data
        if (log_data(timestamp, airflow) == -1) {
            fprintf(stderr, "Failed to log data. Retrying in 100ms.\n");
        }

        free(timestamp);

        // Wait 100 milliseconds
        delay(100);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (logFile != NULL) {
        fclose(logFile);
    }

    return 0;
}

