    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %s\n", channel, strerror(errno));
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value, int min_adc, int max_adc) {
    float percentage = 100.0 - ((float)(adc_value - min_adc) / (float)(max_adc - min_adc) * 100.0);
    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }
    return percentage;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert
void send_email_alert(float moisture_percentage) {
    char command[256];
    char email_body[256];
    int result;

    // Construct email command
    snprintf(command, sizeof(command), "echo \"Subject: Plant Moisture Alert\n\nPlant moisture level is below threshold (%.2f%%). Check the plant!\n\" | msmtp -t -a %s", email_address, config.msmtp_config_file);

    // Construct email body
    snprintf(email_body, sizeof(email_body), "Plant moisture level is below threshold (%.2f%%). Check the plant!", moisture_percentage);

    // Execute msmtp command
    result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error: Failed to execute msmtp command\n");
    } else {
        if (WEXITSTATUS(result) != 0) {
            fprintf(stderr, "Error: msmtp command failed with exit status %d\n", WEXITSTATUS(result));
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize SPI
int initialize_spi(int channel) {
    int handle = spiOpen(channel, 500000, 0); // Channel, baud rate, flags
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open SPI channel %d: %s\n", channel, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Default values
    config.spi_channel = 0;
    config.adc_channel = 0;
    config.min_adc_value = 0;
    config.max_adc_value = 1023;
    config.moisture_threshold = 30.0;
    config.logging_interval = 60;
    config.email_address = "recipient@example.com";
    config.msmtp_config_file = "/etc/msmtprc";

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:t:i:e:f:")) != -1) {
        switch (opt) {
            case 'c':
                config.spi_channel = atoi(optarg);
                break;
            case 'a':
                config.email_address = optarg;
                break;
            case 'm':
                config.min_adc_value = atoi(optarg);
                break;
            case 't':
                config.moisture_threshold = atof(optarg);
                break;
            case 'i':
                config.logging_interval = atoi(optarg);
                break;
            case 'e':
                config.msmtp_config_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a email_address] [-m min_adc_value] [-t moisture_threshold] [-i logging_interval] [-e msmtp_config_file]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Validate configuration
    if (config.spi_channel < 0 || config.spi_channel > 7) {
        fprintf(stderr, "Error: Invalid SPI channel %d\n", config.spi_channel);
        return EXIT_FAILURE;
    }
    if (config.adc_channel < 0 || config.adc_channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", config.adc_channel);
        return EXIT_FAILURE;
    }
    if (config.min_adc_value < 0 || config.min_adc_value > 1023) {
        fprintf(stderr, "Error: Invalid minimum ADC value %d\n", config.min_adc_value);
        return EXIT_FAILURE;
    }
    if (config.max_adc_value < 0 || config.max_adc_value > 1023) {
        fprintf(stderr, "Error: Invalid maximum ADC value %d\n", config.max_adc_value);
        return EXIT_FAILURE;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_handle = initialize_spi(config.spi_channel);
    if (spi_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(config.logging_interval);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value, config.min_adc_value, config.max_adc_value);

        // Log data
        log_data(moisture_percentage);

        // Check moisture threshold and send email alert
        if (moisture_percentage < config.moisture_threshold) {
            send_email_alert(moisture_percentage);
        }

        // Wait for the next reading
        sleep(config.logging_interval);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

