    int sample_interval = 1; // Default interval is 1 second

    // Parse command-line argument for sample interval
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Error: Invalid sample interval. Using default (1 second).\n");
            sample_interval = 1;
        }
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            int adc_value = read_mcp3008(sensors[i].channel);
            if (adc_value >= 0) {
                float moisture_percentage = calculate_moisture_percentage(adc_value);
                log_data(sensors[i].name, adc_value, moisture_percentage);
