    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_local) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_local) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_local) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Perform SPI transfer
int spi_transfer(int spi_fd, uint8_t spi_mode, uint8_t bits_per_word, uint32_t speed, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = speed,
        .bits_per_word = bits_per_word,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message for MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Perform SPI transfer
    if (spi_transfer(spi_fd, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED, tx_buf, rx_buf, 3) < 0) {
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Calculate moisture percentage from ADC value
float calculate_moisture_percentage(int adc_value) {
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close SPI device if it's open
    if (spi_fd != -1) {
        close(spi_fd);
    }

    exit(0);
}

