#define MAX_VOLTAGE 3.3f
#define MIN_PRESSURE 0.0f
#define MAX_PRESSURE 100.0f
#define READ_INTERVAL 1 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_adc(int channel);
float voltage_to_pressure(int adc_value);
void log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    float vref;
    float min_voltage;
    float max_voltage;
    float min_pressure;
