    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleaned up and exiting.\n");
}

