#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL 5 // seconds
#define ADC_STUCK_THRESHOLD 5 // Number of consecutive readings

// Global variables
static int spi_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(int channel);
int read_mcp3008(int channel);
void log_data(int adc_value);
void signal_handler(int sig);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// SPI initialization function
int spi_init(void) {
    int fd;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 1)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2]; // Extract 10-bit ADC value
}

// Read MCP3008 function
int read_mcp3008(int channel) {
    int adc_value = spi_transfer(channel);
    if (adc_value < 0) {
        fprintf(stderr, "Error reading ADC value from channel %d\n", channel);
        return -1;
    }
    return adc_value;
}

// Log data function
void log_data(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - ADC Value: %d\n", timestamp, adc_value);
}

// Cleanup function
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    printf("Cleanup complete. SPI closed.\n");
}

int main(void) {
    int adc_value;
    int stuck_count = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("Soil Moisture Sensor Data Logger\n");

    while (!terminate) {
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            log_data(adc_value);
            stuck_count = 0; // Reset stuck count on successful read
        } else {
            stuck_count++;
            fprintf(stderr, "Failed to read ADC value. Stuck count: %d\n", stuck_count);
        }

        if (adc_value == 0 || adc_value == 1023) {
            stuck_count++;
            fprintf(stderr, "ADC value stuck at %d. Stuck count: %d\n", adc_value, stuck_count);
        }

        if (stuck_count >= ADC_STUCK_THRESHOLD) {
            fprintf(stderr, "Sensor absent or wiring fault detected. Cleaning up.\n");
            cleanup();
            return 1;
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

