#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_SENSORS 4
#define CSV_FILE "environmental_data.csv"

// Global variables
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
void log_data(float voltage0, float voltage1, float voltage2, float voltage3);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        perror("SPI data read failed");
        return -1; // Indicate an error
    }

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return (adc_value * 3.3) / 1024.0;
}

// Function to log data to CSV file
void log_data(float voltage0, float voltage1, float voltage2, float voltage3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (csv_file != NULL) {
        fprintf(csv_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, voltage0, voltage1, voltage2, voltage3);
        fflush(csv_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: CSV file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialization function
int initialize() {
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error: wiringPiSetup failed: %s\n", strerror(errno));
        return -1;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Error: wiringPiSPISetup failed: %s\n", strerror(errno));
        return -1;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file: %s\n", strerror(errno));
        return -1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Sensor0,Sensor1,Sensor2,Sensor3\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    // No explicit SPI close needed with wiringPi, but good practice to note
    printf("Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() == -1) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    printf("Environmental data logging started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value0 = read_mcp3008(0);
        int adc_value1 = read_mcp3008(1);
        int adc_value2 = read_mcp3008(2);
        int adc_value3 = read_mcp3008(3);

        if (adc_value0 == -1 || adc_value1 == -1 || adc_value2 == -1 || adc_value3 == -1) {
            fprintf(stderr, "Error reading ADC values. Skipping logging.\n");
        } else {
            float voltage0 = convert_to_voltage(adc_value0);
            float voltage1 = convert_to_voltage(adc_value1);
            float voltage2 = convert_to_voltage(adc_value2);
            float voltage3 = convert_to_voltage(adc_value3);

            log_data(voltage0, voltage1, voltage2, voltage3);
        }

        delay(1000); // Sample every 1 second
    }

    cleanup();
    return 0;
}

