#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <stdbool.h>

// Configuration
#define SPI_BUS 0
#define SPI_CE0 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define CIRCULAR_BUFFER_SIZE 20
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int spi_fd;
int pump_state = false; // false = off, true = on
int circular_buffer[CIRCULAR_BUFFER_SIZE][100]; // [index][timestamp][reading][pump_state]
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int spi_init(int bus, int ce, int speed);
int mcp3008_read(int channel);
void pump_control(int state);
void log_data(int reading, int pump_state);
void print_circular_buffer();
void signal_handler(int signal);
void timer_callback();

// SPI Initialization
int spi_init(int bus, int ce, int speed) {
    char spi_device[20];
    sprintf(spi_device, "/dev/spidev%d.%d", bus, ce);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// MCP3008 Read
int mcp3008_read(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Pump Control
void pump_control(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", PUMP_GPIO);
    }
    pump_state = state;
}

// Data Logging
void log_data(int reading, int pump_state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    circular_buffer[buffer_index][0] = buf;
    circular_buffer[buffer_index][1] = reading;
    circular_buffer[buffer_index][2] = pump_state;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
    if (buffer_count < CIRCULAR_BUFFER_SIZE) {
        buffer_count++;
    }
}

// Print Circular Buffer
void print_circular_buffer() {
    printf("\n--- Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + CIRCULAR_BUFFER_SIZE) % CIRCULAR_BUFFER_SIZE;
        printf("[%d] %s: %d, Pump: %s\n",
               index, circular_buffer[index][0], circular_buffer[index][1], circular_buffer[index][2]);
    }
    printf("--- End of Log ---\n\n");
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    pump_control(false); // Turn off pump
    close(spi_fd);
    gpioTerminate();
    exit(0);
}

// Timer Callback
void timer_callback() {
    int reading = mcp3008_read(MCP3008_CHANNEL);
    if (reading < 0) {
        fprintf(stderr, "Error reading MCP3008, retrying...\n");
        log_data(-1, pump_state); // Log error
        return;
    }

    int pump_state = (reading < LOW_THRESHOLD) ? true : (reading > HIGH_THRESHOLD) ? false : pump_state; // Hysteresis
    pump_control(pump_state);
    log_data(reading, pump_state);
    print_circular_buffer();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (spi_init(SPI_BUS, SPI_CE0, SPI_SPEED) < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_SEC * 1000, timer_callback, NULL);

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        sleep(1); // Keep the program running
    }

    return 0;
}

