    printf("--- End of Log ---\n\n");
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    pump_control(false); // Turn off pump
    close(spi_fd);
    gpioTerminate();
    exit(0);
}

// Timer Callback
void timer_callback() {
    int reading = mcp3008_read(MCP3008_CHANNEL);
    if (reading < 0) {
        fprintf(stderr, "Error reading MCP3008, retrying...\n");
        log_data(-1, pump_state); // Log error
        return;
    }

    int pump_state = (reading < LOW_THRESHOLD) ? true : (reading > HIGH_THRESHOLD) ? false : pump_state; // Hysteresis
    pump_control(pump_state);
    log_data(reading, pump_state);
    print_circular_buffer();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (spi_init(SPI_BUS, SPI_CE0, SPI_SPEED) < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_SEC * 1000, timer_callback, NULL);

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        sleep(1); // Keep the program running
    }

    return 0;
}

