        int adc_value_1 = read_mcp3008(MCP3008_CHANNEL_1);
        int adc_value_2 = read_mcp3008(MCP3008_CHANNEL_2);

        if (adc_value_0 == -1 || adc_value_1 == -1 || adc_value_2 == -1) {
            fprintf(stderr, "Error: Failed to read ADC values. Skipping logging.\n");
        } else {
            float voltage_0 = convert_to_voltage(adc_value_0);
            float voltage_1 = convert_to_voltage(adc_value_1);
            float voltage_2 = convert_to_voltage(adc_value_2);

            if (log_data(timestamp, MCP3008_CHANNEL_0, voltage_0) != 0 ||
                log_data(timestamp, MCP3008_CHANNEL_1, voltage_1) != 0 ||
                log_data(timestamp, MCP3008_CHANNEL_2, voltage_2) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }

            free(timestamp); // Free the allocated memory for timestamp
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup
    printf("Closing SPI...\n");
    spiClose(spi_handle);
    printf("Terminating pigpio...\n");
    gpioTerminate();
    printf("Closing CSV file...\n");
    fclose(csv_file);

    printf("Exiting.\n");
    return 0;
}

