#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_CONFIG_DEFAULT 0x4003 // Single-shot mode, +/-4.096V, 128 SPS, AIN0
#define GPIO_RELAY 17
#define GPIO_DOOR_SENSOR 27
#define DISTANCE_THRESHOLD 50.0 // cm
#define RELAY_DURATION 3.0      // seconds
#define REED_SENSOR_READING_DELAY 1.0 // seconds
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
float read_distance();
int calibrate_threshold();
int control_relay(int energize);
int read_reed_sensor();
int log_event(const char *event);
void signal_handler(int sig);

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    int result = 0;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }
    result = (buffer[0] << 8) | buffer[1];
    return result;
}

// I2C write function
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buffer[3];
    buffer[0] = reg;
    buffer[1] = (value >> 8) & 0xFF;
    buffer[2] = value & 0xFF;
    if (write(fd, buffer, 3) != 3) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Function to read distance from ADS1115
float read_distance() {
    int16_t adc_value;
    float voltage, distance;

    adc_value = i2c_read_word(i2c_fd, ADS1115_REG_CONVERT);
    if (adc_value == -1) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1.0;
    }

    // Convert ADC value to voltage (assuming +/-4.096V range)
    voltage = (float)adc_value * 4.096 / 32768.0;

    // Convert voltage to distance (using a simplified approximation)
    distance = 27.0 / (voltage + 0.1); // Example approximation, adjust as needed

    return distance;
}

// Function to calibrate the distance threshold
int calibrate_threshold() {
    float sum = 0.0;
    int num_samples = 10;
    int i;

    printf("Calibrating threshold...");
    for (i = 0; i < num_samples; i++) {
        sum += read_distance();
        delay(50); // 50ms delay
    }

    float average = sum / num_samples;
    printf("Calibration complete. Average distance: %.2f cm\n", average);
    return average;
}

// Function to control the relay
int control_relay(int energize) {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed\n");
        return -1;
    }

    pinMode(GPIO_RELAY, OUTPUT);
    digitalWrite(GPIO_RELAY, !energize); // Active-high, so LOW energizes the relay

    if (energize) {
        printf("Energizing relay for %d seconds\n", RELAY_DURATION);
        delay(RELAY_DURATION * 1000);
        printf("De-energizing relay\n");
    } else {
        printf("De-energizing relay\n");
    }

    return 0;
}

// Function to read the reed sensor
int read_reed_sensor() {
    return digitalRead(GPIO_DOOR_SENSOR);
}

// Function to log events
int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Received signal %d, shutting down...\n", sig);
    terminate = 1;
    control_relay(0); // De-energize relay
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
