// Global variables
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
float read_distance();
int calibrate_threshold();
int control_relay(int energize);
int read_reed_sensor();
int log_event(const char *event);
void signal_handler(int sig);

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    int result = 0;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }
    result = (buffer[0] << 8) | buffer[1];
    return result;
}

// I2C write function
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buffer[3];
    buffer[0] = reg;
    buffer[1] = (value >> 8) & 0xFF;
    buffer[2] = value & 0xFF;
    if (write(fd, buffer, 3) != 3) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

