#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for chip selects
#define CS0 8
#define CS1 7
#define CS2 25

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define ADC channels for each sensor
#define SENSOR1_CHANNEL 0
#define SENSOR2_CHANNEL 1
#define SENSOR3_CHANNEL 2

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_adc(int channel);
int log_data(time_t timestamp, int sensor1_value, int sensor2_value, int sensor3_value);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1;
    int sensor2;
    int sensor3;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(CS0, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting CS0 as output\n");
        return -1;
    }
    if (gpioSetMode(CS1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting CS1 as output\n");
        return -1;
    }
    if (gpioSetMode(CS2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting CS2 as output\n");
        return -1;
    }

    gpioWrite(CS0, 1); // Deselect all chips initially
    gpioWrite(CS1, 1);
    gpioWrite(CS2, 1);

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 single-ended read)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    gpioWrite(CS0, 0); // Select sensor 1
    gpioDelay(1); // Small delay
    spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(CS0, 1); // Deselect sensor 1

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to log data to CSV file
int log_data(time_t timestamp, int sensor1_value, int sensor2_value, int sensor3_value) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp_str, sensor1_value, sensor2_value, sensor3_value) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("soil_moisture_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created (empty)
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
        fflush(log_file);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1_value = read_adc(SENSOR1_CHANNEL);
        int sensor2_value = read_adc(SENSOR2_CHANNEL);
        int sensor3_value = read_adc(SENSOR3_CHANNEL);

        // Get current timestamp
        time_t current_time = time(NULL);

        // Log data
        if (sensor1_value != -1 && sensor2_value != -1 && sensor3_value != -1) {
            if (log_data(current_time, sensor1_value, sensor2_value, sensor3_value) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioWrite(CS0, 1);
    gpioWrite(CS1, 1);
    gpioWrite(CS2, 1);
    gpioTerminate();

    return 0;
}

