#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 0.3 // 30% of 0-3V
#define DEFAULT_DURATION 10 // seconds
#define DEFAULT_SLEEP 60 // seconds
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], int *threshold, int *duration, int *sleep_interval);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count, adc_value;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    for (count = 0; count < MAX_RETRIES; count++) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            log_event("SPI read failed. Retrying...");
            gpioDelay(1000); // Wait 1ms before retry
        }
    }

    log_event("SPI read failed after multiple retries.");
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * 3.3;
    return voltage * 100.0;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[50];
    sprintf(message, "Pump turned %s", state ? "ON" : "OFF");
    log_event(message);
}

// Function to log events to file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[], int *threshold, int *duration, int *sleep_interval) {
    int opt;

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                *threshold = atoi(optarg);
                if (*threshold < 0 || *threshold > 100) {
                    fprintf(stderr, "Invalid threshold value. Must be between 0 and 100.\n");
                    return 1;
                }
                break;
            case 'd':
