#define PCF8591_AIN0 0x40

int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_fd = i2cOpen(I2C_BUS, PCF8591_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Perform a dummy read
        if (i2cWriteByteData(i2c_fd, PCF8591_AIN0, 0) < 0) {
            fprintf(stderr, "Error writing to I2C device\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Read the ADC value
        int adc_value = i2cReadByteData(i2c_fd, PCF8591_AIN0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading from I2C device\n");
