#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GAIN_REG 0x40
#define CONTINUOUS_MODE 0x8000
#define GPIO_PIN 27
#define THRESHOLD 500.0 // Gauss
#define VREF 3.3 // Volts
#define BUFFER_SIZE 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int config_ads1115();
int16_t read_ads1115();
float voltage_to_gauss(int16_t raw_value);
void buffer_init(CircularBuffer *cb);
void buffer_add(CircularBuffer *cb, float value);
float buffer_get_average(CircularBuffer *cb);
void gpio_init();
void gpio_set_output(int pin, int value);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Initialize circular buffer
void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get the average of the values in the circular buffer
float buffer_get_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Configure ADS1115
int config_ads1115() {
    char buf[3];
    int16_t config = 0x4083; // Single-ended AIN0, 4.096V, Continuous mode, +/-4.096V

    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        log_message(LOG_ERR, "Failed to write to ADS1115");
        return -1;
    }
    return 0;
}

// Read from ADS1115
int16_t read_ads1115() {
    char buf[1];
    char read_buf[2];
    int16_t raw_value;

    buf[0] = CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        log_message(LOG_ERR, "Failed to write to ADS1115 for read");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        log_message(LOG_ERR, "Failed to read from ADS1115");
        return -1;
    }

    raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

