#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RAIN_SENSOR_CHANNEL 0
#define VREF 3.3 // Reference voltage
#define FULL_SCALE_ADC_VALUE 1023

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
int map_adc_to_intensity(int adc_value);
void log_data(int adc_value, int intensity);
void signal_handler(int signal);

// Structure for SPI configuration (optional, but good practice)
typedef struct {
    int channel;
    int speed;
    int mode;
} spi_config_t;

// Function to initialize the SPI interface
int initialize_spi() {
    spi_config_t config = {SPI_CHANNEL, SPI_SPEED, 0}; // SPI mode 0

    spi_handle = spiOpen(config.channel, config.speed, config.mode);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 single-ended read)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map ADC value to rainfall intensity level
int map_adc_to_intensity(int adc_value) {
    // Linear mapping: 0 ADC = 0 intensity, 1023 ADC = 100 intensity
    return (int)(((float)adc_value / FULL_SCALE_ADC_VALUE) * 100.0);
}

// Function to log data to stdout
void log_data(int adc_value, int intensity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, ADC: %d, Intensity: %d\n", timestamp, adc_value, intensity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI interface
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from rain sensor
        int adc_value = read_adc(RAIN_SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Map ADC value to rainfall intensity
        int intensity = map_adc_to_intensity(adc_value);

        // Log data
        log_data(adc_value, intensity);

        // Wait for 1 second
        sleep(1);
    }

    // Close SPI interface
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

