#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define THRESHOLD_DEFAULT 100.0f
#define BLINK_DURATION 1000 // milliseconds
#define BLINK_PERIOD 50 // milliseconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int16_t read_ads1115();
float calculate_gauss(int16_t adc_value);
void blink_led(float threshold);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure ADS1115
int configure_ads1115() {
    char config[3];
    int16_t config_value = 0x4083; // Single-ended AIN0, PGA = 4.096V, 128 SPS

    config[0] = (config_value >> 8) & 0xFF;
    config[1] = config_value & 0xFF;
    config[2] = 0x00; // No effect

    int result = i2cWriteDevice(i2c_handle, config, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115: %d\n", result);
        return -1;
    }

    return 0;
}

// Read ADS1115
int16_t read_ads1115() {
    char reg = CONVERSION_REG;
    char data[2];
    int result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write conversion register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read conversion data: %d\n", result);
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Calculate Gauss
float calculate_gauss(int16_t adc_value) {
    return (float)adc_value * 4.096f / 32768.0f; // 4.096V / 2^15
}

// Blink LED
void blink_led(float threshold) {
    int on_time = (int)(BLINK_PERIOD * 1000); // milliseconds
    int off_time = (int)(BLINK_PERIOD * 1000); // milliseconds
    int duration = BLINK_DURATION * 1000; // milliseconds

    while (time_time() < duration) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
        gpioDelay(on_time);
        gpioWrite(LED_GPIO, 0); // Turn off LED
        gpioDelay(off_time);
    }
}

int main(int argc, char *argv[]) {
    float threshold = THRESHOLD_DEFAULT;

    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        threshold = strtof(argv[1], &endptr);
        if (*endptr != '\0') {
            fprintf(stderr, "Invalid threshold value: %s\n", argv[1]);
            return 1;
        }
    }

    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        int16_t adc_value = read_ads1115();
        if (adc_value >= 0) {
            float gauss = calculate_gauss(adc_value);
            printf("Magnetic Field: %.2f Gauss\n", gauss);

            if (gauss > threshold) {
                blink_led(threshold);
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

