#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MQTT_CLIENT_ID "soil_moisture_monitor"

// Global variables
int spi_handle;
struct mosquitto *mqtt_client = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_relay(int moisture_percentage);
void publish_moisture(float moisture);
void subscribe_to_pump_control();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message(LOG_ERR, "Invalid MCP3008 channel");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        log_message(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        log_message(LOG_ERR, "ADC value out of range");
        return -1.0;
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the relay
void control_relay(int moisture_percentage) {
    if (moisture_percentage < MOISTURE_THRESHOLD_LOW && !gpioRead(RELAY_GPIO) == 0) {
        gpioWrite(RELAY_GPIO, 1); // Turn pump ON
        log_message(LOG_INFO, "Moisture below threshold, turning pump ON");
    } else if (moisture_percentage > MOISTURE_THRESHOLD_HIGH && gpioRead(RELAY_GPIO) == 1) {
        gpioWrite(RELAY_GPIO, 0); // Turn pump OFF
        log_message(LOG_INFO, "Moisture above threshold, turning pump OFF");
    }
}

// Function to publish moisture value to MQTT
void publish_moisture(float moisture) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mqtt_client, NULL, MQTT_TOPIC_SOIL_MOISTURE, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to publish message");
    }
}

// Function to subscribe to pump control topic
void subscribe_to_pump_control() {
    int ret = mosquitto_subscribe(mqtt_client, NULL, MQTT_TOPIC_PUMP_CONTROL, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to subscribe to topic");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    terminate = 1;
}

// Logging function using syslog
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially turn pump OFF

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        log_message(LOG_ERR, "SPI initialisation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mqtt_client) {
        log_message(LOG_ERR, "Failed to create MQTT client");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mqtt_client, NULL);
    mosquitto_message_callback_set(mqtt_client, NULL);

    int ret = mosquitto_connect(mqtt_client, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    subscribe_to_pump_control();

    // Main loop
    while (!terminate) {
        // Read moisture sensor
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            log_message(LOG_ERR, "Failed to read ADC value");
            sleep(60); // Wait before retrying
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);
        if (moisture_percentage < 0.0) {
            log_message(LOG_ERR, "Failed to calculate moisture percentage");
            sleep(60); // Wait before retrying
            continue;
        }

        // Control relay
        control_relay((int)moisture_percentage);

        // Publish moisture value
        publish_moisture(moisture_percentage);

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup
    log_message(LOG_INFO, "Cleaning up...");
    gpioWrite(RELAY_GPIO, 0); // Turn pump OFF
    spiClose(spi_handle);
    mosquitto_disconnect(mqtt_client);
    mosquitto_destroy(mqtt_client);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

