#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// SPI device file
#define SPI_DEVICE "/dev/spidev0.0"

// SPI mode
#define SPI_MODE 0

// SPI speed (Hz)
#define SPI_SPEED 1000000

// Chip Select GPIO pin
#define CS_PIN 8

// VREF value (V)
#define VREF 3.3

// VDD value (V)
#define VDD 3.3

// Number of bits in the ADC value
#define ADC_BITS 10

// Global variable to store the SPI file descriptor
int spi_fd = -1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to initialize the SPI interface
int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set CS pin as output
    int cs_fd = open("/sys/class/gpio/gpio" CS_PIN "/direction", O_WRONLY);
    if (cs_fd < 0) {
        fprintf(stderr, "Error opening CS pin direction file: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }
    if (write(cs_fd, "out", 3) != 3) {
        fprintf(stderr, "Error setting CS pin direction: %s\n", strerror(errno));
        close(cs_fd);
        close(spi_fd);
        return -1;
    }
    close(cs_fd);

    return 0;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8; // Ensure 8-bit transfer
    transfer[0].delay_usecs = 0;

    // Activate chip select
    int cs_fd = open("/sys/class/gpio/gpio" CS_PIN "/value", O_WRONLY);
    if (cs_fd < 0) {
        fprintf(stderr, "Error opening CS pin value file: %s\n", strerror(errno));
        return -1;
    }
    if (write(cs_fd, "0", 1) != 1) {
        fprintf(stderr, "Error deactivating CS pin: %s\n", strerror(errno));
        close(cs_fd);
        return -1;
    }
    close(cs_fd);

    // Perform the SPI transaction
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        fprintf(stderr, "Error during SPI transaction: %s\n", strerror(errno));
        return -1;
    }

    // Deactivate chip select
    cs_fd = open("/sys/class/gpio/gpio" CS_PIN "/value", O_WRONLY);
    if (cs_fd < 0) {
        fprintf(stderr, "Error opening CS pin value file: %s\n", strerror(errno));
        return -1;
    }
    if (write(cs_fd, "1", 1) != 1) {
        fprintf(stderr, "Error activating CS pin: %s\n", strerror(errno));
        close(cs_fd);
        return -1;
    }
    close(cs_fd);

    // Extract the ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / (float)(1 << ADC_BITS)) * VREF;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the SPI interface
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("SPI initialized successfully. Reading from channel 0...\n");

    // Main loop
    while (1) {
        // Read the ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert the ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Print the raw ADC value and the calculated voltage
        printf("Raw ADC Value: %d, Voltage: %.2f V\n", adc_value, voltage);

        // Wait for 500 milliseconds
        usleep(500000);
    }

    return 0;
}

