#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define VREF 3.3
#define NUM_CHANNELS 3
#define CSV_FILE "sensor_data.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
char* get_timestamp();
int write_to_csv(char *timestamp, float voltages[NUM_CHANNELS]);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    float vref;
    char *csv_file;
} config_t;

config_t config = {SPI_CHANNEL, SPI_BAUD, VREF, CSV_FILE};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        float voltages[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                voltages[i] = -1.0; // Indicate error
            } else {
                voltages[i] = convert_to_voltage(adc_value);
            }
        }

        char *timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Error getting timestamp\n");
            continue; // Skip writing to CSV this iteration
        }

        if (write_to_csv(timestamp, voltages) != 0) {
            fprintf(stderr, "Error writing to CSV\n");
        }

        free(timestamp); // Free the timestamp string

        sleep(5);
    }

    // Cleanup (should not reach here if signal handler works)
    spiClose(spi_handle);
    gpioTerminate();
    if (fp != NULL) {
        fclose(fp);
    }

    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    fp = fopen(config.csv_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Channel0,Channel1,Channel2\n");
    }
    fseek(fp, 0, SEEK_END); // Reset file pointer to the end

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

int write_to_csv(char *timestamp, float voltages[NUM_CHANNELS]) {
    if (fp == NULL) {
        fprintf(stderr, "File pointer is NULL\n");
        return 1;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, voltages[0], voltages[1], voltages[2]);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

