int spi_fd = -1;

// Function prototypes
int read_mcp3008(int channel);
void set_motor_speed(int motor_pin, int pwm_value);
void log_vibration_event(int noise_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop vibration motors
    set_motor_speed(MOTOR1_PIN, 0);
    set_motor_speed(MOTOR2_PIN, 0);

