    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Terminate wiringPi
    wiringPiSetupGpio(); // Reinitialize to allow cleanup
    pinMode(MOTOR1_PIN, INPUT); // Set pins to input to avoid short circuits
    pinMode(MOTOR2_PIN, INPUT);
    wiringPiSetup(); // Reinitialize to allow cleanup

    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "Error: SPI read failed: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

