void set_motor_speed(int motor_pin, int pwm_value) {
    if (pwm_value < 0 || pwm_value > 100) {
        fprintf(stderr, "Error: Invalid PWM value: %d\n", pwm_value);
        return;
    }

    // Set GPIO pin to PWM mode
    pinMode(motor_pin, PWM_OUTPUT);

