    pwmSetRange(100);

    // Set PWM frequency (adjust as needed)
    pwmSetClock(192); // Adjust clock divider to achieve desired frequency

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read noise level from MCP3008
        int noise_level = read_mcp3008(0);
        if (noise_level == -1) {
            fprintf(stderr, "Error: Failed to read noise level. Skipping iteration.\n");
            delay(10); // Small delay to avoid flooding the console with errors
            continue;
        }

        // Check if noise level exceeds threshold
        if (noise_level > VIBRATION_THRESHOLD) {
            // Turn on vibration motors
            set_motor_speed(MOTOR1_PIN, 100);
            set_motor_speed(MOTOR2_PIN, 100);

            // Log vibration event
            log_vibration_event(noise_level);
        } else {
            // Turn off vibration motors
            set_motor_speed(MOTOR1_PIN, 0);
            set_motor_speed(MOTOR2_PIN, 0);
        }

        // Delay for 10 ms
        delay(10);
    }

    return 0;
}

