#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_BUS 1
#define LOG_INTERVAL_SEC 5
#define MAX_RETRIES 3

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float read_bh1750();
void log_data(FILE *fp, float sound_level_db, float light_level_lux, int error_code);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to read from BH1750 sensor
float read_bh1750() {
    char config_mode = BH1750_CONTINUOUS_HIGH_RES_MODE;
    int result = i2cWriteByteData(i2c_handle, 0x00, config_mode);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed: %d\n", result);
        return -1.0;
    }

    gpioDelay(180); // Wait for measurement (at least 180ms)

    int raw_value = i2cReadWordData(i2c_handle, 0x00);
    if (raw_value < 0) {
        fprintf(stderr, "Error: I2C read failed: %d\n", raw_value);
        return -1.0;
    }

    // Convert raw value to lux
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Function to log data to CSV file
void log_data(FILE *fp, float sound_level_db, float light_level_lux, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, sound_level_db, light_level_lux, error_code);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen("tamper_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open tamper_log.csv\n");
        spiClose(spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Sound_Level_DB,Light_Level_Lux,Error_Code\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int max_retries = MAX_RETRIES;
        int adc_value = -1;
        float sound_level_db = -1.0;
        float light_level_lux = -1.0;
        int error_code = 0;

        // Read MCP3008 with retries
        while (max_retries > 0) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                sound_level_db = (float)adc_value * 0.1; // Example conversion
                break; // Success, exit retry loop
            } else {
                max_retries--;
                gpioDelay(10); // Small delay before retry
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read MCP3008 after multiple retries\n");
            error_code = 1; // I2C error
        } else {
            // Read BH1750 with retries
            max_retries = MAX_RETRIES;
            light_level_lux = -1.0;
            while (max_retries > 0) {
                light_level_lux = read_bh1750();
                if (light_level_lux >= 0) {
                    break; // Success, exit retry loop
                } else {
                    max_retries--;
                    gpioDelay(10); // Small delay before retry
                }
            }

            if (light_level_lux < 0) {
                fprintf(stderr, "Error: Failed to read BH1750 after multiple retries\n");
                error_code = 2; // I2C error
            } else {
                // Log the data
                log_data(log_file, sound_level_db, light_level_lux, error_code);
                error_code = 0; // No error
            }
        }

        gpioDelay(LOG_INTERVAL_SEC * 1000); // Wait for the next interval
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

