void cleanup() {
    printf("Cleaning up...\n");
    // Turn fan OFF
    gpioWrite(FAN_GPIO, 0);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

