                break;
            }
            continue; // Skip to the next iteration
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Warning: Invalid ADC value: %d\n", adc_value);
            fprintf(log_file, "Warning: Invalid ADC value: %d\n", adc_value);
            fflush(log_file);
        } else {
            // Convert ADC value to voltage
            float voltage = adc_to_voltage(adc_value);

            // Convert voltage to CO2 concentration
            float co2_ppm = voltage_to_co2(voltage);

            // Control the fan
            control_fan(co2_ppm, &fan_state);

            // Log the data
            log_data(adc_value, co2_ppm, fan_state);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

