#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_BUS 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define RELAY_GPIO 17
#define DISTANCE_THRESHOLD 20 // cm
#define DEBOUNCE_DELAY 1000 // ms
#define LOG_FILE "door_events.log"

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_distance(int adc_value);
void control_relay(int state);
void log_event(const char *event);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transaction failed");
