    int valid_count = 0;
    if (a >= 0 && a <= 1023) {
        valid_count++;
    }
    if (b >= 0 && b <= 1023) {
        valid_count++;
    }
    if (c >= 0 && c <= 1023) {
        valid_count++;
    }

