        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Irrigation System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor values
        int a = read_mcp3008(MCP3008_CHANNEL);
        int b = read_mcp3008(MCP3008_CHANNEL);
        int c = read_mcp3008(MCP3008_CHANNEL);

        // Calculate average
        float average = calculate_average(a, b, c);

        // Set valve position
