#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PWM_FREQUENCY 440 // Base frequency (A4)
#define PWM_RANGE 1000
#define CONFIG_FILE "theremin_config.txt"
#define DEFAULT_CONFIG_FILE "theremin_config.txt"

// Global variables
static volatile int running = 1;
static volatile int last_distance = -1;
static volatile int last_volume = -1;
static int spi_handle;
static FILE *log_file;

// Calibration parameters
static float distance_min = 0.0;
static float distance_max = 10.0;
static float volume_min = 0.0;
static float volume_max = 100.0;

// Function prototypes
int read_ultrasonic_sensor();
int read_photoresistor();
int map_distance_to_frequency(int distance);
int map_volume_to_duty_cycle(int volume);
void generate_tone(int frequency, int duty_cycle);
void log_data(int distance, int volume, int frequency, int duty_cycle);
void load_configuration();
void save_configuration();
void signal_handler(int signal);

// Function to read the ultrasonic sensor
int read_ultrasonic_sensor() {
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);

    int start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start > 50000) return -1; // Timeout
    }
    int echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - echo_start > 50000) return -1; // Timeout
    }
    int echo_end = gpioTick();

    int pulse_width = echo_end - echo_start;
    if (pulse_width < 0) pulse_width += 0xFFFFFFFF; // Handle tick rollover

    return pulse_width;
}

// Function to read the photoresistor via MCP3008
int read_photoresistor() {
    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = 0x80; // Single-ended mode, channel 0
    spi_data[2] = 0x00;

    char rx_buffer[3];

    if (spiXfer(spi_handle, spi_data, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map distance to frequency
int map_distance_to_frequency(int distance) {
    if (distance < 0) return 0; // Handle invalid distance
    if (distance < distance_min) distance = distance_min;
    if (distance > distance_max) distance = distance_max;

    // Linear mapping
    float normalized_distance = (float)(distance - distance_min) / (distance_max - distance_min);
    int frequency = (int)(PWM_FREQUENCY * normalized_distance);

    // Clamp frequency to reasonable range
    if (frequency < 20) frequency = 20;
    if (frequency > 2000) frequency = 2000;

    return frequency;
}

// Function to map volume to duty cycle
int map_volume_to_duty_cycle(int volume) {
    if (volume < 0) return 0;
    if (volume > volume_max) volume = volume_max;

    // Linear mapping
    float normalized_volume = (float)(volume - volume_min) / (volume_max - volume_min);
    int duty_cycle = (int)(normalized_volume * PWM_RANGE);

    return duty_cycle;
}

// Function to generate the tone
void generate_tone(int frequency, int duty_cycle) {
    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioPWM(PWM_PIN, duty_cycle);
}

// Function to log data
void log_data(int distance, int volume, int frequency, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Distance: %d, Volume: %d, Frequency: %d, Duty Cycle: %d\n", timestamp, distance, volume, frequency, duty_cycle);
    fflush(log_file);
}

// Function to load configuration from file
void load_configuration() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open config file %s, using defaults. Creating %s as a new file.\n", CONFIG_FILE, CONFIG_FILE);
        log_file = fopen(CONFIG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Could not create config file %s\n", CONFIG_FILE);
            exit(EXIT_FAILURE);
        }
        save_configuration();
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse the line
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "distance_min") == 0) {
                distance_min = atof(value);
            } else if (strcmp(key, "distance_max") == 0) {
                distance_max = atof(value);
            } else if (strcmp(key, "volume_min") == 0) {
                volume_min = atof(value);
            } else if (strcmp(key, "volume_max") == 0) {
                volume_max = atof(value);
            }
        }
    }

    fclose(fp);
}

// Function to save configuration to file
void save_configuration() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not create config file %s\n", CONFIG_FILE);
        return;
    }

    fprintf(fp, "distance_min=%f\n", distance_min);
    fprintf(fp, "distance_max=%f\n", distance_max);
    fprintf(fp, "volume_min=%f\n", volume_min);
    fprintf(fp, "volume_max=%f\n", volume_max);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Load configuration
    load_configuration();

    // Open log file
    log_file = fopen(CONFIG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor data
        int distance = read_ultrasonic_sensor();
        int volume = read_photoresistor();

        if (distance == -1 || volume == -1) {
            // Handle sensor read error
            last_distance = distance; // Update last known value
            last_volume = volume;
            gpioDelay(100); // Small delay to avoid spamming the log
            continue;
        }

        // Map sensor data to audio parameters
        int frequency = map_distance_to_frequency(distance);
        int duty_cycle = map_volume_to_duty_cycle(volume);

        // Generate tone
        generate_tone(frequency, duty_cycle);

        // Log data
        log_data(distance, volume, frequency, duty_cycle);

        // Delay
        gpioDelay(10);
    }

    // Clean up
    spiClose(spi_handle);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();
    fclose(log_file);

    printf("Theremin-like instrument stopped.\n");

    return 0;
}

