#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define NUM_RETRIES 3
#define RETRY_DELAY 1 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_aqi(int adc_value);
void control_fan(int aqi);
void log_data(float aqi);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    for (int i = 0; i < NUM_RETRIES; ++i) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 3) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
        }
    }

    fprintf(stderr, "SPI read failed after multiple retries.\n");
    return -1; // Indicate failure
}

