    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read moisture sensor
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            fprintf(stderr, "Failed to read moisture sensor\n");
        } else {
            // Control pump based on threshold
            int pump_state = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
            control_pump(pump_state);

            // Log data
            log_data(moisture, pump_state);
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Soil Moisture Monitoring System stopped.\n");

    return 0;
}

