        // Set motor speeds
        set_motor_speed(motor1_speed, motor2_speed);

        // Accelerate motors
        accelerate(motor1_speed, motor2_speed);

        // Constant speed phase
        gpioDelay(CONSTANT_SPEED_TIME * 1000); // Convert seconds to milliseconds

