        decelerate(motor1_speed, motor2_speed);

        // Reverse motor direction
        reverse_motor_direction(1, 0); // Motor 1 forward, Motor 2 backward
        gpioDelay(DIRECTION_CHANGE_DELAY * 1000); // Delay between direction changes
        reverse_motor_direction(0, 1); // Motor 1 backward, Motor 2 forward
