#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins
#define SPI_CE 0  // Chip Enable (CS) - WiringPi pin 0 (GPIO8)
#define SPI_MOSI 10 // Master Out Slave In (MOSI) - WiringPi pin 10 (GPIO10)
#define SPI_MISO 9  // Master In Slave Out (MISO) - WiringPi pin 9 (GPIO9)
#define SPI_SCLK 11 // Serial Clock (SCLK) - WiringPi pin 11 (GPIO11)
#define LED_PIN 17  // LED pin - WiringPi pin 17 (BCM)

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
volatile sig_atomic_t program_running = 1;
int baseline = 0;

// Function prototypes
int read_mcp3008(int channel);
void calibrate_baseline();
void control_led(int sound_level);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    // Build SPI message
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    // Transfer data
    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    // Extract ADC value
    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to calibrate the ambient noise level
void calibrate_baseline() {
    int sum = 0;
    int num_samples = 100; // Number of samples to average

    printf("Calibrating baseline for 5 seconds...\n");
    for (int i = 0; i < num_samples; i++) {
        sum += read_mcp3008(0);
        delay(10); // Small delay between samples
    }
    baseline = sum / num_samples;
    printf("Baseline: %d\n", baseline);
}

// Function to control the LED based on sound level
void control_led(int sound_level) {
    if (sound_level > baseline) {
        digitalWrite(LED_PIN, HIGH); // Turn LED on
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    digitalWrite(LED_PIN, LOW); // Turn LED off
    wiringPiSPIClose(SPI_CHANNEL); // Close SPI
    exit(0);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi initialization failed!\n");
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI initialization failed!\n");
        return 1;
    }

    // Configure LED pin as output
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Initially turn the LED off

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Calibrate the baseline
    calibrate_baseline();

    printf("Monitoring sound levels...\n");

    // Main loop
    while (program_running) {
        int sound_level = read_mcp3008(0);
        control_led(sound_level);
        delay(10); // Small delay to avoid excessive CPU usage
    }

    return 0;
}

