#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define AIRFLOW_LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define VREF 3.3 // Reference voltage for MCP3008

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure for calibration data
typedef struct {
    float slope;
    float intercept;
} calibration_data_t;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int read_adc(int spi_fd, int channel);
float voltage_to_airflow(float voltage, calibration_data_t calibration);
char* get_timestamp();
int log_data(const char *timestamp, float airflow);
void signal_handler(int signal);
int cleanup();

// SPI Initialization
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd;
    uint8_t mode_flags = SPI_MODE | SPI_BITS_PER_WORD | SPI_SPEED;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode) == -1) {
        perror("Error getting SPI mode");
        close(fd);
        return -1;
    }

    return fd;
}

// ADC Reading
int read_adc(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Airflow Calculation
float voltage_to_airflow(float voltage, calibration_data_t calibration) {
    // Assuming a linear relationship: airflow = slope * voltage + intercept
    return calibration.slope * voltage + calibration.intercept;
}

// Timestamp Generation
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Data Logging
int log_data(const char *timestamp, float airflow) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        terminate = 1;
    }
}

// Cleanup
int cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

int main() {
    calibration_data_t calibration = {0.01, 0.0}; // Example calibration values
    int adc_value;
    float voltage;
    float airflow;
    char *timestamp;

    // Signal handling
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(AIRFLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_adc(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            timestamp = get_timestamp();
            fprintf(log_file, "%s,ERROR: ADC read failed\n", timestamp);
            fflush(log_file);
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        voltage = (float)adc_value * VREF / 1024.0;

        // Convert voltage to airflow
        airflow = voltage_to_airflow(voltage, calibration);

        // Get timestamp
        timestamp = get_timestamp();

        // Log data
        if (log_data(timestamp, airflow) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

