#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/mman.h>
#include <signal.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/time.h>

// Define GPIO pins
#define CE0 8
#define MOSI 10
#define MISO 9
#define SCLK 11

// Define SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// Define ADC channel
#define ADC_CHANNEL 0

// Define sampling rate
#define SAMPLING_RATE 1000 // Hz

// Define log file
#define LOG_FILE "audio_log.txt"

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static int gpio_request_result = -1;
static uint32_t *gpio_map = NULL;

// Function prototypes
int spi_init(int spi_fd);
int gpio_request(int gpio);
int gpio_set_direction(int gpio, const char *direction);
int spi_transfer(int spi_fd, uint8_t channel);
uint32_t get_timestamp_ns();
void log_data(uint32_t timestamp_ns, uint32_t raw_adc_value);
void signal_handler(int sig);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int gpio;
    char direction[4]; // "in" or "out"
} gpio_config_t;

// Function to initialize GPIO
int gpio_init() {
    gpio_config_t configs[] = {
        {CE0, "out"},
        {MOSI, "out"},
        {MISO, "in"},
        {SCLK, "out"}
    };
    int i;

    for (i = 0; i < sizeof(configs) / sizeof(configs[0]); i++) {
        gpio_request_result = gpio_request(configs[i].gpio, GPIO_REQUEST_DIRECTION_OUTPUT);
        if (gpio_request_result < 0) {
            fprintf(stderr, "Error requesting GPIO %d: %s\n", configs[i].gpio, strerror(errno));
            return -1;
        }
        if (gpio_set_direction(configs[i].gpio, configs[i].direction) < 0) {
            fprintf(stderr, "Error setting direction for GPIO %d: %s\n", configs[i].gpio, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to initialize SPI
int spi_init(int spi_fd) {
    uint8_t mode = 0; // SPI mode 0
    uint8_t bits = 8; // 8 bits per word
    uint32_t speed = 1000000; // 1 MHz

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        return -1;
    }

    return 0;
}

// Function to transfer data via SPI
int spi_transfer(int spi_fd, uint8_t channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2]; // Extract 10-bit value
}

// Function to get timestamp in nanoseconds
uint32_t get_timestamp_ns() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    return (uint32_t)(ts.tv_sec * 1000000000UL + ts.tv_nsec);
}

// Function to log data to file
void log_data(uint32_t timestamp_ns, uint32_t raw_adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%lu|%u\n", timestamp_ns, raw_adc_value);
    fflush(fp);

    // In a distributed system, this data could be sent to a central server
    // using a network protocol like UDP or TCP.
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    keep_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (gpio_map != NULL) {
        munmap((void *)gpio_map, sizeof(uint32_t) * 32);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_request_result != -1) {
        gpio_unrequest(gpio_request_result);
    }
    if (gpio_map != NULL) {
        munmap((void *)gpio_map, sizeof(uint32_t) * 32);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (spi_init(spi_fd) < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Map GPIO memory
    gpio_map = (uint32_t *)mmap(NULL, 0x100, PROT_READ | PROT_WRITE, MAP_SHARED, gpio_fd, 0);
    if (gpio_map == MAP_FAILED) {
        perror("mmap error");
        cleanup();
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read ADC value
        uint32_t raw_adc_value = spi_transfer(spi_fd, ADC_CHANNEL);

        // Get timestamp
        uint32_t timestamp_ns = get_timestamp_ns();

        // Log data
        log_data(timestamp_ns, raw_adc_value);

        // Sleep for 1 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 1000000; // 1 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

