    if (gpio_map == MAP_FAILED) {
        perror("mmap error");
        cleanup();
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read ADC value
        uint32_t raw_adc_value = spi_transfer(spi_fd, ADC_CHANNEL);

        // Get timestamp
        uint32_t timestamp_ns = get_timestamp_ns();

        // Log data
        log_data(timestamp_ns, raw_adc_value);

        // Sleep for 1 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 1000000; // 1 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

