#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI pins
#define SPI_CE 8 // Chip Enable (GPIO8, BCM)
#define SPI_MOSI 10 // Master Out Slave In (GPIO10, BCM)
#define SPI_MISO 9 // Master In Slave Out (GPIO9, BCM)
#define SPI_SCLK 11 // Serial Clock (GPIO11, BCM)

// Define ADXL335 sensitivity (300mV/g)
#define ADXL335_SENSITIVITY 0.300

// Define ADXL335 zero-g output voltage (1.65V)
#define ADXL335_ZERO_G 1.650

// Define MCP3008 reference voltage (3.3V)
#define MCP3008_REF_VOLTAGE 3.300

// Define Kalman filter parameters
#define Q 0.01 // Process noise covariance
#define R 0.1  // Measurement noise covariance

// Global variables for SPI handle and Kalman filter
int spi_handle;
float kalman_x = 0.0, kalman_y = 0.0, kalman_z = 0.0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_g(int adc_value);
void kalman_filter(float measurement, float *state, float *covariance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    if (spiXfer(spi_handle, spi_data, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to g-force
float adc_to_g(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * MCP3008_REF_VOLTAGE;
    float g = (voltage - ADXL335_ZERO_G) / ADXL335_SENSITIVITY;
    return g;
}

// Kalman filter function
void kalman_filter(float measurement, float *state, float *covariance) {
    // Prediction step
    float predicted_state = *state;
    float predicted_covariance = *covariance;

    // Update step
    float kalman_gain = predicted_covariance / (predicted_covariance + R);
    float innovation = measurement - predicted_state;
    float updated_state = predicted_state + kalman_gain * innovation;
    float updated_covariance = (1 - kalman_gain) * predicted_covariance + Q;

    // Store updated state and covariance
    *state = updated_state;
    *covariance = updated_covariance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC values from MCP3008
        int adc_x = read_mcp3008(0);
        int adc_y = read_mcp3008(1);
        int adc_z = read_mcp3008(2);

        if (adc_x == -1 || adc_y == -1 || adc_z == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to g-force
        float g_x = adc_to_g(adc_x);
        float g_y = adc_to_g(adc_y);
        float g_z = adc_to_g(adc_z);

        // Apply Kalman filter
        kalman_filter(g_x, &kalman_x, &kalman_x);
        kalman_filter(g_y, &kalman_y, &kalman_y);
        kalman_filter(g_z, &kalman_z, &kalman_z);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", kalman_x, kalman_y, kalman_z);

        // Delay to achieve 10 Hz sampling rate
        gpioDelay(100000); // 100 ms delay (10 Hz)
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

