#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to read the digital state of a Hall-Effect sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to convert the digital state to a magnetic field strength in millitesla
float convert_to_mT(int sensor_state) {
    if (sensor_state == 1) {
        return 100.0; // 100 mT
    } else if (sensor_state == 0) {
        return 0.0;  // 0 mT
    } else {
        fprintf(stderr, "Invalid sensor state: %d\n", sensor_state);
        return -1.0; // Indicate an error
    }
}

// Function to log the magnetic field strengths to a file
int log_magnetic_field(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1; // Indicate an error
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file: %s\n", LOG_FILE);
        fclose(fp);
        return -1; // Indicate an error
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", LOG_FILE);
        return -1; // Indicate an error
    }

    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);
        int sensor3_state = read_sensor(SENSOR3_GPIO);

        // Convert sensor states to magnetic field strengths
        float sensor1_mT = convert_to_mT(sensor1_state);
        float sensor2_mT = convert_to_mT(sensor2_state);
        float sensor3_mT = convert_to_mT(sensor3_state);

        // Log the magnetic field strengths
        if (log_magnetic_field(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
            fprintf(stderr, "Error logging magnetic field data\n");
        }

        // Check for out-of-range values and print warnings
        if (sensor1_mT < -100.0 || sensor1_mT > 100.0) {
            fprintf(stderr, "Warning: Sensor 1 magnetic field strength out of range: %.2f mT\n", sensor1_mT);
        }
        if (sensor2_mT < -100.0 || sensor2_mT > 100.0) {
            fprintf(stderr, "Warning: Sensor 2 magnetic field strength out of range: %.2f mT\n", sensor2_mT);
        }
        if (sensor3_mT < -100.0 || sensor3_mT > 100.0) {
            fprintf(stderr, "Warning: Sensor 3 magnetic field strength out of range: %.2f mT\n", sensor3_mT);
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

