#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        log_event("Error: SPI transfer failed.");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the pump relay
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[50];
    sprintf(message, "Pump turned %s", state ? "ON" : "OFF");
    log_event(message);
}

// Function to log events to file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Signal received, shutting down...");
    program_running = 0;
    control_pump(0); // Turn off the pump
    cleanup();       // Cleanup resources
    exit(0);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        log_event("Error: SPI open failed.");
        gpioTerminate();
        return 1; // Indicate failure
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1; // Indicate failure
    }

    log_event("Program started.");

    return 0; // Indicate success
}

// Cleanup function
void cleanup() {
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1; // Exit if initialization fails
    }

    int pump_state = 0; // 0 = OFF, 1 = ON
    int moisture_level;

    while (program_running) {
        moisture_level = read_mcp3008(0); // Read from channel 0

        if (moisture_level < 0) {
            log_event("Error: Failed to read moisture level.");
        } else {
            char message[50];
            sprintf(message, "Moisture level: %d", moisture_level);
            log_event(message);

            if (moisture_level < MOISTURE_THRESHOLD && pump_state == 0) {
                control_pump(1); // Turn pump ON
                pump_state = 1;
                log_event("Pump turned ON.");
            } else if (moisture_level >= MOISTURE_THRESHOLD && pump_state == 1) {
                control_pump(0); // Turn pump OFF
                pump_state = 0;
                log_event("Pump turned OFF.");
            }
        }

        time_sleep(60.0); // Wait 60 seconds
    }

    return 0;
}

