#include <errno.h>

// Constants
#define SPI_BUS 0
#define SPI_CE 0
#define SPI_MODE 0
#define SPI_SPEED 1000000 // 1 MHz
#define CSV_FILE "sensor_data.csv"

// Global variables
static int spi_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int read_mcp3008(int channel);
int log_data(int channel0_value, int channel1_value, int channel2_value);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from MCP3008 channel
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 1)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
int log_data(int channel0_value, int channel1_value, int channel2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (csv_file == NULL) {
        csv_file = fopen(CSV_FILE, "a");
        if (csv_file == NULL) {
            perror("Error opening CSV file");
            return -1;
        }
        // Write header if the file is newly created
        fseek(csv_file, 0, SEEK_END);
        long fsize = ftell(csv_file);
        if (fsize == 0) {
            fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2\n");
        }
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, channel0_value, channel1_value, channel2_value);
    fflush(csv_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init("/dev/spidev0.0");
    if (spi_fd < 0) {
        return 1;
    }

    printf("SPI initialized successfully.\n");

    // Main loop
    while (!terminate) {
        int channel0_value = read_mcp3008(0);
        int channel1_value = read_mcp3008(1);
        int channel2_value = read_mcp3008(2);

        if (channel0_value >= 0 && channel1_value >= 0 && channel2_value >= 0) {
            if (log_data(channel0_value, channel1_value, channel2_value) == 0) {
                printf("Data logged successfully.\n");
            } else {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading ADC values.\n");
        }

        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }

    printf("Exiting.\n");
    return 0;
}

