#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60 // seconds

// Global variables for MQTT client and GPIO
struct mosquitto *mqtt_client = NULL;
int gpio_initialized = 0;

// Function prototypes
int connect_mqtt(const char *broker_address, int port, const char *client_id, int *mqtt_client_ptr);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void parse_json_payload(const char *payload, int *led_state);
void control_led(int led_state);
void signal_handler(int signum);
void cleanup();

// Exponential backoff function
int calculate_reconnect_delay(int attempt) {
    int delay = (1 << attempt) * 1000; // Base delay of 1 second, doubling each attempt
    if (delay > MAX_RECONNECT_DELAY) {
        delay = MAX_RECONNECT_DELAY;
    }
    return delay;
}

int main() {
    int rc = 0;
    int led_state = 0; // Initialize to off
    int reconnect_attempt = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpio_initialized = 1;

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize MQTT client
    if ((mqtt_client = connect_mqtt(MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, &mqtt_client)) == NULL) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up MQTT callbacks
    mosquitto_connect_callback_set(mqtt_client, on_connect);
    mosquitto_disconnect_callback_set(mqtt_client, on_disconnect);
    mosquitto_message_callback_set(mqtt_client, on_message);

    // Start the MQTT client loop
    mosquitto_loop_start(mqtt_client);

