#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the sound sensor
int read_sound_sensor() {
    int sound_level = gpioRead(SOUND_SENSOR_PIN);
    if (sound_level < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", SOUND_SENSOR_PIN);
        return -1; // Indicate an error
    }
    return sound_level;
}

// Function to control the alarm LED
void control_alarm_led(int state) {
    if (gpioWrite(ALARM_LED_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", ALARM_LED_PIN);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();
        if (sound_level < 0) {
            // Error reading sensor, exit loop
            break;
        }

        if (sound_level == 0) {
            printf("Sound detected! Activating alarm.\n");
            control_alarm_led(1); // Turn LED on
            gpioDelay(1000);       // Wait for 1 second
            control_alarm_led(0); // Turn LED off
            gpioDelay(100);       // Small delay after alarm
        } else {
            printf("No sound detected. Level: %d\n", sound_level);
            gpioDelay(100); // Delay for 100ms
        }
    }

    // Cleanup GPIO
    gpioTerminate();
    printf("GPIO terminated. Exiting.\n");

    return 0;
}

