#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define DEBOUNCE_DELAY_MS 100

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char* message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    char* timestamp = get_timestamp();
    if (timestamp == NULL) {
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, message);
    free(timestamp); // Free the allocated memory
    fclose(fp);
    return 0;
}

// Function to read the vibration sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to handle vibration detection
void handle_vibration() {
    char* timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log.\n");
        return;
    }

    if (log_message(timestamp) != 0) {
        fprintf(stderr, "Failed to log message.\n");
    }

    printf("%s: Vibration detected! Shutting down...\n", timestamp);
    if (system("sudo shutdown -h now") != 0) {
        perror("Failed to execute shutdown command");
    }
    free(timestamp);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up resistor (optional, depends on sensor configuration)
    // gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    printf("Vibration monitor started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor value
        int sensor_value = read_sensor();

        // Check for falling edge (vibration detected)
        if (sensor_value == 0) {
            handle_vibration();
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // Check every 1 ms
    }

    // Clean up GPIO resources
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set back to input
    gpioTerminate();

    printf("Vibration monitor stopped.\n");
    return 0;
}

