void log_data(FILE *fp, int lux, int adc_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Light: %d lux, Sound: %d\n", timestamp, lux, adc_value);
    fflush(fp); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        int lux = read_bh1750(i2c_fd);
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);

        // Check for errors
        if (lux < 0 || adc_value < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds.\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue; // Skip logging and sleeping if there's an error
        }

        // Log data
        log_data(log_file, lux, adc_value);

        // Sleep for specified interval
        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    printf("Environmental monitoring stopped.\n");
    return 0;
}

