#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to log the event to a CSV file
int log_event(int pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, pin, state);
    fclose(fp);
    return 0;
}

// Function to print an alarm message
void print_alarm(int pin, int state) {
    printf("ALARM: Flame detected on pin %d (state %d)\n", pin, state);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 1) {
            log_event(FLAME_SENSOR_PIN, sensor_value);
            print_alarm(FLAME_SENSOR_PIN, sensor_value);
        } else if (sensor_value < 0) {
