#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <wiringPiI2C.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MCP3008_CHANNEL 0
#define MCP4725_ADDR 0x60
#define VREF 3.3 // Reference voltage for ADC
#define LOG_FILE "temperature_log.txt"

// Global variables
static volatile int keepRunning = 1;
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_spi();
int init_i2c();
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
int set_mcp4725_voltage(float voltage);
int log_data(int adc_value, float temperature, float voltage);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int init_spi() {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "SPI initialization failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    int fd = wiringPiI2CSetup(MCP4725_ADDR);
    if (fd < 0) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float adc_to_temperature(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float temperature = (voltage - 0.5) / 0.01;
    return temperature;
}

// Function to set the DAC output voltage
int set_mcp4725_voltage(float voltage) {
    if (voltage < 0.0 || voltage > 3.3) {
        fprintf(stderr, "Invalid voltage: %f\n", voltage);
        return -1;
    }

    int dutyCycle = (int)(voltage * 4095.0 / 3.3); // 12-bit DAC
    if (wiringPiI2CWrite(i2c_fd, dutyCycle) < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(int adc_value, float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    keepRunning = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_fd != -1) {
        // No explicit SPI close function in wiringPi, but we can reset the channel
        wiringPiSPIClose(SPI_CHANNEL);
    }
    if (i2c_fd != -1) {
        // No explicit I2C close function in wiringPi, but we can reset the bus
        // wiringPiI2CClose(i2c_fd); // Not available in wiringPi
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (init_spi() == -1) {
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (keepRunning) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 1 second.\n");
            delay(1000);
            continue;
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Set DAC voltage
        if (set_mcp4725_voltage(temperature) == -1) {
            fprintf(stderr, "Failed to set DAC voltage. Retrying in 1 second.\n");
        }

        // Log data
        if (log_data(adc_value, temperature, (float)adc_value * VREF / 1023.0) == -1) {
            fprintf(stderr, "Failed to log data. Retrying in 1 second.\n");
        }

        // Wait for 0.5 seconds
        delay(500);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

