#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNELS {0, 1, 2}
#define SLEEP_DURATION 60 // seconds
#define DATA_FILE "soil_data.txt"
#define ERROR_LOG_FILE "error_log.txt"

// Global variables
int spi_handle;
FILE *data_file;
FILE *error_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void log_data(int sensor1_value, int sensor2_value, int sensor3_value);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(error_file, "%s: Invalid MCP3008 channel: %d\n", __func__, channel);
        return -1; // Indicate error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(error_file, "%s: SPI transfer failed: %d\n", __func__, result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to log data to file
void log_data(int sensor1_value, int sensor2_value, int sensor3_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(data_file, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value);
    fflush(data_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen(ERROR_LOG_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file!\n");
        gpioTerminate();
        return 1;
    }

    // Open data log file
    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data log file!\n");
        cleanup();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(error_file, "%s: SPI open failed: %d\n", __func__, spi_handle);
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int sensor1_value = read_mcp3008(0);
        int sensor2_value = read_mcp3008(1);
        int sensor3_value = read_mcp3008(2);

        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(error_file, "%s: Error reading sensor values\n", __func__);
        } else {
            log_data(sensor1_value, sensor2_value, sensor3_value);
            printf("Sensor 1: %d, Sensor 2: %d, Sensor 3: %d\n", sensor1_value, sensor2_value, sensor3_value);
        }

        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0); // Sleep for 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

