// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
void activateRelay(int relayPin);
void deactivateRelay(int relayPin);
void signalHandler(int signum);

// Global variable to track program state for signal handling
volatile sig_atomic_t programRunning = 1;

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initially deactivate all relays
    deactivateRelay(RELAY1_PIN);
    deactivateRelay(RELAY2_PIN);
    deactivateRelay(RELAY3_PIN);
    deactivateRelay(RELAY4_PIN);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop to control the relays
