#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_PIN 16 // BCM GPIO 16
#define THRESHOLD 500
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "sound_events.log"

// Global variables
static volatile int keepRunning = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(const char *device, int mode, int speed);
int read_mcp3008(int channel);
void log_event(const char *timestamp);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device, int mode, int speed) {
    int fd;
    uint8_t mode_local = SPI_MODE;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_local) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read MCP3008 ADC channel
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Log event to file
void log_event(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    keepRunning = 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    digitalWrite(LED_PIN, LOW); // Turn off LED
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int adc_value;
    int threshold_exceeded = 0;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed, exiting.\n");
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Initially off

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "SPI initialization failed, exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (keepRunning) {
        // Read ADC value
        adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            delay(100); // Small delay before retrying
            continue;
        }

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Check if threshold is exceeded
        if (adc_value > THRESHOLD) {
            threshold_exceeded = 1;
            printf("Threshold exceeded! ADC value: %d\n", adc_value);

            // Turn on LED
            digitalWrite(LED_PIN, HIGH);
            delay(500); // 500ms

            // Log event
            log_event(timestamp);

            // Debounce delay
            delay(DEBOUNCE_DELAY_MS);

            // Turn off LED
            digitalWrite(LED_PIN, LOW);
        } else {
            threshold_exceeded = 0;
        }

        // Delay for 10ms
        delay(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

