#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RAIN_THRESHOLD 5
#define MOTOR_FORWARD_PIN 17
#define MOTOR_REVERSE_PIN 18
#define MOTOR_ENABLE_PIN 27
#define PWM_RANGE 255
#define LOG_FILE "rain_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int rain_level);
void log_rain_data(int rain_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the rain sensor value from MCP3008
int read_rain_sensor() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // MCP3008 command to read channel 0 (single-ended)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the ADC value from the response
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to control the DC motor
void control_motor(int rain_level) {
    if (rain_level > RAIN_THRESHOLD) {
        printf("Rain level: %d > Threshold %d, closing window...\n", rain_level, RAIN_THRESHOLD);
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_REVERSE_PIN, 1);
        gpioPWM(MOTOR_ENABLE_PIN, PWM_RANGE / 2); // 50% duty cycle
        gpioDelay(3000); // Run for 3 seconds
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_REVERSE_PIN, 0);
        gpioPWM(MOTOR_ENABLE_PIN, 0); // Stop PWM
        printf("Window closed.\n");
    } else {
        printf("Rain level: %d <= Threshold %d, opening window...\n", rain_level, RAIN_THRESHOLD);
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_REVERSE_PIN, 0);
        gpioPWM(MOTOR_ENABLE_PIN, PWM_RANGE / 2); // 50% duty cycle
        gpioDelay(3000); // Run for 3 seconds
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_REVERSE_PIN, 1);
        gpioPWM(MOTOR_ENABLE_PIN, 0); // Stop PWM
        printf("Window opened.\n");
    }
}

// Function to log the rain data to a file
void log_rain_data(int rain_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Rain Level: %d\n", timestamp, rain_level);
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_REVERSE_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(MOTOR_ENABLE_PIN, PWM_RANGE);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int rain_level = read_rain_sensor();
        if (rain_level >= 0) {
            control_motor(rain_level);
            log_rain_data(rain_level);
        } else {
            fprintf(stderr, "Error: Failed to read rain sensor value\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

