int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(MIC_ADC_PIN, PI_INPUT); // Set MIC_ADC_PIN as input
    gpioSetMode(LED_PIN, PI_OUTPUT);   // Set LED_PIN as output

    return 0; // Indicate success
}

// Read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;
    int i;

    // Set MIC_ADC_PIN as output
    gpioSetMode(MIC_ADC_PIN, PI_OUTPUT);

    // Discharge capacitor
    gpioWrite(MIC_ADC_PIN, 0);
    gpioDelay(1); // Small delay

    // Set MIC_ADC_PIN as input
    gpioSetMode(MIC_ADC_PIN, PI_INPUT);

    // Measure charge time
    for (i = 0; i < 100; i++) {
        // Wait for pin to go high
        if (gpioRead(MIC_ADC_PIN) == 1) {
            break;
        }
        gpioDelay(1); // Small delay
    }

    // Calculate ADC value (crude approximation)
    adc_value = i; // Assuming higher charge time means higher voltage

    return adc_value;
}

// Detect clap event
int detect_clap(int *debounce_count) {
    int threshold_exceeded = 0;
    int adc_value = read_adc();

    if (adc_value > CLAP_THRESHOLD) {
        threshold_exceeded = 1;
        *debounce_count++;
    } else {
        *debounce_count = 0; // Reset debounce counter if below threshold
    }

    return threshold_exceeded;
}

// Control LED
