            debounce_count = 0; // Reset debounce counter
        }

        if (debounce_count >= DEBOUNCE_MS && clap_detected) {
            log_clap_event();
            control_led(1); // Turn on LED
            gpioDelay(LED_ON_TIME_MS * 1000); // Wait for 500ms
            control_led(0); // Turn off LED
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

