#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200 // mm
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the distance sensor value
int read_distance_sensor() {
    int distance = gpioRead(GPIO_PIN);
    if (distance < 0) {
        fprintf(stderr, "Error reading GPIO pin %d\n", GPIO_PIN);
        return -1; // Indicate an error
    }
    return distance;
}

// Function to log the distance to a file
void log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %d\n", timestamp, distance);
    fclose(fp);
}

// Function to check the distance and print appropriate message
void check_distance_and_print(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Distance sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int distance = read_distance_sensor();
        if (distance != -1) {
            log_distance(distance);
            check_distance_and_print(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying in 1 second.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue; // Skip the rest of the loop and retry
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

