#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_BUS 0
#define SPI_CE0 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int bus, int ce, int speed);
int read_mcp3008(int spi_fd, int channel);
float adc_to_moisture(int adc_value);
void control_pump(int gpio_pin, int moisture_percentage, float threshold);
void log_data(FILE *log_file, float moisture_percentage, int pump_status);
void signal_handler(int signal);

// SPI Initialization
int spi_init(int bus, int ce, int speed) {
    char spi_device[20];
    sprintf(spi_device, "/dev/spidev%d.%d", bus, ce);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI bits per word
    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI max speed
    int speed = speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read MCP3008 ADC
int read_mcp3008(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to moisture percentage
float adc_to_moisture(int adc_value) {
    // Assuming a linear relationship between ADC value and moisture percentage
    // You may need to calibrate this based on your sensor's characteristics
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Control the water pump
void control_pump(int gpio_pin, int moisture_percentage, float threshold) {
    if (moisture_percentage < threshold) {
        gpioWrite(gpio_pin, 1); // Turn pump ON
        printf("Moisture below threshold. Turning pump ON.\n");
    } else {
        gpioWrite(gpio_pin, 0); // Turn pump OFF
        printf("Moisture above threshold. Turning pump OFF.\n");
    }
}

// Log data to file
void log_data(FILE *log_file, float moisture_percentage, int pump_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %s\n", timestamp, moisture_percentage, pump_status ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init(SPI_BUS, SPI_CE0, SPI_SPEED) < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            fprintf(log_file, "Error reading ADC value\n");
        } else {
            // Convert ADC value to moisture percentage
            float moisture_percentage = adc_to_moisture(adc_value);

            // Control the pump
            control_pump(PUMP_GPIO, (int)moisture_percentage, MOISTURE_THRESHOLD);

            // Log the data
            log_data(log_file, moisture_percentage, gpioRead(PUMP_GPIO));
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
    fclose(log_file);
    close(spi_fd);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

