#define DRV5055_A1_OFFSET 512.0   // mV

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int bus, int device, int speed, uint8_t mode);
int read_mcp3008(int channel);
float adc_to_magnetic_field(int adc_value);
void log_data(time_t timestamp, float magnetic_field);
void signal_handler(int signal);
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int bus;
    int device;
    int speed;
    uint8_t mode;
} spi_config_t;

// Function to initialize the SPI interface
int spi_init(int bus, int device, int speed, uint8_t mode) {
    spi_config_t config = {bus, device, speed, mode};

    int fd = open("/dev/spidev" SPI_BUS "." SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", "/dev/spidev" SPI_BUS "." SPI_DEVICE);
        return -1;
    }

    // Configure SPI mode
    uint8_t mode_config = SPI_MODE(mode);
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_config) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", "/dev/spidev" SPI_BUS "." SPI_DEVICE);
        close(fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed_config = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_config) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", "/dev/spidev" SPI_BUS "." SPI_DEVICE);
        close(fd);
        return -1;
    }

    return fd;
}

