#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_PIN 17
#define VREF 5.0
#define SENSITIVITY 0.1 // 100mV/A
#define MAX_RETRIES 3

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int gpio_init(int pin);
int read_adc(int channel);
float adc_to_amperes(int adc_value);
int log_data(float current_amperes);
void signal_handler(int signal);
void cleanup(void);

// Structure to hold SPI configuration
typedef struct {
    char *device;
    int mode;
    int bits_per_word;
    int speed;
} spi_config_t;

// Function to initialize SPI
int spi_init(void) {
    spi_config_t config = {SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED};

    spi_fd = open(config.device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int gpio_init(int pin) {
    char buffer[3];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to /sys/class/gpio/export");
        close(fd);
        return -1;
    }
    close(fd);

    // Wait for the GPIO to be ready
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", pin);
    int delay_ms = 100;
    while (1) {
        int fd2 = open(buffer, O_RDONLY);
        if (fd2 < 0) {
            perror("Error opening GPIO value file for reading");
            return -1;
        }
        char value;
        if (read(fd2, &value, 1) < 0) {
            perror("Error reading GPIO value");
            close(fd2);
            return -1;
        }
        close(fd2);
        if (value == '1') {
            break;
        }
        usleep(delay_ms * 1000); // Sleep for 100ms
        delay_ms--;
    }

    return 0;
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to amperes
float adc_to_amperes(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float current_amperes = (voltage - 0.5) / SENSITIVITY;
    return current_amperes;
}

// Function to log data to CSV file
int log_data(float current_amperes) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, current_amperes);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    // Reset GPIO pin (optional, but good practice)
    char buffer[3];
    int fd;
    snprintf(buffer, sizeof(buffer), "%d", GPIO_PIN);
    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd >= 0) {
        write(fd, buffer, strlen(buffer));
        close(fd);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert ADC value to amperes
        float current_amperes = adc_to_amperes(adc_value);

        // Log data
        if (log_data(current_amperes) < 0) {
            fprintf(stderr, "Failed to log data. Retrying in 1 second.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

