#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LOG_FILE "current_log.txt"
#define VREF 5.0 // Reference voltage for MCP3008
#define MLX91211_SENSITIVITY 0.1 // Example sensitivity (adjust based on datasheet)
#define MLX91211_OFFSET 0.0      // Example offset (adjust based on datasheet)
#define MAX_CURRENT 10.0 // Maximum expected current in Amperes

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file = NULL;

// Function prototypes
int init_spi();
int read_adc(int channel);
float adc_to_current(int adc_value);
int log_current(float current);
void signal_handler(int signal);
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Initialize SPI
int init_spi() {
    spi_config_t config = {SPI_CHANNEL, SPI_SPEED};
    spi_handle = spiOpen(config.channel, config.speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    int result = spiXfer(spi_handle, spi_data, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to current
float adc_to_current(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float current = (voltage - MLX91211_OFFSET) / MLX91211_SENSITIVITY;
    return current;
}

// Log current value to file
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
    }

    fprintf(log_file, "%s %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read ADC value
        int adc_value = read_adc(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, skipping sample.\n");
            gpioDelay(100); // Wait 100ms
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Validate current value
        if (current < 0.0 || current > MAX_CURRENT) {
            fprintf(stderr, "Warning: Current value out of range: %.2f A\n", current);
        } else {
            // Log current value
            if (log_current(current) != 0) {
                fprintf(stderr, "Error logging current, skipping.\n");
            }
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

