// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

// Debounce parameters
#define DEBOUNCE_READS 5
#define DEBOUNCE_DELAY_MS 2

// Global variable to track program termination for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value with debouncing
int read_sensor(int gpio) {
    int readings[DEBOUNCE_READS];
    int i;

    // Read the sensor multiple times
    for (i = 0; i < DEBOUNCE_READS; i++) {
        readings[i] = gpioRead(gpio);
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }

    // Determine the majority value
    int majority_value = 0;
    for (i = 0; i < DEBOUNCE_READS; i++) {
        if (readings[i] != 0) {
            majority_value = 1;
            break;
        }
    }

    return majority_value;
}

// Function to log the sensor states
void log_sensor_states(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0) {
        printf("Sensor 1: 0\n");
    } else {
        printf("Sensor 1: 1\n");
    }

    if (sensor2_state == 0) {
        printf("Sensor 2: 0\n");
    } else {
        printf("Sensor 2: 1\n");
    }

    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Log the sensor states
        log_sensor_states(sensor1_state, sensor2_state);

        // Wait for 1 second
        sleep(1);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

