#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_COMMAND "libcamera-still -o /home/pi/security_cam/%s.jpg --width 640 --height 480 --nopreview --immediate"
#define LOG_FILE "/var/log/security_cam.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    program_running = 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %d", gpioInitialise());
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

int verify_gpio_initialization() {
    int pin_mode = gpioGetMode(GPIO_PIN);
    if (pin_mode != PI_INPUT) {
        syslog(LOG_ERR, "GPIO %d is not configured as input. Expected PI_INPUT, got %d", GPIO_PIN, pin_mode);
        return -1;
    }
    return 0;
}

int create_capture_directory() {
    struct stat st = {0};
    if (stat("/home/pi/security_cam", &st) == -1) {
        if (mkdir("/home/pi/security_cam", 0777) == -1) {
            syslog(LOG_ERR, "Failed to create /home/pi/security_cam: %s", strerror(errno));
            return -1;
        }
    }
    syslog(LOG_INFO, "/home/pi/security_cam already exists.");
    return 0;
}

char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(64 * sizeof(char)); // Allocate memory for the filename
    if (filename == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for filename.");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, 64, "/home/pi/security_cam/motion_%Y-%m-%dT%H:%M:%S%z.jpg", timeinfo);
    return filename;
}

int capture_image(const char *filename) {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execlp("libcamera-still", "libcamera-still", "-o", filename, "--width", "640", "--height", "480", "--nopreview", "--immediate", (char*)NULL);
        if (execlp == -1) {
            syslog(LOG_ERR, "Failed to execute libcamera-still: %s", strerror(errno));
            return -1;
        }
    } else if (pid < 0) {
        syslog(LOG_ERR, "Failed to fork: %s", strerror(errno));
        return -1;
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            syslog(LOG_ERR, "libcamera-still exited with status %d", WEXITSTATUS(status));
            return -1;
        }
        return 0;
    }
}

int log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
    return 0;
}

int main() {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    if (verify_gpio_initialization() != 0) {
        syslog(LOG_ERR, "GPIO verification failed. Exiting.");
        gpioTerminate();
        closelog();
        return 1;
    }

    if (create_capture_directory() != 0) {
        syslog(LOG_ERR, "Failed to create capture directory. Exiting.");
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Security camera started.");

    while (program_running) {
        int motion_detected = gpioRead(GPIO_PIN);

        if (motion_detected) {
            syslog(LOG_INFO, "Motion detected!");
            char *filename = generate_filename();
            if (filename != NULL) {
                if (capture_image(filename) == 0) {
                    syslog(LOG_INFO, "Image captured successfully: %s", filename);
                } else {
                    syslog(LOG_ERR, "Failed to capture image.");
                }
                free(filename);
            } else {
                syslog(LOG_ERR, "Failed to generate filename.");
            }

            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
            int confirmed_motion = gpioRead(GPIO_PIN);
            if (confirmed_motion == motion_detected) {
                syslog(LOG_INFO, "Motion confirmed.");
            } else {
                syslog(LOG_WARNING, "Motion not confirmed.");
            }
        } else {
            gpioDelay(50 * 1000); // Polling interval
        }
    }

    syslog(LOG_INFO, "Security camera stopped.");

    gpioTerminate();
    closelog();

    return 0;
}

