#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define BUFFER_COUNT 4
#define BUFFER_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 8)
#define TIMEOUT_SEC 2

// Structure to hold camera configuration
typedef struct {
    int width;
    int height;
    int format;
    int fd;
} camera_config_t;

// Global variables
camera_config_t camera_config;
int buffer_fds[BUFFER_COUNT];
int buffer_index = 0;
int running = 1;

// Function prototypes
int init_camera(camera_config_t *config);
int setup_streaming(camera_config_t *config);
int capture_frame(int fd, unsigned char *buffer);
int save_image(unsigned char *buffer, int buffer_index);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Unmap buffers
    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (buffer_fds[i] != -1) {
            if (munmap((void *)buffer_fds[i], BUFFER_SIZE) == -1) {
                perror("munmap failed");
            }
        }
    }

    // Close file descriptors
    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (buffer_fds[i] != -1) {
            close(buffer_fds[i]);
        }
    }

    // Remove temporary directory
    if (remove("tmp_images") == -1 && errno != ENOENT) {
        perror("remove failed");
    }

    printf("Cleanup complete.\n");
}

// Initialize the camera
int init_camera(camera_config_t *config) {
    int fd = open(config->fd, O_RDWR);
    if (fd == -1) {
        perror("Failed to open camera device");
        return -1;
    }

    // Check if the device is busy
    if (ioctl(fd, VIDIOC_QUERYCAP, &camera_info) == -1) {
        perror("VIDIOC_QUERYCAP failed");
        close(fd);
        return -1;
    }

    config->width = camera_info.VBI dimensional;
    config->height = camera_info.VBI lines;
    config->format = 0; // 8-bit grayscale

    return fd;
}

// Setup memory-mapped streaming
int setup_streaming(camera_config_t *config) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(config->fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS failed");
        return -1;
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(config->fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF failed");
            return -1;
        }

        buffer_fds[i] = open("/dev/mem", O_RDWR | O_SYNC);
        if (buffer_fds[i] == -1) {
            perror("Failed to open /dev/mem");
            return -1;
        }

        if (mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, buffer_fds[i], 0) == -1) {
            perror("mmap failed");
            close(buffer_fds[i]);
            buffer_fds[i] = -1;
            return -1;
        }

        if (ioctl(config->fd, VIDIOC_STREAMON, &buf) == -1) {
            perror("VIDIOC_STREAMON failed");
            return -1;
        }
    }

    return 0;
}

// Capture a frame from the camera
int capture_frame(int fd, unsigned char *buffer) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }

    if (read(fd, buffer, BUFFER_SIZE) == -1) {
        perror("Failed to read frame");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF failed");
        return -1;
    }

    return 0;
}

// Save the frame to a PGM file
int save_image(unsigned char *buffer, int buffer_index) {
    char filename[64];
    snprintf(filename, sizeof(filename), "image_%04d.pgm", buffer_index);

    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Failed to open PGM file");
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
    fwrite(buffer, 1, IMAGE_WIDTH * IMAGE_HEIGHT * 8, fp);

    fclose(fp);
    printf("Saved image to %s\n", filename);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        camera_config.fd = strdup(argv[1]);
    } else {
        camera_config.fd = strdup(DEFAULT_DEVICE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_camera(&camera_config) == -1) {
        return 1;
    }

    if (setup_streaming(&camera_config) == -1) {
        cleanup();
        return 1;
    }

    printf("Streaming started. Press Ctrl+C to stop.\n");

    while (running) {
        fd_set readfds;
        struct timeval timeout;

        FD_ZERO(&readfds);
        FD_SET(camera_config.fd, &readfds);

        timeout.tv_sec = TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int retval = select(camera_config.fd + 1, &readfds, NULL, NULL, &timeout);

        if (retval == -1) {
            perror("select");
            break;
        } else if (retval == 0) {
            // Timeout occurred
            printf("Timeout occurred, no frames available.\n");
        } else {
            unsigned char *frame_buffer = (unsigned char *)buffer_fds[buffer_index];
            if (capture_frame(camera_config.fd, frame_buffer) == -1) {
                break;
            }

            if (save_image(frame_buffer, buffer_index) == -1) {
                break;
            }

            buffer_index = (buffer_index + 1) % BUFFER_COUNT;
        }
    }

    cleanup();
    return 0;
}

