// Structure to hold video device information
typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
    int width;
    int height;
} video_device_t;

// Global variable to signal program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to initialize the video device
int initialize_device(video_device_t *device) {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return -1;
    }

    device->fd = fd;
    device->width = 640; // Default width
    device->height = 480; // Default height
    device->buffer_size = 0; // Initialize buffer size
    device->buffer = NULL;

    // Negotiate frame width and height
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Requested width
    fmt.fmt.pix.height = 480; // Requested height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // Request MJPEG format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    device->width = fmt.fmt.pix.width;
    device->height = fmt.fmt.pix.height;

    // Allocate memory for the buffer
    device->buffer = malloc(device->width * device->height * 2); // MJPEG is YUYV
    if (device->buffer == NULL) {
        perror("Error allocating buffer");
        close(fd);
        return -1;
    }
    device->buffer_size = device->width * device->height * 2;

    return 0;
}

// Function to uninitialize the video device
void uninitialize_device(video_device_t *device) {
    if (device->buffer) {
        free(device->buffer);
    }
    if (device->fd > 0) {
        close(device->fd);
    }
}

// Function to map the video buffer
int map_buffer(video_device_t *device) {
    void *map_buffer = mmap(NULL, device->buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, device->fd, 0);
    if (map_buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        return -1;
    }
    device->buffer = map_buffer; // Update the buffer pointer
    return 0;
}

// Function to unmap the video buffer
void unmap_buffer(video_device_t *device) {
    if (device->buffer) {
        if (munmap(device->buffer, device->buffer_size) < 0) {
            perror("Error unmapping buffer");
        }
        device->buffer = NULL;
    }
}

// Function to capture a single frame
int capture_frame(video_device_t *device, unsigned char **frame_data, size_t *frame_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(device->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *frame_data = device->buffer;
    *frame_size = device->buffer_size;

    if (ioctl(device->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

