#define MAX_BUFFER_COUNT 4
#define MAX_FRAME_SIZE 1048576 // 1MB
#define MAX_FRAGMENT_SIZE 65535 // 65KB
#define MAX_PACKET_SIZE 65535   // 65KB

#define NUM_BUFFERS 4
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480

#define TARGET_IP "192.168.1.100"
#define TARGET_PORT 5000

#define DEVICE_NAME "/dev/video0"
#define DEVICE_PATH "/dev/video0"
#define DEVICE_ID_PATH "/sys/class/video4linux2/devices/video0/device/id"

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Structure to hold camera configuration
typedef struct {
    int   fd;
    buffer_t buffers[NUM_BUFFERS];
    int   n_buffers;
    int   width;
    int   height;
    int   format;
    int   index;
} camera_config_t;

// Global variables
static camera_config_t camera_config;
static int running = 1;
static int sockfd = -1;

// Function prototypes
int init_camera(camera_config_t *config);
int capture_frame(camera_config_t *config, unsigned char *buffer);
int fragment_frame(camera_config_t *config, unsigned char *fragment, unsigned char *packet, size_t *packet_size);
int send_packet(camera_config_t *config, unsigned char *packet, size_t packet_size);
void signal_handler(int sig);
void cleanup(camera_config_t *config);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", sig);
        running = 0;
    }
}

// Cleanup function
void cleanup(camera_config_t *config) {
    printf("Cleaning up...\n");

    // Unmap buffers
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (config->buffers[i].start != NULL) {
            if (munmap(config->buffers[i].start, config->buffers[i].length) == -1) {
                perror("munmap failed");
            }
        }
    }

    // Close device
    if (config->fd != -1) {
        close(config->fd);
    }

    // Close socket
    if (sockfd != -1) {
        close(sockfd);
    }

    printf("Cleanup complete.\n");
}

// Initialize camera
int init_camera(camera_config_t *config) {
    int fd = open(DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open device");
        return -1;
    }

    // Get camera ID
    char id[256];
    int len = snprintf(id, sizeof(id), "%s", DEVICE_ID_PATH);
    if (len < 0 || len >= sizeof(id)) {
        fprintf(stderr, "Error: Could not read camera ID\n");
        close(fd);
        return -1;
    }

    // Check if the device is a V4L2 device
    if (strncmp(id, "video4linux2", 14) != 0) {
        fprintf(stderr, "Error: %s is not a V4L2 device\n", DEVICE_PATH);
        close(fd);
        return -1;
    }

    // Enumerate devices
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_PATH);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_PATH);
        close(fd);
        return -1;
    }

    // Set format
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return -1;
    }

    // Map buffers
    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_requestbuffers req;
        memset(&req, 0, sizeof(req));
        req.count = 1; // Single buffer for simplicity
        req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
            perror("VIDIOC_REQBUFS");
            close(fd);
            return -1;
        }

        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            return -1;
        }

        config->buffers[i].length = buf.length;
        config->buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (config->buffers[i].start == MAP_FAILED) {
            perror("mmap");
            close(fd);
            return -1;
        }
    }

    config->n_buffers = NUM_BUFFERS;
    config->fd = fd;
    config->width = FRAME_WIDTH;
    config->height = FRAME_HEIGHT;
    config->format = V4L2_PIX_FMT_YUYV;
    config->index = 0;

    return 0;
}

// Capture a frame
int capture_frame(camera_config_t *config, unsigned char *buffer) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(config->fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (ioctl(config->fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    memcpy(buffer, config->buffers[config->index].start, buf.bytesused);
    config->index = (config->index + 1) % NUM_BUFFERS;

    return 0;
}

// Fragment a frame into UDP packets
int fragment_frame(camera_config_t *config, unsigned char *fragment, unsigned char *packet, size_t *packet_size) {
    size_t fragment_size = (config->width * config->height * 2 / 3); // YUYV: 2 bytes per pixel
    size_t packet_size = fragment_size + 8; // Header + fragment size

    if (fragment_size > MAX_FRAGMENT_SIZE) {
        fprintf(stderr, "Error: Fragment size exceeds maximum allowed size (%zu > %zu)\n", fragment_size, MAX_FRAGMENT_SIZE);
        return -1;
    }

    if (packet_size > MAX_PACKET_SIZE) {
        fprintf(stderr, "Error: Packet size exceeds maximum allowed size (%zu > %zu)\n", packet_size, MAX_PACKET_SIZE);
        return -1;
    }

    // Allocate packet buffer
    packet = (unsigned char *)malloc(packet_size);
    if (packet == NULL) {
        perror("malloc");
        return -1;
    }

    // Create header
    memcpy(packet, (unsigned char[]){0x01, 0x02, 0x03, 0x04}, 4); // Frame index, fragment index, total fragments, payload size
    memcpy(packet + 4, &fragment_size, 4); // Fragment size

    // Copy fragment data
    memcpy(packet + 8, fragment, fragment_size);

    *packet_size = packet_size;

    return 0;
}

// Send a packet via UDP
int send_packet(camera_config_t *config, unsigned char *packet, size_t packet_size) {
    struct sockaddr_in target_addr;
    memset(&target_addr, 0, sizeof(target_addr));
    target_addr.sin_family = AF_INET;
    target_addr.sin_port = htons(TARGET_PORT);
    if (inet_pton(AF_INET, TARGET_IP, &target_addr.sin_addr) <= 0) {
        perror("inet_pton");
        return -1;
    }

    if (sendto(sockfd, packet, packet_size, 0, (struct sockaddr *)&target_addr, sizeof(target_addr)) < 0) {
        perror("sendto");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <libv4l2_api_call>\n", argv[0]);
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize camera
    if (init_camera(&camera_config) != 0) {
        fprintf(stderr, "Camera initialization failed.\n");
        return 1;
    }

    // Create socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("socket");
        cleanup(&camera_config);
        return 1;
    }

    // Main loop
    while (running) {
        unsigned char *frame_buffer = NULL;
        unsigned char *fragment = NULL;
        unsigned char *packet = NULL;
        size_t packet_size = 0;

        // Capture frame
        if (capture_frame(&camera_config, &frame_buffer) != 0) {
            fprintf(stderr, "Frame capture failed.\n");
            continue; // Continue to next iteration
        }

        // Fragment frame
        if (fragment_frame(&camera_config, frame_buffer, &fragment, &packet_size) != 0) {
            fprintf(stderr, "Frame fragmentation failed.\n");
            continue; // Continue to next iteration
        }

        // Send packet
        if (send_packet(&camera_config, packet, packet_size) != 0) {
            fprintf(stderr, "Packet send failed.\n");
        }

        free(frame_buffer);
        free(fragment);
        free(packet);

        usleep(10000); // 10ms delay
    }

    // Cleanup
    cleanup(&camera_config);

    return 0;
}

