#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define NUM_BUFFERS 4
#define FRAME_WIDTH 192
#define FRAME_HEIGHT 288
#define FRAME_RATE 30

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

buffer_t buffers[NUM_BUFFERS];

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the camera device
int init_camera(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming\n", DEVICE_NAME);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    // Queue buffers
    memset(&buf, 0, sizeof(buf));
    for (int i = 0; i < NUM_BUFFERS; ++i) {
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

// Function to map a buffer
int map_buffer(int fd, int index, void **start, size_t *length) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    *start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*start == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    *length = buf.length;
    return 0;
}

// Function to unmap a buffer
int unmap_buffer(void *start, size_t length) {
    if (munmap(start, length) < 0) {
        perror("munmap");
        return -1;
    }
    return 0;
}

// Function to write a frame to a file
int write_frame_to_file(void *start, size_t length, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    size_t bytes_written = fwrite(start, 1, length, fp);
    if (bytes_written != length) {
        fprintf(stderr, "Error: Failed to write all bytes to file (%zu written, expected %zu)\n", bytes_written, length);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    int fd;
    struct v4l2_streamparm parm;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the camera device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Initialize the camera
    if (init_camera(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(fd) < 0) {
        stop_camera(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_BUFFERS; ++i) {
            void *start;
            size_t length;

            if (map_buffer(fd, i, &start, &length) < 0) {
                // Unmap any previously mapped buffers before exiting
                for (int j = 0; j < i; ++j) {
                    unmap_buffer(buffers[j].start, buffers[j].length);
                }
                stop_streaming(fd);
                stop_camera(fd);
                close(fd);
                return EXIT_FAILURE;
            }

            // Dequeue a frame
            if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("VIDIOC_DQBUF");
                unmap_buffer(start, length);
                continue; // Try the next buffer
            }

            // Verify bytesused
            if (buf.bytesused > 0) {
                // Write frame to file
                if (write_frame_to_file(start, length, IMAGE_FILE) < 0) {
                    fprintf(stderr, "Error writing frame to file, continuing...\n");
                }
            } else {
                fprintf(stderr, "Warning: Frame has no data, skipping.\n");
            }

            // Requeue the buffer
            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF");
                unmap_buffer(start, length);
                continue; // Try the next buffer
            }

            // Unmap the buffer
            if (unmap_buffer(start, length) < 0) {
                fprintf(stderr, "Error unmapping buffer, continuing...\n");
            }
        }
        usleep(333333); // Sleep for approximately 1/30th of a second
    }

    // Stop streaming
    if (stop_streaming(fd) < 0) {
        fprintf(stderr, "Error stopping streaming, continuing cleanup...\n");
    }

    // Unmap all buffers
    for (int i = 0; i < NUM_BUFFERS; ++i) {
        if (buffers[i].start != NULL) {
            if (unmap_buffer(buffers[i].start, buffers[i].length) < 0) {
                fprintf(stderr, "Error unmapping buffer during cleanup, continuing...\n");
            }
        }
    }

    // Free buffer array
    for (int i = 0; i < NUM_BUFFERS; ++i) {
        free(buffers[i].start);
    }

    // Close the device
    if (close(fd) < 0) {
        perror("close");
    }

    printf("Program terminated successfully.\n");
    return EXIT_SUCCESS;
}

