#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <sys/select.h>
#include <jpeglib.h>
#include <setjmp.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>

#define DEVICE_NAME "/dev/video0"
#define JPEG_QUALITY 75
#define MAX_BUFFER_COUNT 4
#define MAX_FRAME_SIZE 2048 * 2048 // Adjust based on camera resolution
#define MAX_JPEG_SIZE (MAX_FRAME_SIZE * 3) // RGB24

// Structure to hold camera configuration
typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *buffers[MAX_BUFFER_COUNT];
    size_t buffer_sizes[MAX_BUFFER_COUNT];
    int n_buffers;
} camera_config_t;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the camera
int init_camera(camera_config_t *config) {
    int fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    // Query capabilities
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    // Set format
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Set desired width
    fmt.fmt.pix.height = 480; // Set desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Queue buffers
    config->n_buffers = 0;
    while (ioctl(fd, VIDIOC_QBUF, &config->buf) == 0 && config->n_buffers < MAX_BUFFER_COUNT) {
        config->buffers[config->n_buffers++] = NULL;
    }

    if (config->n_buffers < 1) {
        fprintf(stderr, "Error queuing buffers\n");
        close(fd);
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming(camera_config_t *config) {
    if (ioctl(config->fd, VIDIOC_STREAMON, &config->buf.type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to stop streaming
int stop_streaming(camera_config_t *config) {
    if (ioctl(config->fd, VIDIOC_STREAMOFF, &config->buf.type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to capture a frame
int capture_frame(camera_config_t *config, uint8_t **frame_data, size_t *frame_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(config->fd, &readfds);

    timeout.tv_sec = 2; // 2-second timeout
    timeout.tv_usec = 0;

    int select_result = select(config->fd + 1, &readfds, NULL, NULL, &timeout);

    if (select_result < 0) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (select_result == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    // Dequeue a buffer
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.index = 0; // Start with the first buffer

    if (ioctl(config->fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *frame_data = config->buffers[buf.index];
    *frame_size = buf.bytesused;

    // Requeue the buffer
    if (ioctl(config->fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error requeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to convert YUYV to RGB24
uint8_t *yuyv_to_rgb24(uint8_t *yuyv_frame, size_t yuyv_size, uint8_t **rgb_frame, size_t *rgb_size) {
    // Simple YUYV to RGB24 conversion (assuming 4:2:0 chroma subsampling)
    int i, j;
    uint8_t *y, *u, *v, *r, *g, *b;
    size_t yuyv_line_size = yuyv_size / 2; // Each line is half the size due to subsampling
    size_t rgb_line_size = yuyv_line_size * 3; // Each RGB line is 3 bytes

    *rgb_frame = (uint8_t *)malloc(rgb_line_size * yuyv_size);
    if (*rgb_frame == NULL) {
        fprintf(stderr, "Error allocating memory for RGB frame\n");
        return NULL;
    }
    *rgb_size = rgb_line_size * yuyv_size;

    for (i = 0; i < yuyv_size; i++) {
        y = &yuyv_frame[i * 2];
        u = &yuyv_frame[i * 2 + 1];
        v = &yuyv_frame[i * 2 + 2];
        r = &(*rgb_frame)[i * rgb_line_size];
        g = &(*rgb_frame)[i * rgb_line_size + 1];
        b = &(*rgb_frame)[i * rgb_line_size + 2];

        for (j = 0; j < yuyv_line_size; j++) {
            r[j] = (y[j] > 128) ? 255 : 0; // Convert Y to grayscale
            g[j] = (u[j] > 128) ? 255 : 0;
            b[j] = (v[j] > 128) ? 255 : 0;
        }
    }

    return *rgb_frame;
}

// Function to apply a blur filter (simple averaging)
uint8_t *blur(uint8_t *rgb_frame, size_t rgb_size) {
    if (rgb_size > MAX_JPEG_SIZE) {
        fprintf(stderr, "Frame too large for blur filter\n");
        return NULL;
    }

    size_t num_pixels = rgb_size / 3;
    uint8_t *blurred_frame = (uint8_t *)malloc(rgb_size);
    if (blurred_frame == NULL) {
        fprintf(stderr, "Error allocating memory for blurred frame\n");
        return NULL;
    }

    for (size_t i = 0; i < num_pixels; i++) {
        int r = 0, g = 0, b = 0;
        for (int j = 0; j < 3; j++) {
            r += rgb_frame[i * 3 + j];
            g += rgb_frame[i * 3 + j + 1];
            b += rgb_frame[i * 3 + j + 2];
        }
        blurred_frame[i] = (uint8_t)(r / 9);
    }

    return blurred_frame;
}

// Function to encode RGB24 to JPEG
int encode_jpeg(uint8_t *rgb_frame, size_t rgb_size, char *jpeg_data, size_t jpeg_size) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    jpeg_mem_dest(&cinfo, jpeg_data, jpeg_size);

    cinfo.image_width = 640; // Adjust based on your RGB frame size
    cinfo.image_height = 480;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb_frame[cinfo.next_scanline * rgb_size];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

// Function to create a filename based on the current timestamp
char *create_filename(char *filename_suffix) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
    snprintf(filename_suffix, 64, "%s%s", timestamp, filename_suffix);

    return filename_suffix;
}

// Function to free all allocated resources
void cleanup(camera_config_t *config) {
    for (int i = 0; i < config->n_buffers; i++) {
        if (config->buffers[i] != NULL) {
            munmap(config->buffers[i], config->buffer_sizes[i]);
        }
    }
    free(config->buffers);
    close(config->fd);
}

int main() {
    camera_config_t camera_config;
    uint8_t *yuyv_frame = NULL;
    uint8_t *rgb_frame = NULL;
    uint8_t *blurred_frame = NULL;
    uint8_t *jpeg_data = NULL;
    char filename_suffix[64] = "raw";
    char jpeg_filename[128];

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize camera
    if (init_camera(&camera_config) < 0) {
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(&camera_config) < 0) {
        cleanup(&camera_config);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Capture frame
        if (capture_frame(&camera_config, &yuyv_frame, &yuyv_size) == 0) {
            // Convert to RGB24
            if (yuyv_to_rgb24(yuyv_frame, yuyv_size, &rgb_frame, &rgb_size) == 0) {
                // Apply blur filter
                if (blur(rgb_frame, rgb_size) == 0) {
                    // Encode to JPEG
                    if (encode_jpeg(rgb_frame, rgb_size, jpeg_data, MAX_JPEG_SIZE) == 0) {
                        // Create filename
                        create_filename(filename_suffix);
                        snprintf(jpeg_filename, sizeof(jpeg_filename), "capture_%s.jpg", filename_suffix);

                        // Save JPEG data to file
                        FILE *fp = fopen(jpeg_filename, "wb");
                        if (fp == NULL) {
                            fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
                        } else {
                            fwrite(jpeg_data, 1, jpeg_size, fp);
                            fclose(fp);
                            printf("Saved JPEG to %s\n", jpeg_filename);
                        }
                    } else {
                        fprintf(stderr, "Error encoding JPEG\n");
                    }
                } else {
                    fprintf(stderr, "Error encoding JPEG\n");
                }
            } else {
                fprintf(stderr, "Error converting YUYV to RGB\n");
            }
        } else {
            fprintf(stderr, "Error capturing frame\n");
        }

        usleep(100000); // Sleep for 100ms
    }

    // Stop streaming
    if (stop_streaming(&camera_config) < 0) {
        fprintf(stderr, "Error stopping streaming\n");
    }

    // Cleanup resources
    cleanup(&camera_config);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

