#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <unistd.h>

#define DEVICE_PATH "/dev/video0"
#define MAX_FRAME_WIDTH 2048
#define MAX_FRAME_HEIGHT 2048
#define MAX_FRAME_RATE 60

// Structure to hold camera capabilities
typedef struct {
    int width;
    int height;
    int rate;
    int focus_auto;
} camera_cap_t;

// Function to check if a file exists
int file_exists(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        return 1; // File exists
    } else {
        return 0; // File does not exist
    }
}

// Function to open the video device
int open_device(const char *device_path) {
    int fd = open(device_path, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_capabilities(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }
    return 0;
}

// Function to enumerate supported frame sizes
int enumerate_frame_sizes(int fd, int *sizes, int max_size, int *num_sizes) {
    struct v4l2_frmsizeenum frmsize;
    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.index = 0;

    if (ioctl(fd, VIDIOC_ENUM_FRMSIZES, &frmsize) < 0) {
        perror("Error enumerating frame sizes");
        return -1;
    }

    *num_sizes = frmsize.count;
    for (int i = 0; i < *num_sizes; i++) {
        sizes[i] = frmsize.sizes[i].n;
    }
    return 0;
}

// Function to enumerate available frame intervals
int enumerate_frame_intervals(int fd, int width, int height, int *intervals, int max_intervals) {
    struct v4l2_frameintervalsenum frameintervals;
    memset(&frameintervals, 0, sizeof(frameintervals));
    frameintervals.index = 0;

    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frameintervals) < 0) {
        perror("Error enumerating frame intervals");
        return -1;
    }

    *max_intervals = frameintervals.count;
    for (int i = 0; i < *max_intervals; i++) {
        intervals[i] = frameintervals.intervals[i].min;
    }
    return 0;
}

// Function to query V4L2_CID_FOCUS_AUTO
int query_focus_auto(int fd) {
    struct v4l2_control ctrl;
    memset(&ctrl, 0, sizeof(ctrl));
    ctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        perror("Error querying focus auto");
        return -1;
    }

    return ctrl.def_value;
}

// Function to print camera capabilities
void print_capabilities(camera_cap_t cap) {
    printf("Camera Capabilities:\n");
    printf("  Width: %d\n", cap.width);
    printf("  Height: %d\n", cap.height);
    printf("  Frame Rate: %d\n", cap.rate);
    printf("  Focus Auto: %s\n", cap.focus_auto ? "Supported" : "Not Supported");
}

int main() {
    int fd = -1; // Initialize file descriptor
    int frame_sizes[MAX_FRAME_WIDTH * MAX_FRAME_HEIGHT];
    int num_frame_sizes = 0;
    int frame_intervals[MAX_FRAME_WIDTH * MAX_FRAME_HEIGHT];
    int max_frame_intervals = 0;
    camera_cap_t camera_cap;

    // Check if the device exists
    if (!file_exists(DEVICE_PATH)) {
        fprintf(stderr, "Error: %s does not exist\n", DEVICE_PATH);
        return 1;
    }

    // Open the device
    fd = open_device(DEVICE_PATH);
    if (fd < 0) {
        return 1;
    }

    // Query capabilities
    if (query_capabilities(fd, &camera_cap) < 0) {
        close(fd);
        return 1;
    }

    // Enumerate frame sizes
    if (enumerate_frame_sizes(fd, frame_sizes, MAX_FRAME_WIDTH, &num_frame_sizes) < 0) {
        close(fd);
        return 1;
    }

    // Enumerate frame intervals for each frame size
    for (int i = 0; i < num_frame_sizes; i++) {
        if (enumerate_frame_intervals(fd, frame_sizes[i], frame_sizes[i], frame_intervals, max_frame_intervals) < 0) {
            close(fd);
            return 1;
        }
    }

    // Print capabilities
    printf("Camera Capabilities:\n");
    printf("  Supported Resolutions:\n");
    for (int i = 0; i < num_frame_sizes; i++) {
        printf("    %d x %d\n", frame_sizes[i], frame_sizes[i]);
    }
    printf("  Frame Intervals (for %d x %d):\n", frame_sizes[i], frame_sizes[i]);
    for (int i = 0; i < max_frame_intervals; i++) {
        printf("    %d\n", frame_intervals[i]);
    }
    printf("  Focus Auto: %s\n", camera_cap.focus_auto ? "Supported" : "Not Supported");

    // Close the device
    close(fd);

    return 0;
}

