#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define servo pulse width limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define center pulse width
#define CENTER_PULSE_WIDTH 1500

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Function to set servo pulse width
void set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (gpioServo(gpio_pin, pulse_width) != 0) {
        fprintf(stderr, "Error setting servo pulse width on GPIO %d\n", gpio_pin);
    }
}

// Function to map button press to servo adjustment
void button_to_servo(int button_pin) {
    int pulse_width;

    if (button_pin == UP_BUTTON_PIN) {
        pulse_width = CENTER_PULSE_WIDTH + 10;
        if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;
        set_servo_pulse_width(PAN_SERVO_PIN, pulse_width);
        printf("UP button pressed, adjusting pan servo to %d us\n", pulse_width);
    } else if (button_pin == DOWN_BUTTON_PIN) {
        pulse_width = CENTER_PULSE_WIDTH - 10;
        if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
        set_servo_pulse_width(PAN_SERVO_PIN, pulse_width);
        printf("DOWN button pressed, adjusting pan servo to %d us\n", pulse_width);
    } else if (button_pin == LEFT_BUTTON_PIN) {
        pulse_width = CENTER_PULSE_WIDTH + 10;
        if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;
        set_servo_pulse_width(TILT_SERVO_PIN, pulse_width);
        printf("LEFT button pressed, adjusting tilt servo to %d us\n", pulse_width);
    } else if (button_pin == RIGHT_BUTTON_PIN) {
        pulse_width = CENTER_PULSE_WIDTH - 10;
        if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
        set_servo_pulse_width(TILT_SERVO_PIN, pulse_width);
        printf("RIGHT button pressed, adjusting tilt servo to %d us\n", pulse_width);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set initial servo positions
    set_servo_pulse_width(PAN_SERVO_PIN, CENTER_PULSE_WIDTH);
    set_servo_pulse_width(TILT_SERVO_PIN, CENTER_PULSE_WIDTH);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Pan-Tilt Mount Control\n");
    printf("Press UP/DOWN/LEFT/RIGHT buttons to adjust servos.\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int up_button_state = gpioRead(UP_BUTTON_PIN);
        int down_button_state = gpioRead(DOWN_BUTTON_PIN);
        int left_button_state = gpioRead(LEFT_BUTTON_PIN);
        int right_button_state = gpioRead(RIGHT_BUTTON_PIN);

        // Map button presses to servo adjustments
        button_to_servo(UP_BUTTON_PIN);
        button_to_servo(DOWN_BUTTON_PIN);
        button_to_servo(LEFT_BUTTON_PIN);
        button_to_servo(RIGHT_BUTTON_PIN);

        // Delay
        gpioDelay(50); // 50ms delay
    }

    // Clean up and exit
    set_servo_pulse_width(PAN_SERVO_PIN, CENTER_PULSE_WIDTH);
    set_servo_pulse_width(TILT_SERVO_PIN, CENTER_PULSE_WIDTH);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

