    set_servo_pulse_width(PAN_SERVO_PIN, CENTER_PULSE_WIDTH);
    set_servo_pulse_width(TILT_SERVO_PIN, CENTER_PULSE_WIDTH);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
