#include <signal.h>
#include <unistd.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_TIME 2000 // milliseconds
#define POLLING_INTERVAL 100 // milliseconds
#define IMAGE_QUALITY 85
#define UPLOAD_URL "http://<IP>:<port>/upload" // Replace <IP> and <port> with actual values

// Global variables
static volatile int running = 1;
static char *image_filename = NULL;
static char *timestamp = NULL;
static char *json_payload = NULL;
static char *error_message = NULL;

// Structure to hold configuration data
typedef struct {
    char *ip_address;
    int port;
} Config;

// Function prototypes
int initialize_gpio();
int read_sensor();
int capture_image(const char *filename);
int create_json_payload(const char *filename, const char *timestamp, const char *motion_status, int gpio_pin);
int upload_image(const char *filename, const char *json_payload);
void signal_handler(int signal);
void cleanup();
void log_message(const char *message);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

// Logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp_str[30];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp_str, message);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

// Read sensor
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Capture image
int capture_image(const char *filename) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp_str[30];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d_%H-%M-%S", t);

    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 --encoding jpeg --quality %d", filename, IMAGE_QUALITY);

    int status = system(command);
    if (status == -1) {
        log_message("Error executing camera command");
        return 1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        log_message("Camera command failed");
        return 1;
    }

    return 0;
}

// Create JSON payload
int create_json_payload(const char *filename, const char *timestamp, const char *motion_status, int gpio_pin) {
    json_t *root = json_object();
    json_t *filename_json = json_string(filename);
    json_t *timestamp_json = json_string(timestamp);
    json_t *motion_status_json = json_string(motion_status);
    json_t *gpio_pin_json = json_integer(gpio_pin);

    json_object_set_new(root, "filename", filename_json);
    json_object_set_new(root, "timestamp", timestamp_json);
    json_object_set_new(root, "motion_status", motion_status_json);
    json_object_set_new(root, "gpio_pin", gpio_pin_json);

    char *json_str = json_dumps(root, JSON_REAL_PRECISION(10));
    if (!json_str) {
        log_message("Failed to create JSON payload");
        json_decref(root);
        return 1;
    }

    json_decref(root);
    json_free(json_str);

    return 0;
}

// Upload image
int upload_image(const char *filename, const char *json_payload) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, UPLOAD_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_payload));

        headers = curl_slist_append(headers, "Content-Type: image/jpeg");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            log_message("HTTP upload failed");
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 400) {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
                log_message("HTTP request failed");
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        log_message("Failed to initialize libcurl");
        curl_global_cleanup();
        return 1;
    }

    curl_global_cleanup();
    return 0;
}

// Cleanup
void cleanup() {
    log_message("Cleaning up...");
    if (image_filename) free(image_filename);
    if (timestamp) free(timestamp);
