#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGES_DIR "/home/pi/images"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to generate a timestamp string
char* generate_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y%m%d_%H%M%S", timeinfo);
    return timestamp;
}

// Function to capture an image using raspistill
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s -w 640 -h 480 -q 85 -timeout 2000 -nopreview", IMAGES_DIR, filename);
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspistill command");
        return -1;
    }
    return status;
}

// Function to log messages to a file
void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    char *timestamp = generate_timestamp();
    if (timestamp != NULL) {
        fprintf(fp, "%s: %s\n", timestamp, message);
        free(timestamp);
    } else {
        fprintf(fp, "Timestamp error: %s\n", message);
    }

    fclose(fp);
}

// Function to handle motion detection with debouncing
void handle_motion() {
    char filename[64];
    char *timestamp = generate_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to generate timestamp, skipping image capture.\n");
        return;
    }

    snprintf(filename, sizeof(filename), "%s/%s.jpg", IMAGES_DIR, timestamp);
    free(timestamp);

    if (capture_image(filename) != 0) {
        log_message("Failed to capture image.");
    } else {
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Image captured: %s", filename);
        log_message(log_message_buffer);
    }
    free(timestamp);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with edge detection
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the state of the GPIO pin
        int motion_detected = gpioRead(GPIO_PIN);

        // Debounce the input
        if (motion_detected == 1) {
            gpioDelay(50); // Wait 50ms
            if (gpioRead(GPIO_PIN) == 0) { // Check if the pin is still low after 50ms
                handle_motion();
            }
        }
        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Motion detection stopped.\n");
    return 0;
}

