void *allocate_buffer(int fd, int width, int height) {
    void *buffer = mmap(NULL, width * height * 2, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return buffer;
}

