#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servo motors
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define neutral servo position (90 degrees)
#define NEUTRAL_ANGLE 90

// Define servo angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define arrow key codes
#define LEFT_ARROW 37
#define RIGHT_ARROW 39
#define UP_ARROW 38
#define DOWN_ARROW 40

// Define 'q' key code
#define Q_KEY 113

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set servo angle using pigpio
int set_servo_angle(int gpio_pin, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Angle must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1; // Indicate error
    }

    // Convert angle to pulse width (500-2500 us)
    int pulse_width = (int)(500 + (angle * 2000.0 / 180.0));

    // Set servo position using pigpio
    if (gpioServo(gpio_pin, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo position on GPIO %d.\n", gpio_pin);
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1; // Exit with error code
    }

    // Set GPIO pins to output mode
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-1000000)
    gpioSetPWMrange(PAN_SERVO_PIN, 1000000);
    gpioSetPWMrange(TILT_SERVO_PIN, 1000000);

    // Set initial servo positions to neutral
    if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Servo control program started. Press 'q' to exit.\n");

    // Main loop
    while (program_running) {
        // Read input from stdin
        int key = getchar();

        // Check for 'q' key
        if (key == Q_KEY) {
            printf("Exiting...\n");
            break; // Exit main loop
        }

        // Handle arrow key presses
        switch (key) {
            case LEFT_ARROW:
                printf("Moving pan servo to the left.\n");
                if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE - 5) != 0) {
                    fprintf(stderr, "Error: Failed to move pan servo to the left.\n");
                }
                break;
            case RIGHT_ARROW:
                printf("Moving pan servo to the right.\n");
                if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE + 5) != 0) {
                    fprintf(stderr, "Error: Failed to move pan servo to the right.\n");
                }
                break;
            case UP_ARROW:
                printf("Moving tilt servo up.\n");
                if (set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE + 5) != 0) {
                    fprintf(stderr, "Error: Failed to move tilt servo up.\n");
                }
                break;
            case DOWN_ARROW:
                printf("Moving tilt servo down.\n");
                if (set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE - 5) != 0) {
                    fprintf(stderr, "Error: Failed to move tilt servo down.\n");
                }
                break;
            default:
                // Do nothing for other keys
                break;
        }

        // Delay to prevent excessive CPU usage
        usleep(100000); // 100 ms
    }

    // Cleanup: Set servos to neutral position and terminate pigpio
    printf("Cleaning up...\n");
    if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        fprintf(stderr, "Error: Failed to set pan servo to neutral during cleanup.\n");
    }
    if (set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        fprintf(stderr, "Error: Failed to set tilt servo to neutral during cleanup.\n");
    }

    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

