#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for row anodes
#define ROW1 17
#define ROW2 18
#define ROW3 27
#define ROW4 22
#define ROW5 23
#define ROW6 24
#define ROW7 25
#define ROW8 4

// Define GPIO pins for column cathodes
#define COL1 5
#define COL2 6
#define COL3 12
#define COL4 13
#define COL5 19
#define COL6 16
#define COL7 26
#define COL8 20

// Define the size of the LED matrix
#define MATRIX_SIZE 8

// Define the delay between row scans (in microseconds)
#define SCAN_DELAY 800

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the GPIO pin mode
int setup_gpio(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error setting GPIO %d mode to %d\n", pin, mode);
        return -1;
    }
    return 0;
}

// Function to set the GPIO pin value
int set_gpio_value(int pin, int value) {
    if (gpioWrite(pin, value) != 0) {
        fprintf(stderr, "Error setting GPIO %d value to %d\n", pin, value);
        return -1;
    }
    return 0;
}

// Function to scan through the rows and light the LEDs
void scan_rows() {
    for (int row = 0; row < MATRIX_SIZE; row++) {
        // Set the row anode HIGH
        if (set_gpio_value(ROW1, 1) != 0) return;
        if (set_gpio_value(ROW2, 1) != 0) return;
        if (set_gpio_value(ROW3, 1) != 0) return;
        if (set_gpio_value(ROW4, 1) != 0) return;
        if (set_gpio_value(ROW5, 1) != 0) return;
        if (set_gpio_value(ROW6, 1) != 0) return;
        if (set_gpio_value(ROW7, 1) != 0) return;
        if (set_gpio_value(ROW8, 1) != 0) return;

        // Set the column cathodes LOW to light the LED
        if (set_gpio_value(COL1, 0) != 0) return;
        if (set_gpio_value(COL2, 0) != 0) return;
        if (set_gpio_value(COL3, 0) != 0) return;
        if (set_gpio_value(COL4, 0) != 0) return;
        if (set_gpio_value(COL5, 0) != 0) return;
        if (set_gpio_value(COL6, 0) != 0) return;
        if (set_gpio_value(COL7, 0) != 0) return;
        if (set_gpio_value(COL8, 0) != 0) return;

        // Delay for the scan duration
        gpioDelay(SCAN_DELAY);
    }
}

// Function to render the wave-like animation
void render_wave(int row, int col) {
    // Set the row anode HIGH
    if (set_gpio_value(ROW1, 1) != 0) return;
    if (set_gpio_value(ROW2, 1) != 0) return;
    if (set_gpio_value(ROW3, 1) != 0) return;
    if (set_gpio_value(ROW4, 1) != 0) return;
    if (set_gpio_value(ROW5, 1) != 0) return;
    if (set_gpio_value(ROW6, 1) != 0) return;
    if (set_gpio_value(ROW7, 1) != 0) return;
    if (set_gpio_value(ROW8, 1) != 0) return;

    // Set the column cathode LOW to light the LED
    if (set_gpio_value(COL1, 0) != 0) return;
    if (set_gpio_value(COL2, 0) != 0) return;
    if (set_gpio_value(COL3, 0) != 0) return;
    if (set_gpio_value(COL4, 0) != 0) return;
    if (set_gpio_value(COL5, 0) != 0) return;
    if (set_gpio_value(COL6, 0) != 0) return;
    if (set_gpio_value(COL7, 0) != 0) return;
    if (set_gpio_value(COL8, 0) != 0) return;

    // Delay for the scan duration
    gpioDelay(SCAN_DELAY);
}

// Function to shift the wave left-to-right
void shift_left() {
    for (int i = 0; i < MATRIX_SIZE; i++) {
        render_wave(i, i);
    }
}

// Function to shift the wave right-to-left
void shift_right() {
    for (int i = 0; i < MATRIX_SIZE; i++) {
        render_wave(i, MATRIX_SIZE - 1 - i);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up GPIO pins
    if (setup_gpio(ROW1, PI_OUTPUT) != 0 ||
        setup_gpio(ROW2, PI_OUTPUT) != 0 ||
        setup_gpio(ROW3, PI_OUTPUT) != 0 ||
        setup_gpio(ROW4, PI_OUTPUT) != 0 ||
        setup_gpio(ROW5, PI_OUTPUT) != 0 ||
        setup_gpio(ROW6, PI_OUTPUT) != 0 ||
        setup_gpio(ROW7, PI_OUTPUT) != 0 ||
        setup_gpio(ROW8, PI_OUTPUT) != 0 ||
        setup_gpio(COL1, PI_OUTPUT) != 0 ||
        setup_gpio(COL2, PI_OUTPUT) != 0 ||
        setup_gpio(COL3, PI_OUTPUT) != 0 ||
        setup_gpio(COL4, PI_OUTPUT) != 0 ||
        setup_gpio(COL5, PI_OUTPUT) != 0 ||
        setup_gpio(COL6, PI_OUTPUT) != 0 ||
        setup_gpio(COL7, PI_OUTPUT) != 0 ||
        setup_gpio(COL8, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Shift the wave left
        shift_left();
        gpioDelay(1000); // Delay between wave shifts

        // Shift the wave right
        shift_right();
        gpioDelay(1000); // Delay between wave shifts
    }

    // Clean up GPIO pins
    gpioTerminate();

    return 0;
}

