// Define GPIO pins for row anodes and column cathodes
const int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};

// Define the number of rows and columns
const int rows = 8;
const int cols = 8;

// Define the delay between columns in milliseconds
const int delay_ms = 150;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set row pins as outputs
    for (int i = 0; i < rows; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set row pin %d as output\n", row_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    // Set column pins as inputs
    for (int i = 0; i < cols; i++) {
        if (gpioSetMode(col_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set column pin %d as input\n", col_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

// Function to clear the LED matrix
void clear_matrix() {
    for (int i = 0; i < rows; i++) {
        gpioWrite(row_pins[i], PI_LOW);
    }
}

// Function to display a single column
void display_column(int col) {
    clear_matrix();

    // Set the column cathode LOW
    gpioWrite(col_pins[col], PI_LOW);

    // Light the LEDs sequentially by setting the corresponding row anodes HIGH
    for (int i = 0; i < rows; i++) {
        gpioWrite(row_pins[i], PI_HIGH);
        gpioDelay(1); // Small delay to allow the LED to light
    }

    gpioDelay(delay_ms);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Wave-like animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int col = 0; col < cols; col++) {
            display_column(col);
        }
    }

    // Cleanly release all GPIO lines before exiting
    for (int i = 0; i < rows; i++) {
        gpioWrite(row_pins[i], PI_LOW);
    }
    for (int i = 0; i < cols; i++) {
        gpioWrite(col_pins[i], PI_INPUT); // Set back to input to avoid short circuit
    }
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

