#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX75031_ADDR 0x4A
#define DISTANCE_REG 0x00 // Example register address, adjust as needed
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILE "depth_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int distance_register;
} sensor_config_t;

// Function prototypes
int initialize_sensor(sensor_config_t config);
int read_distance(int i2c_handle);
int log_data(FILE *fp, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the sensor interface
int initialize_sensor(sensor_config_t config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(config.i2c_bus, config.i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read distance data from the sensor
int read_distance(int i2c_handle) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a single distance value
    int distance = (buf[0] << 8) | buf[1];
    return distance;
}

// Log data to the CSV file
int log_data(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX75031_ADDR,
        .distance_register = DISTANCE_REG
    };

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the sensor interface
    if (initialize_sensor(config) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        return 1;
    }

    // Check if the log file exists. If not, create it and write the header.
    FILE *fp = fopen(CSV_FILE, "r");
    if (fp == NULL) {
        log_file = fopen(CSV_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file for writing\n");
            cleanup();
            return 1;
        }
        fprintf(log_file, "Timestamp,Distance\n");
        fclose(log_file);
    } else {
        fclose(fp);
        log_file = fopen(CSV_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file for appending\n");
            cleanup();
            return 1;
        }
    }

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            if (log_data(log_file, distance) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance, retrying I2C initialization\n");
            i2cClose(i2c_handle);
            gpioTerminate();
