            i2cClose(i2c_handle);
            gpioTerminate();
            if (initialize_sensor(config) != 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
