    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int init_si1145() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

