        fprintf(stderr, "Error: Failed to configure measurement rate.\n");
        return -1;
    }

    // Enable proximity and ALS measurements
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to enable proximity and ALS.\n");
        return -1;
    }

    return 0;
}

// Read proximity and ambient light data from the sensor
int read_sensor_data(int *prox, int *als) {
    int prox_val, als_val;

    prox_val = i2cReadWordData(i2c_handle, PROX_DATA_REG);
    if (prox_val < 0) {
        fprintf(stderr, "Error: Failed to read proximity data.\n");
        return -1;
    }

    als_val = i2cReadWordData(i2c_handle, ALS_DATA_REG);
    if (als_val < 0) {
        fprintf(stderr, "Error: Failed to read ambient light data.\n");
        return -1;
    }

    *prox = prox_val;
    *als = als_val;

    return 0;
}

