#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define BLINK_DURATION_MS 100
#define LOG_FILE "proximity.log"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to log proximity detection with timestamp
int log_detection(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s Object detected\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(BLINK_DURATION_MS * 1000); // Delay for 100ms
    gpioWrite(LED_PIN, 0); // Turn LED off
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor value
        int sensor_value = gpioRead(SENSOR_PIN);

        // Check for falling edge (LOW to HIGH)
        if (sensor_value == 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log detection
            if (log_detection(timestamp) != 0) {
                fprintf(stderr, "Error logging detection\n");
            }

            // Blink LED
            blink_led();
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup GPIO
    gpioTerminate();
    printf("GPIO terminated. Exiting.\n");

    return 0;
}

