#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define PROX_DATA_REG 0x22
#define ALS_DATA_REG 0x24
#define LOG_FILE "biometric_data.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_sensor_data(int *proximity, int *ambient_light);
int log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int init_si1145() {
    int status;

    // Check PART_ID
    status = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", status);
        return -1;
    }
    if (status != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02x\n", status);
        return -1;
    }

    printf("Si1145 sensor initialized successfully.\n");
    return 0;
}

// Read proximity and ambient light data from the sensor
int read_sensor_data(int *proximity, int *ambient_light) {
    int status;

    // Read proximity data
    status = i2cReadWordData(i2c_handle, PROX_DATA_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", status);
        return -1;
    }
    *proximity = status;

    // Read ambient light data
    status = i2cReadWordData(i2c_handle, ALS_DATA_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading ambient light data: %d\n", status);
        return -1;
    }
    *ambient_light = status;

    return 0;
}

// Log data to the CSV file
int log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);

    return 0;
}

int main() {
    int proximity, ambient_light;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(1);
    }

    // Cleanup
    printf("Closing I2C handle...\n");
    i2cClose(i2c_handle);

    printf("Closing log file...\n");
    fclose(log_file);

    printf("Calling sensor API...\n");
