    // This is a placeholder; replace with the actual API call
    // For example, to reset the sensor:
    // i2cWriteByteData(i2c_handle, 0x18, 0x00); // Reset command

    printf("Terminating pigpio...\n");
    gpioTerminate();

    return 0;
}

