#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 400.0    // Maximum distance in cm
#define MIN_PULSE_WIDTH 0.0001 // Minimum pulse width in seconds
#define MAX_PULSE_WIDTH 0.1    // Maximum pulse width in seconds
#define TRIGGER_PULSE_DURATION 0.01 // Trigger pulse duration in seconds
#define TIMEOUT_DURATION 0.06       // Timeout duration in seconds

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_rising = 0;
static volatile int echo_falling = 0;
static volatile int echo_timeout = 0;
static volatile int echo_error = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
void echo_callback(int gpio, int level, uint32_t tick);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_rising = 1;
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_falling = 1;
    } else {
        echo_timeout = 1; // Timeout if echo signal is neither rising nor falling
    }
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate distance from pulse width
double calculate_distance(int pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Indicate an error
    }

    double distance = (pulse_width * SPEED_OF_SOUND) / 2.0;
    return distance;
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }

    if (distance < MIN_DISTANCE) {
        printf("Time to water the plant!\n");
        if (log_file != NULL) {
            fprintf(log_file, "%s, Time to water the plant!\n", timestamp);
            fflush(log_file);
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_timeout = 0; // Reset timeout flag
        echo_error = 0;    // Reset error flag

        // Trigger a pulse
        trigger_pulse();

        // Wait for echo to rise
        int timeout_count = 0;
        while (echo_rising && timeout_count < TIMEOUT_DURATION) {
            gpioDelay(0.0001); // Small delay to avoid busy-waiting
            timeout_count++;
        }
        if (echo_rising) {
            echo_timeout = 1; // Reset timeout if echo rises
        }

        // Wait for echo to fall
        timeout_count = 0;
        while (echo_falling && timeout_count < TIMEOUT_DURATION) {
            gpioDelay(0.0001); // Small delay to avoid busy-waiting
            timeout_count++;
        }
        if (echo_falling) {
            echo_timeout = 0; // Reset timeout if echo falls
        }

        // Calculate pulse width
        if (echo_timeout == 0 && echo_error == 0) {
            int pulse_width = echo_end_tick - echo_start_tick;
            if (pulse_width > 0) {
                double distance = calculate_distance(pulse_width);
                if (distance >= 0) {
                    log_distance(distance);
                } else {
                    echo_error = 1; // Set error flag
                }
            } else {
                echo_error = 1; // Set error flag if pulse width is 0
            }
        } else {
            echo_error = 1; // Set error flag if timeout occurred
        }

        // Wait before next measurement
        gpioDelay(1000); // 1 second delay
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Ultrasonic distance measurement stopped.\n");

    return 0;
}

