#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// APDS9960 I2C address
#define APDS9960_I2C_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_POX 0x9C
#define APDS9960_PXL 0x9D
#define APDS9960_CONTROL2 0x8D

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int apds9960_init();
int apds9960_read_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear);
int log_data(uint16_t red, uint16_t green, uint16_t blue, uint16_t clear);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the APDS9960 sensor
int apds9960_init() {
    // Enable the sensor
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not enable APDS9960\n");
        return -1;
    }

    // Set integration time (ATIME) - Adjust as needed
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xEB) < 0) { // 2.78ms
        fprintf(stderr, "Error: Could not set integration time\n");
        return -1;
    }

    // Set proximity pulse length (PTIME) - Adjust as needed
    if (i2cWriteByteData(i2c_handle, APDS9960_PTIME, 0x03) < 0) {
        fprintf(stderr, "Error: Could not set proximity pulse length\n");
        return -1;
    }

    // Set wait time (WTIME) - Adjust as needed
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set wait time\n");
        return -1;
    }

    // Set proximity threshold (PPULSE) - Adjust as needed
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x0A) < 0) {
        fprintf(stderr, "Error: Could not set proximity threshold\n");
        return -1;
    }

    // Enable proximity sensing
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error: Could not enable proximity sensing\n");
        return -1;
    }

    // Set configuration 1 (CFG1) - Adjust as needed
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG1, 0x0F) < 0) {
        fprintf(stderr, "Error: Could not set configuration 1\n");
        return -1;
    }

    return 0;
}

// Function to read color and proximity data from the APDS9960 sensor
int apds9960_read_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    unsigned char buffer[18];

    // Read all color and proximity data in one go
    if (i2cReadI2CBlockData(i2c_handle, APDS9960_CDATAL, (char *)buffer, 18) < 0) {
        fprintf(stderr, "Error: Could not read color and proximity data\n");
        return -1;
    }

    // Extract RGB values
    *red = (buffer[1] << 8) | buffer[0];
    *green = (buffer[3] << 8) | buffer[2];
    *blue = (buffer[5] << 8) | buffer[4];
    *clear = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Function to log data to a CSV file
int log_data(uint16_t red, uint16_t green, uint16_t blue, uint16_t clear) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, clear);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize APDS9960 sensor
    if (apds9960_init() < 0) {
        fprintf(stderr, "Error: APDS9960 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue, clear;

    // Main loop
    while (!terminate) {
        // Read data from APDS9960
        if (apds9960_read_data(&red, &green, &blue, &clear) == 0) {
            // Log data if proximity is above threshold
            if (clear > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, clear);
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Re-initializing...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait 1 second before re-initializing
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C bus\n");
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (apds9960_init() < 0) {
                    fprintf(stderr, "Error: APDS9960 re-initialisation failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

