// Constants
#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define GPIO_TRIGGER 17
#define DISTANCE_LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 500 // mm
#define TIMEOUT_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int init_gpio(int pin);
int init_vl53l0x(int i2c_fd);
int read_distance(int i2c_fd);
int log_distance(FILE *fp, int distance);
void signal_handler(int signal);

// Helper function to write a register
int write_register(int i2c_fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to I2C");
        return -1;
    }
    return 0;
}

// Helper function to read a register
int read_register(int i2c_fd, uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("Failed to read from I2C");
        return -1;
    }
    return 0;
}

// Helper function to read a register with multiple bytes
int read_register_with_bytes(int i2c_fd, uint8_t reg, uint8_t *value, int len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(i2c_fd, value, len) != len) {
        perror("Failed to read from I2C");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, VL53L0X_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_TRIGGER) != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize VL53L0X sensor
    if (init_vl53l0x(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize VL53L0X sensor. Exiting.\n");
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(DISTANCE_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger measurement
        gpioWrite(GPIO_TRIGGER, 0); // Pull low
        gpioDelay(1); // 1ms delay
        gpioWrite(GPIO_TRIGGER, 1); // Release
        gpioDelay(1); // 1ms delay

        // Wait for measurement to complete (with timeout)
        int timeout_counter = 0;
        while (read_register_with_bytes(i2c_fd, 0x0014, &timeout_counter, 1) == 0 && timeout_counter < 100) {
            gpioDelay(1); // Check every 1ms
        }

        if (timeout_counter >= 100) {
            fprintf(stderr, "Timeout waiting for measurement.\n");
            continue; // Skip to the next iteration
        }

        // Read distance
        int distance = read_distance(i2c_fd);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance.\n");
            continue; // Skip to the next iteration
        }

