#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define CH101_ADDR 0x70
#define TRIGGER_REG 0x00
#define DISTANCE_REG 0x01
#define DISTANCE_THRESHOLD 100 // mm
#define SAMPLE_INTERVAL 200 // ms
#define TRIGGER_DELAY 50 // ms
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int initialize_sensor();
int trigger_sensor();
int read_distance(uint16_t *distance);
int log_data(uint16_t distance);
void signal_handler(int signal);
char* get_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Get timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize sensor
int initialize_sensor() {
    // No specific initialization needed for CH101 in this example.
    // Refer to the datasheet for any required initialization sequences.
    return 0;
}

// Trigger the sensor
int trigger_sensor() {
    char buf[2];
    buf[0] = TRIGGER_REG;
    buf[1] = 0x01; // Trigger value (adjust as needed)
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to trigger register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(uint16_t *distance) {
    char buf[1];
    buf[0] = DISTANCE_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to distance register: %d\n", result);
        return -1;
    }

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return -1;
    }

    *distance = (data[0] << 8) | data[1]; // Combine the two bytes into a 16-bit value
    return 0;
}

// Log data to file
int log_data(uint16_t distance) {
    char *timestamp = get_timestamp();
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    int result = fprintf(log_file, "%s, %u\n", timestamp, distance);
    if (result < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t distance;
    int trigger_result, read_result;

    printf("Starting distance measurement...\n");

    while (!terminate) {
        // Trigger sensor
        trigger_result = trigger_sensor();
        if (trigger_result != 0) {
            fprintf(stderr, "Error triggering sensor, skipping sample.\n");
            gpioDelay(TRIGGER_DELAY * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(TRIGGER_DELAY * 1000); // Delay after trigger

        // Read distance
        read_result = read_distance(&distance);
        if (read_result != 0) {
            fprintf(stderr, "Error reading distance, skipping sample.\n");
            gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in microseconds
            continue;
        }

        // Validate distance
        if (distance < 0 || distance > 4000) { // Reasonable range for CH101
            fprintf(stderr, "Invalid distance reading: %u, skipping sample.\n", distance);
            gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in microseconds
            continue;
        }

        // Log data
        if (log_data(distance) != 0) {
            fprintf(stderr, "Error logging data, skipping sample.\n");
        }

        printf("%s, Distance: %u mm\n", get_timestamp(), distance);

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

