#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x68 // Replace with the actual I2C address
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20 // cm
#define SAMPLE_INTERVAL 100 // ms

// ICU20201 Register Addresses (Example - Refer to datasheet for actual values)
#define ICU20201_REG_DISTANCE_HIGH 0x00 // Example register
#define ICU20201_REG_DISTANCE_LOW 0x01  // Example register

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance;
    char timestamp[32];
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_distance(int *distance);
void control_led(int distance);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    // Read high byte
    result = i2cReadI2CBlockData(i2c_handle, ICU20201_REG_DISTANCE_HIGH, buf, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading high byte: %s\n", strerror(errno));
        return -1;
    }

    // Read low byte
    result = i2cReadI2CBlockData(i2c_handle, ICU20201_REG_DISTANCE_LOW, buf + 1, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading low byte: %s\n", strerror(errno));
        return -1;
    }

    // Combine bytes to form the distance value
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

// Control the LED based on distance
void control_led(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Log data to file
void log_data(sensor_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(data.timestamp, sizeof(data.timestamp), "%Y-%m-%dT%H:%M:%S%z", gmtime(&ts.tv_sec));
    fprintf(log_file, "%s,%d\n", data.timestamp, data.distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for LED
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting distance monitoring...\n");

    // Main loop
    while (!terminate) {
        int distance;
        sensor_data_t data;

        // Read distance
        if (read_distance(&distance) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(data.timestamp, sizeof(data.timestamp), "%Y-%m-%dT%H:%M:%S%z", gmtime(&ts.tv_sec));

            // Control LED
            control_led(distance);

            // Log data
            log_data(data);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

