#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define COMMAND_FRAME_LENGTH 4
#define RESPONSE_LENGTH 15
#define DISTANCE_THRESHOLD 1000 // mm
#define LOG_FILE "intrusion_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(uint8_t *command);
int read_response(uint8_t *response);
int verify_header(uint8_t header);
int extract_distance(uint8_t *response, int *distance);
float calculate_average_distance(int distance_values[], int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    uint8_t sensor_id;
    uint8_t measurement_mode;
} sensor_config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(uint8_t *command) {
    int result = i2cWriteDevice(i2c_handle, (char *)command, COMMAND_FRAME_LENGTH);
    if (result != COMMAND_FRAME_LENGTH) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read response from the sensor
int read_response(uint8_t *response) {
    int result = i2cReadDevice(i2c_handle, (char *)response, RESPONSE_LENGTH);
    if (result != RESPONSE_LENGTH) {
        fprintf(stderr, "Error reading response: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify the header byte of the response
int verify_header(uint8_t header) {
    return (header == 0x02); // Example header value
}

// Extract the distance from the response
int extract_distance(uint8_t *response, int *distance) {
    *distance = (response[11] << 8) | response[12]; // Example: distance is in bytes 11 and 12
    return 0;
}

// Calculate the average distance from multiple samples
float calculate_average_distance(int distance_values[], int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distance_values[i];
    }
    return sum / num_samples;
}

// Log intrusion event to file
int log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, Average Distance: %.2f mm\n", timestamp, average_distance);
    fclose(log_file);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    uint8_t command_frame[COMMAND_FRAME_LENGTH] = {0x01, 0x02, 0x03, 0x04}; // Example command
    uint8_t response[RESPONSE_LENGTH];
    int distance_values[10];
    int distance;
    int i;

    // Main loop
    while (!terminate) {
        // Send command
        if (send_command(command_frame) != 0) {
            fprintf(stderr, "Failed to send command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement (adjust as needed)
        gpioDelay(10); // 10 ms delay

        // Read response
        if (read_response(response) != 0) {
            fprintf(stderr, "Failed to read response, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Verify header
        if (!verify_header(response[0])) {
            fprintf(stderr, "Invalid header, skipping sample\n");
            continue;
        }

        // Extract distance
        if (extract_distance(response, &distance) != 0) {
            fprintf(stderr, "Failed to extract distance, skipping sample\n");
            continue;
        }

        // Store distance value
        distance_values[i] = distance;
        i++;

        // Calculate average distance
        if (i > 0) {
            float average_distance = calculate_average_distance(distance_values, i);
            printf("Average Distance: %.2f mm\n", average_distance);

            // Log intrusion if average distance is below threshold
            if (average_distance < DISTANCE_THRESHOLD) {
                if (log_intrusion(average_distance) != 0) {
                    fprintf(stderr, "Failed to log intrusion\n");
                }
            }
        }

        // Delay before next sample
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

