// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a register from the VL53L0X
int read_register(int handle, unsigned char reg, unsigned char *value) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)value, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a register to the VL53L0X
int write_register(int handle, unsigned char reg, unsigned char value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x(int handle) {
    // Required by datasheet
    if (write_register(handle, 0x88, 0x00) < 0) return -1;
    if (write_register(handle, 0x80, 0x01) < 0) return -1;
    if (write_register(handle, 0xFF, 0x01) < 0) return -1;
    if (write_register(handle, 0x00, 0x00) < 0) return -1;
    if (write_register(handle, 0x91, 0x01) < 0) return -1;
    if (write_register(handle, 0x80, 0x01) < 0) return -1;
    if (write_register(handle, 0xFF, 0x00) < 0) return -1;
    if (write_register(handle, 0x00, 0x00) < 0) return -1;
    if (write_register(handle, 0x80, 0x00) < 0) return -1;
    if (write_register(handle, 0xFF, 0x00) < 0) return -1;
    if (write_register(handle, 0x00, 0x00) < 0) return -1;
