#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address for the Si1182 sensor
#define I2C_BUS 1
#define SI1182_ADDR 0x39

// Define the register address for proximity data
#define SI1182_REG_PROX_DATA 0x02

// Global variable to store the I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C connection
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read proximity data from the Si1182 sensor
int read_proximity() {
    int data = i2cReadWordData(i2c_handle, SI1182_REG_PROX_DATA);
    if (data < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", data);
        return -1;
    }
    return data;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize the I2C connection
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop to read and log proximity data
    while (1) {
        int proximity_data = read_proximity();
        if (proximity_data >= 0) {
            printf("Proximity Data: %d\n", proximity_data);
        } else {
            fprintf(stderr, "Failed to read proximity data. Retrying...\n");
        }

        gpioDelay(500); // Wait for 500 milliseconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

