    *error_flag = 0; // Reset error flag

    // Read ambient light data
    result = i2cReadI2CBlockData(i2c_handle, OPT3101_REG_AMBIENT, buf, 4); // Read 4 bytes
    if (result != 4) {
        fprintf(stderr, "Error reading ambient light data: %d\n", result);
        *error_flag = 1; // Set error flag
        return -1;
    }
    *ambient_light = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3]; // Combine bytes into a 32-bit integer
    *error_flag = 0; // Reset error flag

    return 0;
}

