#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define MAGIC_WORD 0x89ABCD89
#define RANGE_PROFILE_SIZE 128
#define INTRUSION_THRESHOLD 1.0
#define ALERT_LED_GPIO 17
#define ALERT_DURATION 2 // seconds

// Global variables
int uart_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for range profile data
typedef struct {
    float distance_bins[64];
} RangeProfile;

// Function prototypes
int initialize_uart();
int read_range_profile(RangeProfile *profile);
int validate_range_profile(const RangeProfile *profile);
float calculate_distance_bin(const unsigned char *data, int bin_index);
int detect_intrusion(const RangeProfile *profile);
int log_intrusion(const RangeProfile *profile);
void activate_alert_led();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    printf("UART initialized on %s at %d baud\n", UART_DEVICE, BAUD_RATE);
    return 0;
}

// Read range profile from UART
int read_range_profile(RangeProfile *profile) {
    unsigned char buffer[RANGE_PROFILE_SIZE + MAGIC_WORD_LENGTH];
    int bytes_read = 0;

    // Read magic word
    if (serRead(uart_handle, &MAGIC_WORD, MAGIC_WORD_LENGTH) != MAGIC_WORD_LENGTH) {
        fprintf(stderr, "Error reading magic word\n");
        return -1;
    }

    // Read range profile data
    while (bytes_read < RANGE_PROFILE_SIZE) {
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            if (serRead(uart_handle, &buffer[bytes_read], available) != available) {
