#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
void activate_buzzer();
void deactivate_buzzer();
void log_state(int state);
void signal_handler(int signal);
void cleanup();

int main() {
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int previous_state = -1; // Initialize to an invalid state

    while (running) {
        int current_state = read_sensor();

        if (current_state != previous_state) {
            if (current_state == 0) {
                activate_buzzer();
                log_state(0);
            } else {
                deactivate_buzzer();
                log_state(1);
            }
            previous_state = current_state;
        }

        gpioDelay(100); // Poll every 100ms
    }

    cleanup();
    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1);
}

void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0);
}

void log_state(int state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Obstacle: %s\n", buf, state ? "Detected" : "Removed");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file not open!\n");
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

void cleanup() {
    printf("Cleaning up GPIO and closing log file...\n");
    deactivate_buzzer(); // Ensure buzzer is off

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

