#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x70
#define DISTANCE_REG 0x00 // Example register address
#define LED_GPIO 18
#define BLINK_DELAY_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(int *distance);
void set_led_frequency(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201
int read_distance(int *distance) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2) == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Set LED frequency based on distance
void set_led_frequency(int distance) {
    // Map distance (e.g., 0-1000mm) to frequency (e.g., 0-100Hz)
    float frequency = 100.0 - (float)distance / 100.0; // Invert for mapping
    if (frequency < 0.0) frequency = 0.0;
    if (frequency > 100.0) frequency = 100.0;

    // Calculate on/off time in milliseconds
    int on_time_ms = (int)(frequency * 10); // 10ms period
    int off_time_ms = (int)(10 - on_time_ms); // Total period is 10ms

    // Half-cycle blink
    if (distance > 500) { // Example threshold
        gpioWrite(LED_GPIO, 1); // LED on
        gpioDelay(on_time_ms * 1000); // Delay in microseconds
        gpioWrite(LED_GPIO, 0); // LED off
        gpioDelay(off_time_ms * 1000); // Delay in microseconds
    } else {
        gpioWrite(LED_GPIO, 0); // LED off
        gpioDelay(on_time_ms * 1000); // Delay in microseconds
        gpioWrite(LED_GPIO, 1); // LED on
        gpioDelay(off_time_ms * 1000); // Delay in microseconds
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    int distance;
    int init_result = 0;

    // Main loop
    while (!terminate) {
        init_result = init_i2c();
        if (init_result != 0) {
            fprintf(stderr, "I2C initialization failed, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        if (read_distance(&distance) == 0) {
            set_led_frequency(distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(BLINK_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

