#define DISTANCE_REG 0x00 // Example register address, adjust as needed
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
