int init_i2c(config_t *config) {
    i2c_handle = i2cOpen(config->i2c_bus, config->mlx75030_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from MLX75030
int read_distance(int i2c_handle, int *distance) {
    char buf[2];
    int result;

    // Trigger measurement (replace with actual trigger command if needed)
    result = i2cWriteByte(i2c_handle, DISTANCE_REG);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us

    // Read distance data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Combine bytes to form distance value
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

// Log data to file
int log_data(FILE *log_file, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

