        int sensor2_value = debounce(SENSOR_2_GPIO, DEBOUNCE_MS);

        if (sensor1_value < 0 || sensor2_value < 0) {
            // Error occurred during debouncing, exit loop
            break;
        }

        if (sensor1_value == 0) {
            if (log_event(1, "DETECTED") != 0) {
                fprintf(stderr, "Error logging sensor 1 event\n");
            }
        } else {
            if (log_event(1, "CLEARED") != 0) {
