            }
        }

        if (sensor2_value == 0) {
            if (log_event(2, "DETECTED") != 0) {
                fprintf(stderr, "Error logging sensor 2 event\n");
            }
        } else {
            if (log_event(2, "CLEARED") != 0) {
                fprintf(stderr, "Error logging sensor 2 event\n");
            }
        }

        gpioDelay(10000); // 10ms delay
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

