int read_distance(int fd) {
    char buf[DISTANCE_SIZE];
    int result = i2cReadI2CBlockData(fd, DISTANCE_REG, buf, DISTANCE_SIZE);

    if (result < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a single 16-bit value
    int distance_mm = (buf[0] << 8) | buf[1];
    return distance_mm;
}

