#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// VL53L5CX I2C address
#define VL53L5CX_ADDR 0x29

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Register definitions (Example - adjust based on datasheet)
#define REG_IDENTIFICATION_MODEL_ID 0x00c0
#define REG_SYSRANGE_START 0x0040
#define REG_RESULT_RANGE_STATUS 0x0014
#define REG_RESULT_SPAD_NB 0x0022
#define REG_RESULT_DISTANCE 0x001E
#define REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define REG_I2C_SLAVE_DEVICE_ADDRESS_VALUE 0x00
#define REG_SYSRANGE_CONFIG 0x001E
#define REG_ZONE_CONFIG 0x001A

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t stop_flag = 0;

// Signal handler for Ctrl+C
void sigint_handler(int sig) {
    stop_flag = 1;
}

// Function to write a register value
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a register value
int read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L5CX sensor
int init_vl53l5cx(int fd) {
    // Example initialization sequence (adjust based on datasheet)
    if (write_register(fd, REG_I2C_SLAVE_DEVICE_ADDRESS, REG_I2C_SLAVE_DEVICE_ADDRESS_VALUE) < 0) return -1;
    if (write_register(fd, REG_SYSRANGE_CONFIG, 0x01) < 0) return -1; // Example value
    if (write_register(fd, REG_ZONE_CONFIG, 0x08) < 0) return -1; // 8x8 grid

    // Check sensor ID (Example)
    uint8_t sensor_id;
    if (read_register(fd, REG_IDENTIFICATION_MODEL_ID, &sensor_id) < 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    printf("VL53L5CX sensor initialized successfully.\n");
    return 0;
}

// Function to read distance data from the VL53L5CX sensor
int read_distance_data(int fd, uint16_t *distances) {
    // Start a measurement
    if (write_register(fd, REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Failed to start measurement\n");
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    usleep(10000); // 10ms

    // Read distance data for each zone
    for (int i = 0; i < 64; i++) {
        uint8_t distance;
        if (read_register(fd, REG_RESULT_DISTANCE + (i * 2), &distance) < 0) {
            fprintf(stderr, "Failed to read distance for zone %d\n", i);
            return -1;
        }
        distances[i] = (uint16_t)distance;
    }

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize the sensor
    if (init_vl53l5cx(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize VL53L5CX sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        uint16_t distances[64];
        if (read_distance_data(i2c_fd, distances) == 0) {
            // Log distance data to console
            printf("Zone 0: %u mm, Zone 1: %u mm, ", distances[0], distances[1]);
            for (int i = 2; i < 64; i++) {
                printf("%u ", distances[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Failed to read distance data\n");
        }

        // Wait 500ms
        usleep(500000);
    }

    // Close I2C bus
    close(i2c_fd);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

