#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define the I2C bus and address for the MLX75030 sensor
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for distance data (replace with actual address)
#define DISTANCE_REG 0x00

// Define the number of retries for I2C transactions
#define I2C_RETRIES 3

// Define the delay between I2C retries (in milliseconds)
#define I2C_RETRY_DELAY 10

// Global variable to store the I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read distance data from the MLX75030 sensor
int read_distance(uint16_t *distance) {
    char buf[2];
    int result;

    for (int i = 0; i < I2C_RETRIES; ++i) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(I2C_RETRY_DELAY * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", I2C_RETRIES);
    return -1; // Failure
}

// Function to log the distance measurement with a timestamp
void log_distance(uint16_t distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%ld.%09ld: Distance = %u mm\n", ts.tv_sec, ts.tv_nsec, distance);
}

int main() {
    // Register the signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and I2C
    if (initialize() != 0) {
        return 1;
    }

    uint16_t distance;

    // Main loop to read and log distance measurements
    while (1) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(100000); // Delay for 100 milliseconds (100000 microseconds)
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

