#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_STATUS 0x0010
#define VL53L4CX_REG_DISTANCE 0x0014

// I2C handle
int i2c_handle;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to read the distance from the VL53L4CX sensor
int read_distance(int handle) {
    int distance = i2cReadByteData(handle, VL53L4CX_REG_DISTANCE);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance);
        return -1;
    }
    return distance;
}

// Function to get the current timestamp with microsecond precision
void get_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + 19, 7, ".%06ld", ts.tv_nsec / 1000);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read interrupt status
        int status = i2c_read_byte(i2c_handle, VL53L4CX_REG_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status, skipping cycle.\n");
            gpioDelay(500000); // Wait 500ms
            continue;
        }

        // Check if a new measurement is available (bit 0 of status register is set)
        if (status & 0x01) {
            // Read distance
            int distance = read_distance(i2c_handle);
            if (distance >= 0) {
                // Get timestamp
                char timestamp[26];
                get_timestamp(timestamp);

                // Print timestamp and distance
                printf("%s, Distance: %d mm\n", timestamp, distance);
            } else {
                fprintf(stderr, "Error reading distance, skipping cycle.\n");
            }
        } else {
            // No new measurement available, skip cycle
            gpioDelay(500000); // Wait 500ms
        }
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

