    // Example initialization sequence (refer to VL53L1X datasheet)
    // This is a simplified example and might need adjustments
    char data[2];

    // Example: Set some registers (replace with actual register addresses and values)
    data[0] = 0x00; // Register address
    data[1] = 0x01; // Value to write

    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to VL53L1X during initialization\n");
        return -1;
    }

    // Set continuous ranging mode (example)
    data[0] = 0x00; // Register address
    data[1] = 0x02; // Value to write

    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error setting continuous ranging mode\n");
        return -1;
    }

    return 0;
}

