    char cmd[1];
    char data[2];
    int distance;

    // Example: Read distance (replace with actual register addresses)
    cmd[0] = 0x01; // Register address to read from

    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Error writing to VL53L1X for distance read\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading distance from VL53L1X\n");
        return -1;
    }

    distance = (data[0] << 8) | data[1]; // Combine the two bytes into a 16-bit distance

    return distance;
}

