        gpioDelay(500); // Wait 500 ms
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate();

    return 0;
}

