#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_MS 50          // Timeout in milliseconds
#define MIN_DISTANCE 2.0       // Minimum distance in cm
#define MAX_DISTANCE 400.0     // Maximum distance in cm
#define MIN_ANGLE -90.0         // Minimum servo angle
#define MAX_ANGLE +90.0         // Maximum servo angle

// Global variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
float measure_distance();
float map_distance_to_angle(float distance);
int set_servo_angle(float angle);
void log_data(float distance, float angle);
void signal_handler(int signal);

// Function to measure distance using HC-SR04
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to start
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_MS) {
        timeout++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout >= TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_MS) {
        timeout++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout >= TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Timeout error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (diff * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 to convert one-way distance to round-trip

    return distance;
}

// Function to map distance to servo angle
float map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set servo angle
int set_servo_angle(float angle) {
    // Convert angle to pulse width (500-2500 us)
    int pulse_width = (int)(500 + (angle * 2000.0 / 180.0));

    // Set servo pulse width
    gpioServo(SERVO_PIN, pulse_width);
    return 0; // Indicate success
}

// Function to log data to file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %.2f degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measure_distance();
        float angle = 0.0;

        if (distance > 0) {
            angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) != 0) {
                fprintf(stderr, "Error setting servo angle\n");
            }
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Sensor timeout, skipping reading\n");
        }

        gpioDelay(200); // Delay 200 ms
    }

    // Cleanup
    gpioServo(SERVO_PIN, 0); // Stop servo
    fclose(log_file);
    gpioTerminate(); // Terminate pigpio

    printf("Parking assist system stopped.\n");
    return 0;
}

