#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/msg.h>
#include <pigpio.h>
#include <errno.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define DISTANCE_THRESHOLD 100 // mm
#define BUZZER_GPIO 23
#define MSG_QUEUE_NAME "/distance_queue"
#define MAX_MSG_SIZE 256

// VL53L1X Register Addresses (Example - Refer to Datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global Variables
int i2c_handle;
int msg_queue_id;
volatile sig_atomic_t terminate = 0;

// Structure for message queue data
struct msgbuf {
    long mtype; // Message type (must be > 0)
    char message[MAX_MSG_SIZE];
};

// Function Prototypes
int init_i2c();
int init_vl53l1x();
int read_distance(int *distance);
void activate_buzzer();
void deactivate_buzzer();
void log_distance(int distance);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (Refer to VL53L1X datasheet)
    // This is a simplified example and may need adjustments based on the sensor's configuration.
    char data[2];

    // Check sensor ID (example)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error writing to I2C (sensor ID check): %s\n", strerror(errno));
        return -1;
    }
    data[0] = 0x01; // Example model ID
    data[1] = 0x00;
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to I2C (sensor ID check response): %s\n", strerror(errno));
        return -1;
    }

    // Start ranging (example)
    data[0] = 0x00; // Register address for starting ranging
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error writing to I2C (start ranging): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X
int read_distance(int *distance) {
    char cmd[1];
    char data[2];
    int result;

    // Trigger a single measurement (example - refer to datasheet for correct command)
    cmd[0] = VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY; // Trigger measurement
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C (trigger measurement): %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to be ready (polling - improve with interrupts if possible)
    int ready = 0;
    int timeout = 100; // Timeout in ms
    while (!ready && timeout > 0) {
        data[0] = VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY;
        if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
            fprintf(stderr, "Error writing to I2C (check ready): %s\n", strerror(errno));
            return -1;
        }
        int status = i2cReadDevice(i2c_handle, data, 1);
        if (status != 1) {
            fprintf(stderr, "Error reading from I2C (check ready): %s\n", strerror(errno));
            return -1;
        }
        if (data[0] & 0x01) {
            ready = 1;
        }
        gpioDelay(1); // Small delay
        timeout--;
    }

    if (!ready) {
        fprintf(stderr, "Timeout waiting for measurement.\n");
        return -1;
    }

    // Read distance data (example - refer to datasheet for correct registers)
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error writing to I2C (read distance): %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C (read distance): %s\n", strerror(errno));
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Set GPIO HIGH
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0); // Set GPIO LOW
}

// Function to log distance to message queue
void log_distance(int distance) {
    struct msgbuf msg;
    msg.mtype = 1; // Message type (must be > 0)
    msg.message[MAX_MSG_SIZE - 1] = '\0'; // Ensure null termination

    // Format the message
    snprintf(msg.message, MAX_MSG_SIZE, "Distance: %d mm", distance);

    // Send the message
    if (msgsnd(msg_queue_id, &msg, strlen(msg.message), 0) == -1) {
        fprintf(stderr, "Error sending message: %s\n", strerror(errno));
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    deactivate_buzzer(); // Ensure buzzer is off
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (msg_queue_id > 0) {
        msgrcv(-1, &msg, 0, 0, 0); // Clear any pending messages
        msgctl(msg_queue_id, IPC_RMID, NULL); // Remove the message queue
    }
    gpioTerminate();
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    deactivate_buzzer(); // Ensure buzzer is initially off

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        cleanup();
        return 1;
    }

    // Create message queue
    msg_queue_id = msgget(MSG_QUEUE_NAME, IPC_CREAT | 0666);
    if (msg_queue_id == -1) {
        fprintf(stderr, "Error creating message queue: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);
            log_distance(distance);

            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer();
            } else {
                deactivate_buzzer();
            }
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }

        gpioDelay(50); // 50ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

