#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define MIN_DISTANCE_CM 2.0   // Minimum distance in cm
#define MAX_DISTANCE_CM 400.0 // Maximum distance in cm
#define BUZZER_ACTIVE_TIME_MS 200 // Buzzer active time in milliseconds

