#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200 // mm
#define SERVO_OPEN_PULSE 1500
#define SERVO_CLOSE_PULSE 1000
#define SERVO_NEUTRAL_PULSE 1500
#define SERVO_RANGE 500
#define SERVO_FREQUENCY 50
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to initialize VL53L1X sensor
int init_vl53l1x() {
    // Software reset
    char data[2];
    data[0] = 0x00; // Reset command
    data[1] = 0x01; // Reset value
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Failed to send reset command\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Check sensor ID (example)
    char id;
    if (i2cReadDevice(i2c_handle, &id, 1) != 1) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return -1;
    }
    if (id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    // Start ranging
    data[0] = VL53L1X_REG_SYSRANGE_START;
    data[1] = 0x01; // Start ranging
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X
int read_distance() {
    char cmd[1];
    char data[2];
    int distance = -1;
    int retries = 0;

    // Read range status
    cmd[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Failed to write range status register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read range status\n");
        return -1;
    }
    int status = (data[0] << 8) | data[1];

    // Read distance
    cmd[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Failed to write distance register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read distance\n");
        return -1;
    }
    distance = (data[0] << 8) | data[1];

    return distance;
}

// Function to open the gate
void open_gate() {
    gpioPWM(SERVO_PIN, SERVO_OPEN_PULSE);
    log_event("Gate opened");
}

// Function to close the gate
void close_gate() {
    gpioPWM(SERVO_PIN, SERVO_CLOSE_PULSE);
    log_event("Gate closed");
}

// Function to log events
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    close_gate();
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize logging
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Distance: %d mm", distance);
        log_event(log_message);

        if (distance < DISTANCE_THRESHOLD) {
            open_gate();
        } else {
            close_gate();
        }

        gpioDelay(100 * 1000); // Delay 100ms
    }

    cleanup();
    return 0;
}

