#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_PULSE_WIDTH 100.0  // Minimum pulse width in microseconds
#define MAX_PULSE_WIDTH 30000.0 // Maximum pulse width in microseconds
#define TIMEOUT_THRESHOLD 60000 // Timeout threshold in microseconds

// Global variables
static volatile int rising_tick = 0;
static volatile int falling_tick = 0;
static volatile int echo_received = 0;
static volatile int echo_valid = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
int initialize_gpio();

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_tick = tick;
        echo_received = 1;
    } else if (level == 0) {
        falling_tick = tick;
        echo_received = 1;
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) {
        return -1.0; // Indicate invalid reading
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        return -2.0; // Indicate timeout or no object
    } else {
        return (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;
    }
}

// Function to log distance to stdout and file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }

    printf("%s,%.2f\n", timestamp, distance);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    // Register interrupt callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO pin\n");
        gpioTerminate();
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        gpioDelay(200); // Wait 200ms

        if (echo_received) {
            int pulse_width = falling_tick - rising_tick;
            if (pulse_width > 0) {
                double distance = calculate_distance(pulse_width);

