            }
        } else {
            log_distance(-1.0); // Log invalid reading
            fprintf(stderr, "Timeout occurred.\n");
        }
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
