    }
    gpioDelay(10000); // Wait for reset to complete

    // Configure timing budget (example: 50ms)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_TIMING_BUDGET, 0x32) < 0) {
        fprintf(stderr, "Error: Failed to set timing budget: %s\n", strerror(errno));
        return -1;
    }

    // Start ranging (example: short range mode)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    char data[2];
    int distance;

    // Read range status
    if (i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS) < 0) {
        fprintf(stderr, "Error: Failed to read range status: %s\n", strerror(errno));
        return -1;
    }

    // Read distance data
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) < 0) {
        fprintf(stderr, "Error: Failed to read distance: %s\n", strerror(errno));
        return -1;
    }

    distance = (data[0] << 8) | data[1];

    return distance;
}

// Open the gate
void open_gate() {
    gpioWrite(GATE_GPIO, 1);
    gpioWrite(GATE_CLOSE_GPIO, 0);
    log_event("Gate opened");
    gpioDelay(GATE_OPEN_DURATION * 1000000); // Keep open for specified duration
    close_gate();
}

// Close the gate
void close_gate() {
    gpioWrite(GATE_GPIO, 0);
    gpioWrite(GATE_CLOSE_GPIO, 1);
    log_event("Gate closed");
}

// Log an event to the log file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: Failed to read distance, retrying...\n");
            gpioDelay(100000); // Wait before retrying
            continue;
        }

        printf("Distance: %d mm\n", distance);

        if (distance < DISTANCE_THRESHOLD) {
            open_gate();
        } else {
            close_gate();
        }

        gpioDelay(POLL_INTERVAL * 1000); // Poll every 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

