// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pins
#define MOTOR_FORWARD 17
#define MOTOR_BACKWARD 18
#define DISTANCE_SENSOR_PIN 24

// Distance thresholds
#define DISTANCE_LOW 100
#define DISTANCE_HIGH 300

// VL53L1X register addresses
