#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile int distance_ready = 0;
volatile int distance = 0;
volatile int motor_state = 0; // 0: stopped, 1: forward, 2: backward

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void motor_forward();
void motor_backward();
void motor_stop();
void signal_handler(int signal);

// VL53L1X initialization sequence
int vl53l1x_init() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01); // Reset command
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X reset failed (error code %d)\n", status);
        return -1;
    }
    gpioDelay(1); // Delay for reset to complete

    // Start measurement
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x02); // Start measurement
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X start measurement failed (error code %d)\n", status);
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int vl53l1x_read_distance() {
    int status;
    unsigned char data[2];

    // Read range status
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X range status read failed (error code %d)\n", status);
        return -1;
    }

    // Read distance data
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X distance read failed (error code %d)\n", status);
        return -1;
    }

    distance = (data[0] << 8) | data[1];
    return 0;
}

// Motor control functions
void motor_forward() {
    gpioWrite(MOTOR_FORWARD, 1);
    gpioWrite(MOTOR_BACKWARD, 0);
    motor_state = 1;
}

void motor_backward() {
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 1);
    motor_state = 2;
}

void motor_stop() {
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);
    motor_state = 0;
}

