void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    int distance_threshold;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(DISTANCE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(DISTANCE_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (error code %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt on distance sensor pin
    gpioSetISRFuncEx(DISTANCE_SENSOR_PIN, RISING_EDGE, 0, distanceISR, NULL);

    printf("VL53L1X sensor and motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (distance_ready) {
            distance_ready = 0; // Reset the flag
            distance_threshold = (distance < DISTANCE_LOW) ? DISTANCE_LOW : (distance > DISTANCE_HIGH) ? DISTANCE_HIGH : distance;

            if (distance_threshold != distance) {
                printf("Distance: %d mm, Threshold: %d mm\n", distance, distance_threshold);

                if (distance_threshold == DISTANCE_LOW) {
                    motor_forward();
                } else if (distance_threshold == DISTANCE_HIGH) {
                    motor_backward();
                } else {
                    motor_stop();
                }
            }
        }
        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    return 0;
}

// Interrupt service routine for distance sensor pin
void distanceISR(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge detected
        distance_ready = 1;
    }
}

