#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define MPR121 I2C address
#define MPR121_ADDR 0x5A

// Define MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// Define GPIO pins for LEDs
#define LED0_PIN 17
#define LED1_PIN 18
#define LED2_PIN 27
#define LED3_PIN 22

// Define proximity threshold
#define PROXIMITY_THRESHOLD 0x0A

// Define LED patterns
typedef struct {
    uint8_t pattern[4];
} LedPattern;

LedPattern led_patterns[] = {
    {0x0F, 0x00, 0x00, 0x00}, // All LEDs on
    {0x00, 0x0F, 0x00, 0x00}, // All LEDs off
    {0x0F, 0x00, 0x00, 0x0F}, // Alternating LEDs
    {0x00, 0x00, 0x0F, 0x0F}  // Alternating LEDs inverted
};

// Define the number of LED patterns
#define NUM_LEDPATTERNS (sizeof(led_patterns) / sizeof(led_patterns[0]))

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
void set_led_pattern(uint8_t pattern_index);
void log_proximity_event(int electrode_number);
void signal_handler(int signal);

// Function to initialize the MPR121 sensor
int mpr121_init() {
    // Reset the sensor
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121. Error code: %d\n", errno);
        return -1;
    }
    delay(100); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x00) < 0) { // Exit Electrode Config Mode
        fprintf(stderr, "Error: Failed to exit ECR mode. Error code: %d\n", errno);
        return -1;
    }

    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG1, 0x20) < 0) { // Set Electrode Configuration
        fprintf(stderr, "Error: Failed to set electrode config. Error code: %d\n", errno);
        return -1;
    }

    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG2, 0x10) < 0) { // Set Electrode Configuration
        fprintf(stderr, "Error: Failed to set electrode config. Error code: %d\n", errno);
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(uint16_t *touch_status) {
    int lsb = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_L);
    int msb = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_H);

    if (lsb < 0 || msb < 0) {
        fprintf(stderr, "Error: Failed to read touch status. Error code: %d\n", errno);
        return -1;
    }

    *touch_status = ((uint16_t)msb << 8) | lsb;
    return 0;
}

// Function to set the LED pattern based on the index
void set_led_pattern(uint8_t pattern_index) {
    if (pattern_index < 0 || pattern_index >= NUM_LEDPATTERNS) {
        fprintf(stderr, "Error: Invalid LED pattern index: %d\n", pattern_index);
        return;
    }

    uint8_t pattern[4] = led_patterns[pattern_index].pattern;
    digitalWrite(LED0_PIN, pattern[0]);
    digitalWrite(LED1_PIN, pattern[1]);
    digitalWrite(LED2_PIN, pattern[2]);
    digitalWrite(LED3_PIN, pattern[3]);
}

// Function to log a proximity event
void log_proximity_event(int electrode_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Proximity detected on electrode %d\n", timestamp, electrode_number);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize WiringPi. Error code: %d\n", errno);
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C. Error code: %d\n", errno);
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init() == -1) {
        fprintf(stderr, "Error: Failed to initialize MPR121 sensor.\n");
        return 1;
    }

    // Set GPIO pins as output
    pinMode(LED0_PIN, OUTPUT);
    pinMode(LED1_PIN, OUTPUT);
    pinMode(LED2_PIN, OUTPUT);
    pinMode(LED3_PIN, OUTPUT);

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file. Error code: %d\n", errno);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;

    // Main loop
    while (running) {
        // Read touch status
        if (mpr121_read_touch_status(&touch_status) == -1) {
            fprintf(stderr, "Error: Failed to read touch status. Continuing...\n");
            delay(50);
            continue;
        }

        // Check each electrode for proximity
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                // Proximity detected
                printf("Proximity detected on electrode %d\n", i);

                // Log the event
                log_proximity_event(i);

                // Set the LED pattern
                for (int j = 0; j < NUM_LEDPATTERNS; j++) {
                    set_led_pattern(j);
                    delay(100); // Short delay to see the pattern
                }
            }
        }

        // Delay for 50ms
        delay(50);
    }

    // Cleanup
    fclose(log_file);
    // No need to release GPIO pins, wiringPiSetupGpio() handles it on exit

    return 0;
}

