// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_PULSE_WIDTH 58.0  // Minimum pulse width in microseconds (1cm)
#define MAX_PULSE_WIDTH 25000.0 // Maximum pulse width in microseconds (4m)
#define MAX_DISTANCE 4000.0    // Maximum distance in meters (4m)
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_width = 0;
static volatile int echo_received = 0;
static volatile int echo_valid = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
void log_distance(float distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt service routine (ISR) for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        echo_received = 1;
    } else if (level == 0) {
        pulse_end = tick;
        pulse_width = pulse_end - pulse_start;
        echo_valid = 1; // Mark the pulse as valid after both edges are received
    }
}

