#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x1E
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x1D

// GPIO pin for XSHUT
#define XSHUT_PIN 27

// I2C file descriptor
int i2c_fd;

// Function prototypes
int init_i2c(int address);
int init_vl53l1x(int fd);
int read_distance(int fd);
void log_data(int distance, int status);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, closing I2C and exiting.");
    close(i2c_fd);
    syslog(LOG_INFO, "I2C closed.");
    exit(0);
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
        close(fd);
        return -1;
    }

    syslog(LOG_INFO, "I2C bus initialized with address 0x%02X", address);
    return fd;
}

// Initialize VL53L1X sensor
int init_vl53l1x(int fd) {
    // Example initialization sequence (adjust based on datasheet)
    uint8_t data[2];

    // Check sensor ID (example)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    if (write(fd, data, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to sensor: %s", strerror(errno));
        return -1;
    }
    uint8_t model_id;
    if (read(fd, &model_id, 1) != 1) {
        syslog(LOG_ERR, "Failed to read sensor ID: %s", strerror(errno));
        return -1;
    }
    if (model_id != 0xEE) { // Expected value for VL53L1X
        syslog(LOG_ERR, "Incorrect sensor ID: 0x%02X", model_id);
        return -1;
    }

    // Example: Set some registers (adjust based on datasheet)
    data[0] = 0x02D8; // Register to write
    data[1] = 0x01;   // Value to write
    if (write(fd, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to write to sensor: %s", strerror(errno));
        return -1;
    }

    data[0] = 0x02D9; // Register to write
    data[1] = 0x00;   // Value to write
    if (write(fd, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to write to sensor: %s", strerror(errno));
        return -1;
    }

    syslog(LOG_INFO, "VL53L1X sensor initialized.");
    return 0;
}

// Read distance from VL53L1X
int read_distance(int fd) {
    uint8_t data[1];
    uint8_t result;
    int distance = -1; // Default to error value

    // Start a measurement
    data[0] = VL53L1X_REG_SYSRANGE_START;
    if (write(fd, data, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to sensor: %s", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (polling - adjust timeout as needed)
    int timeout = 100; // Timeout in milliseconds
    while (timeout > 0) {
        data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
        if (write(fd, data, 1) != 1) {
            syslog(LOG_ERR, "Failed to write to sensor: %s", strerror(errno));
            return -1;
        }
        if (read(fd, &result, 1) != 1) {
            syslog(LOG_ERR, "Failed to read from sensor: %s", strerror(errno));
            return -1;
        }

        if (result & 0x01) { // Check if data is ready (example)
            break;
        }
        usleep(1000); // Wait 1ms
        timeout--;
    }

    if (timeout == 0) {
        syslog(LOG_ERR, "Timeout waiting for measurement.");
        return -1;
    }

    // Read distance (example - adjust based on datasheet)
    uint8_t distance_bytes[2];
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    if (write(fd, data, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to sensor: %s", strerror(errno));
        return -1;
    }
    if (read(fd, distance_bytes, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance: %s", strerror(errno));
        return -1;
    }

    distance = (distance_bytes[0] << 8) | distance_bytes[1];

    return distance;
}

// Log data to syslog
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s, Distance: %d mm, Status: %d", timestamp, distance, status);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Set XSHUT pin as output
    pinMode(XSHUT_PIN, OUTPUT);
    digitalWrite(XSHUT_PIN, HIGH); // Enable sensor

    // Initialize syslog
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(VL53L1X_ADDR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "I2C initialization failed, exiting.");
        closelog();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x(i2c_fd) < 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed, exiting.");
        close(i2c_fd);
        closelog();
        return 1;
    }

    // Main loop
    while (1) {
        int distance = read_distance(i2c_fd);
        if (distance != -1) {
            int status = 0; // No error
        } else {
            int status = -1; // Error reading distance
        }

        log_data(distance, status);

        usleep(100000); // 100ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    closelog();
    return 0;
}

