#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT 30.0 // milliseconds
#define MIN_DISTANCE 2.0 // cm
#define MAX_DISTANCE 400.0 // cm
#define MIN_PULSE_WIDTH 500 // us
#define MAX_PULSE_WIDTH 2500 // us
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MOVING_AVG_SIZE 5

// Global variables
volatile sig_atomic_t program_running = 1;
volatile int new_pulse = 0;
volatile int pulse_width = 0;
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
int set_servo_angle(int angle);
int log_data(double distance, int angle);
int filter_distance(double new_distance);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Trigger pulse function
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Echo callback function
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 0; // Reset flag
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_received = 1; // Set flag
    }
}

// Calculate distance from pulse width
double calculate_distance(int pulse_width) {
    if (pulse_width <= 0) return -1.0; // Invalid pulse width
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Set servo angle function
int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d)\n", angle);
        return -1; // Indicate error
    }
    int pulse_width = (int)(500 + (angle * 2000 / 180)); // Map angle to pulse width (500-2500 us)
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d)\n", pulse_width);
        return -1; // Indicate error
    }
    gpioServo(SERVO_PIN, pulse_width);
    return 0; // Indicate success
}

// Log data to CSV file
int log_data(double distance, int angle) {
    FILE *fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1; // Indicate error
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Distance (cm),Angle (degrees)\n");
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, distance, angle);

    fclose(fp);
    return 0; // Indicate success
}

// Filter distance with moving average
int filter_distance(double new_distance) {
    static double distances[MOVING_AVG_SIZE] = {0.0}; // Initialize with zeros
    static int index = 0;
    static int count = 0;

    if (new_distance >= MIN_DISTANCE && new_distance <= MAX_DISTANCE) {
        distances[index] = new_distance;
        index = (index + 1) % MOVING_AVG_SIZE;
        count++;

        if (count >= MOVING_AVG_SIZE) {
            double sum = 0.0;
            for (int i = 0; i < MOVING_AVG_SIZE; i++) {
                sum += distances[i];
            }
            return (sum / MOVING_AVG_SIZE);
        }
    } else {
        return -1.0; // Indicate invalid distance
    }
}

// Initialize pigpio and GPIO pins
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1; // Indicate error
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioServo(SERVO_PIN, 1500); // Initialize servo to 90 degrees

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    return 0; // Indicate success
}

// Cleanup function
void cleanup() {
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();
}

int main() {
    if (initialize() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Ultrasonic sensor and servo control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_pulse();
        gpioDelay(100); // 100 ms delay

        if (echo_received) {
            int pulse_width = pulse_width;
            pulse_width = 0; // Reset for next reading
            new_pulse = 0; // Reset flag
            echo_received = 0; // Reset flag

            double filtered_distance = filter_distance(calculate_distance(pulse_width));

            if (filtered_distance >= MIN_DISTANCE && filtered_distance <= MAX_DISTANCE) {
                int angle = set_servo_angle((int)(filtered_distance / 2.0)); // Map distance to angle (0-180)
                if (angle != -1) {
                    log_data(filtered_distance, angle);
                }
            } else {
                log_data(-1.0, 90); // Log -1.0 and set servo to 90 degrees
            }
        }
    }

    cleanup();
    return 0;
}

