// Helper function to write a byte to a register
int write_register(int i2c_handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Helper function to read a byte from a register
int read_register(int i2c_handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the Si1102 sensor
int init_sensor(int i2c_handle) {
    uint8_t part_id;

    // Verify Part ID
    if (read_register(i2c_handle, SI1102_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading Part ID\n");
        return -1;
    }
    if (part_id != 0x52) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Reset the sensor
    if (write_register(i2c_handle, SI1102_REG_COMMAND, 0x01) != 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure measurement rate
    if (write_register(i2c_handle, SI1102_REG_MEAS_RATE0, 0x0A) != 0) {
        fprintf(stderr, "Error configuring measurement rate\n");
        return -1;
    }
    if (write_register(i2c_handle, SI1102_REG_MEAS_RATE1, 0x00) != 0) {
        fprintf(stderr, "Error configuring measurement rate\n");
        return -1;
    }

    // Enable ALS IR and Visible sensors
    if (write_register(i2c_handle, SI1102_REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "Error writing HW_KEY\n");
        return -1;
    }

    // Configure ALS IR ADC
    if (write_register(i2c_handle, SI1102_REG_ALS_IR_ADC_MISC, 0x00) != 0) {
        fprintf(stderr, "Error configuring ALS IR ADC misc\n");
        return -1;
    }

    // Configure ALS Visible ADC
    if (write_register(i2c_handle, SI1102_REG_ALS_VIS_ADC_MISC, 0x00) != 0) {
        fprintf(stderr, "Error configuring ALS Visible ADC misc\n");
        return -1;
    }

    // Enable interrupt on rising edge of ALS IR
    if (write_register(i2c_handle, SI1102_REG_IRQ_ENABLE, 0x01) != 0) {
        fprintf(stderr, "Error enabling interrupt\n");
        return -1;
    }

    // Set interrupt mode to level
    if (write_register(i2c_handle, SI1102_REG_IRQ_MODE1, 0x00) != 0) {
        fprintf(stderr, "Error setting interrupt mode\n");
        return -1;
    }

    // Set interrupt mode to rising edge
    if (write_register(i2c_handle, SI1102_REG_IRQ_MODE2, 0x01) != 0) {
        fprintf(stderr, "Error setting interrupt mode\n");
        return -1;
    }

    // Set interrupt mode to active low
    if (write_register(i2c_handle, SI1102_REG_IRQ_MODE3, 0x00) != 0) {
        fprintf(stderr, "Error setting interrupt mode\n");
        return -1;
    }

    return 0;
}

// Read proximity value from the sensor
int read_proximity(int i2c_handle) {
    uint8_t als_ir_data0, als_ir_data1, als_vis_data0, als_vis_data1;
    int proximity_value;

    if (read_register(i2c_handle, SI1102_REG_ALS_IR_DATA0, &als_ir_data0) != 0 ||
        read_register(i2c_handle, SI1102_REG_ALS_IR_DATA1, &als_ir_data1) != 0 ||
        read_register(i2c_handle, SI1102_REG_ALS_VIS_DATA0, &als_vis_data0) != 0 ||
        read_register(i2c_handle, SI1102_REG_ALS_VIS_DATA1, &als_vis_data1) != 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    proximity_value = (als_ir_data1 << 8) | als_vis_data1;

    return proximity_value;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused

    interrupt_flag = 1;
}

// Log proximity data to file
void log_proximity(int proximity_value, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen("proximity.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening proximity.log\n");
        return;
    }

    fprintf(fp, "%s, %d, %s\n", timestamp, proximity_value, status);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // unused
    running = 0;
    interrupt_flag = 0;
