// Initialize the Si1102 sensor
int init_sensor(int i2c_handle) {
    uint8_t part_id;

    // Verify Part ID
    if (read_register(i2c_handle, SI1102_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading Part ID\n");
        return -1;
    }
    if (part_id != 0x52) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Reset the sensor
    if (write_register(i2c_handle, SI1102_REG_COMMAND, 0x01) != 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

