        return -1;
    }
    if (write_register(i2c_handle, SI1102_REG_MEAS_RATE1, 0x00) != 0) {
        fprintf(stderr, "Error configuring measurement rate\n");
        return -1;
    }

    // Enable ALS IR and Visible sensors
    if (write_register(i2c_handle, SI1102_REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "Error writing HW_KEY\n");
        return -1;
    }

    // Configure ALS IR ADC
    if (write_register(i2c_handle, SI1102_REG_ALS_IR_ADC_MISC, 0x00) != 0) {
        fprintf(stderr, "Error configuring ALS IR ADC misc\n");
        return -1;
    }

    // Configure ALS Visible ADC
    if (write_register(i2c_handle, SI1102_REG_ALS_VIS_ADC_MISC, 0x00) != 0) {
        fprintf(stderr, "Error configuring ALS Visible ADC misc\n");
        return -1;
    }

