    if (write_register(i2c_handle, SI1102_REG_IRQ_ENABLE, 0x01) != 0) {
        fprintf(stderr, "Error enabling interrupt\n");
        return -1;
    }

    // Set interrupt mode to level
    if (write_register(i2c_handle, SI1102_REG_IRQ_MODE1, 0x00) != 0) {
        fprintf(stderr, "Error setting interrupt mode\n");
        return -1;
    }

    // Set interrupt mode to rising edge
    if (write_register(i2c_handle, SI1102_REG_IRQ_MODE2, 0x01) != 0) {
        fprintf(stderr, "Error setting interrupt mode\n");
        return -1;
    }

    // Set interrupt mode to active low
    if (write_register(i2c_handle, SI1102_REG_IRQ_MODE3, 0x00) != 0) {
        fprintf(stderr, "Error setting interrupt mode\n");
        return -1;
    }

    return 0;
}

// Read proximity value from the sensor
int read_proximity(int i2c_handle) {
    uint8_t als_ir_data0, als_ir_data1, als_vis_data0, als_vis_data1;
    int proximity_value;

    if (read_register(i2c_handle, SI1102_REG_ALS_IR_DATA0, &als_ir_data0) != 0 ||
