        read_register(i2c_handle, SI1102_REG_ALS_VIS_DATA0, &als_vis_data0) != 0 ||
        read_register(i2c_handle, SI1102_REG_ALS_VIS_DATA1, &als_vis_data1) != 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    proximity_value = (als_ir_data1 << 8) | als_vis_data1;

    return proximity_value;
}

