#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0    // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TIMEOUT_MS 200         // Timeout for echo in milliseconds

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
float measure_distance();
float map_distance_to_frequency(float distance);
void set_pwm_frequency(float frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to start
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_MS) {
        timeout++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout >= TIMEOUT_MS) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_MS) {
        timeout++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout >= TIMEOUT_MS) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 to get one-way distance

    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Logarithmic mapping
    float frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (1.0 - log10(distance / MIN_DISTANCE) / log10(MAX_DISTANCE / MIN_DISTANCE));

    return frequency;
}

// Function to set PWM frequency
void set_pwm_frequency(float frequency) {
    if (frequency < 0.0 || frequency > 5000.0) {
        fprintf(stderr, "Error: Invalid frequency: %f\n", frequency);
        return;
    }

    int range = 50000; // PWM range (adjust as needed)
    int duty_cycle = range / 2; // 50% duty cycle

    gpioSetPWMfrequency(PWM_PIN, (int)frequency);
    gpioPWM(PWM_PIN, duty_cycle); // Set duty cycle
}

