#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000 // 50ms timeout

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measureEchoPulse() {
    long start_tick, end_tick, diff;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;

    return diff;
}

// Function to convert pulse duration to distance in centimeters
float distanceFromPulseDuration(long pulse_duration) {
    return (float)pulse_duration * 0.0343 / 2.0;
}

// Function to validate the distance reading
float validateDistance(float distance) {
    if (distance < 2.0 || distance > 400.0) {
        return -1.0; // Invalid reading
    }
    return distance;
}

// Function to print the distance with a timestamp
void printDistance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance < 10.0) {
        printf("%s Too close! Distance: %.2f cm\n", timestamp, distance);
    } else {
        printf("%s Distance: %.2f cm\n", timestamp, distance);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        triggerSensor();
        long pulse_duration = measureEchoPulse();
        float distance = distanceFromPulseDuration(pulse_duration);
        float validated_distance = validateDistance(distance);

        if (validated_distance >= 0.0) {
            printDistance(validated_distance);
        } else {
            fprintf(stderr, "Invalid reading\n");
        }

        gpioDelay(500); // 500 ms delay
    }

    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

