#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define ALS_DATA_REG 0x22
#define PROX_DATA_REG 0x24
#define PART_ID_REG 0x00
#define RESET_REG 0x07
#define RESET_VALUE 0x01
#define LOG_FILE "si1120_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *als, int *prox);
int log_data(int als, int prox);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the Si1120 sensor
int initialize_sensor() {
    int retries = 3;
    int result;

    // Reset the sensor
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, RESET_REG, RESET_VALUE);
        if (result >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error resetting sensor (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to reset sensor after multiple retries.\n");
        return -1;
    }

    // Verify Part ID
    retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, PART_ID_REG);
        if (result >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading Part ID (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read Part ID after multiple retries.\n");
        return -1;
    }

    if (result != 0x50) {
        fprintf(stderr, "Incorrect Part ID: 0x%02x\n", result);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Reads ambient light and proximity data from the sensor
int read_sensor_data(int *als, int *prox) {
    int retries = 3;
    int als_value, prox_value;

    while (retries > 0) {
        als_value = i2cReadByteData(i2c_handle, ALS_DATA_REG);
        if (als_value >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading ALS data (attempt %d): %d\n", 4 - retries, als_value);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
