// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x60
#define SI1182_PART_ID_REG 0x00
#define SI1182_ALS_RATE_REG 0x08
#define SI1182_PS_RATE_REG 0x09
#define SI1182_ALS_DATA_REG 0x22
#define SI1182_PS_DATA_REG 0x24
#define SI1182_RESET_REG 0x07
#define SI1182_RESET_VALUE 0x01

#define LUX_MIN 0
#define LUX_MAX 1000
#define PROXIMITY_MIN 0
#define PROXIMITY_MAX 65535

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int si1182_init(int fd);
int si1182_read_data(int fd, float *lux, uint16_t *proximity);
void log_data(FILE *fp, float lux, uint16_t proximity);
void signal_handler(int sig);
void cleanup();

// I2C open function
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Si1182 initialization function
int si1182_init(int fd) {
    // Reset the sensor
    if (i2c_write_reg(fd, SI1182_RESET_REG, SI1182_RESET_VALUE) < 0) {
        fprintf(stderr, "Error resetting Si1182 sensor.\n");
        return -1;
    }
    usleep(100000); // Wait for reset to complete

    // Verify sensor ID
    uint8_t part_id;
    if (i2c_read_reg(fd, SI1182_PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Error reading Si1182 part ID.\n");
        return -1;
    }

    if (part_id != 0x82) {
        fprintf(stderr, "Error: Incorrect Si1182 part ID: 0x%02X (expected 0x82).\n", part_id);
        return -1;
    }

    printf("Si1182 sensor found with part ID: 0x%02X\n", part_id);

    // Configure measurement rate (ALS every 100ms, PS every 100ms)
    if (i2c_write_reg(fd, SI1182_ALS_RATE_REG, 0x0A) < 0) { // 0x0A = 0b00001010 (100ms ALS, 100ms PS)
        fprintf(stderr, "Error configuring ALS rate.\n");
        return -1;
    }
    if (i2c_write_reg(fd, SI1182_PS_RATE_REG, 0x0A) < 0) {
        fprintf(stderr, "Error configuring PS rate.\n");
        return -1;
    }

    return 0;
}

// Read ambient light and proximity data
int si1182_read_data(int fd, float *lux, uint16_t *proximity) {
    uint8_t als_data[2];
    uint8_t ps_data[2];

    if (i2c_read_bytes(fd, SI1182_ALS_DATA_REG, als_data, 2) < 0) {
        fprintf(stderr, "Error reading ALS data.\n");
        return -1;
    }
    *lux = (float)((als_data[0] << 8) | als_data[1]) / 1.2; // Example conversion, adjust as needed

    if (i2c_read_bytes(fd, SI1182_PS_DATA_REG, ps_data, 2) < 0) {
        fprintf(stderr, "Error reading PS data.\n");
        return -1;
    }
    *proximity = (uint16_t)((ps_data[0] << 8) | ps_data[1]); // Raw 16-bit value

    return 0;
}

// Log data to CSV file
void log_data(FILE *fp, float lux, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%u\n", timestamp, lux, proximity);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS, SI1182_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return 1;
    }

    // Initialize Si1182 sensor
    if (si1182_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize Si1182 sensor. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    float lux;
    uint16_t proximity;
    while (!terminate) {
        if (si1182_read_data(i2c_fd, &lux, &proximity) == 0) {
            log_data(log_file, lux, proximity);
            printf("Lux: %.2f, Proximity: %u\n", lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        usleep(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

