#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define DISTANCE_THRESHOLD 20.0 // cm
#define TRIGGER_PULSE_DURATION 10 // us
#define TIMEOUT_US 50000 // 50ms timeout

// Global variables
volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(uint32_t pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for clean exit
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt handler for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that the rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0; // Reset the flag after falling edge
    }
}

// Function to calculate distance in centimeters
float calculate_distance(uint32_t pulse_width) {
    if (pulse_width == 0) {
        return -1.0; // Indicate timeout
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to control the buzzer
void control_buzzer(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo or timeout
        uint32_t start_time = time(NULL);
        while (end_tick == 0 && (time(NULL) - start_time) < 1) {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        if (end_tick == 0) {
            fprintf(stderr, "Timeout waiting for echo\n");
            gpioTerminate();
            return 1;
        }

        // Calculate pulse width
        uint32_t pulse_width = end_tick - start_tick;

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Control buzzer
        control_buzzer(distance);

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup (should not reach here under normal circumstances due to the signal handler)
    gpioTerminate();
    return 0;
}

