// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds
#define MAX_RETRIES 3

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int pulse_width = 0;
volatile int distance = -1.0; // Initialize to -1.0 to indicate error
volatile int echo_valid = 0; // Flag to indicate valid echo reading

// Function prototypes
void trigger_pulse();
float calculate_distance(int pulse_width);
void set_servo_angle(int angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate(); // Terminate pigpio
    exit(0);         // Exit the program
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin HIGH
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin LOW
}

// Function to calculate distance from pulse width
float calculate_distance(int pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert microseconds to seconds and divide by 2
}

// Function to set the servo angle
void set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle. Angle must be between 0 and 180.\n");
        return;
    }

    // Calculate pulse width based on angle
    int pulse_width = (int)(500 + (angle * (2000 - 500) / 180));

    gpioServo(SERVO_PIN, pulse_width); // Set servo pulse width
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Trigger the ultrasonic sensor
        trigger_pulse();

        // Wait for echo pulse
        int start_seconds, start_micros, end_seconds, end_micros;
        gpioTime(0, &start_seconds, &start_micros);
        while (pulse_width <= 0 && (gpioTime(0, &end_seconds, &end_micros) - (gpioTime(0, &start_seconds, &start_micros) - 1) < 10000)); // Timeout after 10ms
        if (pulse_width <= 0) {
            fprintf(stderr, "Error: Echo timeout. Retrying...\n");
            pulse_width = 0; // Reset pulse width
            continue;         // Retry the loop
        }

        // Calculate pulse width
        gpioTime(0, &start_seconds, &start_micros);
        while (pulse_width > 0 && (gpioTime(0, &end_seconds, &end_micros) - (gpioTime(0, &start_seconds, &start_micros) - 1) < 10000)); // Timeout after 10ms
        if (pulse_width > 0) {
            pulse_end = end_seconds * 1000000 + end_micros;
            pulse_width = pulse_end - pulse_start;
            pulse_start = pulse_end;
            echo_valid = 1; // Mark as valid
        } else {
            echo_valid = 0; // Mark as invalid
        }

        // Calculate distance
        if (echo_valid) {
            distance = calculate_distance(pulse_width);
            if (distance < 0) {
                fprintf(stderr, "Error: Distance calculation failed. Retrying...\n");
                distance = -1.0; // Reset distance
                continue;         // Retry the loop
            }
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Echo reading invalid. Retrying...\n");
            distance = -1.0; // Reset distance
            continue;         // Retry the loop
        }

        // Set servo angle
        set_servo_angle(200 - distance); // Calculate servo angle based on distance

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    return 0;
}

