#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define MIN_ANGLE 0.0          // Minimum servo angle in degrees
#define MAX_ANGLE 180.0        // Maximum servo angle in degrees
#define TIMEOUT 50000          // Timeout in microseconds (50ms)

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int pulse_width = 0;
volatile int valid_pulse = 0;

// Function prototypes
void trigger_pulse();
float measure_distance();
int map_distance_to_angle(float distance);
void set_servo_angle(int angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_servo_angle(0); // Stop the servo
    gpioTerminate();      // Terminate pigpio
    exit(0);
}

// Function to generate a 10µs trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float measure_distance() {
    pulse_start = 0;
    pulse_end = 0;
    pulse_width = 0;
    valid_pulse = 0;

    // Wait for the echo pin to go high (rising edge)
    int start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 0 && (gpioTick() - start_time) < TIMEOUT) {
        // Wait for the echo pin to go high
    }
    if (gpioRead(ECHO_PIN) == 1) {
        pulse_start = gpioTick();
        valid_pulse = 1;
    } else {
        return -1.0; // Timeout
    }

    // Wait for the echo pin to go low (falling edge)
    start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 1 && (gpioTick() - start_time) < TIMEOUT) {
        // Wait for the echo pin to go low
    }
    if (gpioRead(ECHO_PIN) == 0) {
        pulse_end = gpioTick();
        pulse_width = pulse_end - pulse_start;
        valid_pulse = 1;
    } else {
        return -1.0; // Timeout
    }

    if (!valid_pulse) {
        return -1.0; // Invalid pulse
    }

    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Distance in cm
