#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x01
#define TEMP_REG 0x00
#define HUMID_REG 0x02
#define HUMIDITY_THRESHOLD 70.0f
#define TEMP_THRESHOLD 30.0f

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configures the Si7005 sensor
int configure_sensor() {
    int status = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00); // Default settings
    if (status < 0) {
        fprintf(stderr, "Failed to write to CONFIG register: %d\n", status);
        return -1;
    }
    return 0;
}

// Reads temperature and humidity from the sensor
int read_sensor(float *temperature, float *humidity) {
    int status;

    // Trigger temperature measurement
    status = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Failed to write to CONFIG register for temperature: %d\n", status);
        return -1;
    }
    gpioDelay(10); // Wait for conversion

    // Trigger humidity measurement
    status = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Failed to write to CONFIG register for humidity: %d\n", status);
        return -1;
    }
    gpioDelay(10); // Wait for conversion

    // Read temperature
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Failed to read temperature: %d\n", raw_temp);
        return -1;
    }

    // Read humidity
    int raw_humidity = i2cReadWordData(i2c_handle, HUMID_REG);
    if (raw_humidity < 0) {
        fprintf(stderr, "Failed to read humidity: %d\n", raw_humidity);
        return -1;
    }

    // Convert raw data to temperature and humidity
    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

// Logs the temperature and humidity data to the console
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);

            // Tamper detection
            if (humidity > HUMIDITY_THRESHOLD || temperature < TEMP_THRESHOLD) {
                fprintf(stderr, "Tamper detected! Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Closing and re-opening I2C.\n");
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait before re-initializing
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
            if (configure_sensor() != 0) {
                fprintf(stderr, "Failed to re-configure sensor. Exiting.\n");
                terminate = 1; // Exit loop if re-configuration fails
            }
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

