#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, int reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two I2C registers
int16_t read_word(int handle, int reg) {
    int high = read_register(handle, reg);
    int low = read_register(handle, reg + 1);

    if (high < 0 || low < 0) {
        return -1; // Indicate error
    }

    return (int16_t)((high << 8) | low);
}

// Function to read all sensor data
int read_sensor_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    *accel_x = read_word(handle, ACCEL_XOUT_H);
    *accel_y = read_word(handle, ACCEL_XOUT_H + 2);
    *accel_z = read_word(handle, ACCEL_XOUT_H + 4);
    *gyro_x = read_word(handle, GYRO_XOUT_H);
    *gyro_y = read_word(handle, GYRO_XOUT_H + 2);
    *gyro_z = read_word(handle, GYRO_XOUT_H + 4);

    if (*accel_x < 0 || *accel_y < 0 || *accel_z < 0 || *gyro_x < 0 || *gyro_y < 0 || *gyro_z < 0) {
        return -1; // Indicate error
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = read_register(i2c_handle, PWR_MGMT_1);
    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU6050 not found. WHO_AM_I returned 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the sensor
    if (write_register(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error waking up MPU6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

        if (read_sensor_data(i2c_handle, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d  ", accel_x, accel_y, accel_z);
            printf("Gyro: X=%6d, Y=%6d, Z=%6d\n", gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

