int validate_crc(uint8_t data[], int len, uint8_t polynomial, uint8_t init_value) {
    uint8_t crc = init_value;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

