    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t data[9];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRC
            if (!validate_crc(data, 9, CRC8_POLYNOMIAL, CRC8_INIT_VALUE)) {
                fprintf(stderr, "CRC validation failed\n");
                continue; // Skip logging if CRC fails
            }

            // Convert data
            sensor_data = convert_data(data);

            // Log data
            if (log_data(sensor_data) != 0) {
