// Read temperature and humidity from SHT40
int read_sht40(sensor_data_t *data) {
    uint8_t cmd[1] = {MEASURE_HIGH_REPEATABILITY};
    uint8_t buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(10); // Small delay before retry
            retries++;
