#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUMID_CMD 0xE5
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
char* get_timestamp();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to initialize the Si7015 sensor
int initialize_sensor() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteByteData(i2c_handle, MEASURE_TEMP_CMD, 0) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to write temperature command (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }
    fprintf(stderr, "Failed to initialize sensor after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteByteData(i2c_handle, MEASURE_HUMID_CMD, 0) == 0) {
            gpioDelay(15000); // Wait for measurement (at least 15ms)
            int raw_humidity = i2cReadWordData(i2c_handle, 0);
            if (raw_humidity >= 0) {
                // Success
                data->humidity = ((float)raw_humidity / 65536.0) * 100.0;
                data->temperature = ((float)(raw_humidity & 0x3FFF) / 65536.0) * 165.0 + 40.0;
                return 0; // Success
            } else {
                fprintf(stderr, "Failed to read humidity data (attempt %d): %s\n", retries + 1, strerror(errno));
                gpioDelay(10000); // 10ms delay
                retries++;
            }
        } else {
            fprintf(stderr, "Failed to write humidity command (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to log data to file
int log_data(sensor_data_t data) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written immediately
    free(timestamp);
    return 0;
}

// Function to get a timestamp string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Failed to allocate memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
            printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", get_timestamp(), sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay for 5 seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

