#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_I2C_ADDR 0x25
#define TRIGGER_COMMAND 0x362F // Trigger continuous measurement without averaging
#define SCALE_FACTOR_REG 0x436F
#define PRESSURE_REG 0x3B
#define TEMPERATURE_REG 0x3C
#define CRC8_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t stop_flag = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_write(int fd, uint16_t command);
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len);
int crc8(const uint8_t *data, int len);
int sdp800_trigger_measurement(int fd);
int sdp800_read_data(int fd, sensor_data_t *data);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address to I2C device");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC8 calculation function
int crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// SDP800 trigger measurement function
int sdp800_trigger_measurement(int fd) {
    uint16_t command = TRIGGER_COMMAND;
