#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// STS30 I2C address
#define STS30_ADDR 0x4A

// I2C bus
#define I2C_BUS 1

// Measurement command (high repeatability)
#define MEASURE_CMD 0x2C06

// CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    char timestamp[32];
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sts30(int handle, float *temperature);
int validate_crc(uint8_t data[], uint8_t crc);
int log_data(const sensor_data_t *data);
int log_error(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read temperature from STS30
int read_sts30(int handle, float *temperature) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[3];
    int result;

    result = i2cWriteDevice(handle, (char *)cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return -1;
    }

    gpioDelay(20); // Wait for conversion (at least 15ms)

    result = i2cReadDevice(handle, (char *)data, 3);
    if (result != 3) {
        log_error("Failed to read temperature data");
        return -1;
    }

    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint8_t crc = data[2];

    if (validate_crc(data, crc) != 0) {
        log_error("CRC validation failed");
        return -1;
    }

    *temperature = -45.0 + (175.0 * raw_temperature / 65535.0);

    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], uint8_t crc) {
    uint8_t polynomial[] = {0x31, 0x00};
    uint8_t crc_calculated = 0xFF;
    uint8_t i, j;

    for (i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ polynomial[0];
            } else {
                crc_calculated = (crc_calculated << 1) ^ polynomial[1];
            }
        }
    }

    if (crc_calculated != crc) {
        return -1; // CRC mismatch
    }

    return 0; // CRC valid
}

// Log data to file
int log_data(const sensor_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(data->timestamp, sizeof(data->timestamp), "%Y-%m-%dT%H:%M:%S%z", gmtime(&ts.tv_sec));
    fprintf(log_file, "%s,%.2f\n", data->timestamp, data->temperature);
    fflush(log_file);
    return 0;
}

// Log error to file
int log_error(const char *message) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", gmtime(&ts.tv_sec));
    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);
    return 0;
}

int main() {
    float temperature;
    sensor_data_t sensor_data;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("enclosure_temp_log.txt", "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_file = fopen("error_log.txt", "a");
    if (error_file == NULL) {
        log_error("Failed to open error log file");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sts30(i2c_handle, &temperature) == 0) {
            sensor_data.temperature = temperature;
            strftime(sensor_data.timestamp, sizeof(sensor_data.timestamp), "%Y-%m-%dT%H:%M:%S%z", gmtime(&time(NULL)));
            log_data(&sensor_data);
        } else {
            log_error("Failed to read temperature");
        }

        sleep(5);
    }

    // Cleanup
    fclose(log_file);
    fclose(error_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

