        gpioTerminate();
        return 1;
    }

    // Write command for continuous measurement
    if (write_command(i2c_handle, MEASURE_COMMAND) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t raw_data[6];
    sensor_data_t sensor_data;

    printf("Starting data acquisition...\n");

    while (!terminate) {
