        // Read data from the sensor
        if (read_data(i2c_handle, raw_data, 6) == 0) {
            // Validate CRC
            if (validate_crc(raw_data, 2, CRC8_POLYNOMIAL) &&
                validate_crc(raw_data + 3, 2, CRC8_POLYNOMIAL)) {

                // Convert data
                sensor_data = convert_data(raw_data);

                // Log data
                log_data(sensor_data);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
    }

    // Cleanup
    printf("Closing resources...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

