#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    time_t timestamp;
    float temperature;
} Reading;

// Circular buffer
Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_temperature(float *temperature);
void control_fan(float temperature);
void add_reading(time_t timestamp, float temperature);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from Si7021 sensor
int read_temperature(float *temperature) {
    unsigned char cmd = 0xE3; // Command for temperature measurement
    unsigned char data[2];
    int result, i;

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteByte(i2c_handle, cmd);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d. Retry %d/%d\n", result, i + 1, RETRY_COUNT);
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(50); // Wait for measurement (datasheet specifies 20ms)

        result = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from I2C: %d. Retry %d/%d\n", result, i + 1, RETRY_COUNT);
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert raw data to temperature (Celsius)
        int16_t raw_temp = (data[0] << 8) | data[1];
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON\n");
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Function to add a reading to the circular buffer
void add_reading(time_t timestamp, float temperature) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    int i;
    printf("\n--- Temperature Readings ---\n");
    for (i = 0; i < BUFFER_SIZE; ++i) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[index].timestamp));
        printf("[%s] Temperature: %.2f °C\n", time_str, buffer[index].temperature);
    }
    printf("-----------------------\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle); // Close I2C connection
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    float temperature;
    time_t current_time;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Get current timestamp
            current_time = time(NULL);

            // Add reading to buffer
            add_reading(current_time, temperature);

            // Control fan
            control_fan(temperature);

            // Print buffer contents
            print_buffer();
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        // Wait for 2 seconds
        gpioDelay(2000); // pigpio's delay function
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle); // Close I2C connection
    gpioTerminate(); // Terminate pigpio

    return 0;
}

