// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_READ_MEASUREMENT 0xEC05

// CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int start_periodic_measurement();
int read_measurement(sensor_data_t *data);
int stop_periodic_measurement();
int verify_crc(uint8_t *data, int len);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, stopping...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char cmd[2] = {(CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write start periodic measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read measurement data
int read_measurement(sensor_data_t *data) {
    char cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    char buffer[9];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after writing the command

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    verify_crc(buffer, 9);
    data->co2 = (uint16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = -45 + 175 * ((float)((buffer[3] << 8) | buffer[4])) / 65535;
    data->humidity = 100 * ((float)((buffer[6] << 8) | buffer[7])) / 65535;

    return 0;
}

// Verify CRC checksum
int verify_crc(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Stop periodic measurement
int stop_periodic_measurement() {
    char cmd[2] = {(CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_STOP_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write stop periodic measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);
}

