#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define CO2_THRESHOLD 1000
#define LED_GPIO 17
#define BUFFER_SIZE 20

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xE4B8
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// Data Structures
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
    uint8_t crc;
} sensor_data_t;

// Global Variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
int validate_checksum(uint16_t data, uint8_t checksum);
void store_reading(sensor_data_t data);
void print_reading(sensor_data_t data);
void control_led(int co2_level);
void signal_handler(int signal);

// Circular Buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Validate checksum
            if (validate_checksum(sensor_data.co2, sensor_data.crc) == 0) {
                // Store reading
                store_reading(sensor_data);

                // Print reading
                print_reading(sensor_data);

                // Control LED
                control_led(sensor_data.co2);
            } else {
                fprintf(stderr, "Checksum validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Stop the sensor
    if (i2cWriteByteData(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT, 0) != 0) {
        fprintf(stderr, "Failed to stop sensor\n");
    }

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

// Initialize the SCD40 sensor
int initialize_sensor() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Start periodic measurement
    if (i2cWriteByteData(i2c_handle, CMD_START_PERIODIC_MEASUREMENT, 0) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read data from the SCD40 sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int result;

    // Read measurement command
    if (i2cWriteByte(i2c_handle, CMD_READ_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to write read measurement command\n");
        return 1;
    }

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return 1;
    }

    // Extract data
    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = -45 + 175 * ((float)((buf[2] << 8) | buf[3])) / 65535;
    data->humidity = 100 * ((float)((buf[4] << 8) | buf[5])) / 65535;
    data->crc = buf[5];

    return 0;
}

// Validate the CRC-8 checksum
int validate_checksum(uint16_t data, uint8_t checksum) {
    uint8_t crc = 0xFF;
    uint8_t data_bytes[2] = {data >> 8, data & 0xFF};

    for (int i = 0; i < 2; i++) {
        crc ^= data_bytes[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }

    return (crc == checksum);
}

// Store the reading in the circular buffer
void store_reading(sensor_data_t data) {
    circular_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print the reading to stdout
void print_reading(sensor_data_t data) {
    printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%RH, CRC: 0x%02X\n",
           data.co2, data.temperature, data.humidity, data.crc);
}

// Control the LED based on the CO2 level
void control_led(int co2_level) {
    if (co2_level > CO2_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating program...\n");
    terminate = 1;
}

