        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read data from the SCD40 sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int result;

    // Read measurement command
    if (i2cWriteByte(i2c_handle, CMD_READ_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to write read measurement command\n");
        return 1;
    }

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return 1;
    }

    // Extract data
    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = -45 + 175 * ((float)((buf[2] << 8) | buf[3])) / 65535;
    data->humidity = 100 * ((float)((buf[4] << 8) | buf[5])) / 65535;
    data->crc = buf[5];

    return 0;
}

// Validate the CRC-8 checksum
int validate_checksum(uint16_t data, uint8_t checksum) {
    uint8_t crc = 0xFF;
    uint8_t data_bytes[2] = {data >> 8, data & 0xFF};

    for (int i = 0; i < 2; i++) {
        crc ^= data_bytes[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }

    return (crc == checksum);
}

// Store the reading in the circular buffer
void store_reading(sensor_data_t data) {
    circular_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print the reading to stdout
void print_reading(sensor_data_t data) {
    printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%RH, CRC: 0x%02X\n",
           data.co2, data.temperature, data.humidity, data.crc);
}

// Control the LED based on the CO2 level
void control_led(int co2_level) {
    if (co2_level > CO2_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating program...\n");
    terminate = 1;
}

