#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define PWM_FREQUENCY 1000000 // 1 MHz
#define PWM_RANGE 1000000      // 1 MHz
#define PWM_RESOLUTION 1000    // 1 us resolution
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_S 5
#define MAX_RETRIES 3
#define MAX_RETRIES_DELAY_S 1

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;
static int sensor_fault_count = 0;

// Structure to hold temperature data
typedef struct {
    double temperature;
    time_t timestamp;
} TemperatureData;

// Function prototypes
int initialize_gpio();
double read_temperature();
void log_temperature(double temperature);
void signal_handler(int signal);
void cleanup();
char* get_iso8601_timestamp();

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the temperature from the TMP05 sensor
double read_temperature() {
    int high_count = 0;
    int total_cycles = 0;
    int timeout = 0;
    int edge = 0; // Edge counter for timeout
    double temperature = -1000.0; // Initialize with an invalid value
    time_t start_time = time(NULL);
    time_t current_time;
    double elapsed_time;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Wait for the GPIO pin to go high
        while (gpioRead(GPIO_PIN) == 0 && timeout < TIMEOUT_MS * 1000) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout++;
        }

        if (timeout >= TIMEOUT_MS * 1000) {
            fprintf(stderr, "Timeout waiting for high edge\n");
            return -1000.0; // Indicate timeout error
        }

        high_count = 0;
        total_cycles = 0;
        edge = 0;

        // Measure the high pulse width and total cycle width
        while (gpioRead(GPIO_PIN) == 1 && timeout < TIMEOUT_MS * 1000) {
            gpioDelay(1);
            timeout++;
        }

        if (timeout >= TIMEOUT_MS * 1000) {
            fprintf(stderr, "Timeout waiting for low edge\n");
            return -1000.0; // Indicate timeout error
        }

        high_count = total_cycles = edge = 0;

        // Wait for the GPIO pin to go low
        while (gpioRead(GPIO_PIN) == 1 && timeout < TIMEOUT_MS * 1000) {
            gpioDelay(1);
            timeout++;
        }

        if (timeout >= TIMEOUT_MS * 1000) {
            fprintf(stderr, "Timeout waiting for low edge\n");
            return -1000.0; // Indicate timeout error
        }

        // Calculate the high pulse width and total cycle width
        high_count = total_cycles - 1 - high_count;
        total_cycles = total_cycles - 1;

        // Calculate the temperature
        if (total_cycles > 0) {
            temperature = (double)high_count / total_cycles * 165.0; // TMP05 datasheet formula
        } else {
            fprintf(stderr, "Divide by zero error: total_cycles is zero\n");
            return -1000.0; // Indicate division by zero error
        }

        // Validate the temperature
        if (temperature < -40.0 || temperature > 150.0) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            return -1000.0; // Indicate out-of-range error
        }

        // Get the current timestamp
        current_time = time(NULL);

        // Calculate the elapsed time since the last valid reading
        elapsed_time = difftime(current_time, start_time);

        // Check if the elapsed time exceeds the sample interval
        if (elapsed_time >= SAMPLE_INTERVAL_S) {
            // Log the temperature
            log_temperature(temperature);
            start_time = current_time;
        }

        // Check for sensor faults
        if (temperature < -40.0 || temperature > 150.0) {
            sensor_fault_count++;
            if (sensor_fault_count >= 3) {
                fprintf(stderr, "Sensor malfunction detected. Logging to log file.\n");
                char* timestamp = get_iso8601_timestamp();
                fprintf(log_file, "%s - SENSOR MALFUNCTION\n", timestamp);
                fflush(log_file);
                fprintf(stderr, "Sensor malfunction logged.\n");
                sensor_fault_count = 0; // Reset the counter after logging
            }
        } else {
            sensor_fault_count = 0; // Reset the counter if reading is valid
        }
    }

    return -1000.0; // Return error value if all retries failed
}

// Function to log the temperature to a file
void log_temperature(double temperature) {
    char* timestamp = get_iso8601_timestamp();
    fprintf(log_file, "%s - Temperature: %.2f\n", timestamp, temperature);
    fflush(log_file);
    free(timestamp);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Logging to temperature_log.txt\n");

    // Main loop
    while (running) {
        double temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            printf("Temperature: %.2f\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in %d seconds.\n", MAX_RETRIES_DELAY_S);
            log_temperature(-1000.0); // Log the error
            sleep(MAX_RETRIES_DELAY_S);
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

