#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define DATA_LENGTH 6
#define RETRY_COUNT 3
#define RETRY_DELAY_SEC 1
#define LOG_INTERVAL_SEC 5
#define SINE_PERIOD_SEC 3600
#define SINE_AMPLITUDE 2.0
#define SINE_PHASE 0.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize();
int read_sht35(int i2c_handle, float *temperature, float *humidity);
void validate_crc(uint8_t data[], int len, uint8_t checksum);
void convert_data(uint8_t data[], int len, float *temperature, float *humidity);
float apply_sinusoidal_offset(float value, float time);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8-ATM checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity from the SHT35 sensor
int read_sht35(int i2c_handle, float *temperature, float *humidity) {
    uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    uint8_t data[DATA_LENGTH];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cWriteDevice(i2c_handle, (char *)command, 2) != 2) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY_SEC * 1000); // Delay in milliseconds
            retries++;
            continue;
        }

        gpioDelay(15); // Wait for measurement (at least 15ms)

        if (i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH) != DATA_LENGTH) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY_SEC * 1000); // Delay in milliseconds
            retries++;
            continue;
        }

        break; // Success, exit retry loop
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read SHT35 after %d retries\n", RETRY_COUNT);
        *temperature = NAN;
        *humidity = NAN;
        return -1;
    }

    validate_crc(data, DATA_LENGTH, data[DATA_LENGTH - 1]);
    convert_data(data, DATA_LENGTH, temperature, humidity);

    return 0;
}

// Function to validate the CRC checksum
void validate_crc(uint8_t data[], int len, uint8_t checksum) {
    uint8_t crc_calculated = crc8(data, len);
    if (crc_calculated != checksum) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", crc_calculated, checksum);
    }
}

// Function to convert raw data to temperature and humidity
void convert_data(uint8_t data[], int len, float *temperature, float *humidity) {
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    *humidity = 100.0 * (float)humidity_raw / 65535.0;
}

// Function to apply a sinusoidal offset to the temperature or humidity value
float apply_sinusoidal_offset(float value, float time) {
    float offset = SINE_AMPLITUDE * (SINE_PHASE * time);
    return value + offset;
}

// Function to log the temperature and humidity data to a file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    float temperature, humidity;
    float temperature_offset, humidity_offset;
    time_t start_time = time(NULL);

    while (!terminate) {
        if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
            temperature_offset = apply_sinusoidal_offset(temperature, (time(NULL) - start_time) / SINE_PERIOD_SEC);
            humidity_offset = apply_sinusoidal_offset(humidity, (time(NULL) - start_time) / SINE_PERIOD_SEC);

            temperature = temperature_offset;
            humidity = humidity_offset;

            log_data(temperature, humidity);
        } else {
            temperature = NAN;
            humidity = NAN;
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(LOG_INTERVAL_SEC * 1000); // Delay in milliseconds
    }

    cleanup();
    return 0;
}

