    uint8_t crc = CRC_INITIAL_VALUE;
    uint8_t polynomial[] = {CRC_POLYNOMIAL};

    for (int i = 0; i < 5; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial[j];
            } else {
                crc <<= 1;
            }
        }
    }

    return (crc == checksum);
}

