    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (csv_file == NULL) {
        csv_file = fopen(CSV_FILE, "a+");
        if (csv_file == NULL) {
            fprintf(stderr, "Failed to open CSV file for writing\n");
            return -1;
        }
        fprintf(csv_file, "Timestamp,Temperature (C),Humidity (%%)\n");
    }

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(csv_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float temperature, humidity;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_sht35(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            // Log data to CSV file
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Sleep for 5 seconds
        sleep(SLEEP_DURATION);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    if (csv_file != NULL) {
        fclose(csv_file);
    }

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

