#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement without averaging
#define SAMPLE_INTERVAL_SEC 1
#define FILENAME "airflow.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize();
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
int validate_crc(uint8_t data[], int len, uint8_t checksum);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// CRC-8 calculation (Sensirion SDP810-500Pa)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        uint8_t data[9];
        uint16_t raw_pressure, raw_temperature;
        float pressure, temperature;

        // Read data from the sensor
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Error reading data from sensor.\n");
            continue; // Try again
        }

        // Validate CRC for pressure
        uint8_t pressure_data[2] = {data[0], data[1]};
        uint8_t pressure_checksum = data[2];
        if (validate_crc(pressure_data, 2, pressure_checksum) != 0) {
            fprintf(stderr, "Pressure CRC validation failed.\n");
            continue; // Try again
        }

        // Validate CRC for temperature
        uint8_t temperature_data[2] = {data[3], data[4]};
        uint8_t temperature_checksum = data[5];
        if (validate_crc(temperature_data, 2, temperature_checksum) != 0) {
            fprintf(stderr, "Temperature CRC validation failed.\n");
            continue; // Try again
        }

        // Convert raw data to floating-point values
        raw_pressure = (data[0] << 8) | data[1];
        raw_temperature = (data[3] << 8) | data[4];

        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Log the data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    if (fp != NULL) {
        fclose(fp);
    }

    printf("Program terminated gracefully.\n");
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int write_command(int handle, uint16_t command) {
    char buf[3];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    buf[2] = 0x00; // Dummy byte

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return 1;
    }
    return 0;
}

int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return 1;
    }
    return 0;
}

int validate_crc(uint8_t data[], int len, uint8_t checksum) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == checksum);
}

float convert_pressure(uint16_t raw_pressure) {
    return (float)raw_pressure / 240.0f; // Sensitivity of SDP810-500Pa
}

float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature / 200.0f; // Sensitivity of SDP810-500Pa
}

int log_data(float pressure, float temperature) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long timestamp_ms = (tv.tv_sec * 1000) + (tv.tv_usec / 1000);

    // Write pressure and temperature to file
    if (fprintf(fp, "%ld.%03ld %f %f\n", timestamp_ms, pressure, temperature) < 0) {
        fprintf(stderr, "Error writing to file.\n");
        return 1;
    }

    // Flush the buffer to ensure data is written to disk
    fflush(fp);

    return 0;
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

