int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t buffer[9];

    if (send_command(handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        return -1;
    }

    gpioDelay(CONVERSION_TIME_US); // Wait for conversion

    if (read_data(handle, buffer, 9) != 0) {
        return -1;
    }

    data->pressure_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature_raw = (int16_t)((buffer[3] << 8) | buffer[4]);
    data->crc_pressure = buffer[2];
    data->crc_temperature = buffer[5];
    data->status = buffer[6];

    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE_FACTOR;
}

// Log pressure reading to file
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            float pressure = convert_pressure(sensor_data.pressure_raw);

            if (validate_crc(sensor_data.pressure_raw, 2, CRC8_POLYNOMIAL) &&
                validate_crc(sensor_data.temperature_raw, 2, CRC8_POLYNOMIAL)) {

                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Failed to log pressure\n");
                }
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

