#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor_data(int *pressure);
float calculate_flow_rate(int pressure);
void control_fan(float flow_rate);
void log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    int pressure;
    float flow_rate;
} sensor_data_t;

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 100); // Set PWM range to 0-100 for percentage control

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data from the I2C bus
int read_sensor_data(int *pressure) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    *pressure = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to calculate flow rate from pressure (example linear relationship)
float calculate_flow_rate(int pressure) {
    // Assuming pressure range is 0-1000 Pa and flow rate is 0-100 SLPM
    return (float)pressure / 10.0; // Example linear conversion
}

// Function to control the fan speed using PWM
void control_fan(float flow_rate) {
    // Map flow rate (0-100 SLPM) to PWM duty cycle (0-100%)
    int duty_cycle = (int)(flow_rate * 2.55); // Assuming 0-100 SLPM maps to 0-255 duty cycle
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to a file
void log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioPWM(FAN_GPIO, 0); // Turn off the fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    int pressure;
    float flow_rate;
    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor_data(&pressure) == 0) {
            flow_rate = calculate_flow_rate(pressure);
            control_fan(flow_rate);
            log_data(flow_rate);
            sensor_data.pressure = pressure;
            sensor_data.flow_rate = flow_rate;
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

