#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lps33hw();
int read_pressure(int32_t *pressure);
int read_temperature(int16_t *temperature);
char* format_data(int32_t pressure, int16_t temperature);
int log_data(const char *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize LPS33HW sensor
int init_lps33hw() {
    // Enable continuous data acquisition, 1 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Read pressure data from LPS33HW
int read_pressure(int32_t *pressure) {
    char buffer[3];
    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    *pressure = (int32_t)((((uint32_t)buffer[2]) << 16) | (((uint32_t)buffer[1]) << 8) | ((uint32_t)buffer[0]));
    *pressure = *pressure >> 4; // Align to 20 bits
    return 0;
}

// Read temperature data from LPS33HW
int read_temperature(int16_t *temperature) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    *temperature = (int16_t)((((uint16_t)buffer[1]) << 8) | ((uint16_t)buffer[0]));
    return 0;
}

// Format data into a string
char* format_data(int32_t pressure, int16_t temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0
    static char data_string[100]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime_r(&rawtime, timestamp);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(data_string, sizeof(data_string), "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, (float)pressure / 4096.0, (float)temperature / 100.0);

    return data_string;
}

// Log data to file
int log_data(const char *data) {
    FILE *fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    fprintf(fp, "%s", data);
    fflush(fp); // Ensure data is written immediately
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5C, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

