#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
float read_temperature();
void update_circular_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(float average_temperature);
void signal_handler(int signal);
int initialize();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", signal);
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn the LED off

    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read temperature from the STLM75 sensor
float read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Failed to read temperature: %d\n", raw_temp);
        return -1000.0; // Indicate an error
    }

    // The STLM75 returns a 12-bit temperature value, left-aligned.
    // Shift right by 4 bits to get the correct value.
    raw_temp = raw_temp >> 4;

    temperature = (float)raw_temp * 0.0625;

    return temperature;
}

// Function to update the circular buffer
void update_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to calculate the running average of the temperature readings
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to control the LED based on the average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn the LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn the LED off
    }
}

int main() {
    CircularBuffer temperature_buffer;
    temperature_buffer.head = 0;
    temperature_buffer.count = 0;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for read error
            update_circular_buffer(&temperature_buffer, temperature);
            float average_temperature = calculate_average(&temperature_buffer);
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
            control_led(average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping iteration.\n");
        }

        time_sleep(1.0);
    }

    // Cleanup before exiting
    gpioWrite(LED_GPIO, 0); // Turn off the LED
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

