#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int start_periodic_measurement();
int read_measurement(unsigned char *data, int count);
int stop_periodic_measurement();
int write_log(const char *timestamp, int co2, float temperature, float humidity);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// CRC-8 calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0); // Bus 1, address 0x61, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (SCD30_CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read measurement data
int read_measurement(unsigned char *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (SCD30_CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to write log entry
int write_log(const char *timestamp, int co2, float temperature, float humidity) {
    fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, stopping program...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char data[18];
        int co2, temperature, humidity;
        char *timestamp;

        // Read measurement data
        if (read_measurement(data, 18) != 0) {
            fprintf(stderr, "Failed to read measurement, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // CRC check for CO2
        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "CO2 CRC check failed\n");
            continue;
        }

        // CRC check for temperature
        if (crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "Temperature CRC check failed\n");
            continue;
        }

        // CRC check for humidity
        if (crc8(data + 6, 2) != data[8]) {
            fprintf(stderr, "Humidity CRC check failed\n");
            continue;
        }

        // Extract data
        co2 = (data[0] << 8) | data[1];
        temperature = -45 + (data[3] << 8) | data[4];
        humidity = (data[6] << 8) | data[7];

        // Data validation
        if (co2 < 0 || co2 > 65535 || temperature < -40 || temperature > 125 || humidity < 0 || humidity > 65535) {
            fprintf(stderr, "Invalid sensor data, skipping logging\n");
            sleep(5);
            continue;
        }

        // Get timestamp
        timestamp = get_iso8601_timestamp();

        // Write to log file
        write_log(timestamp, co2, (float)temperature, (float)humidity);

        free(timestamp); // Free the allocated memory

        // Ventilation control logic
        int state = 0;
        if (co2 < 800) {
            state = 0; // OFF
        } else if (co2 < 1200) {
            state = 1; // LOW
        } else {
            state = 2; // HIGH
        }

        // Print ventilation state
        printf("CO2: %d ppm, Temp: %.2f °C, Humidity: %.2f %%, Ventilation: %d\n", co2, (float)temperature, (float)humidity, state);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

