    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char data[18];
        int co2, temperature, humidity;
        char *timestamp;

        // Read measurement data
        if (read_measurement(data, 18) != 0) {
            fprintf(stderr, "Failed to read measurement, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // CRC check for CO2
        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "CO2 CRC check failed\n");
            continue;
        }

        // CRC check for temperature
        if (crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "Temperature CRC check failed\n");
            continue;
        }

        // CRC check for humidity
        if (crc8(data + 6, 2) != data[8]) {
            fprintf(stderr, "Humidity CRC check failed\n");
            continue;
        }

        // Extract data
        co2 = (data[0] << 8) | data[1];
        temperature = -45 + (data[3] << 8) | data[4];
        humidity = (data[6] << 8) | data[7];

        // Data validation
        if (co2 < 0 || co2 > 65535 || temperature < -40 || temperature > 125 || humidity < 0 || humidity > 65535) {
            fprintf(stderr, "Invalid sensor data, skipping logging\n");
            sleep(5);
            continue;
        }

        // Get timestamp
        timestamp = get_iso8601_timestamp();

        // Write to log file
        write_log(timestamp, co2, (float)temperature, (float)humidity);

        free(timestamp); // Free the allocated memory

        // Ventilation control logic
        int state = 0;
        if (co2 < 800) {
            state = 0; // OFF
        } else if (co2 < 1200) {
            state = 1; // LOW
        } else {
            state = 2; // HIGH
        }

        // Print ventilation state
        printf("CO2: %d ppm, Temp: %.2f °C, Humidity: %.2f %%, Ventilation: %d\n", co2, (float)temperature, (float)humidity, state);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

