#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP32_ADDR 0x21

// Define the sampling interval in milliseconds
#define DEFAULT_INTERVAL 1000

// Define the CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor;
    uint8_t crc_pressure;
    uint8_t crc_temperature;
    uint8_t crc_scale_factor;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sdp32(sensor_data_t *data);
int verify_checksum(uint8_t data[], int len, uint8_t checksum);
void print_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the SDP32 sensor
int read_sdp32(sensor_data_t *data) {
    char buf[9];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 9);

    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->scale_factor = (int16_t)((buf[6] << 8) | buf[7]);
    data->crc_pressure = buf[2];
    data->crc_temperature = buf[5];
    data->crc_scale_factor = buf[8];

    return 0;
}

// Function to verify the checksum
int verify_checksum(uint8_t data[], int len, uint8_t checksum) {
    uint8_t crc = 0xFF;
    uint8_t polynomial = CRC_POLYNOMIAL;

    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    if (crc != checksum) {
        fprintf(stderr, "Checksum error: calculated 0x%02X, received 0x%02X\n", crc, checksum);
        return -1;
    }

    return 0;
}

// Function to print the sensor data
void print_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Pressure: %6d Pa, Temperature: %6d °C, Scale Factor: %6d\n",
           timestamp, data.pressure, data.temperature, data.scale_factor);
}

// Function to clean up resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int interval = DEFAULT_INTERVAL;

    // Parse command-line arguments
    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid sampling interval. Using default value.\n");
            interval = DEFAULT_INTERVAL;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp32(&sensor_data) == 0) {
            // Verify checksums
            if (verify_checksum(sensor_data.pressure, 2, sensor_data.crc_pressure) != 0 ||
                verify_checksum(sensor_data.temperature, 2, sensor_data.crc_temperature) != 0 ||
                verify_checksum(sensor_data.scale_factor, 2, sensor_data.crc_scale_factor) != 0) {
                fprintf(stderr, "Checksum verification failed. Skipping data point.\n");
            } else {
                // Print data
                print_data(sensor_data);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(interval * 1000); // Convert milliseconds to microseconds
    }

    // Clean up and exit
    cleanup();
    return 0;
}

