// Define the I2C bus and address
#define I2C_BUS 1
#define SDP810_ADDR 0x25

// Define the trigger command
#define TRIGGER_COMMAND 0x362F

// Define the CRC polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variable for I2C handle
int i2c_handle;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, float *pressure, float *temperature) {
    char buf[9];
    int result;

    // Send the trigger command
    result = i2cWriteByte(i2c_handle, (TRIGGER_COMMAND >> 8) & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error writing MSB of trigger command: %d\n", result);
        return -1;
    }
    result = i2cWriteByte(i2c_handle, TRIGGER_COMMAND & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error writing LSB of trigger command: %d\n", result);
        return -1;
    }

    // Wait for the conversion to complete (at least 45ms)
    gpioDelay(50000); // 50ms

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Extract the pressure and temperature values
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];

    // Calculate the scale factors
    float pressure_scale_factor = (float)buf[2];
    float temperature_scale_factor = (float)buf[5];

    // Calculate the pressure and temperature
    *pressure = (float)raw_pressure / pressure_scale_factor;
    *temperature = (float)raw_temperature / temperature_scale_factor;

    // Validate the CRC
    unsigned char crc_pressure = buf[6];
    unsigned char crc_temperature = buf[7];

    unsigned char crc_calculated_pressure = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc_calculated_pressure ^= buf[0 + i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated_pressure & 0x80) {
                crc_calculated_pressure = (crc_calculated_pressure << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated_pressure = (crc_calculated_pressure << 1);
            }
        }
    }
    if (crc_calculated_pressure != crc_pressure) {
        fprintf(stderr, "CRC error for pressure: calculated 0x%02X, received 0x%02X\n", crc_calculated_pressure, crc_pressure);
        return -2;
    }

    unsigned char crc_calculated_temperature = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc_calculated_temperature ^= buf[3 + i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated_temperature & 0x80) {
                crc_calculated_temperature = (crc_calculated_temperature << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated_temperature = (crc_calculated_temperature << 1);
            }
        }
    }
    if (crc_calculated_temperature != crc_temperature) {
        fprintf(stderr, "CRC error for temperature: calculated 0x%02X, received 0x%02X\n", crc_calculated_temperature, crc_temperature);
        return -2;
    }

    return 0;
}

int main() {
    float pressure, temperature;

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the sensor data
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            // Print the pressure and temperature values
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Close the I2C handle and terminate the pigpio library (this part will not be reached in the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

