#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x02
#define CONFIGURATION_REG 0x0F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the HDC1000 sensor
int init_hdc1000() {
    // Configure the HDC1000 for continuous measurement mode
    // Resolution: 14 bits, Temperature and Humidity measurement
    uint8_t config_data[2] = {0x00, 0x00}; // Default configuration
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data from the HDC1000
int read_hdc1000(float *temperature, float *humidity) {
    uint8_t data[4];
    int result;

    // Trigger a temperature and humidity conversion
    uint8_t trigger_data[2] = {0x01, 0x02}; // Trigger measurement
    result = i2cWriteDevice(i2c_handle, trigger_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for at least 20 ms for the conversion to complete
    gpioDelay(20000); // 20 ms

    // Read the temperature and humidity data
    result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

