#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define TEMP_ERROR -999.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
double read_temperature();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature from Si7051
double read_temperature() {
    int raw_temperature;
    double temperature;

    // Send temperature measurement command
    if (i2cWriteByteData(i2c_handle, 0, TEMP_MEASURE_CMD) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return TEMP_ERROR;
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read two bytes of temperature data
    raw_temperature = i2cReadWordData(i2c_handle, 0);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return TEMP_ERROR;
    }

    // Convert raw temperature to Celsius
    temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

    return temperature;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        double temperature = read_temperature();

        if (temperature == TEMP_ERROR) {
            fprintf(stderr, "Error reading temperature. Retrying in 5 seconds...\n");
        } else {
            printf("Temperature: %.2f °C\n", temperature);
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

