#define ICP10101_REG_PRODUCT_ID 0x71
#define ICP10101_REG_MEASURE 0x06
#define ICP10101_REG_TEMP_MSB 0x03
#define ICP10101_REG_TEMP_LSB 0x04
#define ICP10101_REG_PRESS_MSB 0x00
#define ICP10101_REG_PRESS_LSB 0x01
#define ICP10101_REG_PRESS_XLSB 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint16_t *temperature, uint32_t *pressure);
float convert_temperature(uint16_t raw_temperature);
float convert_pressure(uint32_t raw_pressure);
char* format_iso8601(char *timestamp, float temperature, float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, ICP10101_ADDR, 0); // Bus 1, address 0x69, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    char buf[2];
    buf[0] = ICP10101_REG_MEASURE; // MSB of register address
    buf[1] = 0x07; // Value to trigger measurement (adjust as needed)

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *temperature, uint32_t *pressure) {
    char buf[6];
    int result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    *pressure = (uint32_t)buf[0] | ((uint32_t)buf[1] << 8) | ((uint32_t)buf[2] << 16);
    *temperature = (uint16_t)buf[3] | ((uint16_t)buf[4] << 8);

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    // Placeholder conversion formula.  Replace with actual formula from datasheet.
    return (float)raw_temperature / 100.0; // Example conversion
}

// Convert raw pressure to Pascals
float convert_pressure(uint32_t raw_pressure) {
    // Placeholder conversion formula.  Replace with actual formula from datasheet.
    return (float)raw_pressure / 10.0; // Example conversion
}

// Format data into ISO 8601 timestamp
char* format_iso8601(char *timestamp, float temperature, float pressure) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", info);

    snprintf(timestamp + strlen(timestamp), 30 - strlen(timestamp), " - Temperature: %.2f C, Pressure: %.2f Pa", temperature, pressure);
    return timestamp;
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    printf("ICP-10101 sensor reader started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_temperature;
        uint32_t raw_pressure;
        float temperature;
        float pressure;
        char timestamp[30];

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Wait for measurement to complete (adjust delay as needed)
        gpioDelay(10); // 10 ms delay

        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Convert data
        temperature = convert_temperature(raw_temperature);
        pressure = convert_pressure(raw_pressure);

        // Format data
        format_iso8601(timestamp, temperature, pressure);

        // Print data
        printf("%s\n", timestamp);

        // Check for sensor absence
        if (raw_temperature == 0 && raw_pressure == 0) {
            fprintf(stderr, "Sensor absent. Check I2C connection.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    cleanup();

    return 0;
}

