#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F // Trigger measurement command
#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define CRC_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1
#define CRC_INITIAL_VALUE 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t crc_pressure;
    uint8_t crc_temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(sensor_data_t *data);
int validate_crc(uint8_t data[], int len, uint8_t polynomial, uint8_t initial_value);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Trigger a measurement on the SDP800 sensor
int trigger_measurement() {
    char command[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP800 sensor
int read_sensor_data(sensor_data_t *data) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->crc_pressure = buffer[4];
    data->crc_temperature = buffer[5];

    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len, uint8_t polynomial, uint8_t initial_value) {
    uint8_t crc = initial_value;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Convert raw pressure data to pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE_FACTOR;
}

// Convert raw temperature data to degrees Celsius
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / TEMPERATURE_SCALE_FACTOR;
}

// Log data to a file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (datasheet recommends at least 20ms)
        gpioDelay(20);

        // Read sensor data
        if (read_sensor_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(sensor_data.pressure, 2, CRC_POLYNOMIAL, CRC_INITIAL_VALUE) ||
            !validate_crc(sensor_data.temperature, 2, CRC_POLYNOMIAL, CRC_INITIAL_VALUE)) {
            fprintf(stderr, "CRC validation failed, discarding data\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data
        float pressure = convert_pressure(sensor_data.pressure);
        float temperature = convert_temperature(sensor_data.temperature);

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Wait before next measurement
        gpioDelay(45000); // 45 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

