}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Process sensor data
SensorData process_sensor_data(const uint8_t *data) {
    SensorData sensor_data;
    uint16_t humidity_raw = (data[0] << 8) | data[1];
    uint16_t temperature_raw = (data[2] << 8) | data[3];

    // Check status bits (bits 6 and 7 of humidity_raw)
    int status = (humidity_raw >> 6) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Error: Sensor status indicates an error (status = %d)\n", status);
        sensor_data.temperature = -999.0; // Indicate error
        sensor_data.humidity = -999.0;    // Indicate error
        return sensor_data;
    }

    // Convert raw data to temperature and humidity
    sensor_data.humidity = ((float)humidity_raw / 16383) * 100;
    sensor_data.temperature = ((float)temperature_raw / 16383) * 165 - 40;

    return sensor_data;
}

// Log data to file
int log_data(const SensorData *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fclose(fp);

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Environmental data logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint8_t sensor_data[4];
        SensorData sensor_values;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying in %d seconds.\n", MEASUREMENT_INTERVAL_S);
            sleep(MEASUREMENT_INTERVAL_S);
            continue;
        }

        // Wait for measurement to complete
        gpioDelay(MEASUREMENT_DELAY_MS);

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", MEASUREMENT_INTERVAL_S);
            sleep(MEASUREMENT_INTERVAL_S);
            continue;
        }

        // Process sensor data
        sensor_values = process_sensor_data(sensor_data);

        // Log data
        if (log_data(&sensor_values) != 0) {
            fprintf(stderr, "Failed to log data. Retrying in %d seconds.\n", MEASUREMENT_INTERVAL_S);
        }

        // Check log file size and truncate if necessary
        FILE *fp = fopen(LOG_FILE, "r");
        if (fp != NULL) {
            fseek(fp, 0, SEEK_END);
            long file_size = ftell(fp);
            fclose(fp);

            if (file_size > LOG_FILE_SIZE_LIMIT) {
                fclose(fp);
                remove(LOG_FILE); // Remove the file to truncate it
                printf("Log file exceeded size limit. Truncated.\n");
            }
        }

        // Wait before next measurement
        sleep(MEASUREMENT_INTERVAL_S);
    }

    // Cleanup and exit
    cleanup();
    printf("Environmental data logger stopped.\n");
    return 0;
}

