#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 4
#define TIMEOUT_US 10000 // 10ms timeout
#define NUM_PULSES 32

// Structure to hold SENT data
typedef struct {
    unsigned int status_nibble;
    unsigned int data_nibble1;
    unsigned int data_nibble2;
    unsigned int data_nibble3;
    unsigned int checksum_nibble;
} SENT_Data;

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
SENT_Data read_sent_data();
void log_pressure_data(SENT_Data data);
void log_error(const char *message);
void signal_handler(int signal);
void pulse_callback(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Callback function for pulse width measurement
void pulse_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t pulse_width;

    if (last_tick != 0) {
        pulse_width = tick - last_tick;
        last_tick = tick;

        if (pulse_width < TIMEOUT_US) {
            log_error("Timeout: No pulse received.");
            return;
        }

        if (pulse_width > NUM_PULSES * 10) { // Basic range check
            log_error("Invalid pulse width.");
            return;
        }

        if (pulse_width < 12 || pulse_width > 271) {
            log_error("Pulse width out of range.");
            return;
        }
    }
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Optional: pull-down resistor

    // Set up interrupt on rising edge of the signal
    gpioSetAlertFunc(GPIO_PIN, pulse_callback);

    return 0;
}

// Read SENT data from the sensor
SENT_Data read_sent_data() {
    SENT_Data data;
    int i = 0;

    // Wait for synchronization pulse (56 ticks)
    while (i < 56 && !terminate) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        i++;
    }

    if (terminate) return data; // Exit if signal received during sync pulse

    // Read status nibble (6 pulses)
    data.status_nibble = 0;
    for (i = 0; i < 6; i++) {
        if (pulse_callback(GPIO_PIN, 1, gpioTick()) && pulse_callback(GPIO_PIN, 0, gpioTick())) {
            data.status_nibble |= (1 << (5 - i));
        }
    }

    // Read data nibble 1 (6 pulses)
    data.data_nibble1 = 0;
    for (i = 0; i < 6; i++) {
        if (pulse_callback(GPIO_PIN, 1, gpioTick()) && pulse_callback(GPIO_PIN, 0, gpioTick())) {
            data.data_nibble1 |= (1 << (5 - i));
        }
    }

    // Read data nibble 2 (6 pulses)
    data.data_nibble2 = 0;
    for (i = 0; i < 6; i++) {
        if (pulse_callback(GPIO_PIN, 1, gpioTick()) && pulse_callback(GPIO_PIN, 0, gpioTick())) {
            data.data_nibble2 |= (1 << (5 - i));
        }
    }

    // Read data nibble 3 (6 pulses)
    data.data_nibble3 = 0;
    for (i = 0; i < 6; i++) {
        if (pulse_callback(GPIO_PIN, 1, gpioTick()) && pulse_callback(GPIO_PIN, 0, gpioTick())) {
            data.data_nibble3 |= (1 << (5 - i));
        }
    }

    // Read checksum nibble (6 pulses)
    data.checksum_nibble = 0;
    for (i = 0; i < 6; i++) {
        if (pulse_callback(GPIO_PIN, 1, gpioTick()) && pulse_callback(GPIO_PIN, 0, gpioTick())) {
            data.checksum_nibble |= (1 << (5 - i));
        }
    }

    return data;
}

// Log pressure data to file
void log_pressure_data(SENT_Data data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Pressure: %d.%d Pa\n", timestamp, (data.status_nibble << 12) | (data.data_nibble1 << 8) | (data.data_nibble2 << 4) | (data.data_nibble3 >> 4), (data.status_nibble & 0x0F) == 0 ? 0 : 1); // Check status bit
    fflush(log_file);
}

// Log errors to file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s: %s\n", timestamp, message);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    printf("Pressure sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        SENT_Data data = read_sent_data();

        log_pressure_data(data);

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    gpioSetAlertFunc(GPIO_PIN, NULL); // Disable callback
    gpioTerminate();
    fclose(log_file);

    printf("Pressure sensor data logging stopped.\n");

    return 0;
}

