#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define CONFIG_REG 0x01
#define MEASUREMENT_CONFIG 0x00 // Continuous conversion mode
#define TEMP_SCALE 0.0078125f
#define TEMP_OFFSET 0.0f
#define LOG_FILE "greenhouse_temps.dat"
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature();
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    const char *log_file;
    int sleep_seconds;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
float read_temperature() {
    char buf[2];
    int16_t raw_temp;
    float temperature;

    // Write temperature register address
    if (i2cWriteByteData(i2c_handle, TEMP_REG, 0) < 0) {
        fprintf(stderr, "Error writing to temperature register: %d\n", i2c_handle);
        return -1000.0f; // Indicate error
    }

    // Read two bytes of temperature data
    if (i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", i2c_handle);
        return -1000.0f; // Indicate error
    }

    // Combine bytes into a 16-bit integer
    raw_temp = (buf[0] << 8) | buf[1];

    // Convert to Celsius
    temperature = raw_temp * TEMP_SCALE + TEMP_OFFSET;

    return temperature;
}

// Log temperature to file
int log_temperature(float temperature) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0f) { // Check for read error
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping logging.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

