int shtc3_init();
int shtc3_read_data(uint8_t *data);
int shtc3_validate_crc(uint8_t data[], int len);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the SHTC3 sensor
int shtc3_init() {
    // No specific initialization needed for SHTC3 in this example.
    // The sensor is ready after power-up.
    return 0;
}

// Function to read data from the SHTC3 sensor
int shtc3_read_data(uint8_t *data) {
    char cmd[2] = {(SHTC3_MEASURE_HIGH >> 8) & 0xFF, SHTC3_MEASURE_HIGH & 0xFF};
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(20); // Wait for measurement (datasheet specifies 12.4ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to validate the CRC-8 checksum
int shtc3_validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    uint8_t polynomial = CRC8_POLYNOMIAL;

    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    if (crc != data[len]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }

    return 0;
}

// Function to convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + (175.0 * (float)raw_temp / 65535.0);
}

// Function to convert raw humidity data to percentage RH
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Function to log data to a file
void log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    uint8_t data[6];
    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read data from sensor
        if (shtc3_read_data(data) == 0) {
            // Validate CRC
            if (shtc3_validate_crc(data, 2) == 0 && shtc3_validate_crc(data + 3, 2) == 0) {
                // Convert data
                raw_temperature = (data[0] << 8) | data[1];
                raw_humidity = (data[3] << 8) | data[4];

                // Validate sensor readings
                if (raw_temperature >= -450 && raw_temperature <= 12500 && raw_humidity >= 0 && raw_humidity <= 65535) {
                    // Convert to Celsius and percentage RH
                    temperature = convert_temperature(raw_temperature);
                    humidity = convert_humidity(raw_humidity);

                    // Log data
                    log_data(temperature, humidity);
                    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
                } else {
                    fprintf(stderr, "Sensor readings out of range!\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

