#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define REG_TEMP 0x03
#define REG_RPM 0x04
#define SAMPLE_INTERVAL_SEC 1
#define LOG_FILE "mag_temp_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float rpm;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result;

    // Read RPM
    result = i2cReadI2CBlockData(i2c_handle, REG_RPM, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading RPM data: %d\n", result);
        data->rpm = NAN; // Indicate error
        return -1;
    }
    int16_t rpm_raw = (buf[0] << 8) | buf[1];
    data->rpm = (float)rpm_raw * 1000.0; // Convert to RPM (example scaling)

    // Read Temperature
    result = i2cReadI2CBlockData(i2c_handle, REG_TEMP, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        data->temperature = NAN; // Indicate error
        return -1;
    }
    int16_t temp_raw = (buf[0] << 8) | buf[1];
    data->temperature = (float)temp_raw * 0.01 - 40.0; // Convert to Celsius (example scaling)

    return 0;
}

// Function to log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (data.rpm == NAN || data.temperature == NAN) {
        fprintf(log_file, "%s,NaN,NaN\n", timestamp);
        fflush(log_file);
        return -1; // Indicate error
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.rpm);
    fflush(log_file);
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),RPM\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

