// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define SAMPLE_INTERVAL_SEC 1
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_slpm;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint32_t *raw_data);
sensor_data_t process_sensor_data(uint32_t raw_data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the I2C device
int read_sensor_data(uint32_t *raw_data) {
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    *raw_data = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
    return 0;
}

// Process raw sensor data to extract flow and temperature
sensor_data_t process_sensor_data(uint32_t raw_data) {
    sensor_data_t data;
    // Extract flow value (14 bits)
    int16_t flow_raw = (raw_data >> 2) & 0x3FFF; // Shift right by 2 bits and mask
    data.flow_slpm = (float)flow_raw / 100.0; // Scale to SLPM

    // Extract temperature value (12 bits)
    int16_t temperature_raw = (raw_data >> 10) & 0x3FF; // Shift right by 10 bits and mask
    data.temperature_c = (float)temperature_raw / 100.0; // Scale to Celsius

    return data;
}

