#include <pigpio.h>

#define DHT11_GPIO 4
#define DHT11_TIMEOUT 1000 // Timeout in milliseconds

// Structure to hold DHT11 data
typedef struct {
    float temperature;
    float humidity;
    int status;
} DHT11Data;

// Global variables
FILE *log_file = NULL;
FILE *error_log_file = NULL;
int running = 1;

// Function prototypes
int dht11_start_signal();
int dht11_receive_data(unsigned char *data);
DHT11Data dht11_decode_data(const unsigned char *data);
int dht11_checksum(const unsigned char *data, int len);
void log_data(const DHT11Data *data);
void log_error(const char *message);
void signal_handler(int signal);
int gpio_init();
void gpio_cleanup();

// Function to initialize GPIO
int gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    return 0;
}

// Function to cleanup GPIO
void gpio_cleanup() {
    gpioTerminate();
}

// Function to generate the start signal
int dht11_start_signal() {
    gpioWrite(DHT11_GPIO, 0); // Pull low
    gpioDelay(18);           // Wait 18ms
    gpioWrite(DHT11_GPIO, 1); // Release
    gpioDelay(80);           // Wait 80us
    return 0;
}

// Function to receive data from the DHT11 sensor
int dht11_receive_data(unsigned char *data) {
    unsigned int start_time = 0;
    unsigned int end_time = 0;
    int bit_index = 0;
    int timeout_count = 0;

    // Wait for the start signal (low pulse)
    while (gpioRead(DHT11_GPIO) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
        if (timeout_count > DHT11_TIMEOUT) {
            log_error("Timeout waiting for start signal");
            return -1;
        }
        if (start_time == 0) start_time = gpioTick();
    }

    // Wait for the response (low pulse)
    timeout_count = 0;
    while (gpioRead(DHT11_GPIO) == 0) {
        gpioDelay(1);
        timeout_count++;
        if (timeout_count > DHT11_TIMEOUT) {
            log_error("Timeout waiting for response pulse");
            return -1;
        }
        if (end_time == 0) end_time = gpioTick();
    }

    // Read 40 bits of data
    for (int i = 0; i < 40; i++) {
        timeout_count = 0;
        while (gpioRead(DHT11_GPIO) == 1) {
            gpioDelay(1);
            timeout_count++;
            if (timeout_count > DHT11_TIMEOUT) {
                log_error("Timeout waiting for data bit high");
                return -1;
            }
            if (start_time == 0) start_time = gpioTick();
        }

        timeout_count = 0;
        while (gpioRead(DHT11_GPIO) == 0) {
            gpioDelay(1);
            timeout_count++;
            if (timeout_count > DHT11_TIMEOUT) {
                log_error("Timeout waiting for data bit low");
                return -1;
            }
            if (end_time == 0) end_time = gpioTick();
        }

        // Determine if the bit is a 0 or a 1 based on the pulse length
        if ((end_time - start_time) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    return 0;
}

// Function to decode the data and verify the checksum
DHT11Data dht11_decode_data(const unsigned char *data) {
    DHT11Data dht11_data;
    dht11_data.temperature = (float)(((unsigned char)data[0] << 8) | (unsigned char)data[1]) / 10.0;
    dht11_data.humidity = (float)(((unsigned char)data[2] << 8) | (unsigned char)data[3]) / 10.0;
    dht11_data.status = 0; // Success

    // Checksum verification
    if (dht11_checksum(data, 4) != data[4]) {
        dht11_data.status = -1; // Checksum failure
    }

    return dht11_data;
}

// Function to calculate the checksum
int dht11_checksum(const unsigned char *data, int len) {
    unsigned char checksum = 0;
    for (int i = 0; i < len; i++) {
        checksum += data[i];
    }
    return checksum;
}

// Function to log the data to a file
void log_data(const DHT11Data *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.1f,%.1f,%d\n", timestamp, data->temperature, data->humidity, data->status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(error_log_file, "%s,%s\n", timestamp, message);
    fflush(error_log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    unsigned char data[5] = {0}; // Buffer to store received data
    DHT11Data dht11_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() != 0) {
        return 1;
    }

    // Open log files
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpio_cleanup();
        return 1;
    }

    error_log_file = fopen("error.log", "a");
    if (error_log_file == NULL) {
        perror("Error opening error log file");
        fclose(log_file);
        gpio_cleanup();
        return 1;
    }

    printf("DHT11 sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        // Generate start signal
        if (dht11_start_signal() != 0) {
            log_error("Failed to generate start signal");
            continue; // Try again
        }

        // Receive data
        if (dht11_receive_data(data) != 0) {
            log_error("Failed to receive data from DHT11");
            continue; // Try again
        }

        // Decode data
        dht11_data = dht11_decode_data(data);

        // Log data
        if (dht11_data.status == 0) {
            log_data(&dht11_data);
        } else {
            log_error("Failed to decode data from DHT11");
        }

        sleep(2); // Wait 2 seconds before next reading
    }

    // Cleanup resources
    fclose(log_file);
    fclose(error_log_file);
    gpio_cleanup();

    printf("DHT11 sensor reader stopped.\n");

    return 0;
}

