#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define LOG_FILE "sht31d_data.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize();
int read_sht31d(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
int crc8(const uint8_t *data, size_t len);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// CRC-8 calculation
int crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read temperature and humidity from SHT31-D
int read_sht31d(sensor_data_t *data) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(15); // Wait for measurement (at least 15ms)

        if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        // CRC validation
        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
            fprintf(stderr, "CRC validation failed (attempt %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        // Convert data
        int temperature_raw = (buffer[0] << 8) | buffer[1];
        int humidity_raw = (buffer[3] << 8) | buffer[4];

        data->temperature = -45.0 + (175.0 * temperature_raw) / 65535.0;
        data->humidity = (100.0 * humidity_raw) / 65535.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT31-D after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Log data to file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sht31d(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
            fprintf(log_file, "%s,ERROR: Failed to read sensor data\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

