#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX90824_ADDR 0x60

// Define the log file name
#define LOG_FILE "pressure_log.txt"

// Define the pressure and temperature registers
#define PRESSURE_REG 0x01
#define TEMPERATURE_REG 0x02

// Define the number of bytes to read for each register
#define PRESSURE_BYTES 2
#define TEMPERATURE_BYTES 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure and temperature data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[PRESSURE_BYTES + TEMPERATURE_BYTES];
    int bytes_read;

    // Read pressure data
    bytes_read = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, PRESSURE_BYTES);
    if (bytes_read != PRESSURE_BYTES) {
        fprintf(stderr, "Error reading pressure data: %d\n", bytes_read);
        return -1;
    }
    int16_t raw_pressure = (buf[PRESSURE_REG] << 8) | buf[PRESSURE_REG + 1];
    data->pressure = (float)raw_pressure; // Placeholder conversion

    // Read temperature data
    bytes_read = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf + PRESSURE_BYTES, TEMPERATURE_BYTES);
    if (bytes_read != TEMPERATURE_BYTES) {
        fprintf(stderr, "Error reading temperature data: %d\n", bytes_read);
        return -1;
    }
    int16_t raw_temperature = (buf[TEMPERATURE_REG] << 8) | buf[TEMPERATURE_REG + 1];
    data->temperature = (float)raw_temperature; // Placeholder conversion

    return 0;
}

// Log data to file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->pressure, data->temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
            fprintf(log_file, "%s,ERROR: Sensor read failed\n", timestamp);
            fflush(log_file);
        }
        sleep(2);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

