// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define SAMPLE_INTERVAL_SEC 1
#define BUFFER_SIZE 60
#define AVG_BUFFER_SIZE 10
#define AVG_BUFFER_INDEX 0
#define AVG_BUFFER_START 1
#define AVG_BUFFER_END AVG_BUFFER_START + AVG_BUFFER_SIZE - 1
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 26.0
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void update_circular_buffer(float temperature);
float calculate_average();
void control_fan(float average_temperature);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from LM75B
int read_temperature(float *temperature) {
    char buf[2];
    int result;

    for (int i = 0; i < I2C_RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
