#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
void control_led(float temperature);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read temperature from STTS2004
float read_temperature() {
    int raw_temp;
    int retries = 0;
    int result;

    while (retries < I2C_RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, TEMP_REG);
        if (result >= 0) {
            raw_temp = result;
            // Convert raw temperature to Celsius (refer to STTS2004 datasheet)
            float temperature = (float)(raw_temp >> 8) * 0.125; // Example conversion
            return temperature;
        } else {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C read failed (errno=%d): %s", errno, strerror(errno));
            log_error(error_message);
            retries++;
            gpioDelay(100); // Wait before retrying
        }
    }

    log_error("Failed to read temperature after multiple retries.");
    return -273.15; // Return absolute zero as error value
}

// Function to control the LED based on temperature
void control_led(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Function to log errors to stdout
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -273.0) {
            printf("Temperature: %.2f °C\n", temperature);
            control_led(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping LED control.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

