#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define SCALE_FACTOR_SIZE 3
#define MEASUREMENT_DELAY_US 45000 // 45 ms
#define CRC_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1
#define CRC_INIT_VALUE 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
    float scale_factor;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int len, uint8_t init_value, uint8_t polynomial);
sensor_data_t process_sensor_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len, uint8_t init_value, uint8_t polynomial) {
    uint8_t crc = init_value;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data from the SDP800-500Pa
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US); // Wait for measurement

    result = i2cReadDevice(i2c_handle, (char *)data, SCALE_FACTOR_SIZE);
    if (result != SCALE_FACTOR_SIZE) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len, uint8_t init_value, uint8_t polynomial) {
    uint8_t crc = init_value;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Process sensor data
sensor_data_t process_sensor_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t differential_pressure_raw = (data[0] << 8) | data[1];
    int16_t temperature_raw = (data[2] << 8) | data[3];
    uint16_t scale_factor_raw = (data[4] << 8) | data[5];

    // Convert raw values to physical units (refer to SDP800 datasheet)
    sensor_data.differential_pressure = (float)differential_pressure_raw / 10.0; // Pa
    sensor_data.temperature = (float)temperature_raw / 200.0; // °C
    sensor_data.scale_factor = (float)scale_factor_raw / 1000.0; // Scale factor

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, data.differential_pressure, data.temperature, data.scale_factor);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data_buffer[SCALE_FACTOR_SIZE];
    sensor_data_t sensor_values;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data_buffer) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data_buffer, SCALE_FACTOR_SIZE, CRC_INIT_VALUE, CRC_POLYNOMIAL)) {
                // Process sensor data
                sensor_values = process_sensor_data(sensor_data_buffer);

                // Log data
                log_data(sensor_values);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

