#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_NO_HOLD 0xE3
#define MEASURE_HUMIDITY_NO_HOLD 0xE5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "environment.log"
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, MEASURE_TEMP_NO_HOLD);
        if (result >= 0) {
            *temperature = (uint16_t)result;
            result = i2cReadWordData(i2c_handle, MEASURE_HUMIDITY_NO_HOLD);
            if (result >= 0) {
                *humidity = (uint16_t)result;
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading humidity: %d\n", result);
            }
        } else {
            fprintf(stderr, "Error reading temperature: %d\n", result);
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries--;
    }
    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Function to convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk
    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
            // Convert data
            temperature = convert_temperature(raw_temperature);
            humidity = convert_humidity(raw_humidity);

            // Validate sensor readings
            if (temperature < -40.0 || temperature > 85.0) {
                fprintf(stderr, "Warning: Temperature reading out of range: %.2f\n", temperature);
            }
            if (humidity < 0.0 || humidity > 100.0) {
                fprintf(stderr, "Warning: Humidity reading out of range: %.2f\n", humidity);
            }

            // Log data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Sleep for 60 seconds
        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

