#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define BUFFER_SIZE 100
#define LOG_FILE "scd40_data.csv"
#define ERROR_LOG_FILE "scd40_error.log"
#define START_PERIODIC_MEASUREMENT_COMMAND 0x21B1
#define STOP_PERIODIC_MEASUREMENT_COMMAND 0x3F86
#define READ_MEASUREMENT_COMMAND 0xEC05
#define CRC_POLYNOMIAL 0x31
#define INITIAL_VALUE 0xFF

// Data structure for sensor readings
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
    time_t timestamp;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
static int i2c_handle;
static circular_buffer_t data_buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;
static bool logging_enabled = true;

// Function prototypes
int init_i2c();
int start_periodic_measurement();
int read_sensor_data(sensor_data_t *data);
int validate_crc(uint8_t *data, int len);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
int get_from_buffer(circular_buffer_t *buffer, sensor_data_t *data);
void *logging_thread_func(void *arg);
int write_to_csv(const sensor_data_t *data);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char command[2] = {(START_PERIODIC_MEASUREMENT_COMMAND >> 8) & 0xFF, START_PERIODIC_MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char read_command[2] = {(READ_MEASUREMENT_COMMAND >> 8) & 0xFF, READ_MEASUREMENT_COMMAND & 0xFF};
    char buffer[9];
    int result;

    result = i2cWriteDevice(i2c_handle, read_command, 2);
    if (result != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }

    gpioDelay(1); // Small delay after sending the read command

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        log_error("Failed to read sensor data");
        return -1;
    }

    data->co2 = (uint16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = -45 + 175 * ((float)((buffer[3] << 8) | buffer[4])) / 65535;
    data->humidity = 100 * ((float)((buffer[6] << 8) | buffer[7])) / 65535;
    data->timestamp = time(NULL);

    return 0;
}

// Validate CRC
int validate_crc(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != data[len]) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "CRC check failed for data: ");
        for (int i = 0; i < len; i++) {
            error_message[strlen(error_message)] = (char)(data[i] + 48); // Convert hex to char
            if (i < len - 1) {
                error_message[strlen(error_message)] = ',';
            }
        }
        log_error(error_message);
        return -1;
    }
    return 0;
}

// Add data to the buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Get data from the buffer
int get_from_buffer(circular_buffer_t *buffer, sensor_data_t *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Buffer is empty
    }
    *data = buffer->buffer[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    buffer->count--;
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Logging thread function
void *logging_thread_func(void *arg) {
    while (running) {
        sleep(60);
        sensor_data_t data;
        if (get_from_buffer(&data_buffer, &data) == 0) {
            if (write_to_csv(&data) != 0) {
                log_error("Failed to write to CSV file");
            }
        } else {
            log_error("No data in buffer to write to CSV");
        }
    }
    pthread_exit(NULL);
}

// Write data to CSV file
int write_to_csv(const sensor_data_t *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Failed to open CSV file for writing");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");
    }

    fprintf(fp, "%ld,%d,%.2f,%.2f\n", data->timestamp, data->co2, data->temperature, data->humidity);

    fclose(fp);
    return 0;
}

// Log errors
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    pthread_cancel(logging_thread);
    pthread_join(logging_thread, NULL);
    pthread_mutex_destroy(&data_buffer.mutex);
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize circular buffer
    pthread_mutex_init(&data_buffer.mutex, NULL);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    sleep(1); // Wait for 1 second

    // Create log directory if it doesn't exist
    char command[50];
    snprintf(command, sizeof(command), "mkdir -p /var/log/scd40_data");
    system(command);

    // Create error log file
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file for creation");
        cleanup();
        return 1;
    }
    fclose(fp);

    // Create CSV file
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Failed to open CSV file for creation");
        cleanup();
        return 1;
    }
    fclose(fp);

    // Create logging thread
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }

    sensor_data_t data;
    time_t last_write_time = time(NULL);

    // Main loop
    while (running) {
        if (read_sensor_data(&data) == 0) {
            add_to_buffer(&data_buffer, data);
            if (time(NULL) - last_write_time >= 60) {
                if (write_to_csv(&data) != 0) {
                    log_error("Failed to write to CSV file");
                }
                last_write_time = time(NULL);
            }
        } else {
            log_error("Failed to read sensor data");
        }
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

