#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define TRIGGER_MEASUREMENT 0x362F
#define SAMPLE_INTERVAL_SEC 1
#define CRC_POLYNOMIAL 0x31 // x^8 + x^5 + x^4 + 1
#define CRC_INIT 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int len, uint8_t polynomial, uint8_t init);
sensor_data_t process_sensor_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Trigger measurement
int trigger_measurement() {
    char buf[2];
    buf[0] = (TRIGGER_MEASUREMENT >> 8) & 0xFF;
    buf[1] = TRIGGER_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], int len, uint8_t polynomial, uint8_t init) {
    uint8_t crc = init;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Process sensor data
sensor_data_t process_sensor_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[2] << 8) | data[3];
    int16_t raw_scale = (data[4] << 8) | data[5];

    // Scale factors (from datasheet)
    float pressure_scale = 60.0f; // Pa
    float temperature_scale = 200.0f; // °C

    sensor_data.pressure = (float)raw_pressure / pressure_scale;
    sensor_data.temperature = (float)raw_temperature / temperature_scale;

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sdp810_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(45); // Wait for measurement to complete

        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (!validate_crc(data, 3, CRC_POLYNOMIAL, CRC_INIT)) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (!validate_crc(data + 3, 3, CRC_POLYNOMIAL, CRC_INIT)) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (!validate_crc(data + 6, 3, CRC_POLYNOMIAL, CRC_INIT)) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        sensor_data_t sensor_data = process_sensor_data(data);

        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for the next sample
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

