#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define ICP10110_ADDR 0x69

// Define register addresses (replace with actual values from datasheet)
#define ICP10110_REG_PRESSURE_MSB 0x00
#define ICP10110_REG_TEMPERATURE_MSB 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
void format_data(sensor_data_t data, char *timestamped_string);
int write_to_file(const char *timestamped_string);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result;

    // Read pressure data (MSB, LSB, XLSB)
    result = i2cReadI2CBlockData(i2c_handle, ICP10110_REG_PRESSURE_MSB, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read pressure data: %d\n", result);
        return -1;
    }
    int32_t pressure_raw = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    data->pressure = (float)pressure_raw / 4096.0; // Example conversion, adjust as needed

    // Read temperature data (MSB, LSB)
    result = i2cReadI2CBlockData(i2c_handle, ICP10110_REG_TEMPERATURE_MSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }
    int16_t temperature_raw = (buf[0] << 8) | buf[1];
    data->temperature = (float)temperature_raw / 100.0; // Example conversion, adjust as needed

    return 0;
}

// Function to format the data with ISO 8601 timestamp
void format_data(sensor_data_t data, char *timestamped_string) {
    time_t rawtime;
    struct tm *info;
    char buffer[80];

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, 80, "%Y-%m-%dT%H:%M:%SZ", info);

    snprintf(timestamped_string, 256, "%s,%.2f,%.2f\n", buffer, data.pressure, data.temperature);
}

// Function to write the data to a file
int write_to_file(const char *timestamped_string) {
    FILE *fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return -1;
    }

    if (fputs(timestamped_string, fp) == EOF) {
        fprintf(stderr, "Failed to write to file\n");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Failed to flush file buffer\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Format the data
            char timestamped_string[256];
            format_data(sensor_data, timestamped_string);

            // Write to file
            if (write_to_file(timestamped_string) != 0) {
                fprintf(stderr, "Failed to write data to file\n");
            }

            // Print to stdout
            printf("%s", timestamped_string);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 10ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

