                float temperature = convert_pressure(sensor_data + 1, sensor_data + 4);

                // Control LED
                control_led(pressure);

                // Print data (optional)
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed\n");
        }

        gpioDelay(DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
