    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return 1;
    }
    return 0;
}

// Verify CRC
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    uint8_t polynomial = 0x31; // x^8 + x^5 + x^4 + x^0

    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
