#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define AMBIENT_TEMP_THRESHOLD 30.0
#define OBJECT_TEMP_THRESHOLD 28.0
#define AMBIENT_TEMP_HYSTERESIS 32.0
#define OBJECT_TEMP_HYSTERESIS 30.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_temperature(int reg, float *value);
int log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperature from the sensor
int read_temperature(int reg, float *value) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(i2c_handle, reg);
        if (result >= 0) {
            // Success, convert to Celsius
            *value = (float)(result * 0.02) - 273.15;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X, attempt %d): %d\n", reg, retries + 1, result);
            retries++;
            gpioDelay(10); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "Failed to read temperature from register 0x%02X after %d retries\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Function to log temperature data to a file
int log_temperature(float ambient_temp, float object_temp) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to control the cooling fan
void control_fan(float object_temp) {
    if (object_temp > OBJECT_TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else if (object_temp < AMBIENT_TEMP_HYSTERESIS) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_temperature(AMBIENT_TEMP_REG, &sensor_data.ambient_temp) == 0 &&
            read_temperature(OBJECT_TEMP_REG, &sensor_data.object_temp) == 0) {

            log_temperature(sensor_data.ambient_temp, sensor_data.object_temp);
            control_fan(sensor_data.object_temp);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping logging\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    cleanup();
    return 0;
}

