#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define SERVER_PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
int server_socket;
struct sockaddr_in server_address;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sht40(float *temperature, float *humidity);
int create_html(float temperature, float humidity, char *html);
int serve_page(const char *html);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read SHT40 sensor data
int read_sht40(float *temperature, float *humidity) {
    unsigned char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, MEASURE_HIGH_PRECISION) != 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(10000); // Wait 10ms

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) == 6) {
            // Convert data
            unsigned short temperature_raw = (buf[0] << 8) | buf[1];
            unsigned short humidity_raw = (buf[3] << 8) | buf[4];

            *temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
            *humidity = 100.0 * (float)humidity_raw / 65535.0;

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C: %d\n", i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to create HTML page
int create_html(float temperature, float humidity, char *html) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    snprintf(html, 256, 
             "<!DOCTYPE html><html><head><title>SHT40 Data</title><style>body {font-family: Arial, sans-serif;}</style></head><body><h1>SHT40 Data</h1><p>Timestamp: %s</p><p>Temperature: %.2f &deg;C</p><p>Humidity: %.2f %%</p></body></html>",
             timestamp, temperature, humidity);
    return 0;
}

// Function to serve HTML page
int serve_page(const char *html) {
    ssize_t bytes_sent = send(server_socket, html, strlen(html), 0);
    if (bytes_sent < 0) {
        perror("Error sending data");
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(SERVER_PORT);

    // Bind socket
    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_socket, 3) < 0) {
        perror("Error listening on socket");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    char html[256];

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sht40(&temperature, &humidity) == 0) {
            // Create HTML
            if (create_html(temperature, humidity, html) == 0) {
                // Serve page
                if (serve_page(html) != 0) {
                    fprintf(stderr, "Error serving page\n");
                }
            } else {
                fprintf(stderr, "Error creating HTML\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(5000000); // Delay 5 seconds
    }

    // Cleanup
    close(server_socket);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

