    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        return 1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
    return 0;
}

