#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG 0x0F
#define TEMPERATURE_REGISTER 0x00
#define HUMIDITY_REGISTER 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
void process_sensor_data(uint16_t raw_temperature, uint16_t raw_humidity, sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t config_value = 0x00; // Configure for temperature and humidity measurement
    int retries = 0;
    int result;

    while (retries < 3) {
        result = i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, config_value);
        if (result >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error writing to MEASUREMENT_CONFIG (attempt %d): %d\n", retries + 1, result);
            gpioDelay(100); // Wait 100ms before retrying
            retries++;
        }
    }

    if (retries >= 3) {
        fprintf(stderr, "Failed to write to MEASUREMENT_CONFIG after multiple retries.\n");
        return -1; // Indicate failure
    }

    gpioDelay(10); // Wait for measurement to complete (adjust as needed)

    uint16_t raw_temperature, raw_humidity;
    int result;

    result = i2cReadWordData(i2c_handle, TEMPERATURE_REGISTER);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1; // Indicate failure
    }
    raw_temperature = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, HUMIDITY_REGISTER);
    if (result < 0) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1; // Indicate failure
    }
    raw_humidity = (uint16_t)result;

    process_sensor_data(raw_temperature, raw_humidity, data);
    return 0; // Indicate success
}

// Process raw sensor data and convert to Celsius and relative humidity
void process_sensor_data(uint16_t raw_temperature, uint16_t raw_humidity, sensor_data_t *data) {
    // Convert raw temperature to Celsius (see HDC2010 datasheet)
    data->temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;

    // Convert raw humidity to relative humidity (see HDC2010 datasheet)
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

