#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASUREMENT_INTERVAL_MS 500
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// CRC polynomial and initial value
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read data from the sensor
int read_sensor_data(int handle, int *pressure, int *temperature) {
    char cmd[2] = {0x36, 0x2F}; // Trigger measurement command
    char buffer[6];
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, cmd, 2) == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error writing to I2C device: %d, retries remaining: %d\n", handle, retries);
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to write to I2C device after multiple retries.\n");
        return -1;
    }

    gpioDelay(45); // Wait for measurement to complete

    retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        if (i2cReadDevice(handle, buffer, 6) == 6) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device: %d, retries remaining: %d\n", handle, retries);
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read from I2C device after multiple retries.\n");
        return -1;
    }

    // Extract pressure and temperature values
    *pressure = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[2] << 8) | buffer[3];

    // Validate CRC checksums
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC checksum error\n");
        return -1;
    }

    return 0;
}

// Function to log the sensor data
void log_sensor_data(int pressure, int temperature) {
    printf("Pressure: %d, Temperature: %d\n", pressure, temperature);
}

// Function to clean up resources
void cleanup(int handle) {
    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(I2C_BUS, SDP800_ADDRESS);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int pressure, temperature;

        if (read_sensor_data(i2c_handle, &pressure, &temperature) == 0) {
            log_sensor_data(pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL_MS);
    }

    // Clean up resources before exiting
    cleanup(i2c_handle);
    return 0;
}

