#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MAX6675_CS 8       // GPIO8 (CE0)
#define SSR_GPIO 17         // GPIO17 (BCM numbering)
#define TARGET_TEMP_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define ERROR_TEMP -999.0

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static float target_temperatures[100]; // Assuming a maximum of 100 points in the profile
static int profile_size = 0;

// Function Prototypes
int initialize();
float read_temperature();
float calculate_pid(float setpoint, float actual_value, float *integral, float *previous_error);
void set_ssr_duty_cycle(float duty_cycle);
void log_data(float temperature);
void load_target_profile();
void signal_handler(int signal);
void cleanup();

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MAX6675_CS, PI_OUTPUT);
    gpioSetMode(SSR_GPIO, PI_OUTPUT);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load target temperature profile from file
    load_target_profile();

    return 0;
}

// Function to read temperature from MAX6675
float read_temperature() {
    unsigned char data[3];
    int i;

    gpioWrite(MAX6675_CS, 0); // Select the MAX6675
    gpioDelay(1); // Small delay after CS goes low

    for (i = 0; i < 3; i++) {
        data[i] = spiRead(spi_handle);
        if (data[i] < 0) {
            fprintf(stderr, "SPI read error\n");
            gpioWrite(MAX6675_CS, 1); // Deselect the MAX6675
            return ERROR_TEMP;
        }
    }

    gpioWrite(MAX6675_CS, 1); // Deselect the MAX6675

    // Check for fault conditions
    if (data[1] & 0x04) {
        fprintf(stderr, "Thermocouple open\n");
        return ERROR_TEMP;
    }
    if (data[1] & 0x02) {
        fprintf(stderr, "Thermocouple shorted to GND\n");
        return ERROR_TEMP;
    }
    if (data[1] & 0x01) {
        fprintf(stderr, "Thermocouple shorted to VCC\n");
        return ERROR_TEMP;
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    float temperature = (float)raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_value, float *integral, float *previous_error) {
    float error = setpoint - actual_value;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;

    // Clamp the output to the range 0.0 to 1.0
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to set the SSR duty cycle
void set_ssr_duty_cycle(float duty_cycle) {
    int on_time_us = (int)(duty_cycle * 1000000.0); // Convert duty cycle to microseconds
    int off_time_us = (int)((1.0 - duty_cycle) * 1000000.0);

    gpioWrite(SSR_GPIO, 1); // Turn on SSR
    gpioDelay(on_time_us);
    gpioWrite(SSR_GPIO, 0); // Turn off SSR
    gpioDelay(off_time_us);
}

// Function to log data to file
void log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load the target temperature profile from file
void load_target_profile() {
    FILE *fp = fopen(TARGET_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open target profile file, using a default profile (constant temperature)\n");
        // Initialize with a constant temperature if the file cannot be opened
        for (int i = 0; i < 100; i++) {
            target_temperatures[i] = 150.0; // Default temperature
        }
        return;
    }

    char line[256];
    int count = 0;

    while (fgets(line, sizeof(line), fp) != NULL && count < 100) {
        if (sscanf(line, "%f,%f", &target_temperatures[count], &count) != 2) {
            fprintf(stderr, "Error parsing target profile, skipping line: %s", line);
        }
    }

    fclose(fp);

    if (count == 0) {
        fprintf(stderr, "No target temperatures found in file, using a default profile (constant temperature)\n");
        // Initialize with a constant temperature if no data is found
        for (int i = 0; i < 100; i++) {
            target_temperatures[i] = 150.0; // Default temperature
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    set_ssr_duty_cycle(0.0); // Turn off SSR
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    float temperature, pid_output, duty_cycle;
    float previous_temperature = 25.0; // Initial temperature
    float integral = 0.0;
    float previous_error = 0.0;

    printf("Reflow oven control started. Press Ctrl+C to exit.\n");

    while (running) {
        temperature = read_temperature();

        if (temperature == ERROR_TEMP) {
            fprintf(stderr, "Error reading temperature, skipping PID calculation\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        pid_output = calculate_pid(150.0, temperature, &integral, &previous_error); // Setpoint is 150°C

        duty_cycle = pid_output;
        set_ssr_duty_cycle(duty_cycle);
        log_data(temperature);

        gpioDelay(1000); // Control loop runs at approximately 1 Hz
    }

    cleanup();
    return 0;
}

