#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define W1_DEVICES_PATH "/sys/bus/w1/devices/"
#define LOG_FILE "greenhouse.log"
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000000 // PWM range (0-1000000)
#define HEATER_POWER 12.0 // Heater power in watts
#define SETPOINT_ARG_NAME "setpoint"
#define KP_ARG_NAME "kp"
#define KI_ARG_NAME "ki"
#define KD_ARG_NAME "kd"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int gpio17 = 17; // GPIO pin for relay enable
static int gpio18 = 18; // GPIO pin for PWM duty cycle
static double setpoint = 25.0; // Default setpoint
static double kp = 1.0; // Default PID gains
static double ki = 0.1; // Default PID gains
static double kd = 0.01; // Default PID gains

// Function prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double kp, double ki, double kd, double *integral, double *previous_error);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(double average_temperature, double setpoint, double pid_output, int duty_cycle);
void signal_handler(int signal);
int validate_crc(const char *data, int len);

// Function to read temperature from DS18B20 sensor
double read_temperature() {
    char filepath[100];
    char line[256];
    FILE *fp;
    double temperature = -999.0; // Default error value

    // Construct the full file path to the sensor's w1_slave file
    snprintf(filepath, sizeof(filepath), "%s%s/w1_slave", W1_DEVICES_PATH, "28-000006abca6f");

    // Open the w1_slave file
    fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("Error opening w1_slave file");
        return -999.0;
    }

    // Read the file line by line
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Check for the "YES" string in the CRC validation line
        if (strstr(line, "YES") != NULL) {
            // Extract the temperature value
            char *temp_str = strstr(line, "t=");
            if (temp_str != NULL) {
                long temp_raw = strtol(temp_str + 2, NULL, 10);
                temperature = (double)temp_raw / 1000.0;
                break; // Exit the loop after finding the temperature
            }
        }
    }

    // Close the file
    fclose(fp);

    // Validate CRC
    if (!validate_crc(line, strlen(line))) {
        fprintf(stderr, "CRC validation failed for sensor %s\n", filepath);
        return -999.0;
    }

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double kp, double ki, double kd, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(gpio18, duty_cycle);
}

// Function to log data to file
void log_data(double average_temperature, double setpoint, double pid_output, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, average_temperature, setpoint, pid_output, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to validate CRC
int validate_crc(const char *data, int len) {
    unsigned char crc = 0xFF;
    unsigned char poly = 0x31;
    unsigned char bit;

    for (int i = 0; i < len; i++) {
        crc ^= (unsigned char)data[i];
        for (int j = 0; j < 8; j++) {
            bit = crc & 0x80;
            if (bit) {
                crc = (crc << 1) ^ poly;
            } else {
                crc = (crc << 1);
            }
        }
    }
    return (crc == 0x00);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <kp> <ki> <kd>\n", argv[0]);
        fprintf(stderr, "  setpoint: Desired temperature in Celsius\n");
        fprintf(stderr, "  kp: Proportional gain\n");
        fprintf(stderr, "  ki: Integral gain\n");
        fprintf(stderr, "  kd: Derivative gain\n");
        return 1;
    }

    setpoint = atof(argv[1]);
    kp = atof(argv[2]);
    ki = atof(argv[3]);
    kd = atof(argv[4]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(gpio17, PI_OUTPUT);
    gpioSetMode(gpio18, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(gpio18, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(gpio18, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    double integral = 0.0;
    double previous_error = 0.0;
    double temperature;
    double pid_output;
    int duty_cycle;

    // Main loop
    while (running) {
        // Read temperature
        temperature = read_temperature();

        if (temperature == -999.0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
            // Consider a default temperature or other error handling here
        } else {
            // Calculate PID output
            pid_output = calculate_pid(setpoint, temperature, kp, ki, kd, &integral, &previous_error);

            // Determine PWM duty cycle and relay state
            if (pid_output >= 0) {
                // Proportional control
                duty_cycle = (int)(pid_output * PWM_RANGE / 1000.0); // Scale PID output to PWM range
                gpioWrite(gpio17, 1); // Enable relay
                set_pwm_duty_cycle(duty_cycle);
            } else {
                // Set PWM to zero and disable relay for cooling
                gpioWrite(gpio17, 0); // Disable relay
                set_pwm_duty_cycle(0);
            }

            // Log data
            log_data(temperature, setpoint, pid_output, duty_cycle);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    gpioWrite(gpio17, 0); // Disable relay
    set_pwm_duty_cycle(0); // Set PWM to zero
    fclose(log_file);
    gpioTerminate();

    return 0;
}

