#define AHT20_ADDR 0x38
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define DEHUMIDIFIER_GPIO 17
#define MEASUREMENT_DELAY_MS 80
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_aht20(float *humidity);
void control_dehumidifier(float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    float humidity;
    time_t timestamp;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Function to read humidity from AHT20 sensor
int read_aht20(float *humidity) {
    unsigned char buf[6];
    int retries = 0;
    int status;

    // Trigger measurement
    unsigned char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    if (i2cWriteDevice(i2c_handle, trigger_cmd, 3) != 0) {
        fprintf(stderr, "Error triggering measurement (attempt %d)\n", retries + 1);
        return -1;
    }

    // Wait for measurement to complete
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to microseconds

    // Read 6 bytes of data
    while (retries < MAX_RETRIES) {
        status = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (status == 6) {
            // Check status byte (bit 7 indicates ready)
            if ((buf[0] & 0x80) == 0) {
                // Check humidity data
                uint32_t humidity_raw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
                *humidity = ((float)humidity_raw / 0x100000) * 100.0;
                return 0; // Success
            } else {
