        }
        retries++;
        gpioDelay(10 * 1000); // 10ms delay
    }

    fprintf(stderr, "Failed to read AHT20 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to control the dehumidifier relay
void control_dehumidifier(float humidity) {
    static int dehumidifier_state = 0; // 0 = off, 1 = on

    if (humidity > HUMIDITY_THRESHOLD_HIGH && dehumidifier_state == 0) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        dehumidifier_state = 1;
        printf("Dehumidifier ON\n");
    } else if (humidity < HUMIDITY_THRESHOLD_LOW && dehumidifier_state == 1) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        dehumidifier_state = 0;
        printf("Dehumidifier OFF\n");
    }
}

// Function to log data to the console
void log_data(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float humidity;
    int read_result;

    // Main loop
    while (!terminate) {
        read_result = read_aht20(&humidity);
        if (read_result == 0) {
            log_data(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Failed to read humidity\n");
        }

        gpioDelay(5 * 1000 * 1000); // 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is off on exit
    gpioTerminate();

    return 0;
}

