#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HTU21D_ADDR 0x40
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define HTTP_TIMEOUT_SEC 5
#define JSON_BUFFER_SIZE 128

// Global variables
int i2c_handle;
int sockfd;
struct sockaddr_in server_addr;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_htu21d(float *temperature, float *humidity);
char *format_json(float temperature, float humidity);
int send_http_post(const char *json_data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %d", i2c_handle);
        return -1;
    }
    syslog(LOG_INFO, "I2C bus opened successfully.");
    return 0;
}

// Read temperature and humidity from HTU21D
int read_htu21d(float *temperature, float *humidity) {
    unsigned char buf[3];
    int result;
    unsigned short raw_temperature, raw_humidity;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        // Trigger temperature measurement
        result = i2cWriteByte(i2c_handle, TRIGGER_TEMP_MEASURE);
        if (result != 0) {
            syslog(LOG_ERR, "Failed to trigger temperature measurement: %d", result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(100000); // Wait for measurement (at least 50ms)

        // Read temperature data
        result = i2cReadDevice(i2c_handle, (char *)buf, 3);
        if (result != 3) {
            syslog(LOG_ERR, "Failed to read temperature data: %d", result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        raw_temperature = (buf[0] << 8) | buf[1];
        raw_temperature &= 0xFFFC; // Clear status bits

        // Trigger humidity measurement
        result = i2cWriteByte(i2c_handle, TRIGGER_HUMID_MEASURE);
        if (result != 0) {
            syslog(LOG_ERR, "Failed to trigger humidity measurement: %d", result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(100000); // Wait for measurement (at least 50ms)

        // Read humidity data
        result = i2cReadDevice(i2c_handle, (char *)buf, 3);
        if (result != 3) {
            syslog(LOG_ERR, "Failed to read humidity data: %d", result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        raw_humidity = (buf[0] << 8) | buf[1];
        raw_humidity &= 0xFFFC; // Clear status bits

        // Convert raw data to temperature and humidity
        *temperature = -46.85 + 175.72 * (float)raw_temperature / 65536.0;
        *humidity = -6.0 + 125.0 * (float)raw_humidity / 65536.0;

        // Validate sensor readings
        if (*temperature < -40.0 || *temperature > 125.0 || *humidity < 0.0 || *humidity > 100.0) {
            syslog(LOG_ERR, "Invalid sensor readings: temperature=%.2f, humidity=%.2f", *temperature, *humidity);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        return 0; // Success
    }

    syslog(LOG_ERR, "Failed to read HTU21D after %d retries.", RETRY_COUNT);
    return -1; // Failure
}

// Format data as JSON
char *format_json(float temperature, float humidity) {
    static char json_string[JSON_BUFFER_SIZE];
    snprintf(json_string, JSON_BUFFER_SIZE, "{\"temperature\":%.2f,\"humidity\":%.2f}", temperature, humidity);
    return json_string;
}

// Send HTTP POST request
int send_http_post(const char *json_data) {
    struct timeval timeout;
    timeout.tv_sec = HTTP_TIMEOUT_SEC;
    timeout.tv_usec = 0;

    // Set socket options to use timeout
    int flags = fcntl(sockfd, F_GETSOCKOPT, NULL);
    if (flags == -1) {
        perror("fcntl F_GETSOCKOPT");
        return -1;
    }

    if (setsockopt(sockfd, SOL_SOCKET, SO_SNDTIMEO, &timeout, sizeof(timeout)) == -1) {
        perror("setsockopt SO_SNDTIMEO");
        return -1;
    }

    flags = fcntl(sockfd, F_GETSOCKOPT, NULL);
    if (flags == -1) {
        perror("fcntl F_GETSOCKOPT");
        return -1;
    }

    if (setsockopt(sockfd, SOL_SOCKET, SO_SNDTIMEO, &timeout, sizeof(timeout)) == -1) {
        perror("setsockopt SO_SNDTIMEO");
        return -1;
    }

    // Prepare the request
    char request[1024] = {0};
    snprintf(request, sizeof(request), "POST /humidity HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n%s", strlen(json_data), json_data);

    // Send the request
    ssize_t bytes_sent = sendto(sockfd, request, strlen(request), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (bytes_sent == -1) {
        perror("sendto");
        return -1;
    }

    // Receive the response
    char response[1024] = {0};
    ssize_t bytes_received = recvfrom(sockfd, response, sizeof(response) - 1, 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (bytes_received == -1) {
        perror("recvfrom");
        return -1;
    }
    response[bytes_received] = '\0';

    // Log the response
    syslog(LOG_INFO, "HTTP Response: %s", response);

    // Check for success
    if (bytes_received > 0 && strstr(response, "200 OK") != NULL) {
        syslog(LOG_INFO, "HTTP POST successful.");
        return 0;
    } else {
        syslog(LOG_ERR, "HTTP POST failed or received error: %s", response);
        return -1;
    }
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (sockfd >= 0) {
        close(sockfd);
    }
    closelog();
    gpioTerminate();
}

int main() {
    openlog("htu21d_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting HTU21D monitor...");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        cleanup();
        return 1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    if (inet_pton(AF_INET, "api.example.com", &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        cleanup();
        return 1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        cleanup();
        return 1;
    }

    float temperature, humidity;
    char *json_data;

    while (!terminate) {
        // Read sensor data
        if (read_htu21d(&temperature, &humidity) == 0) {
            // Format data as JSON
            json_data = format_json(temperature, humidity);

            // Send HTTP POST request
            if (send_http_post(json_data) != 0) {
                syslog(LOG_ERR, "Failed to send HTTP POST, retrying...");
            }
        } else {
            syslog(LOG_ERR, "Failed to read HTU21D sensor.");
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup resources before exiting
    cleanup();

    syslog(LOG_INFO, "HTU21D monitor terminated.");
    return 0;
}

