    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the sensor
int read_calibration_data() {
    uint8_t data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib.dig_T1 = data[0] | (data[1] << 8);
    calib.dig_T2 = (data[2] | (data[3] << 8));
    calib.dig_T3 = (data[4] | (data[5] << 8));
    calib.dig_P1 = data[6] | (data[7] << 8);
    calib.dig_P2 = (data[8] | (data[9] << 8));
    calib.dig_P3 = (data[10] | (data[11] << 8));
