    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;

    return p;
}

// Function to log pressure to file
int log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (pressure > 1020.0 || pressure < 980.0) {
        fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk immediately
        printf("%s, %.2f hPa\n", timestamp, pressure);
        return 0;
    } else {
        return -1; // Pressure within normal range, no logging
    }
}

