    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify chip ID
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%x\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set oversampling and mode
    uint8_t config = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | 0x03; // Normal mode
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;

        // Trigger measurement
        if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) { // Temperature and pressure oversampling x4 and x16, normal mode
            fprintf(stderr, "Error triggering measurement\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Wait for conversion (datasheet specifies up to 7ms for temp and pressure)
        gpioDelay(10); // Wait 10ms

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading raw data\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature);
        pressure = compensate_pressure(raw_pressure, temperature);

        // Log pressure
        log_pressure(pressure);

        // Wait 2 seconds
        gpioDelay(2000); // 2000 ms = 2 seconds
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

