    float humidity;
    int motion;
} sensor_data_t;

// Function to read temperature from TMP117
float read_temperature() {
    unsigned char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Convert raw data to temperature (example formula, adjust as needed)
            int raw_temp = (buf[0] << 8) | buf[1];
            float temperature = (float)raw_temp * 0.01 - 40.0; // Example conversion
            return temperature;
        } else {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            gpioDelay(BACKOFF_DELAY_US);
            retries--;
        }
    }
    return -273.15; // Return absolute zero on failure
}

// Function to read humidity from AHT20
float read_humidity() {
    unsigned char buf[6];
    int result;
    int retries = RETRY_COUNT;
    unsigned char init_cmd[] = {0xBE, 0x08, 0x00};

    // Send initialization command
    result = i2cWriteDevice(i2c_handle, init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error initializing AHT20: %s\n", strerror(errno));
        return -1.0;
    }
    gpioDelay(20); // Wait for initialization

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result == 6) {
            // Convert raw data to humidity (example formula, adjust as needed)
            unsigned long humidity_raw = ((unsigned long)buf[1] << 12) | ((unsigned long)buf[2] << 4) | (buf[3] >> 4);
            float humidity = (float)humidity_raw * 100.0 / 10000.0; // Example conversion
            return humidity;
        } else {
            fprintf(stderr, "Error reading humidity: %s\n", strerror(errno));
