    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char filename[64];
    strftime(filename, sizeof(filename), LOG_FILE_PREFIX "logger_%Y-%m-%d.csv", t);
    log_file = fopen(filename, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(PIR_GPIO, PI_INPUT);
    return 0;
}

// Function to initialize logging
int init_logging() {
    log_file = fopen("logger.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening logger.log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting.\n");
        return 1;
    }
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        cleanup();
        return 1;
    }
    if (init_logging() != 0) {
        fprintf(stderr, "Logging initialization failed, exiting.\n");
        cleanup();
        return 1;
    }

    create_log_file();

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        float humidity = read_humidity();
        int motion = read_motion();

        log_data(temperature, humidity, motion);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

