#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor direction constants
#define MOTOR_FORWARD 1
#define MOTOR_BACKWARD 0

// Define motor run duration (seconds)
#define MOTOR_RUN_DURATION 5

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
int control_motor(int direction, int duration);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message("Received signal, stopping motor and cleaning up...");
        control_motor(MOTOR_BACKWARD, 0); // Stop the motor
        gpioTerminate(); // Release GPIO resources
        program_running = 0; // Set flag to exit main loop
        exit(0); // Exit the program
    }
}

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Error reading rain sensor: %d", sensor_value);
        log_message(error_message);
        return -1; // Indicate an error
    }
    return (sensor_value == 0) ? 1 : 0; // Active low
}

// Function to control the motor
int control_motor(int direction, int duration) {
    int result;

    if (direction == MOTOR_FORWARD) {
        result = gpioWrite(MOTOR_IN1_PIN, 1);
        if (result < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Error setting MOTOR_IN1_PIN: %d", result);
            log_message(error_message);
            return -1;
        }
        result = gpioWrite(MOTOR_IN2_PIN, 0);
        if (result < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Error setting MOTOR_IN2_PIN: %d", result);
            log_message(error_message);
            return -1;
        }
        log_message("Motor started forward");
    } else if (direction == MOTOR_BACKWARD) {
        result = gpioWrite(MOTOR_IN1_PIN, 0);
        if (result < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Error setting MOTOR_IN1_PIN: %d", result);
            log_message(error_message);
            return -1;
        }
        result = gpioWrite(MOTOR_IN2_PIN, 1);
        if (result < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Error setting MOTOR_IN2_PIN: %d", result);
            log_message(error_message);
            return -1;
        }
        log_message("Motor started backward");
    } else {
        log_message("Invalid motor direction");
        return -1;
    }

    gpioDelay(duration * 1000000); // Delay for the specified duration (microseconds)

    result = gpioWrite(MOTOR_ENA_PIN, 0);
    if (result < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Error stopping motor: %d", result);
        log_message(error_message);
        return -1;
    }
    log_message("Motor stopped");
    return 0;
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting RAIN_SENSOR_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting MOTOR_ENA_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting MOTOR_IN1_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting MOTOR_IN2_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected == 1) {
            log_message("Rain detected, closing window");
            if (control_motor(MOTOR_FORWARD, MOTOR_RUN_DURATION) != 0) {
                log_message("Error controlling motor");
            }
        } else if (rain_detected < 0) {
            log_message("Error reading rain sensor, skipping motor control");
        }

        gpioDelay(2000000); // Delay for 2 seconds (microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_motor(MOTOR_BACKWARD, 0); // Stop the motor
    gpioTerminate(); // Release GPIO resources
    log_message("Program terminated");

    return 0;
}

