#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define BUFFER_SIZE 20
#define MAX31855_READ_ATTEMPTS 3

// Temperature thresholds and duty cycle mappings
#define TEMP_THRESHOLD_1 25.0
#define TEMP_THRESHOLD_2 40.0
#define TEMP_THRESHOLD_3 60.0

#define DUTY_CYCLE_1 0.0
#define DUTY_CYCLE_2 50.0
#define DUTY_CYCLE_3 200.0
#define DUTY_CYCLE_4 100.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} buffer_entry_t;

buffer_entry_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_gpio();
int init_spi();
int read_max31855(float *temperature);
int calculate_duty_cycle(float temperature);
void set_fan_speed(int duty_cycle);
void signal_handler(int signal);
void print_buffer();
void add_to_buffer(float temperature, int duty_cycle);

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    return 0;
}

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read temperature from MAX31855
int read_max31855(float *temperature) {
    unsigned char data[4];
    int i, attempts = 0;

    while (attempts < MAX31855_READ_ATTEMPTS) {
        int count = spiRead(spi_handle, data, 4);
        if (count == 4) {
            // Check for fault bits
            if (data[3] & 0x04) {
                fprintf(stderr, "MAX31855 Fault: Open circuit\n");
