#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_TEMPDATA 0xF6
#define BMP180_REG_PRESSUREDATA 0xF6
#define BMP180_REG_CALIB_START 0xAA

// Oversampling setting
#define OSS 3

// GPIO pin for interrupt
#define INTERRUPT_PIN 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t logging_enabled = 0;
volatile sig_atomic_t program_running = 1;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
float calculate_temperature(int raw_temp);
float calculate_pressure(int raw_pressure, int raw_temp);
float calculate_altitude(float pressure);
int log_data(float temperature, float pressure);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CALIB_START, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int *raw_temp) {
    char write_data[2] = {BMP180_REG_CONTROL, 0x2E}; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_data, 2) != 2) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_TEMPDATA, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int *raw_pressure) {
    char write_data[2] = {BMP180_REG_CONTROL, 0x34 + (OSS << 6)}; // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_data, 2) != 2) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }
    gpioDelay(2 + (3 << OSS)) ; // Wait for conversion

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_PRESSUREDATA, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in Celsius
float calculate_temperature(int raw_temp) {
    long x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temp) {
    long x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * ((b6 * b6) >> 12)) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3 + x4) << OSS) + 2) >> 2;

    unsigned long p;
    x1 = ((long)ac3 * b6) >> 13;
    x2 = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    long b4 = ((unsigned long)ac4 * (unsigned long)(x1 + x2 + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    float pressure = p + ((x1 + x2 + 3791) >> 4);
    return pressure;
}

// Function to calculate altitude
float calculate_altitude(float pressure) {
    float sea_level_pressure = 101325.0f; // Standard sea level pressure in Pascals
    return 44330.0f * (1.0f - pow(pressure / sea_level_pressure, 0.1903f));
}

// Function to log data to file
int log_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    logging_enabled = !logging_enabled;
    printf("Logging toggled to: %d\n", logging_enabled);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO2 as input with pull-up resistor
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    // Set interrupt handler
    gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL);

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        if (logging_enabled) {
            int raw_temp, raw_pressure;
            float temperature, pressure, altitude;

            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                temperature = calculate_temperature(raw_temp);
                pressure = calculate_pressure(raw_pressure, raw_temp);
                altitude = calculate_altitude(pressure);

                log_data(temperature, pressure);
                printf("Temperature: %.2f C, Pressure: %.2f Pa, Altitude: %.2f m\n", temperature, pressure, altitude);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }
        sleep(1);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

