    spi_fd = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_fd);
        return -1;
    }
    return 0;
}

// Function to read data from MAX31865
int read_max31865(uint8_t *data) {
    int i, result, retry = 0;
    int delay_ms = 1; // Initial delay

    while (retry < RETRY_COUNT) {
        result = spiXfer(spi_fd, (char *)data, (char *)data, 4); // Read 4 bytes
