float calculate_temperature(uint16_t rtd_value) {
    float rtd_resistance = (float)rtd_value / 32768.0; // 14-bit resolution
    float temperature = -242.02 + 0.003922 * rtd_resistance + 0.0000675 * rtd_resistance * rtd_resistance;
