        uint8_t data[4];
        uint16_t rtd_value;
        float temperature;

        // Read data from MAX31865
        if (read_max31865(data) == 0) {
            // Extract RTD value (bits 31:18)
            rtd_value = ((uint16_t)data[0] << 8) | data[1];

            // Check for fault conditions
            if (data[3] & 0x07) {
                fprintf(stderr, "Fault detected: %02X\n", data[3]);
                fprintf(log_fp, "Fault detected: %02X\n", data[3]);
            }

            // Calculate temperature
            temperature = calculate_temperature(rtd_value);

            // Log temperature
            log_temperature(temperature);

            // Print temperature to console
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(5); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

