// Initialize the BME280 sensor
int init_bme280() {
    // Set humidity oversampling to 1x
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_HUM register\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and mode to normal
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
