        // Compensate data
        temperature = compensate_temperature(raw_temperature);
        pressure = compensate_pressure(raw_pressure, temperature);
        humidity = compensate_humidity(raw_humidity, temperature);

        // Log data
        if (log_data(temperature, humidity, pressure) < 0) {
            fprintf(stderr, "Failed to log data, retrying in 5 seconds...\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

