// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// GPIO pin for alert
#define ALERT_PIN 24

// Circular buffer size (60 seconds * 50ms = 3000 samples)
#define BUFFER_SIZE 3000

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold pressure data with timestamp
typedef struct {
    time_t timestamp;
    float pressure;
} pressure_data_t;

// Global variables
int i2c_fd;
bmp180_calibration_data_t calibration_data;
pressure_data_t pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;
bool alert_active = false;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp180_calibration_data_t *calibration);
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
float calculate_temperature(int raw_temp, bmp180_calibration_data_t calibration);
float calculate_pressure(int raw_pressure, int raw_temp, bmp180_calibration_data_t calibration);
void add_to_buffer(float pressure);
float calculate_rolling_average();
bool check_pressure_deviation(float current_pressure, float average_pressure);
void trigger_alert();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(BMP180_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data(bmp180_calibration_data_t *calibration) {
    calibration->ac1 = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC1);
    calibration->ac2 = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC2);
    calibration->ac3 = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC3);
    calibration->ac4 = (uint16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC4);
    calibration->ac5 = (uint16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC5);
    calibration->ac6 = (uint16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC6);
    calibration->b1 = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_B1);
    calibration->b2 = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_B2);
    calibration->mb = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MB);
    calibration->mc = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MC);
    calibration->md = (int16_t)wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MD);

    // Check for I2C errors
    if (calibration->ac1 == -1 || calibration->ac2 == -1 || calibration->ac3 == -1 ||
        calibration->ac4 == -1 || calibration->ac5 == -1 || calibration->ac6 == -1 ||
        calibration->b1 == -1 || calibration->b2 == -1 || calibration->mb == -1 ||
        calibration->mc == -1 || calibration->md == -1) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int *raw_temp) {
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x2E); // Request temperature reading
    delay(5); // Wait for conversion (at least 4.5ms)

    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);

    if (msb == -1 || lsb == -1) {
        fprintf(stderr, "Error reading raw temperature data: %s\n", strerror(errno));
        return -1;
    }

    *raw_temp = (msb << 8) + lsb;
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int *raw_pressure) {
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)); // Request pressure reading
    delay(2 + (3 << BMP180_OSS)); // Wait for conversion

    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        fprintf(stderr, "Error reading raw pressure data: %s\n", strerror(errno));
        return -1;
    }

    *raw_pressure = ((msb << 16) + (lsb << 8) + xlsb) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int raw_temp, bmp180_calibration_data_t calibration) {
    long x1 = (((long)raw_temp - (long)calibration.ac6) * (long)calibration.ac5) >> 15;
    long x2 = ((long)calibration.mc << 11) / (x1 + calibration.md);
    long b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temp, bmp180_calibration_data_t calibration) {
    long x1 = (((long)raw_temp - (long)calibration.ac6) * (long)calibration.ac5) >> 15;
    long x2 = ((long)calibration.mc << 11) / (x1 + calibration.md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)calibration.b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)calibration.ac2 * b6) >> 11;
    long b3 = (((((long)calibration.ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    unsigned long x1_pressure = ((long)calibration.ac3 * b6) >> 13;
    unsigned long x2_pressure = ((long)calibration.b1 * ((b6 * b6) >> 12)) >> 16;
    unsigned long x3_pressure = ((x1_pressure + x2_pressure + 2) >> 2);
    unsigned long b4 = ((unsigned long)calibration.ac4 * (x3_pressure + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);

    long pressure;
    if (b7 < 0x80000000) {
        pressure = (b7 * 2) / b4;
    } else {
        pressure = (b7 / b4) * 2;
    }

    x1_pressure = (pressure >> 8) * (pressure >> 8);
    x1_pressure = (x1_pressure * 3038) >> 16;
    x2_pressure = (-7357 * pressure) >> 16;
    pressure = pressure + ((x1_pressure + x2_pressure + 3791) >> 4);

    return pressure;
}

// Function to add pressure data to the circular buffer
void add_to_buffer(float pressure) {
    pressure_buffer[buffer_index].timestamp = time(NULL);
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average of pressure readings
float calculate_rolling_average() {
    float sum = 0.0f;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += pressure_buffer[i].pressure;
    }
    return sum / BUFFER_SIZE;
}

// Function to check if the current pressure deviates from the rolling average
bool check_pressure_deviation(float current_pressure, float average_pressure) {
    float difference = current_pressure - average_pressure;
    if (difference > 500.0f) {
        return true;
    } else if (difference < -500.0f) {
        return true;
    } else {
        return false;
    }
}

// Function to trigger the alert
void trigger_alert() {
    digitalWrite(ALERT_PIN, HIGH);
    fprintf(stderr, "Alert triggered! Pressure deviation detected.\n");
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to clean up resources
void cleanup() {
    // Reset GPIO pin
    digitalWrite(ALERT_PIN, LOW);

    // Close I2C interface
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Reset wiringPi
    wiringPiSetup(); // Reinitialize to reset
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calibration_data) == -1) {
        cleanup();
        return 1;
    }

    // Configure GPIO pin as output
    pinMode(ALERT_PIN, OUTPUT);
    digitalWrite(ALERT_PIN, LOW);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("BMP180 pressure sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int raw_temp, raw_pressure;
        float temperature, pressure;

        // Read raw temperature
        if (read_raw_temperature(&raw_temp) == -1) {
            fprintf(stderr, "Error reading raw temperature, retrying I2C initialization...\n");
            close(i2c_fd);
            delay(1000); // Wait before retrying
            if (init_i2c() == -1) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                break; // Exit the loop if re-initialization fails
            }
            continue; // Skip to the next iteration
        }

        // Read raw pressure
        if (read_raw_pressure(&raw_pressure) == -1) {
            fprintf(stderr, "Error reading raw pressure, retrying I2C initialization...\n");
            close(i2c_fd);
            delay(1000); // Wait before retrying
            if (init_i2c() == -1) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                break; // Exit the loop if re-initialization fails
            }
            continue; // Skip to the next iteration
        }

        // Calculate temperature and pressure
