    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x2E); // Request temperature reading
    delay(5); // Wait for conversion (at least 4.5ms)

    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);

    if (msb == -1 || lsb == -1) {
        fprintf(stderr, "Error reading raw temperature data: %s\n", strerror(errno));
        return -1;
    }

    *raw_temp = (msb << 8) + lsb;
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int *raw_pressure) {
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)); // Request pressure reading
    delay(2 + (3 << BMP180_OSS)); // Wait for conversion

    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        fprintf(stderr, "Error reading raw pressure data: %s\n", strerror(errno));
        return -1;
