    long b3 = (((((long)calibration.ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    unsigned long x1_pressure = ((long)calibration.ac3 * b6) >> 13;
    unsigned long x2_pressure = ((long)calibration.b1 * ((b6 * b6) >> 12)) >> 16;
