    long b6 = b5 - 4000;
    long x3 = ((long)b2 * ((b6 * b6) >> 12)) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3 + x4) << OSS) + 2) >> 2;

    unsigned long p;
    x1 = ((long)ac3 * b6) >> 13;
    x2 = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2 + 2) >> 2);
    unsigned long b4 = ((unsigned long)ac4 * (unsigned long)(x3 + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);

    if (b7 < 0x80000000)
