    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    double pressure = p + ((x1 + x2 + 3791) >> 4);
    return pressure;
}

// Function to log data to a file
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Timer interrupt handler
void timer_interrupt_handler() {
    int raw_temp, raw_pressure;
    double temperature, pressure;

    if (read_raw_temperature(&raw_temp) != 0) {
        fprintf(stderr, "Error reading raw temperature in interrupt\n");
        return;
    }

    if (read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Error reading raw pressure in interrupt\n");
        return;
    }

    temperature = calculate_temperature(raw_temp);
    pressure = calculate_pressure(raw_pressure, raw_temp);

    log_data(temperature, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer interrupt (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_interrupt_handler, NULL);

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

