#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"

volatile sig_atomic_t program_running = 1;

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to map temperature to duty cycle
int map_temp_to_duty_cycle(int temp) {
    if (temp < 40) {
        return 0;
    } else if (temp > 70) {
        return 255;
    } else {
        return (int)(((float)(temp - 40) / (70 - 40)) * 255);
    }
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(int temp, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %d, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temp, duty_cycle);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
}

int main() {
    int temp, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(GPIO_PIN, 255);

    // Set PWM duty cycle to 0 initially
    set_pwm_duty_cycle(0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Failed to read temperature, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        duty_cycle = map_temp_to_duty_cycle(temp);

        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            fprintf(stderr, "Failed to set duty cycle, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        if (log_data(temp, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        printf("Temperature: %d, Duty Cycle: %d\n", temp, duty_cycle);

        sleep(5);
    }

    // Stop the fan and terminate pigpio
    set_pwm_duty_cycle(0);
    gpioTerminate();

    printf("Fan control program stopped.\n");

    return 0;
}

