#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define ALERT_LED_GPIO 18
#define BUFFER_SIZE 60
#define ALERT_THRESHOLD 28.0
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int i2c_handle;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
pthread_mutex_t mutex;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(double *temperature);
double calculate_average();
void *alert_led_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from LM75 sensor
int read_temperature(double *temperature) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    int raw_temp = (buf[0] << 8) | buf[1];
    if (raw_temp & 0x8000) {
        raw_temp |= 0xF000; // Sign extend if negative
    }
    *temperature = (double)raw_temp / 256.0;

    return 0; // Indicate success
}

// Function to calculate the running average of the temperature readings
double calculate_average() {
    pthread_mutex_lock(&mutex);
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    double average = sum / BUFFER_SIZE;
    pthread_mutex_unlock(&mutex);
    return average;
}

// Thread function to control the alert LED
void *alert_led_thread(void *arg) {
    double average_temperature;
    while (!terminate) {
        calculate_average();
        average_temperature = *temperature_buffer[buffer_index];
        if (average_temperature > ALERT_THRESHOLD) {
            gpioWrite(ALERT_LED_GPIO, 1); // Turn LED on
        } else {
            gpioWrite(ALERT_LED_GPIO, 0); // Turn LED off
        }
        sleep(SAMPLE_INTERVAL);
    }
    pthread_exit(NULL);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(ALERT_LED_GPIO, 0); // Turn off LED
    gpioSetMode(ALERT_LED_GPIO, PI_INPUT); // Set GPIO back to input
    i2cClose(i2c_handle);
    pthread_mutex_destroy(&mutex);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(ALERT_LED_GPIO, PI_OUTPUT);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    double temperature;
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            pthread_mutex_lock(&mutex);
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            pthread_mutex_unlock(&mutex);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying...\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

