#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration structure
typedef struct {
    double target_temperature;
    double Kp;
    double Ki;
    double Kd;
    int spi_channel;
    int pwm_pin;
    int pwm_frequency;
    int driver_range;
    char log_file[256];
} Config;

// Global variables
static int spi_handle;
static int pwm_handle;
static volatile sig_atomic_t terminate = 0;
static Config config;

// Function prototypes
int read_config(const char *filename, Config *config);
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error, double dt, double Kp, double Ki, double Kd);
int set_pwm_duty_cycle(double duty_cycle);
void signal_handler(int signal);
void log_message(const char *message);

// Function to read the configuration from a JSON file
int read_config(const char *filename, Config *config) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load configuration file: %s\n", error.text);
        return 1;
    }

    config->target_temperature = json_real_value(json_object_get(root, "target_temperature"));
    config->Kp = json_real_value(json_object_get(root, "Kp"));
    config->Ki = json_real_value(json_object_get(root, "Ki"));
    config->Kd = json_real_value(json_object_get(root, "Kd"));
    config->spi_channel = json_integer_value(json_object_get(root, "spi_channel"));
    config->pwm_pin = json_integer_value(json_object_get(root, "pwm_pin"));
    config->pwm_frequency = json_integer_value(json_object_get(root, "pwm_frequency"));
    config->driver_range = json_integer_value(json_object_get(root, "driver_range"));
    strncpy(config->log_file, json_string_value(json_object_get(root, "log_file")), sizeof(config->log_file) - 1);
    config->log_file[sizeof(config->log_file) - 1] = '\0'; // Ensure null termination

    json_decref(root);
    return 0;
}

// Function to read the temperature from the PT100 RTD
double read_temperature() {
    unsigned char data[5];
    int i;
    double rtd_resistance, temperature;

    // Read 5 bytes from SPI
    spiRead(spi_handle, (char *)data, 5);

    // Extract RTD resistance (bits 0-3) and fault status (bit 4)
    int fault = (data[4] & 0x01) ? 1 : 0; // Check for fault bit
    if (fault) {
        log_message("Error: MAX31865 fault detected!");
        return -273.15; // Return absolute zero as error indicator
    }

    // Extract RTD MSB (bits 0-3)
    rtd_resistance = ((data[0] << 8) | data[1]) >> 1; // Shift right by 1 to account for sign bit

    // Convert RTD resistance to temperature (PT100 formula)
    temperature = (rtd_resistance - 430.0) / 3.9083;

    return temperature;
}

// Function to calculate the PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error, double dt, double Kp, double Ki, double Kd) {
    double error = setpoint - actual_temperature;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set the PWM duty cycle
int set_pwm_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    int pwm_value = (int)(duty_cycle * (pwm_handle) / 1000.0); // Scale duty cycle to driver range
    gpioPWM(pwm_handle, pwm_value);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_message("Signal received, shutting down...");
}

// Function to log messages with timestamps
void log_message(const char *message) {
    FILE *fp = fopen(config.log_file, "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        fprintf(stderr, "Error: Could not open log file: %s\n", config.log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Read configuration from file
    if (read_config("config.json", &config) != 0) {
        fprintf(stderr, "Error: Failed to read configuration. Using default values.\n");
        config.target_temperature = 25.0;
        config.Kp = 1.0;
        config.Ki = 0.1;
        config.Kd = 0.01;
        config.spi_channel = 0;
        config.pwm_pin = 18;
        config.pwm_frequency = 1000;
        config.driver_range = 1000;
        strncpy(config.log_file, "error.log", sizeof(config.log_file) - 1);
        config.log_file[sizeof(config.log_file) - 1] = '\0';
    }

    // Initialize SPI
    spi_handle = spiOpen(config.spi_channel, 500000, 0); // Channel, frequency, mode
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize PWM
    pwm_handle = gpioSetMode(config.pwm_pin, PI_OUTPUT);
    if (pwm_handle < 0) {
        fprintf(stderr, "Error: GPIO mode setting failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(pwm_handle, config.pwm_frequency);

    // Set PWM range
    gpioSetPWMrange(pwm_handle, config.driver_range);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    double integral = 0.0;
    double previous_error = 0.0;
    double dt = 0.01; // 100ms
    double pid_output;
    double duty_cycle;

    // Main loop
    while (!terminate) {
        // Read temperature
        double temperature = read_temperature();

        if (temperature < -273.0) {
            log_message("Error: Failed to read temperature. Retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate PID output
        pid_output = calculate_pid(config.target_temperature, temperature, &integral, &previous_error, dt, config.Kp, config.Ki, config.Kd);

        // Set PWM duty cycle
        duty_cycle = pid_output;
        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            log_message("Error: Failed to set PWM duty cycle.");
        }

        // Log temperature and duty cycle
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Temperature: %.2f C, Duty Cycle: %.2f%%", temperature, duty_cycle);
        log_message(log_buffer);

        gpioDelay(100); // Wait 100ms
    }

    // Shutdown sequence
    set_pwm_duty_cycle(0.0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

