        return 1;
    }

    // Read configuration from file
    if (read_config("config.json", &config) != 0) {
        fprintf(stderr, "Error: Failed to read configuration. Using default values.\n");
        config.target_temperature = 25.0;
        config.Kp = 1.0;
        config.Ki = 0.1;
        config.Kd = 0.01;
        config.spi_channel = 0;
        config.pwm_pin = 18;
        config.pwm_frequency = 1000;
        config.driver_range = 1000;
        strncpy(config.log_file, "error.log", sizeof(config.log_file) - 1);
        config.log_file[sizeof(config.log_file) - 1] = '\0';
    }

    // Initialize SPI
    spi_handle = spiOpen(config.spi_channel, 500000, 0); // Channel, frequency, mode
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize PWM
    pwm_handle = gpioSetMode(config.pwm_pin, PI_OUTPUT);
    if (pwm_handle < 0) {
        fprintf(stderr, "Error: GPIO mode setting failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(pwm_handle, config.pwm_frequency);

    // Set PWM range
    gpioSetPWMrange(pwm_handle, config.driver_range);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    double integral = 0.0;
    double previous_error = 0.0;
    double dt = 0.01; // 100ms
    double pid_output;
    double duty_cycle;

    // Main loop
    while (!terminate) {
        // Read temperature
        double temperature = read_temperature();

        if (temperature < -273.0) {
            log_message("Error: Failed to read temperature. Retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate PID output
        pid_output = calculate_pid(config.target_temperature, temperature, &integral, &previous_error, dt, config.Kp, config.Ki, config.Kd);

        // Set PWM duty cycle
        duty_cycle = pid_output;
        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            log_message("Error: Failed to set PWM duty cycle.");
        }

        // Log temperature and duty cycle
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Temperature: %.2f C, Duty Cycle: %.2f%%", temperature, duty_cycle);
        log_message(log_buffer);

        gpioDelay(100); // Wait 100ms
    }

    // Shutdown sequence
    set_pwm_duty_cycle(0.0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

