// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    char write_buf[2];

    // Write temperature conversion command
    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }

    // Wait for conversion (4.5ms)
    gpioDelay(5000); // 5ms

    // Read raw temperature data
    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, write_buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing read register address\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
