}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    char write_buf[2];

    // Write pressure conversion command
    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    // Wait for conversion (based on OSS)
    switch (BMP180_OSS) {
        case 0: gpioDelay(5000); break; // 4.5ms
        case 1: gpioDelay(8000); break; // 7.5ms
        case 2: gpioDelay(14000); break; // 13.5ms
        case 3: gpioDelay(26000); break; // 25.5ms
        default: gpioDelay(5000); break; // 4.5ms
    }

    // Read raw pressure data
    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, write_buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing read register address\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS); // Shift right by (8 - OSS) bits
    return 0;
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int raw_temp) {
    long x1, x2, b5;
    x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_pressure, int raw_temp) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    long ut = raw_temp;
    long up = raw_pressure;

    long x1_temp = (((long)ut - (long)ac6) * (long)ac5) >> 15;
    long x2_temp = ((long)mc << 11) / (x1_temp + md);
    long b5_temp = x1_temp + x2_temp;

    b6 = b5_temp - 4000;
