#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define OSS 0

// GPIO pin for fan control
#define FAN_PIN 18

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
sensor_data_t data_buffer[BUFFER_SIZE];
int buffer_index = 0;
int fan_state = 0; // 0 = off, 1 = on
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp180_calibration_data_t *calibration);
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_temperature(int32_t ut, bmp180_calibration_data_t calibration);
float calculate_pressure(int32_t up, int32_t ut, bmp180_calibration_data_t calibration);
void add_to_buffer(float temperature, float pressure);
void print_buffer();
void control_fan(float temperature);
void timer_callback();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data(bmp180_calibration_data_t *calibration) {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calibration->ac1 = (data[0] << 8) | data[1];
    calibration->ac2 = (data[2] << 8) | data[3];
    calibration->ac3 = (data[4] << 8) | data[5];
    calibration->ac4 = (data[6] << 8) | data[7];
    calibration->ac5 = (data[8] << 8) | data[9];
    calibration->ac6 = (data[10] << 8) | data[11];
    calibration->b1 = (data[12] << 8) | data[13];
    calibration->b2 = (data[14] << 8) | data[15];
    calibration->mb = (data[16] << 8) | data[17];
    calibration->mc = (data[18] << 8) | data[19];
    calibration->md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int32_t *raw_temperature) {
    char write_data[2] = {BMP180_REG_CONTROL, 0x2E};
    char read_data[2];

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_data, 1) != 1) {
        fprintf(stderr, "Error writing temperature conversion command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, read_data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = (read_data[0] << 8) | read_data[1];
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char write_data[2] = {BMP180_REG_CONTROL, 0x34 + (OSS << 6)};
    char read_data[3];

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_data, 1) != 1) {
        fprintf(stderr, "Error writing pressure conversion command\n");
        return -1;
    }

    gpioDelay(2 + (3 << OSS)); // Wait for conversion

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, read_data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((uint32_t)read_data[0] << 16 | (uint32_t)read_data[1] << 8 | (uint32_t)read_data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int32_t ut, bmp180_calibration_data_t calibration) {
    int32_t x1 = (((int32_t)ut - (int32_t)calibration.ac6) * (int32_t)calibration.ac5) >> 15;
    int32_t x2 = ((int32_t)calibration.mc << 11) / (x1 + calibration.md);
    int32_t b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate pressure in Pascals
float calculate_pressure(int32_t up, int32_t ut, bmp180_calibration_data_t calibration) {
    int32_t x1 = (((int32_t)ut - (int32_t)calibration.ac6) * (int32_t)calibration.ac5) >> 15;
    int32_t x2 = ((int32_t)calibration.mc << 11) / (x1 + calibration.md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = (calibration.b2 * (b6 * b6) >> 12) >> 11;
    x2 = (calibration.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)calibration.ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = (calibration.ac3 * b6) >> 13;
    x2 = (calibration.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (calibration.ac4 * (uint32_t)(x3 + 32768)) >> 15;

    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return p;
}

// Function to add data to the circular buffer
void add_to_buffer(float temperature, float pressure) {
    data_buffer[buffer_index].timestamp = time(NULL);
    data_buffer[buffer_index].temperature = temperature;
    data_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&data_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f C, Pressure: %.2f Pa\n", time_str, data_buffer[index].temperature, data_buffer[index].pressure);
    }
    printf("--- End of Data ---\n\n");
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > 30.0f) {
        if (!fan_state) {
            gpioWrite(FAN_PIN, 1); // Turn fan on
            fan_state = 1;
            printf("Fan turned ON\n");
        }
    } else if (temperature < 28.0f) {
        if (fan_state) {
            gpioWrite(FAN_PIN, 0); // Turn fan off
            fan_state = 0;
            printf("Fan turned OFF\n");
        }
    }
}

// Timer callback function
void timer_callback() {
    int32_t raw_temperature, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temperature) == 0 &&
        read_raw_pressure(&raw_pressure) == 0) {

        temperature = calculate_temperature(raw_temperature, calibration_data);
        pressure = calculate_pressure(raw_pressure, raw_temperature, calibration_data);

        add_to_buffer(temperature, pressure);
        printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);

        control_fan(temperature);
    } else {
        fprintf(stderr, "Error reading sensor data in timer callback\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calibration_data) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure fan pin as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL); // Timer 0, every 500ms

    printf("BMP180 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep to avoid busy-waiting
    }

    // Cleanup
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("BMP180 sensor monitoring stopped.\n");

    return 0;
}

