#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define HEATER_GPIO 17
#define MAX_DUTY_CYCLE 80.0
#define TARGET_TEMPERATURE 25.0
#define LOG_FILE "heater_log.csv"

// MAX31855 Registers
#define MAX31855_CONFIG_REG 0x00
#define MAX31855_FAULT_REG 0x01
#define MAX31855_THERM_REG 0x02
#define MAX31855_THERM_JPEG_REG 0x03

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int spi_init(void);
int read_max31855(float *temperature);
void set_heater_duty_cycle(float duty_cycle);
void pi_controller(float current_temperature, float target_temperature, float *integral, float *previous_error, float *dt);
void log_data(float temperature, float duty_cycle);
void signal_handler(int signal);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "SPI initialization failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read Temperature from MAX31855
int read_max31855(float *temperature) {
    unsigned char data[4];
    int i;

    // Read configuration register (optional, but good practice)
    wiringPiSPIDataRW(SPI_CHANNEL, data, 1);

    // Read fault register
    data[0] = MAX31855_FAULT_REG;
    wiringPiSPIDataRW(SPI_CHANNEL, data, 1);

    // Read thermocouple temperature register
    data[0] = MAX31855_THERM_REG;
    if (wiringPiSPIDataRW(SPI_CHANNEL, data, 4) < 0) {
        fprintf(stderr, "SPI read failed for temperature data: %s\n", strerror(errno));
        return -1;
    }

    // Check for fault
    if (data[1] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        log_data(-999.0, 0.0); // Log error
        return -1;
    } else if (data[1] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        log_data(-999.0, 0.0); // Log error
        return -1;
    } else if (data[1] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        log_data(-999.0, 0.0); // Log error
        return -1;
    }

    // Extract thermocouple temperature (signed 14-bit value)
    int16_t thermocouple_data = ((data[2] << 6) | (data[3] >> 2));

    // Convert to temperature (see MAX31855 datasheet)
    *temperature = thermocouple_data * 0.25;

    return 0;
}

// Set Heater Duty Cycle using PWM
void set_heater_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    int pwm_value = (int)(duty_cycle * 255.0 / MAX_DUTY_CYCLE); // Scale duty cycle to 0-255
    pwmWrite(HEATER_GPIO, pwm_value);
}

// PI Controller
void pi_controller(float current_temperature, float target_temperature, float *integral, float *previous_error, float *dt) {
    float error = target_temperature - current_temperature;
    *integral += error * *dt;
    float derivative = (error - *previous_error) / *dt;

    float output = (0.5 * *integral) + (0.1 * derivative);

    // Clamp output to 0-100%
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;

    float duty_cycle = output;

    // Anti-windup
    if (output > 100.0) {
        duty_cycle = 100.0;
    }
    if (output < 0.0) {
        duty_cycle = 0.0;
    }

    set_heater_duty_cycle(duty_cycle);
    *previous_error = error;
}

// Log Data to File
void log_data(float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal Handler for Graceful Shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Cleanup Function
void cleanup(void) {
    printf("Cleaning up resources...\n");
    set_heater_duty_cycle(0.0); // Turn off heater
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main(void) {
    float temperature, integral = 0.0, previous_error = 0.0, dt = 1.0; // dt = 1 second
    int spi_status, fault_status;
    float duty_cycle;

    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (spi_init() == -1) {
        return 1;
    }

    // Set GPIO mode for heater control
    pinMode(HEATER_GPIO, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS); // Mark:Space PWM mode
    pwmSetRange(255);        // PWM range of 0-255
    pwmSetClock(192);       // Adjust clock for desired PWM frequency (optional)

