    pwmSetRange(255);        // PWM range of 0-255
    pwmSetClock(192);       // Adjust clock for desired PWM frequency (optional)

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature control system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature from MAX31855
        spi_status = read_max31855(&temperature);
        if (spi_status == 0) {
            // PI Controller
            pi_controller(temperature, TARGET_TEMPERATURE, &integral, &previous_error, &dt);

            // Set heater duty cycle
            duty_cycle = (float)pi_controller(temperature, TARGET_TEMPERATURE, &integral, &previous_error, &dt).duty_cycle;

