// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature file path
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Define temperature ranges and corresponding LED colors
#define TEMP_LOW  40000
#define TEMP_MED  60000

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file %s\n", TEMP_FILE);
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error: Could not read temperature from file %s\n", TEMP_FILE);
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp;
}

// Function to set RGB LED color using hardware PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);   // Invert for common anode
    gpioPWM(GREEN_PIN, 255 - green); // Invert for common anode
    gpioPWM(BLUE_PIN, 255 - blue);  // Invert for common anode
}

// Function to map temperature to RGB color
void map_temp_to_color(int temp, int *red, int *green, int *blue) {
    if (temp < TEMP_LOW) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temp >= TEMP_LOW && temp <= TEMP_MED) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main() {
    int temp;
    int red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(BLUE_PIN, 1000); // 1 kHz

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error reading temperature, skipping update cycle.\n");
            sleep(0.5);
            continue;
        }

        // Convert temperature to millidegrees Celsius
        int temp_millidegrees = temp * 1000 / 1000; // No conversion needed, just cast

        // Map temperature to RGB color
        map_temp_to_color(temp_millidegrees, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Print temperature and PWM values
        printf("Temp: %d m°C, R: %d, G: %d, B: %d\n", temp_millidegrees, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup and exit
    gpioWrite(RED_PIN, 0);   // Turn off Red
    gpioWrite(GREEN_PIN, 0); // Turn off Green
    gpioWrite(BLUE_PIN, 0);  // Turn off Blue

    gpioTerminate(); // Terminate pigpio

    return 0;
}

