#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY 1 // seconds

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int checksum;
} DHT22Data;

// Global variables for graceful shutdown
static volatile int running = 1;
static int terminate_flag = 0;

// Signal handler function
void signal_handler(int sig) {
    running = 0;
    printf("Signal received, exiting gracefully...\n");
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(DHT22_GPIO, PI_OUTPUT); // Set GPIO as output initially
    return 0;
}

// Function to send the start signal to the DHT22 sensor
int send_start_signal() {
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0); // Pull the line low
    gpioDelay(1); // Wait for at least 1 ms
    gpioSetMode(DHT22_GPIO, PI_INPUT); // Release the line
    gpioDelay(30); // Wait for sensor to respond
    return 0;
}

// Function to read data from the DHT22 sensor
int read_dht22_data(unsigned char *data) {
    gpioSetMode(DHT22_GPIO, PI_INPUT); // Ensure GPIO is in input mode
    gpioDelay(1); // Small delay after setting to input
    int i = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1); // Wait for the line to go low
        i++;
        if (i > 100) return -1; // Timeout if no response
    }

    for (int j = 0; j < 40; j++) {
        // Wait for the line to go high
        int count = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            count++;
            gpioDelay(1);
            if (count > 100) return -1; // Timeout
        }

        // Measure the length of the high pulse
        long start = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1);
            if (gpioTick() - start > 100) return -1; // Timeout
        }
        long end = gpioTick();
        long pulse_length = end - start;

        // Determine if it's a 0 or a 1 based on the pulse length
        if (pulse_length > 40) {
            data[j / 8] |= (1 << (7 - (j % 8)));
        }
    }

    return 0;
}

// Function to validate the checksum
int validate_checksum(const unsigned char *data) {
    unsigned char checksum = 0;
    for (int i = 0; i < 32; i++) {
        checksum += data[i];
    }

    if (checksum != data[32]) {
        return -1; // Checksum mismatch
    }

    return 0;
}

// Function to convert raw data to temperature and humidity
DHT22Data convert_data(const unsigned char *data) {
    DHT22Data result;
    result.humidity = (float)(((data[0] << 8) | data[1]) / 10.0);
    result.temperature = (float)(((data[2] << 8) | data[3]) / 10.0);
    result.checksum = data[32];
    return result;
}

// Function to format data into a JSON string
char *format_json(float temperature, float humidity) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    sprintf(json_string, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to post data to the server
int post_data(const char *json_string) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_URL, "http://yourserver.com/api/humidity");
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 400) {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    unsigned char dht22_data[5] = {0};
    DHT22Data dht22_data_obj;
    int retries = 0;
    int result = 0;

    while (running) {
        // Send start signal
        if (send_start_signal() != 0) {
            fprintf(stderr, "Failed to send start signal, retrying...\n");
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting...\n");
                break;
            }
            sleep(RETRY_DELAY);
            continue;
        }

        // Read data from DHT22
        if (read_dht22_data(dht22_data) != 0) {
            fprintf(stderr, "Failed to read DHT22 data, retrying...\n");
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting...\n");
                break;
            }
            sleep(RETRY_DELAY);
            continue;
        }

        // Validate checksum
        if (validate_checksum(dht22_data) != 0) {
            fprintf(stderr, "Checksum validation failed, retrying...\n");
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting...\n");
                break;
            }
            sleep(RETRY_DELAY);
            continue;
        }

        // Convert data
        dht22_data_obj = convert_data(dht22_data);

        // Format data into JSON
        char *json_string = format_json(dht22_data_obj.temperature, dht22_data_obj.humidity);
        if (json_string == NULL) {
            fprintf(stderr, "Failed to format JSON, retrying...\n");
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting...\n");
                break;
            }
            sleep(RETRY_DELAY);
            continue;
        }

        // Post data to server
        result = post_data(json_string);
        if (result != 0) {
            fprintf(stderr, "Failed to post data, retrying...\n");
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting...\n");
                break;
            }
            sleep(RETRY_DELAY);
            continue;
        }

        printf("Data posted successfully: %s\n", json_string);

        free(json_string); // Free the allocated memory

        sleep(5); // Wait 5 seconds before next reading
    }

    gpioTerminate(); // Terminate pigpio
    return 0;
}

