#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <stdbool.h>

// BMP180 I2C address
#define BMP180_I2C_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Oversampling setting
#define OSS 3

// GPIO pin for push-button interrupt
#define BUTTON_PIN 4

// Debounce delay in microseconds
#define DEBOUNCE_DELAY 200000

// Global variables
static int i2c_fd = -1;
static volatile bool logging_enabled = false;
static volatile unsigned long last_interrupt_time = 0;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c(int address);
int read_calibration_data(int fd);
int read_raw_temperature(int fd);
int read_raw_pressure(int fd);
float calculate_temperature(int raw_temperature);
float calculate_pressure(int raw_pressure, int raw_temperature);
void toggle_logging();
void interrupt_handler(void);
void signal_handler(int signal);
void log_pressure(float pressure);
void print_status_message(void);

// Function to initialize I2C
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to read calibration data from BMP180
int read_calibration_data(int fd) {
    ac1 = wiringPiI2CReadReg16(fd, 0xAA);
    ac2 = wiringPiI2CReadReg16(fd, 0xAC);
    ac3 = wiringPiI2CReadReg16(fd, 0xAE);
    ac4 = wiringPiI2CReadReg16(fd, 0xB0);
    ac5 = wiringPiI2CReadReg16(fd, 0xB2);
    ac6 = wiringPiI2CReadReg16(fd, 0xB4);
    b1 = wiringPiI2CReadReg16(fd, 0xB6);
    b2 = wiringPiI2CReadReg16(fd, 0xB8);
    mb = wiringPiI2CReadReg16(fd, 0xBA);
    mc = wiringPiI2CReadReg16(fd, 0xBC);
    md = wiringPiI2CReadReg16(fd, 0xBE);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int fd) {
    wiringPiI2CWriteReg8(fd, BMP180_REG_CONTROL, 0x2E);
    delay(5); // Wait 4.5ms
    int msb = wiringPiI2CReadReg8(fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(fd, BMP180_REG_LSB);
    if (msb == -1 || lsb == -1) {
        fprintf(stderr, "Error reading raw temperature data: %s\n", strerror(errno));
        return -1;
    }
    return (msb << 8) + lsb;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int fd) {
    wiringPiI2CWriteReg8(fd, BMP180_REG_CONTROL, 0x34 + (OSS << 6));
    delay(2 + (3 << OSS)); // Wait for conversion
    int msb = wiringPiI2CReadReg8(fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(fd, BMP180_REG_XLSB);
    if (msb == -1 || lsb == -1 || xlsb == -1) {
        fprintf(stderr, "Error reading raw pressure data: %s\n", strerror(errno));
        return -1;
    }
    return ((msb << 16) + (lsb << 8) + xlsb) >> (8 - OSS);
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int raw_temperature) {
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_pressure, int raw_temperature) {
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3) << OSS) + 2) >> 2;

    unsigned long x5 = ((unsigned long)ac4 * (unsigned long)(x3 + x4 + 32768)) >> 15;
    unsigned long x6 = ((unsigned long)md * (b6 * b6) >> 12) >> 13;
    unsigned long b4 = ((unsigned long)ac3 * (unsigned long)(x3 + x4 + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)up - b3) * (50000 >> OSS);

    long p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    float pressure = p + ((x1 + x2 + 3791) >> 4);

    return pressure / 100.0f; // Convert to hPa
}

// Function to toggle logging
void toggle_logging() {
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

// Interrupt handler for push-button
void interrupt_handler(void) {
    unsigned long current_time = millis();
    if (current_time - last_interrupt_time > DEBOUNCE_DELAY) {
        toggle_logging();
        last_interrupt_time = current_time;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    wiringPiSetup(); // Reinitialize wiringPi to reset GPIO
    exit(0);
}

// Function to log pressure data to file
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%s: %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

// Function to print a status message
void print_status_message(void) {
    printf("Pressure logger disabled.\n");
}

int main(void) {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(BMP180_I2C_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd) == -1) {
        close(i2c_fd);
        return 1;
    }

    // Set up interrupt for push-button
    if (wiringPiISR(BUTTON_PIN, INT_EDGE_FALLING, &interrupt_handler) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (logging_enabled) {
            int raw_temperature = read_raw_temperature(i2c_fd);
            int raw_pressure = read_raw_pressure(i2c_fd);

            if (raw_temperature != -1 && raw_pressure != -1) {
                float temperature = calculate_temperature(raw_temperature);
                float pressure = calculate_pressure(raw_pressure, raw_temperature);

                log_pressure(pressure);
                printf("Pressure: %.2f hPa\n", pressure);
            } else {
                fprintf(stderr, "Error reading sensor data.\n");
            }

            delay(2000); // Wait 2 seconds
        } else {
            print_status_message();
            delay(100); // Check every 100ms
        }
    }

    return 0;
}

