#include <pigpio.h>

#define DHT22_GPIO 4
#define DEFAULT_URL "http://your-the-library's-API-call.com/api/humidity"
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2 // seconds

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Structure to hold DHT22 response data
typedef struct {
    uint8_t data[5];
} DHT22Response;

// Global variables
static volatile int running = 1;
static char *api_url = DEFAULT_URL;
static int gpio_initialized = 0;

// Function prototypes
DHT22Data read_dht22();
char *format_json(DHT22Data data);
CURLcode post_data(const char *json_data);
void signal_handler(int signal);
int initialize_driver();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Function to initialize the pigpio library
int initialize_driver() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }
    gpio_initialized = 1;
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    return 0;
}

// Function to cleanup the pigpio library
void cleanup() {
    if (gpio_initialized) {
        gpioTerminate();
        gpio_initialized = 0;
    }
}

// Function to read data from the DHT22 sensor
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0};
    DHT22Response response;
    int i;
    uint32_t start_time, end_time;
    uint32_t pulse_lengths[40];
    int bit_index = 0;
    int checksum = 0;

    // Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // > 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(40); // 20-40us
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read response
    start_time = gpioTick();
    while (bit_index < 40) {
        end_time = gpioTick();
        int pulse_length = end_time - start_time;
        start_time = end_time;

        if (pulse_length > 0) {
            pulse_lengths[bit_index] = pulse_length;

            if (bit_index < 8) {
                // Ignore first 8 bits
                bit_index++;
            } else if (bit_index < 16) {
                // Checksum bits
                checksum = (checksum << 1) | pulse_lengths[bit_index];
            } else {
                // Data bits
                data[bit_index / 8 - 1] = (pulse_lengths[bit_index] > 40) ? 1 : 0; // Convert pulse length to 0/1
            }
        } else {
            syslog(LOG_ERR, "Timeout waiting for response bit");
            data.temperature = -999.0; // Indicate error
            data.humidity = -999.0;
            return data;
        }
        bit_index++;
    }

    // Validate checksum
    if (checksum != ((pulse_lengths[0] + pulse_lengths[1] + pulse_lengths[2] + pulse_lengths[3]) & 0xFF)) {
        syslog(LOG_ERR, "Checksum validation failed");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Extract humidity and temperature
    int humidity_raw = 0;
    int temperature_raw = 0;
    for (i = 0; i < 16; i++) {
        humidity_raw <<= 1;
        humidity_raw |= pulse_lengths[i];
    }

    for (i = 16; i < 32; i++) {
        temperature_raw <<= 1;
        temperature_raw |= pulse_lengths[i];
    }

    data.humidity = (float)humidity_raw / 10.0;
    data.temperature = (float)temperature_raw / 10.0;

    return data;
}

// Function to format the data as JSON
char *format_json(DHT22Data data) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    sprintf(json_string, "{\"temperature\": %.1f, \"humidity\": %.1f}", data.temperature, data.humidity);
    return json_string;
}

// Function to post the data to the API endpoint
CURLcode post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                syslog(LOG_INFO, "Data posted successfully, HTTP status code: %ld", response_code);
            } else {
                syslog(LOG_ERR, "HTTP POST failed with status code: %ld", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        syslog(LOG_ERR, "curl_easy_init() failed");
        curl_global_cleanup();
        return CURLE_FAILED_INIT;
    }
    curl_global_cleanup();
    return res;
}

int main(int argc, char *argv[]) {
    openlog("dht22_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting DHT22 sensor program");

    // Parse command-line arguments
    if (argc > 1) {
        api_url = argv[1];
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the driver
    if (initialize_driver() != 0) {
        syslog(LOG_ERR, "Driver initialization failed, exiting");
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        DHT22Data data = read_dht22();
        if (data.temperature != -999.0) {
            char *json_data = format_json(data);
            if (json_data != NULL) {
                int retries = 0;
                while (retries < MAX_RETRIES) {
                    CURLcode res = post_data(json_data);
                    if (res == CURLE_OK) {
                        break; // Success, exit retry loop
                    } else {
                        syslog(LOG_ERR, "HTTP POST failed, retrying (%d/%d)", retries + 1, MAX_RETRIES);
                        retries++;
                        sleep(BACKOFF_DELAY);
                    }
                }
                if (res != CURLE_OK) {
                    syslog(LOG_ERR, "HTTP POST failed after multiple retries");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 sensor data");
        }

        sleep(10); // Read every 10 seconds
    }

    // Cleanup and exit
    cleanup();
    syslog(LOG_INFO, "Exiting DHT22 sensor program");
    closelog();
    return 0;
}

