#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>
#include <pigpio.h>

// Configuration
#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_SPEED_FILE "/sys/class/thermal/cooling_device0/speed_control"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

// Temperature Tiers
#define TEMP_TIER_0 45
#define TEMP_TIER_1 55
#define TEMP_TIER_2 65

// Cooling Device Max Speeds
#define MAX_SPEED_0 0
#define MAX_SPEED_1 1
#define MAX_SPEED_2 2
#define MAX_SPEED_3 3

// Global Variables
static volatile int running = 1;
static int current_fan_speed = 0;

// Function Prototypes
int read_cpu_temp();
int read_fan_state();
int set_fan_speed(int speed);
int log_event(const char *message);
void signal_handler(int signal);
int validate_max_state(int max_state);

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received shutdown signal. Shutting down...");
        set_fan_speed(0);
        running = 0;
        log_event("Fan control stopped.");
        closelog();
        gpioTerminate();
        exit(0);
    }
}

// Read CPU Temperature
int read_cpu_temp() {
    FILE *fp;
    int temp = 0;

    fp = fopen(CPU_TEMP_FILE, "r");
    if (fp == NULL) {
        log_event("Error opening CPU temperature file.");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        log_event("Error reading CPU temperature.");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp / 1000; // Convert to degrees Celsius
}

// Read Fan State
int read_fan_state() {
    FILE *fp;
    int state = 0;

    fp = fopen(FAN_STATE_FILE, "r");
    if (fp == NULL) {
        log_event("Error opening fan state file.");
        return -1;
    }

    if (fscanf(fp, "%d", &state) != 1) {
        log_event("Error reading fan state.");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return state;
}

// Set Fan Speed
int set_fan_speed(int speed) {
    FILE *fp;
    int ret;

    fp = fopen(FAN_SPEED_FILE, "w");
    if (fp == NULL) {
        log_event("Error opening fan speed file.");
        return -1;
    }

    if (speed < 0 || speed > 3) {
        log_event("Invalid fan speed.");
        fclose(fp);
        return -1;
    }

    ret = fprintf(fp, "%d", speed);
    if (ret < 0) {
        log_event("Error writing to fan speed file.");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Log Event
int log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_event("Error opening log file.");
        return -1;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Validate Maximum Speed
int validate_max_state(int max_state) {
    return (max_state >= 0 && max_state <= 3);
}

int main() {
    int cpu_temp, fan_state, new_speed;
    int current_max_state = 0;

    // Initialize syslog
    openlog("fan_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        closelog();
        return 1;
    }

    log_event("Fan control program started.");

    while (running) {
        // Read CPU Temperature
        cpu_temp = read_cpu_temp();
        if (cpu_temp == -1) {
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        // Read Fan State
        fan_state = read_fan_state();
        if (fan_state == -1) {
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        // Determine New Fan Speed
        if (fan_state == 0) {
            new_speed = 0;
        } else if (fan_state == 1) {
            new_speed = 1;
        } else if (fan_state == 2) {
            new_speed = 2;
        } else {
            new_speed = 3;
        }

        // Validate Maximum Speed
        if (!validate_max_state(new_speed)) {
            log_event("Invalid fan speed, keeping current speed.");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        // Set Fan Speed
        if (fan_state != current_fan_speed) {
            if (set_fan_speed(new_speed) == 0) {
                current_fan_speed = new_speed;
                log_event("Fan speed set to " + (char *)strcat("Off", "1", "2", "3")[current_fan_speed]);
            } else {
                log_event("Failed to set fan speed.");
            }
        }

        // Log Event if Speed Changed
        if (fan_state != current_fan_speed) {
            log_event("Fan speed changed.");
        }

        // Sleep for Poll Interval
        sleep(POLL_INTERVAL_SEC);
    }

    // Cleanup
    gpioTerminate();
    closelog();
    return 0;
}

