#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 100       // Percentage
#define SPI_CHANNEL 0
#define SPI_SPEED 500000     // Hz
#define TARGET_TEMPERATURE 50.0 // Celsius
#define LOG_FILE "heater_log.txt"

// PID Constants
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function Prototypes
float read_temperature();
void set_heater_pwm(int duty_cycle);
float calculate_pid(float setpoint, float actual_value, float Kp, float Ki, float Kd, float *integral, float *previous_error);
void log_data(float temperature, int duty_cycle, float pid_output);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI initialization failed: %s\n", strerror(errno));
        return 1;
    }

    pinMode(HEATER_GPIO, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetClock(192); // Adjust clock for 1kHz PWM frequency
    pwmSetRange(PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int i;

    if (wiringPiSPIDataRW(SPI_CHANNEL, data, 4) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -273.15; // Return absolute zero on error
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(log_file, "Error: Thermocouple open circuit.\n");
        fflush(log_file);
        return -273.15;
    } else if (data[3] & 0x02) {
        fprintf(log_file, "Error: Thermocouple shorted to GND.\n");
        fflush(log_file);
        return -273.15;
    } else if (data[3] & 0x04) {
        fprintf(log_file, "Error: Thermocouple shorted to VCC.\n");
        fflush(log_file);
        return -273.15;
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 3;
    float temperature = (float)raw_temp * 0.25;

    return temperature;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    pwmWrite(HEATER_GPIO, duty_cycle);
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_value, float Kp, float Ki, float Kd, float *integral, float *previous_error) {
    float error = setpoint - actual_value;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to log data to file
void log_data(float temperature, int duty_cycle, float pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Duty Cycle: %d%%, PID Output: %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to cleanup resources
void cleanup() {
    set_heater_pwm(0); // Turn off heater
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
}

int main() {
    float temperature, pid_output;
    int duty_cycle;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    float integral = 0.0;
    float previous_error = 0.0;

    while (program_running) {
        temperature = read_temperature();
        if (temperature < -273.0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
            // Consider a failsafe mechanism here to prevent heater from running indefinitely
            // For example, set duty_cycle to 0 if temperature is consistently below a threshold
        } else {
            pid_output = calculate_pid(TARGET_TEMPERATURE, temperature, Kp, Ki, Kd, &integral, &previous_error);
            duty_cycle = (int)(pid_output * 100.0);
            set_heater_pwm(duty_cycle);
            log_data(temperature, duty_cycle, pid_output);
        }

        delay(1000); // Log data every second
    }

    cleanup();
    return 0;
}

