#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_LOW 40
#define TEMP_HIGH 70
#define TEMP_MIN 25
#define TEMP_MAX 75

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    gpioPWM(FAN_GPIO, 0); // Turn off the fan
    gpioTerminate();       // Terminate pigpio
    printf("\nExiting gracefully.\n");
    exit(0);
}

// Function to read CPU temperature from /sys/class/thermal/thermal_zone0/temp
float read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;
    float temp_celsius;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        perror("Error reading temperature");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli_celsius / 1000.0;
    return temp_celsius;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature < TEMP_LOW) {
        duty_cycle = 0;
    } else if (temperature > TEMP_HIGH) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((temperature - TEMP_LOW) / (TEMP_HIGH - TEMP_LOW)) * 100);
    }

    return duty_cycle;
}

// Function to set PWM frequency and duty cycle
int set_pwm(int gpio, int frequency, int duty_cycle) {
    if (gpioSetPWMfrequency(gpio, frequency) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", gpio);
        return -1;
    }

    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }

    return 0;
}

// Function to log data to a CSV file
int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("cooling_log.csv", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    gpioSetPWMrange(FAN_GPIO, 255);

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Optionally, exit the program if temperature reading consistently fails
            // break; // Exit the loop if temperature reading fails
        }

        int duty_cycle = calculate_duty_cycle(temperature);
        if (set_pwm(FAN_GPIO, PWM_FREQUENCY, duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM, continuing.\n");
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, continuing.\n");
        }

        printf("Temperature: %.2f°C, Duty Cycle: %d%%\n", temperature, duty_cycle);

        gpioDelay(5000); // Wait 5 seconds
    }

    return 0;
}

