#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDRESS 0x70
#define FLOW_LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int read_flow_sensor(int i2c_handle, int *flow);
int validate_crc(unsigned char data[], unsigned char crc);
void log_flow_data(int flow1, int flow2);
void signal_handler(int signal);

// CRC-8 calculation (as per SLF3S-1300F datasheet)
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow sensor data with retry mechanism
int read_flow_sensor(int i2c_handle, int *flow) {
    unsigned char data[3];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (bytes_read == 3) {
            // CRC validation
            unsigned char crc = validate_crc(data, 2);
            if (crc == data[2]) {
                *flow = (data[0] << 8) | data[1];
                return 0; // Success
            } else {
                fprintf(stderr, "CRC validation failed. Retry %d\n", retries + 1);
            }
        } else {
            fprintf(stderr, "I2C read failed (bytes read: %d). Retry %d\n", bytes_read, retries + 1);
        }
        retries++;
        gpioDelay(10); // Small delay before retrying
    }

    fprintf(stderr, "Failed to read flow sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to validate CRC checksum
int validate_crc(unsigned char data[], unsigned char crc) {
    unsigned char polynomial = 0x31; // CRC-8 polynomial
    unsigned char crc_calculated = crc8(data, 2);

    return (crc_calculated == crc);
}

// Function to log flow data to file
void log_flow_data(int flow1, int flow2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, flow1, flow2);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up...\n", signal);
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int flow1, flow2;
    int init_result;

    // Initialize pigpio
    init_result = gpioInitialise();
    if (init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", init_result);
        return 1;
    }

    // Open I2C bus
    i2c_handle1 = i2cOpen(I2C_BUS, SLF3S_ADDRESS, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %d\n", i2c_handle1);
