int process_sensor_data(int sensor_a_value, int sensor_b_value) {
    int new_position = current_position;

    if (sensor_a_value == 1 && sensor_b_value == 0) {
        new_position = (new_position + 1) % PULSES_PER_REVOLUTION;
    } else if (sensor_a_value == 0 && sensor_b_value == 1) {
        new_position = (new_position + PULSES_PER_REVOLUTION - 1) % PULSES_PER_REVOLUTION;
    }

    return new_position;
}

// Function to calculate the normalized angular position
int calculate_position(int sensor_a_value, int sensor_b_value) {
    int new_position = process_sensor_data(sensor_a_value, sensor_b_value);
