void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1; // Exit if file opening fails
    }

    int sensor_a_value, sensor_b_value;
    int new_position;

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor data
        if (read_sensor_data(&sensor_a_value, &sensor_b_value) != 0) {
            fprintf(stderr, "Error reading sensor data!\n");
            break; // Exit loop if sensor read fails
        }

        // Process sensor data and calculate new position
        new_position = calculate_position(sensor_a_value, sensor_b_value);

        // Update current position
        current_position = new_position;

        // Log the position
        if (log_position(current_position) != 0) {
            fprintf(stderr, "Error logging position!\n");
            break; // Exit loop if logging fails
        }

        // Small delay to avoid excessive CPU usage
        gpioDelay(1000); // 1 millisecond
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

