// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

// Function prototypes
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulse_count);
void log_rpm(double rpm);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)tick; (void)user_data; // Unused parameters
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&mutex);
        pulse_count++;
        pthread_mutex_unlock(&mutex);
    }
}

// Function to calculate RPM
double calculate_rpm(int pulse_count) {
    if (pulse_count == 0) {
        return 0.00;
    }
    return (double)pulse_count * 60.0;
