    struct timespec last_pulse_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &last_pulse_time);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - last_pulse_time.tv_sec) + (current_time.tv_nsec - last_pulse_time.tv_nsec) / 1000000000.0;

        if (elapsed_time >= 1.0) {
            int pulse_count = pulse_count;
            pulse_count = 0; // Reset for the next second
            last_pulse_time = current_time;

            double rpm = calculate_rpm(pulse_count);
            log_rpm(rpm);

            printf("RPM: %.2f\n", rpm);
        }

        gpioDelay(1000); // Check every 1ms
    }

    cleanup();
    return 0;
}

