#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_MIC 17
#define GPIO_GAIN 18
#define LOG_FILE "audio_log.txt"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log audio events to a file
void log_audio_event(int level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s %d\n", timestamp, level);
    fclose(fp);
}

// Callback function for rising edge detection
void rising_edge_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        log_audio_event(1);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(GPIO_MIC, PI_INPUT);

    // Set GPIO18 as output and set gain to 60dB (LOW)
    gpioSetMode(GPIO_GAIN, PI_OUTPUT);
    gpioWrite(GPIO_GAIN, 0);

    // Set up interrupt on GPIO17 for rising edges
    gpioSetAlertFunc(GPIO_MIC, rising_edge_callback);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up and exit
    gpioTerminate();
    printf("Audio monitoring stopped.\n");
    return 0;
}

