#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_RATE_REG 0x00
#define FLOW_RATE_DATA_LENGTH 3
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 1000.0
#define LOG_FILE "flow_log.csv"
#define READ_INTERVAL_MS 1000

// CRC-8 polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t raw_flow_rate;
    uint8_t crc_byte;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_flow_rate(sensor_data_t *data);
float convert_to_ul_per_min(int16_t raw_value);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(sensor_data_t *data) {
    char buf[FLOW_RATE_DATA_LENGTH];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, FLOW_RATE_REG, buf, FLOW_RATE_DATA_LENGTH);

    if (bytes_read != FLOW_RATE_DATA_LENGTH) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }

    // Extract raw flow rate and CRC byte
    data->raw_flow_rate = (int16_t)((buf[0] << 8) | buf[1]);
    data->crc_byte = buf[2];

    // CRC validation
    uint8_t crc_calculated = 0xFF;
    uint8_t crc_check = data->crc_byte;

    for (int i = 0; i < 8; i++) {
        crc_calculated = (crc_calculated ^ CRC_POLYNOMIAL) & 0x01;
        crc_calculated >>= 1;
        if (crc_calculated)
            crc_calculated ^= CRC_INITIAL_VALUE;
        else
            crc_calculated = CRC_INITIAL_VALUE;
        crc_check >>= 1;
        if (crc_check)
            crc_check ^= CRC_POLYNOMIAL;
        else
            crc_check = CRC_INITIAL_VALUE;
    }

    if (crc_calculated != crc_check) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    return 0;
}

// Convert raw flow rate to ul/min
float convert_to_ul_per_min(int16_t raw_value) {
    return (float)raw_value * 0.1; // Example conversion factor
