int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the MICS-VZ-89TE
int read_sensor_data(uint16_t *tvoc, uint16_t *eco2) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *tvoc = (buf[0] << 8) | buf[1];
    *eco2 = (buf[2] << 8) | buf[3];

    return 0;
}

// Function to calculate the IAQ index
float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    // Simple linear IAQ calculation (replace with a more accurate model if needed)
    float iaq = 100.0 - ((float)tvoc / 1000.0); // Example: TVOC inversely proportional to IAQ
    if (iaq < 0) iaq = 0;
    return iaq;
}

// Function to log the data to a CSV file
int log_data(float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CSV_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t tvoc, eco2;
        float iaq;

        // Read sensor data
        if (read_sensor_data(&tvoc, &eco2) == 0) {
            // Calculate IAQ
            iaq = calculate_iaq(tvoc, eco2);

            // Log the data
            log_data(iaq, tvoc, eco2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

