#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define TAMPER_THRESHOLD 5 // seconds

static volatile int running = 1;
static volatile unsigned long last_touch_time = 0;

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioSetMode(GPIO_PIN, PI_INPUT); // Release the line
    gpioTerminate(); // Close the pigpio library
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT); // Set GPIO as input
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Optional: Set pull-down resistor

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tamper detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = gpioRead(GPIO_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PIN, strerror(errno));
            gpioTerminate();
            return 1;
        }

        if (sensor_value == 1) {
            unsigned long current_time = gpioTick();

            if (current_time - last_touch_time > TAMPER_THRESHOLD * 1000000) {
                printf("Intrusion detected!\n");
                last_touch_time = current_time;
            }
        } else {
            last_touch_time = 0; // Reset timer on release
        }

        gpioDelay(100); // Check every 100ms
    }

    gpioTerminate(); // This line might not be reached due to signal handler
    return 0;
}

