    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize ALSA
int init_alsa()
{
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    unsigned int val = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &val, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int init_gpio()
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initially set to left channel
    return 0;
}

// Function to write audio data to file
int write_audio_data(FILE *fp, short *buffer, int num_samples)
{
    size_t bytes_written = fwrite(buffer, sizeof(short), num_samples, fp);
    if (bytes_written != num_samples) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup()
{
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    if (fp) {
        fclose(fp);
    }
    gpioWrite(GPIO_PIN, 0); // Set to left channel before exiting
    gpioTerminate();
}

int main()
{
    signal(SIGINT, int_handler);

    if (init_alsa() != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        return 1;
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        cleanup();
        return 1;
    }

    short *buffer = (short *)malloc(NUM_CHANNELS * SAMPLE_RATE * SAMPLE_SIZE);
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for audio buffer\n");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Audio capture started. Press Ctrl+C to stop.\n");

    while (keep_running) {
        int err = snd_pcm_readi(pcm_handle, buffer, NUM_CHANNELS * SAMPLE_RATE);
        if (err == -EPIPE) {
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            break;
        } else if (err != NUM_CHANNELS * SAMPLE_RATE) {
            fprintf(stderr, "Short read, read %d frames\n", err);
        } else {
            if (write_audio_data(fp, buffer, NUM_CHANNELS * SAMPLE_RATE) != 0) {
                break;
            }
        }
    }

    cleanup();
    free(buffer);
    fprintf(stderr, "Audio capture finished.\n");
    return 0;
}

