#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define FAN_GPIO 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioPWM(FAN_GPIO, 0); // Initially turn the fan off

    return 0;
}

int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

void control_fan(int flame_detected) {
    if (flame_detected) {
        gpioPWM(FAN_GPIO, 255); // Full speed
    } else {
        gpioPWM(FAN_GPIO, 0); // Stop the fan
    }
}

void log_event(const char *event_type) {
    FILE *fp = fopen("flame_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s %s\n", timestamp, event_type);
    fclose(fp);
}

void cleanup_gpio() {
    gpioPWM(FAN_GPIO, 0); // Stop PWM
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT); // Reset GPIO mode
    gpioSetMode(FAN_GPIO, PI_INPUT); // Reset GPIO mode
    gpioTerminate();
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    int last_flame_state = 1; // Assume no flame initially
    time_t start_time = time(NULL);
    int timeout_counter = 0;

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0 && last_flame_state == 1) {
            // Flame detected
            timeout_counter = 0; // Reset timeout counter
        } else if (flame_detected == 1 && last_flame_state == 0) {
            // Flame gone
            timeout_counter = 0; // Reset timeout counter
        } else if (flame_detected == 1 && last_flame_state == 1) {
            // Flame still present
            timeout_counter++;
            if (timeout_counter > 5) {
                fprintf(stderr, "Timeout: No valid reading for 5 seconds. Stopping program.\n");
                program_running = 0; // Stop the program
                break;
            }
        } else {
            // Sensor absent or invalid reading
            timeout_counter = 0; // Reset timeout counter
        }

        last_flame_state = flame_detected;

        if (flame_detected == 0) {
            control_fan(1); // Turn fan on
            log_event("Flame detected");
        } else {
            control_fan(0); // Turn fan off
        }

        gpioDelay(50); // 50ms delay
    }

    cleanup_gpio();
    printf("Program terminated.\n");
    return 0;
}

