#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_FRAME_TRIGGER 23
#define GPIO_DATA_READY 24
#define LOG_FILE "radar_data.bin"
#define MAGIC_NUMBER 0x4144
#define TIMESTAMP_SIZE 8
#define CONFIG_SIZE 256
#define FRAME_SIZE 32768
#define NUM_FRAMES 10
#define PERIOD_MS 100

// AWR1642 Configuration Structure
typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint16_t chirp_count;
    uint16_t samples_per_chirp;
} awr1642_config_t;

// Global Variables
int spi_handle;
FILE *log_file;
awr1642_config_t config;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize();
int configure_spi();
int configure_gpio();
int read_config();
int write_config(const awr1642_config_t *config);
int capture_frame(uint8_t *frame_data);
int log_data(const uint8_t *frame_data);
void signal_handler(int signal);
void frame_complete_callback(int gpio, int level, uint32_t tick);

// Function Implementations
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_FRAME_TRIGGER, PI_OUTPUT);
    gpioSetMode(GPIO_DATA_READY, PI_INPUT);
    gpioSetPullUpDown(GPIO_DATA_READY, PI_PUD_UP);

    if (configure_gpio() != 0) {
        gpioTerminate();
        return -1;
    }

    if (configure_spi() != 0) {
        gpioTerminate();
        return -1;
    }

    if (read_config() != 0) {
        gpioTerminate();
        return -1;
    }

    if (write_config(&config) != 0) {
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return -1;
    }

    // Write header to log file
    uint8_t header[CONFIG_SIZE + TIMESTAMP_SIZE + MAGIC_NUMBER + FRAME_SIZE + 8];
    memcpy(header, &config, CONFIG_SIZE);
    memcpy(header + CONFIG_SIZE, (uint8_t *)&(time_t)time(NULL), TIMESTAMP_SIZE);
    memcpy(header + CONFIG_SIZE + TIMESTAMP_SIZE, (uint8_t *)&MAGIC_NUMBER, MAGIC_NUMBER);
    memcpy(header + CONFIG_SIZE + TIMESTAMP_SIZE + MAGIC_NUMBER, frame_data, FRAME_SIZE);

    fwrite(header, 1, sizeof(header), log_file);

    return 0;
}

int configure_gpio() {
    gpioSetMode(GPIO_FRAME_TRIGGER, PI_OUTPUT);
    gpioSetMode(GPIO_DATA_READY, PI_INPUT);
    gpioSetPullUpDown(GPIO_DATA_READY, PI_PUD_UP);
    gpioSetAlertFunc(GPIO_DATA_READY, frame_complete_callback);
    return 0;
}

int configure_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        return -1;
    }
    return 0;
}

int read_config() {
    FILE *fp = fopen("config.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Parse the line (very basic parsing)
        if (sscanf(line, "%x %x %hu %hu", &config.start_frequency, &config.end_frequency, &config.chirp_count, &config.samples_per_chirp) != 4) {
            fprintf(stderr, "Error parsing config file\n");
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

int write_config(const awr1642_config_t *config) {
    FILE *fp = fopen("config.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file for writing\n");
        return -1;
    }

    fprintf(fp, "%u %u %hu %hu\n", config->start_frequency, config->end_frequency, config->chirp_count, config->samples_per_chirp);
    fclose(fp);
    return 0;
}

int capture_frame(uint8_t *frame_data) {
    // Trigger frame capture
    gpioWrite(GPIO_FRAME_TRIGGER, 1);
    gpioDelay(1); // Small delay
    gpioWrite(GPIO_FRAME_TRIGGER, 0);

    // Wait for data ready signal
    int timeout = 1000; // Timeout after 1 second
    while (gpioRead(GPIO_DATA_READY) == 0 && timeout > 0) {
        gpioDelay(1); // Check every 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    // Read frame data
    int bytes_read = spiRead(spi_handle, frame_data, FRAME_SIZE);
    if (bytes_read != FRAME_SIZE) {
        fprintf(stderr, "SPI read failed, read %d bytes\n", bytes_read);
        return -1;
    }

    return 0;
}

int log_data(const uint8_t *frame_data) {
    uint8_t header[CONFIG_SIZE + TIMESTAMP_SIZE + MAGIC_NUMBER + FRAME_SIZE + 8];
    memcpy(header, &config, CONFIG_SIZE);
    memcpy(header + CONFIG_SIZE, (uint8_t *)&(time_t)time(NULL), TIMESTAMP_SIZE);
    memcpy(header + CONFIG_SIZE + TIMESTAMP_SIZE, (uint8_t *)&MAGIC_NUMBER, MAGIC_NUMBER);
    memcpy(header + CONFIG_SIZE + TIMESTAMP_SIZE + MAGIC_NUMBER, frame_data, FRAME_SIZE);

    fwrite(header, 1, sizeof(header), log_file);
    return 0;
}

void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

void frame_complete_callback(int gpio, int level, uint32_t tick) {
    // This function is called when the data ready interrupt is triggered.
    // You can add any necessary processing here, such as logging the frame number.
    // For this example, we just print a message.
    printf("Data ready interrupt triggered\n");
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t frame_data[FRAME_SIZE];
    for (int i = 0; i < NUM_FRAMES; i++) {
        if (capture_frame(frame_data) == 0) {
            log_data(frame_data);
        } else {
            fprintf(stderr, "Failed to capture frame %d\n", i + 1);
        }
        gpioDelay(PERIOD_MS * 1000); // Delay for the period
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

