#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define CONVERSION_TIME_MS 100
#define DATA_FILE "light_data.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_lux(float *lux);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, float lux);
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    uint16_t gain;
    uint16_t full_scale;
} sensor_config_t;

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure the OPT3001 sensor
int configure_sensor() {
    uint16_t config_value = 0b1100000000000000; // Continuous conversion mode, auto range
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to OPT3001 config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read lux value from the OPT3001 sensor
int read_lux(float *lux) {
    char buf[2];
    char read_buf[2];
    int result;

    // Read result register
    buf[0] = RESULT_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to OPT3001 result register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from OPT3001 result register: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    uint16_t raw_data = (read_buf[0] << 8) | read_buf[1];

    // Convert raw data to lux
    *lux = (float)raw_data * 0.01;

    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log data to a file
int log_data(const char *timestamp, float lux) {
    FILE *fp = fopen(DATA_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, lux);
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float lux;
    char *timestamp;

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_lux(&lux) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Log data
            if (log_data(timestamp, lux) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        // Wait for the next conversion time
        gpioDelay(CONVERSION_TIME_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

