#include <pigpio.h>

#define FLAME_SENSOR_PIN 17
#define LOG_INTERVAL_SEC 1

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_message[50];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Flame detection program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the flame sensor value
        gpio_status = gpioRead(FLAME_SENSOR_PIN);
        if (gpio_status != 0 && gpio_status != 1) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", FLAME_SENSOR_PIN, gpio_status);
        } else {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Format log message
            snprintf(log_message, sizeof(log_message), "%s Flame Detected: %s", timestamp, gpio_status == 0 ? "YES" : "NO");

            // Log the message to the console
            printf("%s\n", log_message);
        }

        // Wait for the specified interval
        gpioDelay(LOG_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup: Release the line request, close the chip, and free all configuration and settings objects
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

