#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensor outputs
#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor state
int read_sensor_state() {
    int left_state = gpioRead(LEFT_PIN);
    int center_state = gpioRead(CENTER_PIN);
    int right_state = gpioRead(RIGHT_PIN);

    if (left_state < 0 || center_state < 0 || right_state < 0) {
        fprintf(stderr, "Error reading GPIO pin. Exiting.\n");
        return -1; // Indicate an error
    }

    return (left_state << 2) | (center_state << 1) | right_state;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_PIN, PI_INPUT);
    gpioSetMode(CENTER_PIN, PI_INPUT);
    gpioSetMode(RIGHT_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to read and print sensor states
    while (program_running) {
        int sensor_state = read_sensor_state();

        if (sensor_state >= 0) {
            printf("Left: %d, Center: %d, Right: %d\n", sensor_state & 1, (sensor_state >> 1) & 1, (sensor_state >> 2) & 1);
        } else {
            fprintf(stderr, "Failed to read sensor state. Retrying...\n");
        }

        usleep(50000); // Wait 50 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

