#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the TTP226 sensor array
const int sensor_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set all sensor pins as inputs with pull-down resistors
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN);
    }

    return 0;
}

// Function to read the state of all sensor channels
int read_sensor_channels(int *channel_states) {
    for (int i = 0; i < num_channels; i++) {
        channel_states[i] = gpioRead(sensor_pins[i]);
    }
    return 0;
}

// Function to format the sensor data into a CSV string with ISO 8601 timestamp
char *format_data(int *channel_states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char *data_string = (char *)malloc(100 * sizeof(char)); // Allocate memory for the string

    if (data_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    sprintf(data_string, "%s,%d,%d,%d,%d,%d,%d,%d\n", timestamp, channel_states[0], channel_states[1], channel_states[2], channel_states[3], channel_states[4], channel_states[5], channel_states[6], channel_states[7]);

    return data_string;
}

// Function to write the data string to the console
void write_to_console(char *data_string) {
    printf("%s", data_string);
}

// Function to release GPIO resources
void cleanup_gpio() {
    // No need to explicitly release pins, gpioTerminate handles it
    gpioTerminate();
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    int channel_states[num_channels];

    // Main loop to read sensor data and write to console
    while (program_running) {
        // Read sensor channels
        if (read_sensor_channels(channel_states) != 0) {
            fprintf(stderr, "Error reading sensor channels\n");
        }

        // Format the data
        char *data_string = format_data(channel_states);
        if (data_string != NULL) {
            // Write the data to the console
            write_to_console(data_string);
            free(data_string); // Free the allocated memory
        } else {
            fprintf(stderr, "Error formatting data\n");
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpioDelay takes microseconds
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

