#define TILT_SENSOR_GPIO 4 // GPIO4 (BCM pin 7)

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int tilt_state;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO4 as input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Print startup banner
    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the tilt sensor state
        result = gpioRead(TILT_SENSOR_GPIO);
        if (result != 0 && result != 1) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", TILT_SENSOR_GPIO, result);
            gpioTerminate();
            return 1;
        }

        tilt_state = (result == 0) ? 0 : 1; // Convert to integer for logging

        // Log the tilt state
        fflush(stdout);
        if (tilt_state == 0) {
            printf("Tilted\n");
        } else {
            printf("Not Tilted\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

