#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define CSV_FILE "uv_als_log.csv"

// Si1145 Registers
#define REG_PARTID 0x00
#define REG_REVID 0x01
#define REG_SEQID 0x02
#define REG_INTCFG 0x03
#define REG_IRQEN 0x04
#define REG_ALSVISDATA0 0x22
#define REG_ALSVISDATA1 0x23
#define REG_UVINDEX0 0x2C
#define REG_UVINDEX1 0x2D
#define REG_COMMAND 0x30
#define REG_HW_KEY 0x07

// Commands
#define CMD_RESET 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145_data(uint16_t *uv_index, uint16_t *als_visible);
void log_data(uint16_t uv_index, uint16_t als_visible);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Initialize Si1145 sensor
int init_si1145() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Enable force mode
    if (i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY\n");
        return -1;
