#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5 // ml/min
#define LOG_FILE "flow_log.txt"

// CRC polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flow_rate(int i2c_handle);
float calculate_average_flow(float flow1, float flow2);
void control_alarm(float average_flow);
void log_data(float flow1, float flow2, float average_flow);
void signal_handler(int signal);

// Function to read flow rate from the sensor
int read_flow_rate(int i2c_handle) {
    char cmd[1] = {0x36}; // Command to start continuous measurement
    char buffer[3];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1; // Indicate error
    }

    gpioDelay(100); // Wait for measurement (100ms)

    result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1; // Indicate error
    }

    // CRC validation
    uint8_t crc = buffer[2];
    uint8_t crc_calculated = 0xFF;
    uint8_t data = buffer[0];

    for (int i = 0; i < 8; i++) {
        crc_calculated ^= data;
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated = (crc_calculated << 1);
            }
        }
    }

    if (crc_calculated != crc) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1; // Indicate CRC failure
    }

    // Convert to flow rate (ml/min)
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    float flow_rate = (float)raw_flow / 120.0; // Scale factor from datasheet

    return (int)flow_rate;
}

// Function to calculate the average flow rate
float calculate_average_flow(float flow1, float flow2) {
    if (flow1 < 0 || flow2 < 0) {
        return 0.0; // Return 0 if one or both readings are invalid
    }
    return (flow1 + flow2) / 2.0;
}

// Function to control the alarm
void control_alarm(float average_flow) {
    if (average_flow < FLOW_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Set GPIO HIGH
    } else {
        gpioWrite(ALARM_GPIO, 0); // Set GPIO LOW
    }
}

// Function to log data to file
void log_data(float flow1, float flow2, float average_flow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, flow1, flow2, average_flow);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioSetMode(ALARM_GPIO, PI_INPUT); // Set GPIO to input mode
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for alarm
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Initially set alarm LOW

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float flow1, flow2, average_flow;

        // Read flow rates from sensors
        flow1 = read_flow_rate(i2c_handle1);
        flow2 = read_flow_rate(i2c_handle2);

        // Validate sensor readings
        if (flow1 >= 0) {
            average_flow = calculate_average_flow(flow1, flow2);
        } else {
            average_flow = 0.0;
        }

        // Control alarm
        control_alarm(average_flow);

        // Log data
        log_data(flow1, flow2, average_flow);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0);
    gpioSetMode(ALARM_GPIO, PI_INPUT);
    gpioTerminate();

    return 0;
}

