void add_to_buffer(time_t timestamp, int sensor_value);
void dump_buffer();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = read_sensor();

        // Get current timestamp
        time_t current_time = time(NULL);

        // Add data to circular buffer
        add_to_buffer(current_time, sensor_value);

        // Check if buffer is full
        if (buffer_index == BUFFER_SIZE) {
            // Dump the buffer
            dump_buffer();
            buffer_index = 0; // Reset index after dumping
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

// Function to initialize the pigpio library and configure GPIO4
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor value from GPIO4
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add sensor data to the circular buffer
void add_to_buffer(time_t timestamp, int sensor_value) {
    sensor_buffer[buffer_index].timestamp = timestamp;
    sensor_buffer[buffer_index].sensor_value = sensor_value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to dump the contents of the circular buffer to stdout
void dump_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        if (sensor_buffer[index].timestamp != 0) {
            struct tm *timeinfo = localtime(&sensor_buffer[index].timestamp);
            char timestamp_str[20];
            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("[%s] Sensor Value: %d\n", timestamp_str, sensor_buffer[index].sensor_value);
        }
    }
}

// Signal handler function to handle SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting program...\n");
}

