#define D7S_REG_X_LSB 0x28
#define D7S_REG_X_MSB 0x29
#define D7S_REG_Y_LSB 0x2A
#define D7S_REG_Y_MSB 0x2B
#define D7S_REG_Z_LSB 0x2C
#define D7S_REG_Z_MSB 0x2D

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x, y, z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_d7s();
int read_d7s_data(sensor_data_t *data);
