    return 0;
}

// Read data from D7S sensor
int read_d7s_data(sensor_data_t *data) {
    char reg_addr = D7S_REG_X_LSB;
    char buffer[6]; // 2 bytes per axis (X, Y, Z)
    int result;

    // Read X axis
    result = i2cWriteI2CBlockData(i2c_handle, reg_addr, buffer, 1); // Write register address
    if (result < 0) {
        fprintf(stderr, "Failed to write register address for X: %s\n", strerror(errno));
        return -1;
    }
    result = i2cReadI2CBlockData(i2c_handle, reg_addr, buffer, 6); // Read 6 bytes (X_LSB, X_MSB, Y_LSB, Y_MSB, Z_LSB, Z_MSB)
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    // Combine LSB and MSB for each axis
    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

