        return -1;
    }

    fprintf(csv_file, "Timestamp,X,Y,Z\n");
    fclose(csv_file);
    return 0;
}

// Write CSV data
int write_csv_data(sensor_data_t data) {
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file for writing data: %s\n", strerror(errno));
        return -1;
    }

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    fprintf(csv_file, "%s,%d,%d,%d\n", buf, data.x, data.y, data.z);
    fclose(csv_file);
    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (csv_file != NULL) {
        fclose(csv_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize D7S sensor
    if (init_d7s() < 0) {
        cleanup();
        return 1;
    }

    // Write CSV header
    if (write_csv_header() < 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    int retry_count = 0;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_d7s_data(&sensor_data) == 0) {
            // Write data to CSV file
            if (write_csv_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to write data to CSV file\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

