#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read sensor values
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR_1_PIN);
    int sensor2_value = gpioRead(SENSOR_2_PIN);

    if (sensor1_value < 0 || sensor2_value < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1; // Indicate error
    }

    return (sensor1_value << 1) | sensor2_value; // Combine sensor values into a single byte
}

// Function to control the LED
void control_led(int led_state) {
    gpioWrite(LED_PIN, led_state);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensors();

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break; // Exit loop on sensor read error
        }

        // Check if either sensor detects an obstacle
        if (sensor_value == 0) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup GPIO resources before exiting
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

