#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION_SEC 2

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
    time_t stall_start_time;
} StallData;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int validate_sensor_reading(int sensor_value);
int detect_stall(int sensor1_value, int sensor2_value);
int log_stall(const char *timestamp);
void signal_handler(int signal);
void cleanup();

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("stall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening stall_log.txt. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    StallData current_stall = {0, 0, 0};

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        // Validate sensor readings
        if (validate_sensor_reading(sensor1_value) && validate_sensor_reading(sensor2_value)) {
            // Detect stall
            if (detect_stall(sensor1_value, sensor2_value)) {
                // Log stall if not already logged
                time_t now = time(NULL);
                if (current_stall.sensor1_value == 0 && current_stall.sensor2_value == 0) {
                    if (difftime(now, current_stall.stall_start_time) >= STALL_DURATION_SEC) {
                        if (log_stall(now) != 0) {
                            fprintf(stderr, "Error logging stall.\n");
                        }
                        current_stall.stall_start_time = now;
                    }
                }
            }
        }

        // Small delay to avoid busy-waiting
        usleep(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    return 0;
}

// Read sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Validate sensor reading (LOW indicates obstacle detected)
int validate_sensor_reading(int sensor_value) {
    return (sensor_value == 0);
}

// Detect stall condition
int detect_stall(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Log stall event to file
int log_stall(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

