// Constants
#define I2C_BUS 1
#define TMAG5170_ADDR 0x0E
#define CONTINUOUS_CONVERSION_MODE 0x00
#define 50MT_RANGE 0x00
#define X_AXIS_LSB 0x01
#define Y_AXIS_LSB 0x03
#define Z_AXIS_LSB 0x05
#define CSV_FILE "magnetic_log.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
int log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to initialize the TMAG5170 sensor
int initialize_sensor() {
    int status;

    // Configure continuous conversion mode
    status = i2cWriteByteData(i2c_handle, CONTINUOUS_CONVERSION_MODE, 0x00); // Example value, check datasheet
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    // Configure 50mT range
    status = i2cWriteByteData(i2c_handle, 0x02, 0x00); // Example value, check datasheet
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    // Read X, Y, and Z axis data
    status = i2cReadI2CBlockData(i2c_handle, X_AXIS_LSB, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    // Combine LSB and MSB for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to log data to CSV file
int log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    int status;

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write data to CSV file
    status = fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    if (status < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }

    // Flush the buffer to ensure data is written to the file
    fflush(csv_file);

    return 0;
}

int main() {
    int16_t x, y, z;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Log data to CSV file
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup resources
    i2cClose(i2c_handle);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

