#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL 2 // seconds

// Global variables
static volatile int running = 1;
static int gpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void log_alert(const char *message);
void log_error(const char *message);
void signal_handler(int signal);
void reinitialize_gpio();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    log_alert("Program terminated by signal.");
    gpioTerminate();
    exit(0);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpio_initialized = 1;

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        log_error("Failed to set GPIO as input.");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read the sensor value
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", GPIO_PIN);
        log_error("Failed to read GPIO.");
        return -1; // Indicate error
    }
    return value;
}

// Log an alert message to stdout and flood_log.txt
void log_alert(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s %s\n", timestamp, message);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }
    fprintf(fp, "%s %s\n", timestamp, message);
    fclose(fp);
}

// Log an error message to stdout and flood_log.txt
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "%s ERROR: %s\n", timestamp, message);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file for error!\n");
        return;
    }
    fprintf(fp, "%s ERROR: %s\n", timestamp, message);
    fclose(fp);
}

// Re-initialize GPIO after an error
void reinitialize_gpio() {
    printf("Attempting to re-initialize GPIO...\n");
    log_alert("Attempting to re-initialize GPIO.");
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO re-initialization failed\n");
        log_error("GPIO re-initialization failed.");
    }
    else {
        printf("GPIO re-initialized successfully.\n");
        log_alert("GPIO re-initialized successfully.");
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");
    log_alert("Water level monitoring started.");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value == 1) {
            log_alert("Water detected!");
        } else if (sensor_value < 0) {
            // Error reading sensor, attempt re-initialization
            reinitialize_gpio();
        }

        sleep(POLL_INTERVAL);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    printf("GPIO terminated.\n");
    return 0;
}

