#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
volatile int pulse_count = 0;
volatile int running = 1;
FILE *log_file = NULL;

// Mutex for thread safety
pthread_mutex_t log_mutex;

// Function prototypes
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void *logging_thread(void *arg);
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup();

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Logging thread function
void *logging_thread(void *arg) {
    (void)arg; // unused
    while (running) {
        pthread_mutex_lock(&log_mutex);
        int rpm = (int)(pulse_count / SAMPLE_INTERVAL_SEC * 60.0);
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

        if (rpm == 0) {
            fprintf(log_file, "%s 0\n", buf);
            fflush(log_file);
            printf("%s 0\n", buf);
        } else {
            fprintf(log_file, "%s %d\n", buf, rpm);
            fflush(log_file);
            printf("%s %d\n", buf, rpm);
        }
        pulse_count = 0; // Reset pulse count after logging
        sleep(SAMPLE_INTERVAL_SEC);
    }
    pthread_exit(NULL);
}

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // unused
    printf("Caught signal, exiting gracefully...\n");
    running = 0;
}

// Initialization function
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Initialization function
int initialize_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&log_mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        cleanup();
        return 1;
    }

    // Create logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        perror("Failed to create logging thread");
        cleanup();
        return 1;
    }

    // Main loop (keep the program running until a signal is received)
    while (running) {
        sleep(1);
    }

    // Wait for the logging thread to finish
    pthread_join(logging_thread_id, NULL);

    // Cleanup and exit
    cleanup();

    return 0;
}

