static volatile quadrature_state_t current_state = QSTATE_IDLE;
static volatile int last_tick_a = 0;
static volatile int last_tick_b = 0;
static volatile int last_state = QSTATE_IDLE;
static volatile int rotation_count = 0;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t rotation_cond = PTHREAD_COND_INITIALIZER;
static FILE *log_file = NULL;

// Function prototypes
void interrupt_handler_a(int gpio, int level, uint32_t tick, void *user_data);
void interrupt_handler_b(int gpio, int level, uint32_t tick, void *user_data);
quadrature_state_t determine_rotation_direction(int tick_a, int tick_b);
void log_rotation_direction(quadrature_state_t new_state);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Interrupt handler for Sensor A
void interrupt_handler_a(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)user_data; // unused
    int current_tick = tick;
    int diff = current_tick - last_tick_a;

    pthread_mutex_lock(&state_mutex);
    if (diff > 0) {
        if (current_state == QSTATE_IDLE) {
            current_state = QSTATE_CLOCKWISE;
            last_state = QSTATE_CLOCKWISE;
        } else if (current_state == QSTATE_CLOCKWISE) {
            current_state = QSTATE_COUNTER_CLOCKWISE;
            last_state = QSTATE_COUNTER_CLOCKWISE;
        }
    } else if (diff < 0) {
        if (current_state == QSTATE_COUNTER_CLOCKWISE) {
            current_state = QSTATE_CLOCKWISE;
            last_state = QSTATE_CLOCKWISE;
        } else if (current_state == QSTATE_CLOCKWISE) {
            current_state = QSTATE_IDLE;
            last_state = QSTATE_IDLE;
        }
    }
    last_tick_a = current_tick;
    pthread_mutex_unlock(&state_mutex);
}

// Interrupt handler for Sensor B
void interrupt_handler_b(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)user_data; // unused
    int current_tick = tick;
    int diff = current_tick - last_tick_b;

    pthread_mutex_lock(&state_mutex);
    if (diff > 0) {
        if (current_state == QSTATE_IDLE) {
