            last_state = QSTATE_CLOCKWISE;
        } else if (current_state == QSTATE_CLOCKWISE) {
            current_state = QSTATE_COUNTER_CLOCKWISE;
            last_state = QSTATE_COUNTER_CLOCKWISE;
        }
    } else if (diff < 0) {
        if (current_state == QSTATE_COUNTER_CLOCKWISE) {
            current_state = QSTATE_CLOCKWISE;
            last_state = QSTATE_CLOCKWISE;
        } else if (current_state == QSTATE_CLOCKWISE) {
            current_state = QSTATE_IDLE;
            last_state = QSTATE_IDLE;
        }
    }
    last_tick_b = current_tick;
    pthread_mutex_unlock(&state_mutex);
}

// Function to determine the rotation direction based on the sensor inputs
quadrature_state_t determine_rotation_direction(int tick_a, int tick_b) {
    (void)tick_a; // unused
    (void)tick_b; // unused
    if (current_state == QSTATE_CLOCKWISE) {
        return QSTATE_COUNTER_CLOCKWISE;
    } else if (current_state == QSTATE_COUNTER_CLOCKWISE) {
        return QSTATE_CLOCKWISE;
    } else {
        return QSTATE_IDLE;
    }
}

