    (void)new_state; // unused

    pthread_mutex_lock(&state_mutex);
    int rotation_count_lock = rotation_count;
    pthread_mutex_unlock(&state_mutex);

    if (log_file != NULL) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s.%03d: Rotation %d\n", timestamp, rotation_count_lock, rotation_count);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
