    (void)signal; // unused

    printf("Caught signal, exiting gracefully...\n");

    pthread_mutex_lock(&state_mutex);
    pthread_cond_signal(&rotation_cond);
    pthread_mutex_unlock(&state_mutex);

    if (log_file != NULL) {
        fclose(log_file);
    }

    cleanup_gpio();

    exit(0);
}

