        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR_B_GPIO, RISING_EDGE, 0, interrupt_handler_b, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Sensor B\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to cleanup the pigpio library and GPIO pins
void cleanup_gpio() {
    gpioTerminate();
}

