        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        pthread_cond_wait(&rotation_cond, &state_mutex);

        pthread_mutex_lock(&state_mutex);
        int current_state_lock = current_state;
        pthread_mutex_unlock(&state_mutex);

        if (current_state_lock == QSTATE_CLOCKWISE) {
            log_rotation_direction(QSTATE_COUNTER_CLOCKWISE);
        } else if (current_state_lock == QSTATE_COUNTER_CLOCKWISE) {
            log_rotation_direction(QSTATE_CLOCKWISE);
        } else {
            log_rotation_direction(QSTATE_IDLE);
        }
        rotation_count++;
        pthread_cond_signal(&rotation_cond);
    }

