#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_led(int state);
void log_message(int priority, const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        control_led(0); // Turn off LED
        gpioTerminate(); // Release GPIO resources
        log_message(LOG_INFO, "GPIO terminated.");
        closelog(); // Close syslog
        program_running = 0; // Set flag to exit main loop
    }
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set TOUCH_SENSOR_PIN to input");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set LED_PIN to output");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the LED
int control_led(int state) {
    return gpioWrite(LED_PIN, state);
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Open syslog
    openlog("touch_sensor_app", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "GPIO initialized successfully.");

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            log_message(LOG_INFO, "Touch detected!");
            control_led(1); // Turn on LED
            gpioDelay(DEBOUNCE_DELAY); // Debounce delay
            touch_detected = read_touch_sensor(); // Re-read after debounce
            if (touch_detected == 1) {
                gpioDelay(500); // Keep LED on for 500ms
                control_led(0); // Turn off LED
            }
        } else {
            control_led(0); // Ensure LED is off if no touch
        }

        gpioDelay(50); // Check every 50ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    log_message(LOG_INFO, "GPIO terminated.");
    closelog();

    return 0;
}

