#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 100

// Structure for touch event
typedef struct {
    int sensor_pin;
    struct timespec timestamp;
    int state;
} touch_event_t;

// Circular buffer
touch_event_t touch_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;

// Function prototypes
int read_sensor(int pin);
void control_led(int pin, int state);
void add_to_buffer(int sensor_pin, struct timespec timestamp, int state);
void print_buffer();
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to control LED
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to add event to circular buffer
void add_to_buffer(int sensor_pin, struct timespec timestamp, int state) {
    touch_buffer[buffer_index].sensor_pin = sensor_pin;
    touch_buffer[buffer_index].timestamp = timestamp;
    touch_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_index == 0) {
        overflow_count++;
    }
}

// Function to print the contents of the buffer
void print_buffer() {
    printf("\n--- Touch Event Log ---\n");
    printf("Overflow Count: %d\n", overflow_count);
    for (int i = 0; i < overflow_count; i++) {
        int index = (buffer_index - overflow_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        printf("[%s.%09ld] Sensor: %d, State: %d\n", timestamp_str, ts.tv_nsec, touch_buffer[index].sensor_pin, touch_buffer[index].state);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        if (sensor1_value == 1) {
            add_to_buffer(SENSOR_1_PIN, ts, 1);
            control_led(LED_1_PIN, 1);
        } else {
            add_to_buffer(SENSOR_1_PIN, ts, 0);
            control_led(LED_1_PIN, 0);
        }

        if (sensor2_value == 1) {
            add_to_buffer(SENSOR_2_PIN, ts, 1);
            control_led(LED_2_PIN, 1);
        } else {
            add_to_buffer(SENSOR_2_PIN, ts, 0);
            control_led(LED_2_PIN, 0);
        }

        gpioDelay(50); // Debounce delay
    }

    return 0;
}

