// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log rain events to a file
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s: %s\n", get_timestamp(), message);
    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input with pull-up resistor
    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Raindrop sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int rain_detected = gpioRead(RAIN_SENSOR_GPIO);

        if (rain_detected == 0) {
            // Rain detected
            char *timestamp = get_timestamp();
            if (log_event("Rain Detected") != 0) {
                fprintf(stderr, "Error logging rain event.\n");
            }
        } else {
            // No rain
            char *timestamp = get_timestamp();
            if (log_event("No Rain") != 0) {
                fprintf(stderr, "Error logging no rain event.\n");
            }
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup and exit
    gpioTerminate();
    printf("Raindrop sensor monitoring stopped.\n");
    return 0;
}

