#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_MS 5
#define LOG_FILE "shaft_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0;
}

// Function to read sensor states with debouncing
SensorStates read_sensors() {
    SensorStates states;
    int sensor1_value = gpioRead(SENSOR1_GPIO);
    int sensor2_value = gpioRead(SENSOR2_GPIO);

    // Debounce sensor 1
    gpioDelay(DEBOUNCE_MS * 1000); // Convert ms to microseconds
    if (gpioRead(SENSOR1_GPIO) == sensor1_value) {
        states.sensor1_state = sensor1_value;
    }

    // Debounce sensor 2
    gpioDelay(DEBOUNCE_MS * 1000);
    if (gpioRead(SENSOR2_GPIO) == sensor2_value) {
        states.sensor2_state = sensor2_value;
    }

    return states;
}

// Function to log sensor data to a file
int log_data(SensorStates states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to calculate RPM
double calculate_rpm(SensorStates states) {
    int state_diff = states.sensor2_state - states.sensor1_state;
    if (state_diff == 0) return 0.0; // Avoid division by zero

    double time_diff = (double)(gpioTick() - last_tick) / 1000000.0; // Time in seconds
    if (time_diff == 0.0) return 0.0; // Avoid division by zero

    return 60.0 / (time_diff * state_diff); // RPM calculation
}

// Function to log RPM to the console
void log_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

// Function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize last tick
    last_tick = gpioTick();

    // Main loop
    while (running) {
        SensorStates current_states = read_sensors();
        log_data(current_states);
        double rpm = calculate_rpm(current_states);
        log_rpm(rpm);
        last_tick = gpioTick();
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

