#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define LOG_FILE "biometric_log.txt"
#define SLEEP_DURATION 1 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *heart_rate, uint16_t *spo2);
int log_data(uint16_t heart_rate, uint16_t spo2);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    uint16_t heart_rate;
    uint16_t spo2;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read heart rate and SpO2 data from the sensor
int read_sensor_data(uint16_t *heart_rate, uint16_t *spo2) {
    char cmd[1] = {0x24}; // Command to trigger a measurement
    char buf[4]; // Buffer to store the received data

    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for the measurement to complete (adjust delay as needed)
    gpioDelay(10); // 10 ms delay

    if (i2cReadDevice(i2c_handle, buf, 4) != 4) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *heart_rate = (buf[0] << 8) | buf[1];
    *spo2 = (buf[2] << 8) | buf[3];

    return 0;
}

// Log the data to a file
int log_data(uint16_t heart_rate, uint16_t spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %u BPM, SpO2: %u%%\n", timestamp, heart_rate, spo2);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint16_t heart_rate, spo2;
    while (!terminate) {
        if (read_sensor_data(&heart_rate, &spo2) == 0) {
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(SLEEP_DURATION);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

