#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define alarm duration (seconds)
#define ALARM_DURATION 2

// Define log file name
#define LOG_FILE "bridge_integrity.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_event(const char *event_type);
void activate_alarm();
void deactivate_alarm();
void deactivate_alarm_and_cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    return 0; // Indicate success
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to log events to file
int log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", buf, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return 1; // Indicate failure
    }
}

// Function to activate the alarm
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1);
}

// Function to deactivate the alarm
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0);
}

// Function to deactivate the alarm and cleanup resources
void deactivate_alarm_and_cleanup() {
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    deactivate_alarm_and_cleanup();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == PI_BAD_GPIO || sensor2_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading sensor values!\n");
            // Attempt to recover by re-initializing GPIO
            gpioTerminate();
            if (initialize_gpio() != 0) {
                fprintf(stderr, "Failed to re-initialize GPIO. Exiting.\n");
                running = 0; // Exit the loop if re-initialization fails
                continue; // Skip the rest of the loop iteration
            }
            continue; // Skip the rest of the loop iteration
        }

        // Check if either sensor is tilted
        if (sensor1_value == 1 || sensor2_value == 1) {
            // Check if the alarm is already active
            if (gpioRead(ALARM_PIN) == 0) {
                // Activate the alarm
                activate_alarm();
                log_event("threshold_exceeded");
            }
        } else {
            // Check if both sensors are not tilted
            if (sensor1_value == 0 && sensor2_value == 0) {
                // Deactivate the alarm
                deactivate_alarm();
                log_event("tilt_end");
            }
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up and exit
    deactivate_alarm_and_cleanup();

    return 0;
}

