            fprintf(stderr, "Error: Failed to read CTRL1_REG (attempt %d)\n", i + 1);
            gpioDelay(10); // Small delay before retry
        }
    }
    fprintf(stderr, "Error: Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        status = i2cReadI2CBlockData(i2c_handle, X_LSB_REG, buffer, 6);
        if (status == 6) {
            // Combine LSB and MSB for each axis
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to read sensor data (attempt %d)\n", i + 1);
            gpioDelay(10); // Small delay before retry
        }
    }
    fprintf(stderr, "Error: Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to calculate Euclidean vibration magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to log an event to the log file
int log_event(float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to turn on the alert LED
void alert_led() {
    gpioWrite(ALERT_LED_PIN, 1); // Turn LED on
    gpioDelay(1000);             // Wait for 1 second
    gpioWrite(ALERT_LED_PIN, 0); // Turn LED off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, 0x30, 0); // 0x30 is the default address
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set alert LED pin as output
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.x, &sensor_data.y, &sensor_data.z) == 0) {
            // Calculate vibration magnitude
            float magnitude = calculate_magnitude(sensor_data.x, sensor_data.y, sensor_data.z);

            // Check if magnitude exceeds threshold
            if (magnitude > VIBRATION_THRESHOLD) {
                // Log the event
                log_event(magnitude);

                // Turn on alert LED
                alert_led();
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

