// Define GPIO pins for sensors and LED
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN 18

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set sensor pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read sensor data
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR1_PIN);
    int sensor2_value = gpioRead(SENSOR2_PIN);
    int sensor3_value = gpioRead(SENSOR3_PIN);
    int sensor4_value = gpioRead(SENSOR4_PIN);

    // Active-low sensors: 0 indicates obstacle detected
    return (sensor1_value || sensor2_value || sensor3_value || sensor4_value);
}

// Function to control the LED
void control_led(int obstacle_detected) {
    gpioWrite(LED_PIN, obstacle_detected);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int obstacle_detected = read_sensors();
        control_led(obstacle_detected);
        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Cleanup GPIO resources before exiting
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

