#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <pigpio.h>

#define NUM_SENSORS 5
#define LOG_FILE "/var/log/flame_events.log"
#define DEBOUNCE_DELAY_MS 50

// Sensor configuration
typedef struct {
    int id;
    int gpio_pin;
    int *line;
    int line_index;
} sensor_config_t;

// Global variables
volatile sig_atomic_t program_running = 1;
sensor_config_t sensors[NUM_SENSORS];
int log_fd = -1; // File descriptor for the log file

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
int open_gpio_chip();
int request_gpio_line(int gpio_pin);
int read_sensor(int gpio_pin);
void log_event(int sensor_id, int gpio_pin, const char *message);
void log_sensor_data(int sensor_id, int gpio_pin, int value);
void log_error(int sensor_id, int gpio_pin, const char *message);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, shutting down...");
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins as inputs
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpioSetMode(sensors[i].gpio_pin, PI_INPUT);
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio() {
    gpioTerminate();
}

// Open GPIO chip
int open_gpio_chip() {
    int fd = open("/dev/gpioc", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }
    return fd;
}

// Request GPIO line
int request_gpio_line(int gpio_pin) {
    char buffer[3];
    snprintf(buffer, sizeof(buffer), "%d", gpio_pin);
    if (flock(fileno(stdout), LOCK_EX) < 0) {
        syslog(LOG_ERR, "Failed to acquire lock on stdout: %s", strerror(errno));
        return -1;
    }
    if (dprintf(fileno(stdout), "%s", buffer) < 0) {
        syslog(LOG_ERR, "Failed to write to stdout: %s", strerror(errno));
        flock(fileno(stdout), LOCK_UN);
        return -1;
    }
    flock(fileno(stdout), LOCK_UN);
    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read GPIO %d: %s", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

// Log event to file
void log_event(int sensor_id, int gpio_pin, const char *message) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        syslog(LOG_ERR, "Failed to get timestamp");
        return;
    }

    if (log_fd == -1) {
        syslog(LOG_ERR, "Log file not opened");
        free(timestamp);
        return;
    }

    if (flock(log_fd, LOCK_EX) < 0) {
        syslog(LOG_ERR, "Failed to acquire lock on log file: %s", strerror(errno));
        free(timestamp);
        return;
    }

    if (fprintf(log_fd, "%s - Sensor %d: %s (GPIO %d)\n", timestamp, sensor_id, message, gpio_pin) < 0) {
        syslog(LOG_ERR, "Failed to write to log file: %s", strerror(errno));
    }

    fflush(log_fd);
    flock(log_fd, LOCK_UN);
    free(timestamp);
}

// Log sensor data to file
void log_sensor_data(int sensor_id, int gpio_pin, int value) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        syslog(LOG_ERR, "Failed to get timestamp");
        return;
    }

    if (log_fd == -1) {
        syslog(LOG_ERR, "Log file not opened");
        free(timestamp);
        return;
    }

    if (flock(log_fd, LOCK_EX) < 0) {
        syslog(LOG_ERR, "Failed to acquire lock on log file: %s", strerror(errno));
        free(timestamp);
        return;
    }

    if (fprintf(log_fd, "%s - Sensor %d: GPIO %d - Value: %d\n", timestamp, sensor_id, gpio_pin, value) < 0) {
        syslog(LOG_ERR, "Failed to write to log file: %s", strerror(errno));
    }

    fflush(log_fd);
    flock(log_fd, LOCK_UN);
    free(timestamp);
}

// Log error to file
void log_error(int sensor_id, int gpio_pin, const char *message) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        syslog(LOG_ERR, "Failed to get timestamp");
        return;
    }

    if (log_fd == -1) {
        syslog(LOG_ERR, "Log file not opened");
        free(timestamp);
        return;
    }

    if (flock(log_fd, LOCK_EX) < 0) {
        syslog(LOG_ERR, "Failed to acquire lock on log file: %s", strerror(errno));
        free(timestamp);
        return;
    }

    if (fprintf(log_fd, "%s - ERROR: Sensor %d (GPIO %d): %s\n", timestamp, sensor_id, gpio_pin, message) < 0) {
        syslog(LOG_ERR, "Failed to write to log file: %s", strerror(errno));
    }

    fflush(log_fd);
    flock(log_fd, LOCK_UN);
    free(timestamp);
}

// Get ISO 8601 UTC timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (buffer == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    if (strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        syslog(LOG_ERR, "Failed to format timestamp");
        free(buffer);
        return NULL;
    }

    return buffer;
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        cleanup_gpio();
        closelog();
        return 1;
    }

    // Sensor configurations
    sensors[0].id = 1;
    sensors[0].gpio_pin = 2;
    sensors[0].line = NULL;
    sensors[0].line_index = 0;

    sensors[1].id = 2;
    sensors[1].gpio_pin = 3;
    sensors[1].line = NULL;
    sensors[1].line_index = 0;

    sensors[2].id = 3;
    sensors[2].gpio_pin = 4;
    sensors[2].line = NULL;
    sensors[2].line_index = 0;

    sensors[3].id = 4;
    sensors[3].gpio_pin = 17;
    sensors[3].line = NULL;
    sensors[3].line_index = 0;

    sensors[4].id = 5;
    sensors[4].gpio_pin = 27;
    sensors[4].line = NULL;
    sensors[4].line_index = 0;

    // Main loop
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = read_sensor(sensors[i].gpio_pin);
            if (value >= 0) {
                log_sensor_data(sensors[i].id, sensors[i].gpio_pin, value);
            } else {
                log_error(sensors[i].id, sensors[i].gpio_pin, "Failed to read sensor value");
            }
        }
        sleep(1); // Check every second
    }

    // Cleanup
    cleanup_gpio();
    if (log_fd != -1) {
        close(log_fd);
    }
    closelog();

    return 0;
}

