#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define ALS_DATA_REG 0x04
#define ALS_CONF_REG 0x00
#define GROW_LIGHT_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define LUX_THRESHOLD_100 100
#define LUX_THRESHOLD_500 500
#define LUX_THRESHOLD_1000 1000
#define LUX_THRESHOLD_2000 2000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_veml7700();
int read_lux();
int map_lux_to_brightness(int lux);
void set_led_brightness(int brightness);
void log_data(int lux, int brightness);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure VEML7700
int configure_veml7700() {
    // Configuration register: Gain = 1/4, Integration Time = 100ms, ALS Enable
    unsigned short config_value = 0x0000; // Default configuration
    config_value |= (0x02 << 11); // ALS_EN = 1
    config_value |= (0x00 << 6);  // Gain = 1/4
    config_value |= (0x00 << 1);  // Integration Time = 100ms

    char buf[3];
    buf[0] = ALS_CONF_REG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read lux value from VEML7700
int read_lux() {
    char buf[1];
    buf[0] = ALS_DATA_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 data register: %d\n", result);
        return -1;
    }

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from VEML7700 data register: %d\n", result);
        return -1;
    }

    unsigned int raw_data = (data[0] << 8) | data[1];
    // Conversion formula from datasheet
    float lux = (float)raw_data * 0.0576; // Example conversion, adjust as needed

    return (int)lux;
}

// Function to map lux value to PWM duty cycle
int map_lux_to_brightness(int lux) {
    if (lux < LUX_THRESHOLD_100) {
        return 100;
    } else if (lux < LUX_THRESHOLD_500) {
        return 75;
    } else if (lux < LUX_THRESHOLD_1000) {
        return 50;
    } else {
        return 25;
    }
}

// Function to set LED brightness using hardware PWM
void set_led_brightness(int brightness) {
    gpioPWM(GROW_LIGHT_GPIO, brightness);
}

// Function to log data to file
void log_data(int lux, int brightness) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %d, %d\n", timestamp, lux, brightness);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    set_led_brightness(0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure VEML7700
    if (configure_veml7700() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO mode for grow light LED
    gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(GROW_LIGHT_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(GROW_LIGHT_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        int lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Map lux to brightness
        int brightness = map_lux_to_brightness(lux);

        // Set LED brightness
        set_led_brightness(brightness);

        // Log data
        log_data(lux, brightness);

        // Wait 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

