#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for touch sensors and LED
#define TOUCH_SENSOR_1 2
#define TOUCH_SENSOR_2 3
#define TOUCH_SENSOR_3 4
#define TOUCH_SENSOR_4 5
#define TOUCH_SENSOR_5 6
#define TOUCH_SENSOR_6 7
#define TOUCH_SENSOR_7 8
#define TOUCH_SENSOR_8 9

#define LED_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensors();
void log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set touch sensor pins as inputs with pull-down resistors
    gpioSetMode(TOUCH_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_3, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_3, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_4, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_4, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_5, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_5, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_6, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_6, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_7, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_7, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_8, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_8, PI_PUD_DOWN);

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read touch sensor values
int read_touch_sensors() {
    int sensor1 = gpioRead(TOUCH_SENSOR_1);
    int sensor2 = gpioRead(TOUCH_SENSOR_2);
    int sensor3 = gpioRead(TOUCH_SENSOR_3);
    int sensor4 = gpioRead(TOUCH_SENSOR_4);
    int sensor5 = gpioRead(TOUCH_SENSOR_5);
    int sensor6 = gpioRead(TOUCH_SENSOR_6);
    int sensor7 = gpioRead(TOUCH_SENSOR_7);
    int sensor8 = gpioRead(TOUCH_SENSOR_8);

    return (sensor1 << 0) | (sensor2 << 1) | (sensor3 << 2) | (sensor4 << 3) | (sensor5 << 4) | (sensor6 << 5) | (sensor7 << 6) | (sensor8 << 7);
}

// Function to log touch events to a file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    int last_touch_state = 0; // Store the last known state of the touch sensors

    // Main loop
    while (running) {
        int current_touch_state = read_touch_sensors();

        // Check for changes in the touch sensors
        if (current_touch_state != last_touch_state) {
            last_touch_state = current_touch_state;

            // Log touch events
            if (current_touch_state & 1) {
                log_touch_event(1);
            }
            if (current_touch_state & 2) {
                log_touch_event(2);
            }
            if (current_touch_state & 4) {
                log_touch_event(3);
            }
            if (current_touch_state & 8) {
                log_touch_event(4);
            }
            if (current_touch_state & 16) {
                log_touch_event(5);
            }
            if (current_touch_state & 32) {
                log_touch_event(6);
            }
            if (current_touch_state & 64) {
                log_touch_event(7);
            }
            if (current_touch_state & 128) {
                log_touch_event(8);
            }

            // Control the LED
            if ((current_touch_state & 1) || (current_touch_state & 2) || (current_touch_state & 4) || (current_touch_state & 8) || (current_touch_state & 16) || (current_touch_state & 32) || (current_touch_state & 64) || (current_touch_state & 128)) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }
        }

        gpioDelay(DEBOUNCE_DELAY); // Debounce delay
    }

    return 0;
}

