#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_VALUE 0x1080 // Continuous mode, 800ms conversion time
#define LUX_SCALE_FACTOR 0.01
#define LUX_OFFSET 0.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int write_config();
int read_result(uint16_t *raw_result);
float convert_to_lux(uint16_t raw_result);
char* format_data(float lux_value);
int log_data(char *data);
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int opt3001_address;
    int config_value;
} sensor_config_t;

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Write configuration to the OPT3001
int write_config() {
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (CONFIG_VALUE >> 8) & 0xFF;
    buf[2] = CONFIG_VALUE & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write config: %d\n", result);
        return -1;
    }

    return 0;
}

// Read result from the OPT3001
int read_result(uint16_t *raw_result) {
    char buf[1];
    buf[0] = RESULT_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write result register address: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read result: %d\n", result);
        return -1;
    }

    *raw_result = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Convert raw result to lux
float convert_to_lux(uint16_t raw_result) {
    return (float)raw_result * LUX_SCALE_FACTOR + LUX_OFFSET;
}

// Format data into a string
char* format_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    static char buffer[64]; // Static buffer to avoid memory allocation issues
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", t);
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), ", %.2f lux", lux_value);
    return buffer;
}

// Log data to file
int log_data(char *data) {
    if (fputs(data, log_file) == EOF) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Write configuration
        if (write_config() != 0) {
            fprintf(stderr, "Skipping iteration due to config write failure\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for conversion (at least 800ms)
        gpioDelay(800000); // 800ms

        // Read result
        uint16_t raw_result;
        if (read_result(&raw_result) != 0) {
            fprintf(stderr, "Skipping iteration due to read failure\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert to lux
        float lux_value = convert_to_lux(raw_result);

        // Format data
        char *data = format_data(lux_value);

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Skipping iteration due to log failure\n");
        }

        printf("%s\n", data);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

