    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected == 0) {
            printf("Flame detected!\n");
            log_event("Flame detected!");
            set_alert_output(1); // Set alert HIGH
            gpioDelay(1000);      // Wait for 1 second
            set_alert_output(0); // Set alert LOW
            log_event("Alert deactivated.");
        } else if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor. Continuing...\n");
        }

        gpioDelay(POLLING_INTERVAL_MS); // Wait before next poll
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

