#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to read the GPIO pin state
int read_gpio() {
    return gpioRead(GPIO_PIN);
}

// Function to log the touch event
int log_touch_event(const char *event_type) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, event_type);
    fflush(fp);

    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = read_gpio();

        if (current_state == 1 && previous_state == 0) {
            // Touch detected
            if (log_touch_event("Touch Detected") != 0) {
                fprintf(stderr, "Error logging touch detected event\n");
            }
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
        } else if (current_state == 0 && previous_state == 1) {
            // Touch released
            if (log_touch_event("Touch Released") != 0) {
                fprintf(stderr, "Error logging touch released event\n");
            }
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
        }

        previous_state = current_state;
        gpioDelay(10000); // Check every 10ms
    }

    // Cleanup
    gpioTerminate();
    printf("GPIO terminated. Exiting.\n");
    return 0;
}

