#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDRESS 0x36
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define LOG_FILE "cooling_log.csv"
#define REINIT_DELAY 5 // seconds

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_init(int bus, int address);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int slf3s_start_measurement(int fd);
int slf3s_read_flow_rate(int fd, float *flow_rate);
int crc8(const uint8_t *data, int len);
void log_data(FILE *fp, float flow_rate, uint16_t raw_flow, const char *status);
void signal_handler(int signal);
int i2c_reinit(int bus, int address);

// I2C initialization function
int i2c_init(int bus, int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading data");
        return -1;
    }

    return 0;
}

// I2C write bytes function
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing data");
        return -1;
    }

    return 0;
}

// Start measurement command
int slf3s_start_measurement(int fd) {
    uint8_t start_cmd[] = {0x36, 0x08}; // Start continuous measurement
    if (i2c_write_bytes(fd, 0x00, start_cmd, sizeof(start_cmd)) != 0) {
        fprintf(stderr, "Error starting measurement\n");
        return -1;
    }
    return 0;
}

// Read flow rate function
int slf3s_read_flow_rate(int fd, float *flow_rate) {
    uint8_t flow_data[3];
    if (i2c_read_bytes(fd, 0x00, flow_data, sizeof(flow_data)) != 0) {
        fprintf(stderr, "Error reading flow data\n");
        return -1;
    }

    uint16_t raw_flow = (flow_data[0] << 8) | flow_data[1];
    *flow_rate = (float)raw_flow / 120.0; // Scale factor from datasheet

    return 0;
}

// CRC8 calculation function
int crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log data function
void log_data(FILE *fp, float flow_rate, uint16_t raw_flow, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%u,%s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, flow_rate, raw_flow, status);
    fflush(fp);
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// I2C re-initialization function
int i2c_reinit(int bus, int address) {
    int fd = i2c_init(bus, address);
    if (fd < 0) {
        fprintf(stderr, "I2C re-initialization failed\n");
        return -1;
    }
    return fd;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_reinit(I2C_BUS, SLF3S_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Main loop
    float flow_rate;
    uint16_t raw_flow;
    char status[20];
    while (program_running) {
        // Start measurement
        if (slf3s_start_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Failed to start measurement. Re-initializing I2C.\n");
            close(i2c_fd);
            sleep(REINIT_DELAY);
            i2c_fd = i2c_reinit(I2C_BUS, SLF3S_ADDRESS);
            if (i2c_fd < 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
            }
            continue; // Skip to the next iteration after re-initialization
        }

        // Read flow rate
        if (slf3s_read_flow_rate(i2c_fd, &flow_rate) == 0) {
            // Validate flow rate
            if (flow_rate >= FLOW_MIN && flow_rate <= FLOW_MAX) {
                // CRC validation
                uint8_t crc_calculated = crc8((uint8_t *)(&raw_flow), 1);
                uint8_t crc_received = flow_data[2];

                if (crc_calculated == crc_received) {
                    // Log data
                    log_data(log_file, flow_rate, raw_flow, "OK");
                    strcpy(status, "OK");
                } else {
                    fprintf(stderr, "CRC check failed!\n");
                    log_data(log_file, flow_rate, raw_flow, "ERROR");
                    strcpy(status, "ERROR");
                }
            } else {
                fprintf(stderr, "Flow rate out of range: %.2f ml/min\n", flow_rate);
                log_data(log_file, flow_rate, raw_flow, "INVALID");
                strcpy(status, "INVALID");
            }
        } else {
            fprintf(stderr, "Failed to read flow rate. Re-initializing I2C.\n");
            close(i2c_fd);
            sleep(REINIT_DELAY);
            i2c_fd = i2c_reinit(I2C_BUS, SLF3S_ADDRESS);
            if (i2c_fd < 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
            }
            continue; // Skip to the next iteration after re-initialization
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

