static volatile bool running = true;

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} SensorData;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read sensor data
SensorData read_sensors() {
    SensorData data;
    data.left = gpioRead(LEFT_SENSOR_PIN);
    data.middle = gpioRead(MIDDLE_SENSOR_PIN);
    data.right = gpioRead(RIGHT_SENSOR_PIN);
    return data;
}

// Function to write data to the CSV file
bool write_to_csv(const char* timestamp, SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return false;
    }

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.left, data.middle, data.right);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return false;
    }

    fclose(fp);
    return true;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = false;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

