    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting sensor logging...\n");

    while (running) {
        // Read sensor data
        SensorData data = read_sensors();

        // Get timestamp
        char* timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping logging.\n");
            gpioDelay(50000); // Wait 50ms
            continue;
        }

        // Write data to CSV file
        if (!write_to_csv(timestamp, data)) {
            fprintf(stderr, "Failed to write data to CSV file.\n");
        }

        free(timestamp);

        // Wait 50ms
        gpioDelay(50000);
    }

    // Clean up GPIO
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

