#include <sys/types.h>
#include <pigpio.h>

#define TOUCH_PIN 23
#define LED_PIN 24
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_DELAY_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int log_touch_event(int led_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, %d\n", timestamp, led_state);
    fclose(fp);
    return 0;
}

int main() {
    int pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_PIN mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set initial LED state to off
    gpioWrite(LED_PIN, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch-activated lamp started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int touch_detected = gpioRead(TOUCH_PIN);

        if (touch_detected) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Re-read the pin after the delay to confirm the touch
            if (gpioRead(TOUCH_PIN) == touch_detected) {
                // Toggle LED state
                int current_led_state = gpioRead(LED_PIN);
                gpioWrite(LED_PIN, !current_led_state);

                // Log the event
                if (log_touch_event(current_led_state) != 0) {
                    fprintf(stderr, "Failed to log touch event.\n");
                }
            } else {
                fprintf(stderr, "Touch signal unstable, not toggling LED.\n");
            }
        }

        gpioDelay(1000000); // Check every 1 second
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED on exit
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

