#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define ALERT_LOG_FILE "alert_log.txt"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_S 2
#define ALERT_LOG_INTERVAL_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int log_alert(const char *timestamp) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening alert log file");
        return -1;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    return 0;
}

int send_alert(const char *timestamp) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (sendto(sockfd, timestamp, strlen(timestamp), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

void flame_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Flame detected (active-low)
        char *timestamp = get_timestamp();
        if (timestamp != NULL) {
            printf("FLAME DETECTED at %s\n", timestamp);
            if (log_alert(timestamp) != 0) {
                fprintf(stderr, "Failed to log alert.\n");
            }
            if (send_alert(timestamp) != 0) {
                fprintf(stderr, "Failed to send alert.\n");
            }
            free(timestamp);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetAlertFuncEx(FLAME_SENSOR_GPIO, flame_detected_callback, NULL);

    while (program_running) {
        // Check for shutdown signals
        if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
            perror("Error reinstalling signal handler");
            break;
        }

        // Poll the flame sensor
        if (gpioRead(FLAME_SENSOR_GPIO) == 0) {
            gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
            gpioDelay(BUZZER_DURATION_S * 1000000); // Wait for buzzer duration
            gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
        }

        gpioDelay(POLL_INTERVAL_MS); // Wait before next poll
    }

    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate(); // Release GPIO resources

    printf("System stopped.\n");
    return 0;
}

