#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HEART_RATE_REG 0x24
#define CONFIG_REG 0x18
#define CONFIG_VALUE 0x80 // Example configuration value, adjust as needed
#define MOVING_AVG_SIZE 5
#define BPM_MIN 30
#define BPM_MAX 220
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration data
typedef struct {
    int i2c_bus;
    int i2c_address;
    int part_id;
    int hw_rev;
    int config_value;
} sensor_config_t;

// Function prototypes
int init_i2c(sensor_config_t *config);
int read_sensor_data(int handle, uint8_t reg, uint8_t *data, int len);
int write_sensor_data(int handle, uint8_t reg, uint8_t value);
int read_sensor_reg(int handle, uint8_t reg, uint8_t *data, int len);
int read_sensor_reg_with_retry(int handle, uint8_t reg, uint8_t *data, int len);
int read_sensor_config(int handle, uint8_t *data, int len);
int configure_sensor(int handle, uint8_t config_value);
int read_heart_rate(int handle, int *heart_rate);
int apply_moving_average(int *raw_data, int data_len, int *filtered_data, int data_len);
int validate_bpm(int bpm);
int log_data(int bpm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c(sensor_config_t *config) {
    i2c_handle = i2cOpen(config->i2c_bus, config->i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor presence
    uint8_t part_id, hw_rev;
    if (read_sensor_reg_with_retry(i2c_handle, PART_ID_REG, &part_id, 1) != 0) {
        fprintf(stderr, "Error reading PART_ID\n");
        return -1;
    }
    if (read_sensor_reg_with_retry(i2c_handle, HW_REV_REG, &hw_rev, 1) != 0) {
        fprintf(stderr, "Error reading HW_REV\n");
        return -1;
    }

    if (part_id != 0x82 || hw_rev != 0x00) {
        fprintf(stderr, "Error: Incorrect PART_ID (0x%02X) or HW_REV (0x%02X). Check sensor connection.\n", part_id, hw_rev);
        return -1;
    }

    return 0;
}

// Read sensor data with retry
int read_sensor_reg_with_retry(int handle, uint8_t reg, uint8_t *data, int len) {
    int retries = 0;
    int result;
    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(handle, reg, (char *)data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(10); // Small delay before retrying
            retries++;
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure after all retries
}

// Read sensor register
int read_sensor_reg(int handle, uint8_t reg, uint8_t *data, int len) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }
    return 0;
}

// Write sensor data
int write_sensor_data(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "I2C write error: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor configuration
int read_sensor_config(int handle, uint8_t *data, int len) {
    int result = i2cReadI2CBlockData(handle, CONFIG_REG, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }
    return 0;
}

// Configure the sensor
int configure_sensor(int handle, uint8_t config_value) {
    if (write_sensor_data(handle, CONFIG_REG, config_value) != 0) {
        fprintf(stderr, "Error configuring sensor.\n");
        return -1;
    }
    return 0;
}

// Read heart rate data
int read_heart_rate(int handle, int *heart_rate) {
    uint8_t data[2];
    if (read_sensor_reg_with_retry(handle, HEART_RATE_REG, data, 2) != 0) {
        fprintf(stderr, "Error reading heart rate data.\n");
        return -1;
    }

    *heart_rate = (data[0] << 8) | data[1];
    return 0;
}

// Apply moving average filter
int apply_moving_average(int *raw_data, int data_len, int *filtered_data, int data_len) {
    for (int i = 0; i < data_len; i++) {
        filtered_data[i] = 0;
        for (int j = 0; j < MOVING_AVG_SIZE; j++) {
            filtered_data[i] += raw_data[i + j];
        }
        filtered_data[i] /= MOVING_AVG_SIZE;
    }
    return 0;
}

// Validate BPM value
int validate_bpm(int bpm) {
    return (bpm >= BPM_MIN && bpm <= BPM_MAX);
}

// Log data to file
int log_data(int bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    sensor_config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = SI1182_ADDR,
        .part_id = 0x82,
        .hw_rev = 0x00,
        .config_value = CONFIG_VALUE
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c(&config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle, config.config_value) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int raw_heart_rate[MOVING_AVG_SIZE];
    int filtered_heart_rate;
    int bpm;
    int read_result;

    while (!terminate) {
        // Read heart rate data
        read_result = read_heart_rate(i2c_handle, &raw_heart_rate[0]);
        if (read_result != 0) {
            fprintf(stderr, "Error reading heart rate, retrying in 1 second...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Apply moving average filter
        apply_moving_average(raw_heart_rate, MOVING_AVG_SIZE, filtered_heart_rate, MOVING_AVG_SIZE);

        // Validate BPM
        if (validate_bpm(filtered_heart_rate)) {
            // Log data
            if (log_data(filtered_heart_rate) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
            fprintf(stderr, "Invalid BPM value: %d\n", filtered_heart_rate);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

