        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c(&config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle, config.config_value) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

