            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Apply moving average filter
        apply_moving_average(raw_heart_rate, MOVING_AVG_SIZE, filtered_heart_rate, MOVING_AVG_SIZE);

        // Validate BPM
        if (validate_bpm(filtered_heart_rate)) {
            // Log data
            if (log_data(filtered_heart_rate) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
