#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for touch sensors and counter outputs
const int touch_pins[] = {5, 6, 7, 8, 9, 10, 11, 12};
const int counter_pins[] = {17, 18, 19, 20, 21, 22, 23, 24};
const int num_channels = 8;

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void signal_handler(int signal);
char* get_iso8601_timestamp();
int write_to_log(const char* timestamp, int channel, int counter_value);
int set_output_pins(int counter_value);
int read_touch_sensors();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set touch sensor pins as inputs
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(touch_pins[i], PI_INPUT);
        gpioSetPullUpDown(touch_pins[i], PI_PUD_UP); // Enable pull-up resistors
    }

    // Set counter output pins as outputs
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(counter_pins[i], PI_OUTPUT);
        gpioWrite(counter_pins[i], 0); // Initialize all bits to 0
    }

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    // Reset all output pins to 0
    for (int i = 0; i < num_channels; i++) {
        gpioWrite(counter_pins[i], 0);
    }

    gpioTerminate();
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to write to the log file
int write_to_log(const char* timestamp, int channel, int counter_value) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
    fclose(fp);
    return 0;
}

// Function to set the output pins based on the counter value
int set_output_pins(int counter_value) {
    for (int i = 0; i < num_channels; i++) {
        gpioWrite(counter_pins[i], (counter_value >> i) & 1);
    }
    return 0;
}

// Function to read the touch sensors
int read_touch_sensors() {
    for (int i = 0; i < num_channels; i++) {
        int value = gpioRead(touch_pins[i]);
        if (value < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Error reading GPIO %d: %s", touch_pins[i], strerror(errno));
            fprintf(stderr, "%s\n", error_message);
            return -1; // Indicate an error
        }
        if (value == 0) { // Assuming touch sensor outputs 0 when touched
            return i; // Return the channel number
        }
    }
    return -1; // No touch detected
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read touch sensors
        int touch_channel = read_touch_sensors();
        if (touch_channel == -1) {
            // Error reading sensors, skip this iteration
            gpioDelay(10); // Small delay to avoid busy-waiting
            continue;
        }

        // Get timestamp
        char* timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping log entry\n");
            gpioDelay(10);
            continue;
        }

        // Increment counter
        int counter_value = (counter_value + 1) % 256; // Ensure counter wraps at 255

        // Set output pins
        set_output_pins(counter_value);

        // Write to log
        if (write_to_log(timestamp, touch_channel, counter_value) != 0) {
            fprintf(stderr, "Failed to write to log\n");
        }

        // Print to stdout
        printf("Touch on channel %d | Counter: %d\n", touch_channel, counter_value);

        // Free the timestamp memory
        free(timestamp);

        // Delay for 10ms
        gpioDelay(10);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

