#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define SENSOR_3_GPIO 27
#define SENSOR_4_GPIO 22

#define POLLING_INTERVAL_MS 100

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_3_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_4_GPIO, PI_INPUT);

    return 0;
}

// Function to read sensor values
int read_sensors(int sensor1_gpio, int sensor2_gpio, int sensor3_gpio, int sensor4_gpio) {
    int sensor1_value = gpioRead(sensor1_gpio);
    int sensor2_value = gpioRead(sensor2_gpio);
    int sensor3_value = gpioRead(sensor3_gpio);
    int sensor4_value = gpioRead(sensor4_gpio);

    if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0 || sensor4_value < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1; // Indicate an error
    }

    return (sensor1_value << 3) | (sensor2_value << 2) | (sensor3_value << 1) | sensor4_value;
}

// Function to format timestamp
void format_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to write data to CSV file
int write_to_csv(const char *timestamp, int sensor1, int sensor2, int sensor3, int sensor4) {
    FILE *fp = fopen("tracking_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4);
    fflush(fp); // Ensure data is written immediately
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Infrared Tracking Program started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_values = read_sensors(SENSOR_1_GPIO, SENSOR_2_GPIO, SENSOR_3_GPIO, SENSOR_4_GPIO);

        if (sensor_values == -1) {
            // Error reading sensors, but continue running
            gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
            continue;
        }

        char timestamp[20];
        format_timestamp(timestamp);

        if (write_to_csv(timestamp, (sensor_values >> 2) & 1, (sensor_values >> 1) & 1, (sensor_values >> 0) & 1, (sensor_values >> 3) & 1) != 0) {
            fprintf(stderr, "Error writing to CSV file\n");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup GPIO
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

