#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 4
#define LED_OUTPUT_PIN 17

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to sample the audio input
int sample_audio() {
    return gpioRead(AUDIO_INPUT_PIN);
}

// Function to detect sound peaks
int detect_peak(int sample) {
    return (sample == 1) ? 1 : 0; // HIGH is considered a peak
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_OUTPUT_PIN, on);
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", &tm_info);
    char milliseconds[5];
    snprintf(milliseconds, 5, ".%03ld", ts.tv_nsec / 1000000);
    strcat(timestamp, milliseconds);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT);
    gpioSetMode(LED_OUTPUT_PIN, PI_OUTPUT);

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Sample audio
        int peak_detected = detect_peak(sample_audio());

        // Detect sound peak
        if (peak_detected) {
            // Get timestamp
            char timestamp[26];
            get_timestamp(timestamp);

            // Control LED
            control_led(1); // Turn LED on
            gpioDelay(100);   // Wait for 100ms
            control_led(0); // Turn LED off
        }

        // Delay to achieve approximately 8kHz sampling rate
        gpioDelay(125); // 125 microseconds
    }

    // Cleanup
    gpioWrite(LED_OUTPUT_PIN, 0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio

    return 0;
}

