#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize a GPIO pin as an active-low input with pull-up resistor
int initialize_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode\n", pin);
        return -1;
    }

    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up resistor on GPIO %d\n", pin);
        return -1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }
    return value;
}

// Function to log the sensor states to the console
void log_sensor_states(int left, int center, int right) {
    printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio(LEFT_SENSOR_PIN) != 0 ||
        initialize_gpio(CENTER_SENSOR_PIN) != 0 ||
        initialize_gpio(RIGHT_SENSOR_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop to read and log sensor states
    while (program_running) {
        int left_state = read_sensor(LEFT_SENSOR_PIN);
        int center_state = read_sensor(CENTER_SENSOR_PIN);
        int right_state = read_sensor(RIGHT_SENSOR_PIN);

        if (left_state == -1 || center_state == -1 || right_state == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        log_sensor_states(left_state, center_state, right_state);

        gpioDelay(100); // Wait 100 milliseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated successfully\n");
    return 0;
}

