#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address for the Si1175 sensor
#define I2C_BUS 1
#define SI1175_ADDR 0x60

// Define the register addresses for the ALS data
#define ALS_LSB_REG 0x22
#define ALS_MSB_REG 0x23

// Global variable to store the I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read the ALS data from the Si1175 sensor
int read_als_data(int i2c_handle) {
    int als_lsb, als_msb;

    // Read the LSB register
    als_lsb = i2cReadByteData(i2c_handle, ALS_LSB_REG);
    if (als_lsb < 0) {
        fprintf(stderr, "Error reading ALS LSB register: %d\n", als_lsb);
        return -1; // Indicate an error
    }

    // Read the MSB register
    als_msb = i2cReadByteData(i2c_handle, ALS_MSB_REG);
    if (als_msb < 0) {
        fprintf(stderr, "Error reading ALS MSB register: %d\n", als_msb);
        return -1; // Indicate an error
    }

    // Combine the LSB and MSB values into a single 16-bit raw value
    int raw_value = (als_msb << 8) | als_lsb;

    return raw_value;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

