        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read the ALS data from the Si1175 sensor
int read_als_data(int i2c_handle) {
    int als_lsb, als_msb;

    // Read the LSB register
    als_lsb = i2cReadByteData(i2c_handle, ALS_LSB_REG);
    if (als_lsb < 0) {
