    gpioSetMode(TP1, PI_INPUT);
    gpioSetMode(TP2, PI_INPUT);
    gpioSetMode(TP3, PI_INPUT);
    gpioSetMode(TP4, PI_INPUT);
    gpioSetMode(TP5, PI_INPUT);
    gpioSetMode(TP6, PI_INPUT);
    gpioSetMode(TP7, PI_INPUT);
    gpioSetMode(TP8, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read the state of each touch sensor channel
        int tp1_value = read_touch_channel(TP1);
        int tp2_value = read_touch_channel(TP2);
        int tp3_value = read_touch_channel(TP3);
        int tp4_value = read_touch_channel(TP4);
        int tp5_value = read_touch_channel(TP5);
        int tp6_value = read_touch_channel(TP6);
        int tp7_value = read_touch_channel(TP7);
        int tp8_value = read_touch_channel(TP8);

        // Check for errors during sensor reads
        if (tp1_value < 0 || tp2_value < 0 || tp3_value < 0 || tp4_value < 0 ||
            tp5_value < 0 || tp6_value < 0 || tp7_value < 0 || tp8_value < 0) {
            fprintf(stderr, "Error reading sensor data, exiting...\n");
            break; // Exit the loop if there's an error
