        printf("%s\n", output_string);

        // Delay for 200 milliseconds
        gpioDelay(200000); // Delay in microseconds
    }

    // Release all GPIO resources
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

