#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define number of steps for fading
#define NUM_STEPS 50

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void set_led_color(int red, int green, int blue);
void fade_color(int red, int green, int blue, int steps, int delay_ms);
void generate_random_hue(int *red, int *green, int *blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        syslog(LOG_INFO, "Received signal, shutting down...");
        program_running = 0;
        set_led_color(0, 0, 0); // Turn off LED
        cleanup_gpio();          // Release GPIO resources
        closelog();              // Close syslog
        exit(0);
    }
}

// Function to initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

// Function to set the color of the RGB LED
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to fade the color of the RGB LED
void fade_color(int red, int green, int blue, int steps, int delay_ms) {
    for (int i = 0; i < steps; i++) {
        int new_red = red;
        int new_green = green;
        int new_blue = blue;

        // Generate a new hue (red, green, blue) for the next step
        generate_random_hue(&new_red, &new_green, &new_blue);

        // Linear interpolation
        red = (red + new_red) / steps;
        green = (green + new_green) / steps;
        blue = (blue + new_blue) / steps;

        // Clamp values to 0-255 range
        if (red < 0) red = 0;
        if (red > 255) red = 255;
        if (green < 0) green = 0;
        if (green > 255) green = 255;
        if (blue < 0) blue = 0;
        if (blue > 255) blue = 255;

        set_led_color(red, green, blue);

        gpioDelay(delay_ms * 1000); // Delay in microseconds
    }
}

// Function to generate a random hue (red, green, blue) using rand()
void generate_random_hue(int *red, int *green, int *blue) {
    srand(time(NULL)); // Seed the random number generator
    *red = rand() % 256;
    *green = rand() % 256;
    *blue = rand() % 256;
}

int main() {
    // Open syslog for logging
    openlog("rgb_led", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "RGB LED control program started");

    // Main loop: continuously fade colors
    while (program_running) {
        int red, green, blue;
        generate_random_hue(&red, &green, &blue);

        fade_color(red, green, blue, NUM_STEPS, 1000); // Fade over 5 seconds (1000ms delay)
    }

    // Cleanup and exit (should not reach here if signal handler works)
    cleanup_gpio();
    closelog();
    return 0;
}

