#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ENABLE_PON      (0x01)
#define TCS34725_ENABLE_AEN      (0x02)
#define TCS34725_ID              (0x12)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)
#define TCS34725_ATIME           (0x01)
#define TCS34725_CONTROL         (0x0F)

// GPIO Pin for LED
#define LED_PIN                 (17)

// Red Value Threshold
#define RED_THRESHOLD           (200)

// Global Variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int tcs34725_init();
int tcs34725_read_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear);
void signal_handler(int signal);
void cleanup();

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize TCS34725 Sensor
int tcs34725_init() {
    int status;

    // Enable power and RGBC
    status = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN);
