#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define BH1750_ADDR 0x23
#define WS2812B_GPIO 18
#define PWM_FREQUENCY 8000000 // 8 MHz
#define PWM_RANGE 1000000      // 1 MHz
#define PWM_CLOCK_DIVIDER 400  // 8 MHz / 400 = 20 MHz / 400 = 50 kHz
#define PWM_DUTY_CYCLE_RANGE 1000000 // 1 MHz / 1000000 = 1 us
#define PWM_CLOCK_DIVIDER 400  // 8 MHz / 400 = 20 MHz / 400 = 50 kHz
#define PWM_DUTY_CYCLE_RANGE 1000000 // 1 MHz / 1000000 = 1 us
#define NUM_LEDS 10
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750();
float read_bh1750();
int map_lux_to_brightness(float lux);
void generate_ws2812b_data(int brightness_levels[NUM_LEDS]);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

// Initialize BH1750 sensor
int init_bh1750() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illumination value from BH1750 sensor
float read_bh1750() {
    char config_cmd = 0x10; // Continuous high resolution mode
    char buffer[2];
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, config_cmd) != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        gpioDelay(180000); // Wait 180 ms

        if (i2cReadDevice(i2c_handle, buffer, 2) == 2) {
            unsigned int raw_value = (buffer[0] << 8) | buffer[1];
            return (float)raw_value / 1.2; // Convert to lux
        } else {
            fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to read from BH1750 after multiple retries.\n");
    return -1.0; // Indicate error
}

// Map lux value to brightness level (logarithmic)
int map_lux_to_brightness(float lux) {
    // Ensure lux is positive
    if (lux < 0) {
        lux = 0;
    }

    // Calculate log10(lux + 1) to avoid log(0)
    float log_lux = log10(lux + 1);

    // Scale to brightness range (0-255)
    int brightness = (int)(log_lux * 255.0); // Scale log10 to 0-255

    // Clamp brightness to 0-255 range
    if (brightness < 0) {
        brightness = 0;
    } else if (brightness > 255) {
        brightness = 255;
    }

    return brightness;
}

// Generate WS2812B data stream
void generate_ws2812b_data(int brightness_levels[NUM_LEDS]) {
    int num_leds = NUM_LEDS;
    int num_bytes = num_leds * 4 + 4; // 4 bytes per LED + start bits
    uint32_t *data = (uint32_t *)malloc(num_bytes * sizeof(uint32_t));
    if (data == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return;
    }

    // Start frame (0x00, 0x00, 0x00, 0x00)
    data[0] = 0x00; // Blue
    data[1] = 0x00; // Green
    data[2] = 0x00; // Red
    data[3] = 0x00;

    // LED data
    for (int i = 0; i < num_leds; i++) {
        data[4 + i] = 0xE0 | brightness_levels[i]; // Global brightness
        data[5 + i] = brightness_levels[i];       // Blue
        data[6 + i] = brightness_levels[i];       // Green
        data[7 + i] = brightness_levels[i];       // Red
    }

    // End frame (0xFF, 0xFF, 0xFF, 0xFF)
    for (int i = num_leds; i < num_bytes; i++) {
        data[i] = 0xFF;
    }

    // Send data using hardware PWM
    gpioWaveClear();
    gpioPulse_t pulse[NUM_BYTES];
    for (int i = 0; i < num_bytes; i++) {
        pulse[i].gpioOn = 1 << WS2812B_GPIO;
        pulse[i].gpioOff = 0;
        pulse[i].usDelay = (uint32_t)(((uint32_t)data[i] & 0xFF) * PWM_DUTY_CYCLE_RANGE / 255.0);
        if ((data[i] >> 8) != 0) {
            pulse[i].usDelay += PWM_DUTY_CYCLE_RANGE / 255.0;
        }
        gpioWaveAddGeneric(1, &pulse[i]);
    }

    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
        gpioDelay(10000); // Delay for transmission (adjust as needed)
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
    }

    free(data);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize BH1750 sensor
    if (init_bh1750() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure PWM
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(WS2812B_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(WS2812B_GPIO, PWM_RANGE);
    gpioSetPWMclock(WS2812B_GPIO, PWM_CLOCK_DIVIDER);

    // Main loop
    while (!terminate) {
        // Read illumination value
        float lux = read_bh1750();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, skipping iteration.\n");
            gpioDelay(100000); // Delay 100ms
            continue;
        }

        // Map lux to brightness
        int brightness_levels[NUM_LEDS];
        for (int i = 0; i < NUM_LEDS; i++) {
            brightness_levels[i] = map_lux_to_brightness(lux);
        }

        // Generate WS2812B data
        generate_ws2812b_data(brightness_levels);

        // Delay
        gpioDelay(100000); // Delay 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

