#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_ADDR_3 0x60
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define NUM_LEDS 30
#define TARGET_BRIGHTNESS 500 // Example target brightness
#define FADE_DURATION_MS 500
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
int i2c_handle_3 = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
float average_light_sensors(int sensor1, int sensor2, int sensor3);
int map_light_to_brightness(float average_light);
int set_apa102_brightness(int brightness);
void fade_led_strip(int target_brightness);
void signal_handler(int signal);

// Function to read light intensity from BH1750 sensor
int read_bh1750(int i2c_handle) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Invalid I2C handle.\n");
        return -1;
    }

    int count = 0;
    int retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        // Send start measurement command (High Resolution Mode)
        if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
            fprintf(stderr, "Error: Failed to send start measurement command. Retries remaining: %d\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        gpioDelay(180000); // Wait 180ms for measurement

        // Read two bytes of data
        char buf[2];
        if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) == 2) {
            // Combine the two bytes into a single 16-bit value
            return (buf[0] << 8) | buf[1];
        } else {
            fprintf(stderr, "Error: Failed to read data from BH1750. Retries remaining: %d\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Error: Failed to read BH1750 after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to average the light sensor readings
float average_light_sensors(int sensor1, int sensor2, int sensor3) {
    float sum = 0.0;
    int valid_sensors = 0;

    if (sensor1 != -1) {
        sum += sensor1;
        valid_sensors++;
    }
    if (sensor2 != -1) {
        sum += sensor2;
        valid_sensors++;
    }
    if (sensor3 != -1) {
        sum += sensor3;
        valid_sensors++;
    }

    if (valid_sensors > 0) {
        return sum / valid_sensors;
    } else {
        return 0.0; // Return 0 if no valid sensors
    }
}

// Function to map light intensity to brightness value (0-255)
int map_light_to_brightness(float average_light) {
    // Define a maximum light intensity (adjust as needed)
    float max_light = 1000.0; // Example maximum light intensity

    // Ensure average_light is within the valid range
    if (average_light < 0.0) {
        average_light = 0.0;
    } else if (average_light > max_light) {
        average_light = max_light;
    }

    // Map the light intensity to a brightness value (0-255)
    int brightness = (int)((average_light / max_light) * 255.0);

    // Clamp the brightness value to the valid range
    if (brightness < 0) {
        brightness = 0;
    } else if (brightness > 255) {
        brightness = 255;
    }

    return brightness;
}

// Function to set the APA102 LED strip brightness
int set_apa102_brightness(int brightness) {
    unsigned char data[4];
    data[0] = 0xE0; // Global brightness (255 - brightness)
    data[1] = 0x00; // Blue
    data[2] = 0x00; // Green
    data[3] = 0x00; // Red

    // Send the data over SPI
    if (spiWrite(spi_handle, (char *)data, 4) != 4) {
        fprintf(stderr, "Error: Failed to write to SPI.\n");
        return -1;
    }

    return 0;
}

// Function to fade the LED strip brightness
void fade_led_strip(int target_brightness) {
    int current_brightness = 0;
    int step = (target_brightness > current_brightness) ? (target_brightness - current_brightness) : (current_brightness - target_brightness);
    float delay_ms = (float)FADE_DURATION_MS / 20.0; // 20 steps over FADE_DURATION_MS

    for (int i = 0; i < 20; i++) {
        current_brightness += step;
        if (current_brightness > target_brightness) {
            current_brightness = target_brightness;
        }

        if (set_apa102_brightness(current_brightness) != 0) {
            fprintf(stderr, "Error: Failed to set brightness during fade.\n");
            return;
        }

        gpioDelay(delay_ms * 1000); // Convert ms to us
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;

    // Turn off the LED strip
    set_apa102_brightness(0);

    // Close I2C handles
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
    }
    if (i2c_handle_3 >= 0) {
        i2cClose(i2c_handle_3);
    }

    // Close SPI handle
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C handles for each sensor
    i2c_handle_1 = i2cOpen(1, BH1750_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X\n", BH1750_ADDR_1);
        i2c_handle_1 = -1; // Mark as invalid
    }

    i2c_handle_2 = i2cOpen(1, BH1750_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X\n", BH1750_ADDR_2);
        i2c_handle_2 = -1; // Mark as invalid
    }

    i2c_handle_3 = i2cOpen(1, BH1750_ADDR_3, 0);
    if (i2c_handle_3 < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X\n", BH1750_ADDR_3);
        i2c_handle_3 = -1; // Mark as invalid
    }

    // Open SPI handle
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read light sensor values
        int sensor1 = read_bh1750(i2c_handle_1);
        int sensor2 = read_bh1750(i2c_handle_2);
        int sensor3 = read_bh1750(i2c_handle_3);

        // Average the light sensor readings
        float average_light = average_light_sensors(sensor1, sensor2, sensor3);

        // Map light intensity to brightness
        int brightness = map_light_to_brightness(average_light);

        // Fade the LED strip brightness
        fade_led_strip(brightness);

        // Delay for 100ms
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_apa102_brightness(0);
    if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
    if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
    if (i2c_handle_3 >= 0) i2cClose(i2c_handle_3);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

