#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define error codes
#define NO_ERROR 0
#define FLAME_DETECTED 1
#define SELF_TEST_ERROR 2
#define PIGPIO_INIT_ERROR 3

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void activate_buzzer_led(int error_code);
void log_event(int error_code);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return PIGPIO_INIT_ERROR;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return NO_ERROR;
}

// Read flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Activate buzzer and LED based on error code
void activate_buzzer_led(int error_code) {
    gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    gpioWrite(LED_PIN, 1);    // Turn on LED

    switch (error_code) {
        case FLAME_DETECTED:
            printf("Flame detected!\n");
            break;
        case SELF_TEST_ERROR:
            printf("Self-test failed!\n");
            break;
        default:
            break;
    }

    // Short-short-long-short buzzer pattern
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioDelay(200);           // 200ms
    gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    gpioDelay(200);           // 200ms
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioDelay(600);           // 600ms
    gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    gpioDelay(200);           // 200ms
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioDelay(200);           // 200ms
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioWrite(LED_PIN, 0);    // Turn off LED
}

// Log event to file
void log_event(int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Error: %d\n", timestamp, error_code);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Could not write to log file.\n");
    }
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioWrite(LED_PIN, 0);    // Turn off LED
    gpioTerminate();
}

int main() {
    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != NO_ERROR) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_sensor.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = 0;
        int flame_clear = 0;
        int error_code = NO_ERROR;

        // Self-test
        printf("Starting self-test...\n");
        for (int i = 0; i < 5; i++) {
            int sensor_value = read_flame_sensor();
            if (sensor_value == 0) {
                flame_detected = 1;
                break;
            }
            gpioDelay(100); // 100ms delay
        }

        if (flame_detected) {
            activate_buzzer_led(FLAME_DETECTED);
            error_code = FLAME_DETECTED;
        } else {
            error_code = NO_ERROR;
        }

        // Main loop
        while (program_running) {
            int sensor_value = read_flame_sensor();

            if (sensor_value == 0) {
                activate_buzzer_led(FLAME_DETECTED);
                flame_detected = 1;
            } else {
                flame_clear = 1;
            }

            gpioDelay(50); // 50ms delay

            if (sensor_value == 0 && flame_detected) {
                activate_buzzer_led(FLAME_DETECTED);
                error_code = FLAME_DETECTED;
            } else if (sensor_value == 1 && flame_clear) {
                gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
                gpioWrite(LED_PIN, 0);    // Turn off LED
                error_code = NO_ERROR;
            }
        }

        if (error_code == NO_ERROR) {
            printf("Flame sensor monitoring resumed.\n");
        } else {
            printf("Exiting due to error.\n");
            program_running = 0;
        }
    }

    // Cleanup and exit
    printf("Cleaning up and exiting.\n");
    fclose(log_file);
    cleanup_gpio();

    return 0;
}

