// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0
#define MIN_LUX 1000
#define MAX_LUX 10000

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer lux_buffer;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void init_gpio();
void set_led_state(int state);
void blink_led(float frequency);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read light intensity from BH1750 sensor
int read_bh1750(float *lux) {
