#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment patterns for digits 0-9 (common cathode)
const int segments[] = {
    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

// Function to shift out data to the 74HC595
void shiftOut(int dataPin, int clockPin, int latchPin, unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set the data pin
        gpioWrite(dataPin, (data >> (7 - i)) & 1);

        // Pulse the clock pin
        gpioWrite(clockPin, 1);
        gpioDelay(1); // Small delay for clock stability
        gpioWrite(clockPin, 0);
        gpioDelay(1); // Small delay for clock stability

        // Latch the data
        gpioWrite(latchPin, 1);
        gpioDelay(1); // Small delay for latch stability
        gpioWrite(latchPin, 0);
        gpioDelay(1); // Small delay for latch stability
    }
}

// Function to display a digit on the seven-segment display
void displayDigit(int digit) {
    shiftOut(DATA_PIN, CLOCK_PIN, LATCH_PIN, segments[digit]);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LATCH_PIN, PI_OUTPUT);

    // Main loop to display the digit '5' blinking
    while (1) {
        displayDigit(4); // Display digit 5
        gpioDelay(500);   // On for 500ms

        displayDigit(0); // Clear display
        gpioDelay(500);   // Off for 500ms
    }

    // Clean up and terminate the pigpio library (this part will not be reached in the infinite loop)
    gpioTerminate();
    return 0;
}

