#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;
    struct timespec on_time = {1, 0}; // 1 second
    struct timespec off_time = {1, 0}; // 1 second
    struct timespec timeout = {0, 100000000}; // 100ms

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(led_line, 0, 0); // Initial state LOW
    if (ret < 0) {
        perror("Error requesting LED line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request button line as input with pull-up
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(button_line, 0, GPIOD_LINE_REQUEST_PULL_UP); // Pull-up enabled
    if (ret < 0) {
        perror("Error requesting button line as input");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure LED blinking
    while (running) {
        ret = gpiod_line_set_value(led_line, 1, timeout);
        if (ret < 0) {
            perror("Error setting LED on");
            break;
        }
        nanosleep(&on_time, NULL);

        ret = gpiod_line_set_value(led_line, 0, timeout);
        if (ret < 0) {
            perror("Error setting LED off");
            break;
        }
        nanosleep(&off_time, NULL);
    }

    // Button press detection
    while (running) {
        ret = gpiod_line_event_wait(button_line, timeout);
        if (ret < 0) {
            if (ret == -EAGAIN) {
                // Timeout occurred, check for button press
                int value = gpiod_line_get_value(button_line);
                if (value == 0) {
                    printf("Button pressed!\n");
                    break; // Exit blinking loop
                }
            } else {
                perror("Error waiting for button event");
                break;
            }
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpiod_line_set_value(led_line, 0, timeout); // Turn LED off
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

