#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return -1;
    }

    // Set button pin as input with pull-down resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin as input\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on button pin\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to control the LED
void control_led(int on) {
    if (gpioWrite(LED_PIN, on) != 0) {
        fprintf(stderr, "Failed to write to LED pin\n");
    }
}

// Function to monitor the button
int monitor_button() {
    int button_state = gpioRead(BUTTON_PIN);
    if (button_state < 0) {
        fprintf(stderr, "Failed to read button pin\n");
        return -1; // Indicate error
    }
    return button_state;
}

// Function to blink the LED
void blink_led() {
    for (int i = 0; i < 5; i++) { // Blink 5 times
        control_led(1); // Turn LED on
        gpioDelay(500);  // Wait 500ms
        control_led(0); // Turn LED off
        gpioDelay(500);  // Wait 500ms
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int button_state = monitor_button();
        if (button_state < 0) {
            break; // Exit loop on error
        }

        if (button_state == 1) { // Button is pressed (HIGH)
            blink_led();
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    control_led(0); // Ensure LED is off before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

