#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
        gpioTerminate(); // Release GPIO resources
        program_running = 0; // Set flag to exit main loop
    }
}

// Function to set PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Error: Duty cycle out of range (0-255). Using 0.\n");
        duty_cycle = 0;
    }

    gpioPWM(gpio, duty_cycle);
}

// Function to generate random RGB values
void generate_random_rgb(int *red, int *green, int *blue) {
    *red = rand() % 101;
    *green = rand() % 101;
    *blue = rand() % 101;
}

// Function to set the RGB LED color using PWM
void set_rgb_color(int red, int green, int blue) {
    set_pwm_duty_cycle(RED_PIN, red);
    set_pwm_duty_cycle(GREEN_PIN, green);
    set_pwm_duty_cycle(BLUE_PIN, blue);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed the random number generator with the current time
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate random RGB values
        int red, green, blue;
        generate_random_rgb(&red, &green, &blue);

        // Set the RGB color
        set_rgb_color(red, green, blue);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

