#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// GPIO pin for impact interrupt
#define IMPACT_GPIO 17

// Default impact threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double impact_threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_lsm303();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void trigger_interrupt();
void log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LSM303DLHC accelerometer
int init_lsm303() {
    // Enable accelerometer, 50 Hz data rate, enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) < 0) { // Read multiple bytes with auto-increment
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate total G-force magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z) / 16384.0; // Convert to G (assuming +/- 2G range)
}

// Trigger impact interrupt
void trigger_interrupt() {
    gpioWrite(IMPACT_GPIO, 1); // Set GPIO HIGH
    gpioDelay(50);            // Wait 50 ms
    gpioWrite(IMPACT_GPIO, 0); // Set GPIO LOW
}

// Log accelerometer data to file
void log_data(int16_t x, int16_t y, int16_t z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", s, x, y, z);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        impact_threshold = atof(argv[1]);
        printf("Impact threshold set to: %f G\n", impact_threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(IMPACT_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303DLHC
    if (init_lsm303() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    double magnitude;

    printf("Monitoring accelerometer... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Log data
            log_data(x, y, z);

            // Check for impact
            if (magnitude > impact_threshold) {
                printf("Impact detected! Magnitude: %f G\n", magnitude);
                trigger_interrupt();
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        // Delay for 100 ms (10 Hz sampling rate)
        gpioDelay(100);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(IMPACT_GPIO, 0); // Ensure GPIO is LOW on exit
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

