#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define ALS_LSB_REG 0x00
#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000      // PWM range (0-1000)
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue);
int combine_channels(uint16_t als, uint16_t red, uint16_t green, uint16_t blue, uint16_t *combined);
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue, uint16_t combined);
int control_led_brightness(uint16_t combined);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
    uint16_t combined;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO for PWM
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue,Combined\n");
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.als, &sensor_data.red, &sensor_data.green, &sensor_data.blue) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying in 100ms...\n");
            gpioDelay(100); // Wait 100ms
            continue;
        }

        // Combine channels
        if (combine_channels(sensor_data.als, sensor_data.red, sensor_data.green, sensor_data.blue, &sensor_data.combined) != 0) {
            fprintf(stderr, "Error combining channels, retrying in 100ms...\n");
            gpioDelay(100); // Wait 100ms
            continue;
        }

        // Log data
        if (log_data(sensor_data.als, sensor_data.red, sensor_data.green, sensor_data.blue, sensor_data.combined) != 0) {
            fprintf(stderr, "Error logging data, retrying in 100ms...\n");
            gpioDelay(100); // Wait 100ms
            continue;
        }

        // Control LED brightness
        if (control_led_brightness(sensor_data.combined) != 0) {
            fprintf(stderr, "Error controlling LED brightness, retrying in 100ms...\n");
            gpioDelay(100); // Wait 100ms
            continue;
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[2];

    // Read ALS
    if (i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading ALS data\n");
        return 1;
    }
    *als = (buf[1] << 8) | buf[0];

    // Read Red
    if (i2cReadI2CBlockData(i2c_handle, RED_LSB_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading Red data\n");
        return 1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read Green
    if (i2cReadI2CBlockData(i2c_handle, GREEN_LSB_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading Green data\n");
        return 1;
    }
    *green = (buf[1] << 8) | buf[0];

    // Read Blue
    if (i2cReadI2CBlockData(i2c_handle, BLUE_LSB_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading Blue data\n");
        return 1;
    }
    *blue = (buf[1] << 8) | buf[0];

    return 0;
}

// Combine channels
int combine_channels(uint16_t als, uint16_t red, uint16_t green, uint16_t blue, uint16_t *combined) {
    // Simple average (adjust as needed for your sensor's characteristics)
    *combined = (als + red + green + blue) / 4;
    return 0;
}

// Log data to CSV file
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue, uint16_t combined) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
