// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0); // I2C bus 1, address 0x1F, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Verify WHO_AM_I register
int verify_who_am_i() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0xC7)\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I verified: 0x%02X\n", who_am_i);
    return 0;
}

// Configure the FXOS8700CQ sensor
int configure_sensor() {
    // Put sensor in standby mode
    if (i2cWriteByteData(i2c_handle, STANDBY, 0x01) < 0) {
        fprintf(stderr, "Failed to write standby register: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Set accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) { // 200 Hz, ±2g
        fprintf(stderr, "Failed to write CTRL_REG1: %d\n", i2c_handle);
        return -1;
    }

    // Set magnetometer to active mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG2: %d\n", i2c_handle);
        return -1;
    }

    // Set magnetometer to active mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG3: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

