                // Log impact
                if (log_impact(x, y, z, magnitude) < 0) {
                    fprintf(stderr, "Failed to log impact\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data, retrying...\n");
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

