#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

// LSM303DLHC register addresses
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A  0x28
#define LSM303_MAG_MR_REG_M     0x02
#define LSM303_MAG_OUT_X_H_M  0x03

// Sensitivity values (adjust based on your sensor's configuration)
#define ACCEL_SENSITIVITY 0.001 // +/- 2g range
#define MAG_SENSITIVITY 0.08   // +/- 4 gauss range

// Global variables for I2C handles and program state
int accel_handle = -1;
int mag_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int bus, int addr);
int read_accel_axis(int handle, int axis);
int read_mag_axis(int handle, int axis);
float calculate_heading(float accel_x, float accel_y, float accel_z);
void log_data(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z, float heading);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;
} sensor_data_t;

// Function to initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X on bus %d: %d\n", addr, bus, handle);
        return -1;
    }
    return handle;
}

// Function to read accelerometer data
int read_accel_axis(int handle, int axis) {
    int reg = LSM303_ACCEL_OUT_X_L_A + (axis == 0 ? 0 : (axis == 1 ? 1 : 2));
    int16_t raw_data = i2cReadWordData(handle, reg);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading accelerometer axis %d: %d\n", axis, raw_data);
        return -1;
    }
    return (int)(raw_data * ACCEL_SENSITIVITY);
}

// Function to read magnetometer data
int read_mag_axis(int handle, int axis) {
    int reg = LSM303_MAG_OUT_X_H_M + (axis == 0 ? 0 : (axis == 1 ? 1 : 2));
    int16_t raw_data = i2cReadWordData(handle, reg);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading magnetometer axis %d: %d\n", axis, raw_data);
        return -1;
    }
    return (int)(raw_data * MAG_SENSITIVITY);
}

// Function to calculate tilt-compensated heading
float calculate_heading(float accel_x, float accel_y, float accel_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float cos_roll = cos(roll);
    float sin_roll = sin(roll);
    float cos_pitch = cos(pitch);
    float sin_pitch = sin(pitch);

    float heading = atan2(sin_roll * sin_pitch, cos_roll * sin_pitch + sin_roll * cos_pitch) * 180 / M_PI;

    // Normalize to 0-360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Function to log data to a file
void log_data(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z, float heading) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z,Heading\n");
    }

    // Get current timestamp
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write data to file
    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z, heading);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    accel_handle = init_i2c(1, LSM303_ACCEL_ADDR);
    if (accel_handle < 0) {
        gpioTerminate();
        return 1;
    }

    mag_handle = init_i2c(1, LSM303_MAG_ADDR);
    if (mag_handle < 0) {
        i2cClose(accel_handle);
        gpioTerminate();
        return 1;
    }

    // Configure accelerometer (example: +/- 2g range, 100 Hz)
    if (i2cWriteByteData(accel_handle, LSM303_ACCEL_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error configuring accelerometer\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    // Configure magnetometer (example: continuous conversion mode)
    if (i2cWriteByteData(mag_handle, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error configuring magnetometer\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor data
        int accel_x_raw = read_accel_axis(accel_handle, 0);
        int accel_y_raw = read_accel_axis(accel_handle, 1);
        int accel_z_raw = read_accel_axis(accel_handle, 2);
        int mag_x_raw = read_mag_axis(mag_handle, 0);
        int mag_y_raw = read_mag_axis(mag_handle, 1);
        int mag_z_raw = read_mag_axis(mag_handle, 2);

        if (accel_x_raw < 0 || accel_y_raw < 0 || accel_z_raw < 0 || mag_x_raw < 0 || mag_y_raw < 0 || mag_z_raw < 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert raw data to g and gauss
        float accel_x = (float)accel_x_raw * ACCEL_SENSITIVITY;
        float accel_y = (float)accel_y_raw * ACCEL_SENSITIVITY;
        float accel_z = (float)accel_z_raw * ACCEL_SENSITIVITY;
        float mag_x = (float)mag_x_raw * MAG_SENSITIVITY;
        float mag_y = (float)mag_y_raw * MAG_SENSITIVITY;
        float mag_z = (float)mag_z_raw * MAG_SENSITIVITY;

        // Calculate heading
        float heading = calculate_heading(accel_x, accel_y, accel_z);

        // Log data
        log_data(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z, heading);

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Close I2C handles and terminate pigpio
    i2cClose(accel_handle);
    i2cClose(mag_handle);
    gpioTerminate();

    return 0;
}

