#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define SAMPLE_INTERVAL_US 10000 // 10 ms
#define SAMPLE_RATE_HZ 100
#define SAMPLE_RATE_NS (SAMPLE_RATE_HZ * 1000000)
#define MAX_RETRIES 3

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1;
    int16_t sensor2;
    long long tdoa;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int i2c_handle, int16_t *data);
long long get_timestamp_ns();
int calculate_tdoa(int16_t sensor1, int16_t sensor2);
int log_data(FILE *fp, long long timestamp, int16_t sensor1, int16_t sensor2, long long tdoa);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1: %d\n", i2c_handle1);
        return -1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        return -1;
    }

    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(int i2c_handle, int16_t *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(i2c_handle, 0x00); // Read from register 0x00
        if (result >= 0) {
            *data = (int16_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1; // Failure after all retries
}

// Function to get timestamp in nanoseconds
long long get_timestamp_ns() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000000000LL + ts.tv_nsec);
}

// Function to calculate TDOA
int calculate_tdoa(int16_t sensor1, int16_t sensor2) {
    return abs(sensor1 - sensor2);
}

// Function to log data to CSV file
int log_data(FILE *fp, long long timestamp, int16_t sensor1, int16_t sensor2, long long tdoa) {
    if (fprintf(fp, "%lld,%d,%d,%lld\n", timestamp, sensor1, sensor2, tdoa) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t sensor1_data, sensor2_data;
        long long timestamp = get_timestamp_ns();

        // Read sensor data
        if (read_sensor_data(i2c_handle1, &sensor1_data) == 0 &&
            read_sensor_data(i2c_handle2, &sensor2_data) == 0) {

            // Calculate TDOA
            long long tdoa = calculate_tdoa(sensor1_data, sensor2_data);

            // Log data
            if (log_data(log_file, timestamp, sensor1_data, sensor2_data, tdoa) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, skipping logging\n");
        }

        gpioDelay(SAMPLE_RATE_NS); // Delay for the sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

