#include <pigpio.h>

// ADIS16488A Register Addresses
#define REG_GYRO_XOUT 0x04
#define REG_GYRO_YOUT 0x06
#define REG_GYRO_ZOUT 0x08
#define REG_ACCEL_XOUT 0x0A
#define REG_ACCEL_YOUT 0x0C
#define REG_ACCEL_ZOUT 0x0E

// Sensitivities
#define GYRO_SENSITIVITY 0.005  // degrees/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global Variables
static int spi_handle;
static FILE *data_file;
static volatile int running = 1;

// Function Prototypes
int spi_read_register(int spi_handle, uint8_t reg_addr, uint16_t *data);
int spi_write_register(int spi_handle, uint16_t data);
void cleanup(int spi_handle, FILE *data_file);
void signal_handler(int signal);
void delay_ms(int milliseconds);

// Structure to hold IMU data
typedef struct {
    double gyro_x;
    double gyro_y;
    double gyro_z;
    double accel_x;
    double accel_y;
    double accel_z;
} imu_data_t;

// Function to read data from a specific register
int spi_read_register(int spi_handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer (MSB = 0 for read)
    tx_buf[0] = 0x80 | reg_addr; // Read command
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

// Function to write data to a specific register
int spi_write_register(int spi_handle, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x40 | (data >> 8); // Write command
    tx_buf[1] = data & 0xFF; // Data LSB
    tx_buf[2] = (data >> 8) & 0xFF; // Data MSB

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI write failed for data 0x%04X\n", data);
        return -1;
    }

    return 0;
}

// Function to convert raw data to physical units
void convert_data(imu_data_t *data) {
    data->gyro_x *= GYRO_SENSITIVITY;
    data->gyro_y *= GYRO_SENSITIVITY;
    data->gyro_z *= GYRO_SENSITIVITY;
    data->accel_x *= ACCEL_SENSITIVITY;
    data->accel_y *= ACCEL_SENSITIVITY;
    data->accel_z *= ACCEL_SENSITIVITY;
}

// Function to log data to a CSV file
void log_data(imu_data_t data) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    double timestamp = (double)tv.tv_sec + (double)tv.tv_usec / 1000000.0;

    fprintf(data_file, "%.3f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z);
    fflush(data_file); // Ensure data is written immediately
}

// Cleanup function to be called on exit
void cleanup(int spi_handle, FILE *data_file) {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;
}

// Non-blocking delay function
void delay_ms(int milliseconds) {
    struct timespec req;
    req.tv_sec = 0;
    req.tv_nsec = milliseconds * 1000000L;
    nanosleep(&req, NULL);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen("imu_data.csv", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Install cleanup function with atexit
    atexit(cleanup);

    // Main loop
    imu_data_t imu_data;
    struct timeval last_read_time;
    gettimeofday(&last_read_time, NULL);

    while (running) {
        // Read IMU data
        uint16_t gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw;

        if (spi_read_register(spi_handle, REG_GYRO_XOUT, &gyro_x_raw) != 0 ||
            spi_read_register(spi_handle, REG_GYRO_YOUT, &gyro_y_raw) != 0 ||
            spi_read_register(spi_handle, REG_GYRO_ZOUT, &gyro_z_raw) != 0 ||
            spi_read_register(spi_handle, REG_ACCEL_XOUT, &accel_x_raw) != 0 ||
            spi_read_register(spi_handle, REG_ACCEL_YOUT, &accel_y_raw) != 0 ||
            spi_read_register(spi_handle, REG_ACCEL_ZOUT, &accel_z_raw) != 0) {
