#define ACCEL_SCALE 0.00025 // g/LSB

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init();
int spi_transfer(int spi_handle, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int16_t read_register(int spi_handle, uint8_t reg_addr);
