        return -1;
    }
    return 0;
}

// SPI transfer function
int spi_transfer(int spi_handle, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int result = spiXfer(spi_handle, tx_buf, rx_buf, len);
    if (result < 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1;
    }
    return 0;
}

