    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the transmit buffer (address + dummy data)
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy data
    tx_buf[2] = 0x00; // Dummy data

    if (spi_transfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg_addr);
        return 0; // Return 0 on error
    }

