#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define LED_GPIO 17
#define THRESHOLD 2.5f // g
#define SAMPLE_RATE_MS 10
#define LED_ON_TIME_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
    float magnitude;
} AccelData;

// Function prototypes
int init_i2c();
int verify_adxl345();
int set_adxl345_mode();
int read_accelerometer_data(AccelData *data);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(AccelData data);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify ADXL345
int verify_adxl345() {
    int device_id = i2cReadByteData(i2c_handle, 0x00); // DEVICE_ID register
    if (device_id < 0) {
        fprintf(stderr, "Error reading DEVICE_ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect DEVICE_ID: 0x%02X\n", device_id);
        return -1;
    }
    printf("ADXL345 verified: DEVICE_ID = 0x%02X\n", device_id);
    return 0;
}

// Set ADXL345 mode
int set_adxl345_mode() {
    int status = i2cWriteByteData(i2c_handle, POWER_CTL, 0x08); // Enable measurement
    if (status < 0) {
        fprintf(stderr, "Error writing to POWER_CTL: %d\n", status);
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(AccelData *data) {
    char raw_data[6];
    int status = i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g-force units (assuming ±2g range and 256 LSB/g)
    data->x = (float)x / 256.0f;
    data->y = (float)y / 256.0f;
    data->z = (float)z / 256.0f;
    data->magnitude = calculate_magnitude(x, y, z);

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Log event to file
void log_event(AccelData data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g, Magnitude: %.3f g\n",
            timestamp, data.x, data.y, data.z, data.magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Release GPIO
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify ADXL345
    if (verify_adxl345() != 0) {
        cleanup();
        return 1;
    }

    // Set ADXL345 mode
    if (set_adxl345_mode() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    AccelData data;

    // Main loop
    while (!terminate) {
        if (read_accelerometer_data(&data) == 0) {
            // Check if threshold is exceeded
            if (data.magnitude > THRESHOLD) {
                printf("Threshold exceeded! Magnitude: %.3f g\n", data.magnitude);
                control_led(1); // Turn on LED
                log_event(data); // Log the event
                gpioDelay(LED_ON_TIME_MS * 1000); // Wait for 500ms
                control_led(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

