#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Scaling factors
#define ACCEL_SCALE 16384.0f // +/- 2g
#define GYRO_SCALE 131.0f   // +/- 250 dps

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} imu_data_t;

// Function prototypes
int init_imu();
imu_data_t read_imu_data();
int log_data(imu_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the IMU
int init_imu() {
    // Wake up the IMU (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU. Error code: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(100); // Short delay after waking up

    // Verify device ID
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register. Error code: %d\n", i2c_handle);
        return -1;
    }
    if (who_am_i != 0x98) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read IMU data
imu_data_t read_imu_data() {
    imu_data_t data;
    char buf[14];
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) < 0) {
        fprintf(stderr, "Error: Could not read IMU data. Error code: %d\n", i2c_handle);
        data.accel_x = data.accel_y = data.accel_z = 0.0f;
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0f;
        return data;
    }

    accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    // Convert to g and dps
    data.accel_x = (float)accel_x / ACCEL_SCALE;
    data.accel_y = (float)accel_y / ACCEL_SCALE;
    data.accel_z = (float)accel_z / ACCEL_SCALE;
    data.gyro_x = (float)gyro_x / GYRO_SCALE;
    data.gyro_y = (float)gyro_y / GYRO_SCALE;
    data.gyro_z = (float)gyro_z / GYRO_SCALE;

    return data;
}

// Log data to CSV file
int log_data(imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize IMU
    if (init_imu() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        imu_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

