#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define LED_GPIO 17
#define THRESHOLD 2.0f // g
#define G_PER_COUNT 1024.0f // Counts per g

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_mma8451q();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void control_led(int on);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize MMA8451Q
int init_mma8451q() {
    // Set to active mode, 800 Hz data rate, ±2g range
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full resolution
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    y_raw = (int16_t)((raw_data[2] << 8) | raw_data[3]);
    z_raw = (int16_t)((raw_data[4] << 8) | raw_data[5]);

    // Convert to g units
    *x = (float)x_raw / G_PER_COUNT;
    *y = (float)y_raw / G_PER_COUNT;
    *z = (float)z_raw / G_PER_COUNT;

    return 0;
}

// Calculate magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log data
void log_data(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MMA8451Q
    if (init_mma8451q() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > THRESHOLD) {
                printf("Impact detected! Magnitude: %.3f g\n", magnitude);
                control_led(1); // Turn on LED
                gpioDelay(500);   // Wait 500ms
                control_led(0); // Turn off LED
            }

            // Log data
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

