#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_INT1_CFG 0x2E
#define ADXL345_REG_INT_ENABLE 0x2F
#define GPIO_PIN 17
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE) // microseconds
#define FREEFALL_THRESHOLD 0.3 // g
#define FREEFALL_DURATION 50 // milliseconds

// Global variables
static int i2c_fd = -1;
static int gpio_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_gpio(int pin);
int init_adxl345(int i2c_fd);
int read_adxl345_data(int i2c_fd, accelerometer_data_t *data);
int detect_freefall(int i2c_fd, accelerometer_data_t *data);
int log_data(FILE *fp, accelerometer_data_t data);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int sig);
int write_register(int i2c_fd, uint8_t reg, uint8_t value);
int read_register(int i2c_fd, uint8_t reg, uint8_t *value);

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to initialize GPIO
int init_gpio(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(pin, PI_INPUT);
    gpioSetPullUpDown(pin, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to initialize ADXL345
int init_adxl345(int i2c_fd) {
    // Verify device ID
    uint8_t device_id;
    if (read_register(i2c_fd, ADXL345_REG_ID, &device_id) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }

    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Set to standby mode
    if (write_register(i2c_fd, ADXL345_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error setting standby mode\n");
        return -1;
    }

    // Configure INT1 for single tap detection
    if (write_register(i2c_fd, ADXL345_REG_INT1_CFG, 0x00) != 0) {
        fprintf(stderr, "Error configuring INT1\n");
        return -1;
    }

    // Enable interrupts
    if (write_register(i2c_fd, ADXL345_REG_INT_ENABLE, 0x80) != 0) {
        fprintf(stderr, "Error enabling interrupts\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_adxl345_data(int i2c_fd, accelerometer_data_t *data) {
    uint8_t x0, x1, y0, y1, z0, z1;

    if (read_register(i2c_fd, ADXL345_REG_DATAX0, &x0) != 0) return -1;
    if (read_register(i2c_fd, ADXL345_REG_DATAX1, &x1) != 0) return -1;
    if (read_register(i2c_fd, ADXL345_REG_DATAY0, &y0) != 0) return -1;
    if (read_register(i2c_fd, ADXL345_REG_DATAY1, &y1) != 0) return -1;
    if (read_register(i2c_fd, ADXL345_REG_DATAZ0, &z0) != 0) return -1;
    if (read_register(i2c_fd, ADXL345_REG_DATAZ1, &z1) != 0) return -1;

    data->x = (int16_t)((x1 << 8) | x0);
    data->y = (int16_t)((y1 << 8) | y0);
    data->z = (int16_t)((z1 << 8) | z0);

    return 0;
}

// Function to detect free-fall
int detect_freefall(int i2c_fd, accelerometer_data_t *data) {
    float x = (float)data->x / 256.0; // Convert to g
    float y = (float)data->y / 256.0;
    float z = (float)data->z / 256.0;

    if (x < FREEFALL_THRESHOLD && y < FREEFALL_THRESHOLD && z < FREEFALL_THRESHOLD) {
        return 1; // Free-fall detected
    } else {
        return 0; // Not in free-fall
    }
}

// Function to log data to CSV file
int log_data(FILE *fp, accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    accelerometer_data_t data;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if (read_adxl345_data(i2c_fd, &data) == 0) {
        if (detect_freefall(i2c_fd, &data)) {
            log_data(log_file, data);
        }
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;

    // Disable interrupts
    if (i2c_fd != -1) {
        write_register(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00);
    }

    // Close I2C
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close GPIO
    if (gpio_fd != -1) {
        gpioTerminate();
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Function to write a register
int write_register(int i2c_fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C");
        return -1;
    }
    return 0;
}

// Function to read a register
int read_register(int i2c_fd, uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(i2c_fd, value, 1) != 1) {
        perror("Error reading from I2C");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, ADXL345_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    gpio_fd = init_gpio(GPIO_PIN);
    if (gpio_fd < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    fprintf(stderr, "Free-fall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Poll the I2C bus for data ready
        int poll_result = poll(&gpio_fd, 1, SAMPLE_PERIOD); // Wait for 1ms
        if (poll_result > 0) {
            // Data is ready, process it
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
            if (read_adxl345_data(i2c_fd, &data) == 0) {
                if (detect_freefall(i2c_fd, &data)) {
                    log_data(log_file, data);
                }
            }
        } else if (poll_result < 0) {
            perror("Poll error");
            break;
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

