#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Scaling factors
#define ACCEL_SCALE 0.061 // mg/LSB for ±2g range
#define GYRO_SCALE 8.75  // mdps/LSB for ±250dps range

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2 // g
#define IMPACT_THRESHOLD 2.5   // g
#define IMPACT_WINDOW 1.0     // s

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_lsm6dsr();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

// Function to initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Configure accelerometer: ±2g range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 0x80: 104 Hz, ±2g
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: ±250dps, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 0x80: 104 Hz, ±250dps
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data from the LSM6DSR
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.accel_x = data.accel_y = data.accel_z = 0.0;
        return data;
    }

    raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Read gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0;
        return data;
    }

    raw_gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw data to g and dps
    data.accel_x = (float)raw_accel_x * ACCEL_SCALE / 1000.0;
    data.accel_y = (float)raw_accel_y * ACCEL_SCALE / 1000.0;
    data.accel_z = (float)raw_accel_z * ACCEL_SCALE / 1000.0;
    data.gyro_x = (float)raw_gyro_x * GYRO_SCALE / 1000.0;
    data.gyro_y = (float)raw_gyro_y * GYRO_SCALE / 1000.0;
    data.gyro_z = (float)raw_gyro_z * GYRO_SCALE / 1000.0;

    return data;
}

// Function to log sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to implement fall detection
void fall_detection(sensor_data_t data) {
    static int freefall_count = 0;
    static time_t freefall_start_time = 0;
    static int impact_detected = 0;
    time_t current_time;

    // Check for freefall
    if (fabs(data.accel_x) < FREEFALL_THRESHOLD &&
        fabs(data.accel_y) < FREEFALL_THRESHOLD &&
        fabs(data.accel_z) < FREEFALL_THRESHOLD) {
        freefall_count++;
        if (freefall_count >= (int)(IMPACT_WINDOW * 104 / 1000.0)) {
            freefall_start_time = time(NULL);
            freefall_count = 0; // Reset counter after starting freefall
        }
    } else {
        freefall_count = 0; // Reset counter if acceleration is above threshold
    }

    // Check for impact
    if (fabs(data.accel_x) > IMPACT_THRESHOLD &&
        fabs(data.accel_y) > IMPACT_THRESHOLD &&
        fabs(data.accel_z) > IMPACT_THRESHOLD) {
        if (freefall_count > 0) {
            impact_detected = 1;
        }
    } else {
        impact_detected = 0;
    }

    if (impact_detected) {
        time(&current_time);
        double time_diff = difftime(current_time, freefall_start_time);
        if (time_diff <= IMPACT_WINDOW) {
            printf("Impact detected!\n");
        }
    }
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        fall_detection(data);
        gpioDelay(10000); // 10 ms delay (approx. 104 Hz)
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

