    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer (address + dummy byte)
    tx_buf[0] = (reg_addr << 1) | 1; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

