int spi_write_register(int reg_addr, int data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer (address + data)
    tx_buf[0] = (reg_addr << 1) & ~1; // Clear MSB for write
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

