#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// GY-50 L3G4200D I2C address
#define GYRO_ADDRESS 0x69

// GY-50 L3G4200D WHO_AM_I register address
#define WHO_AM_I_REG 0x0F

// GY-50 L3G4200D angular rate data registers
#define X_RATE_REG 0x28
#define Y_RATE_REG 0x29
#define Z_RATE_REG 0x2A

// Sensitivity of the gyroscope (8.75 mdps/LSB)
#define SENSITIVITY 8.75 / 114.285

// I2C bus number
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    long long timestamp_ns;
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_i2c();
int read_who_am_i();
int read_gyro_data(float *x, float *y, float *z);
void convert_raw_data(int16_t raw_data, float *gyro_rate);
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the WHO_AM_I register
int read_who_am_i() {
    int result = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", result);
        return -1;
    }
    return result;
}

// Function to read raw gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, X_RATE_REG, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read gyro data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    convert_raw_data(raw_x, x);
    convert_raw_data(raw_y, y);
    convert_raw_data(raw_z, z);

    return 0;
}

// Function to convert raw data to angular velocity (mdps)
void convert_raw_data(int16_t raw_data, float *gyro_rate) {
    *gyro_rate = (float)raw_data * SENSITIVITY;
}

// Function to log data to a CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(log_file, "%lld,%.6f,%.6f,%.6f\n", timestamp_ns, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for graceful termination
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = read_who_am_i();
    if (who_am_i != 0x53) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x53, got 0x%x\n", who_am_i);
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    float x, y, z;
    gyro_data_t gyro_data;
    struct timespec sleep_time = {0, 10000000}; // 10 ms

    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            gyro_data.timestamp_ns = time(NULL);
            gyro_data.x = x;
            gyro_data.y = y;
            gyro_data.z = z;
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

