    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    float x, y, z;
    gyro_data_t gyro_data;
    struct timespec sleep_time = {0, 10000000}; // 10 ms

    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            gyro_data.timestamp_ns = time(NULL);
            gyro_data.x = x;
            gyro_data.y = y;
            gyro_data.z = z;
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

