#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log sensor data to a file
void log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen("conveyor_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening conveyor_log.txt for writing\n");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(fp, "%ld,%d,%d\n", milliseconds, sensor1_state, sensor2_state);
    fclose(fp);
}

// Function to halt the conveyor
void halt_conveyor() {
    printf("Conveyor halted!\n");
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    printf("Conveyor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        if (sensor1_state == -1 || sensor2_state == -1) {
            // Error reading sensors, exit loop
            break;
        }

        log_data(sensor1_state, sensor2_state);

        if (sensor1_state == 1 && sensor2_state == 1) {
            halt_conveyor();
        }

        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("Conveyor monitoring stopped.\n");
    return 0;
}

