#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 0.00014  // 0.146 mG/LSB
#define Y_SCALE 0.00014  // 0.146 mG/LSB
#define Z_SCALE 0.00014  // 0.146 mG/LSB

// Metal detector threshold
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lis3mdl();
int read_magnetic_data(int16_t *x, int16_t *y, int16_t *z);
double calibrate_data(int16_t x, int16_t y, int16_t z);
void log_data(double x, double y, double z);
void check_metal_detector(double magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize LIS3MDL sensor
int init_lis3mdl() {
    // Enable continuous measurement mode and set data rate to 10 Hz
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70) < 0) { //0x70 = 0b01110000
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to ±4 gauss
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG3\n");
        return -1;
    }

    return 0;
}

// Read magnetic data from LIS3MDL
int read_magnetic_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L | 0x80, buffer, 6) != 6) { //0x80 for auto-increment
        fprintf(stderr, "Error reading magnetic data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate magnetic data
double calibrate_data(int16_t x, int16_t y, int16_t z) {
    double x_mG = x * X_SCALE;
    double y_mG = y * Y_SCALE;
    double z_mG = z * Z_SCALE;

    return sqrt(x_mG * x_mG + y_mG * y_mG + z_mG * z_mG);
}

// Log data to file
void log_data(double x, double y, double z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(log_file);
}

// Check for metal detector alert
void check_metal_detector(double magnitude) {
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Magnitude: %.2f mG\n", magnitude);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3MDL sensor
    if (init_lis3mdl() < 0) {
        fprintf(stderr, "LIS3MDL initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int retry_count = 0;
    while (!terminate) {
        int16_t x, y, z;
        double magnitude;

        // Read magnetic data
        if (read_magnetic_data(&x, &y, &z) == 0) {
            // Calibrate data
            magnitude = calibrate_data(x, y, z);

            // Log data
            log_data(magnitude, magnitude, magnitude);

            // Check for metal detector alert
            check_metal_detector(magnitude);
        } else {
            fprintf(stderr, "Sensor read failed, retrying initialization...\n");
            retry_count++;
            if (retry_count > 3) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                break;
            }
            i2cClose(i2c_handle);
            gpioTerminate();
            gpioInitialise();
            i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C connection: %d\n", i2c_handle);
                retry_count = 0; // Reset retry count if re-opening fails
                continue;         // Skip to the next iteration
            }
            if (init_lis3mdl() < 0) {
                fprintf(stderr, "LIS3MDL re-initialization failed\n");
                retry_count = 0; // Reset retry count if re-initialization fails
                continue;         // Skip to the next iteration
            }
        }

        gpioDelay(100); // 10 Hz sampling rate
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

