#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADIS16362 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACC_OUT 0x0A
#define Y_ACC_OUT 0x0C
#define Z_ACC_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // degrees/sec per LSB
#define ACCEL_SCALE 0.0025 // g per LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double timestamp;
    double gyro_x;
    double gyro_y;
    double gyro_z;
    double accel_x;
    double accel_y;
    double accel_z;
} imu_data_t;

// Function prototypes
int initialize();
int spi_setup();
int read_register(uint8_t address, uint16_t *data);
int write_register(uint8_t address, uint16_t data);
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }

    return 0;
}

// SPI setup function
int spi_setup() {
    // No specific setup needed with pigpio, just open the SPI channel
    return 0;
}

// Read data from a register
int read_register(uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    spiXfer(spi_handle, tx_buf, rx_buf, 3);

    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// Write data to a register
int write_register(uint8_t address, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address & 0x7F; // Clear MSB for write
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    spiXfer(spi_handle, tx_buf, rx_buf, 3);

    return 0;
}

// Read IMU data
imu_data_t read_imu_data() {
    imu_data_t data;
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    if (read_register(X_GYRO_OUT, &raw_gyro_x) != 0) {
        fprintf(stderr, "Error reading gyro X\n");
        data.gyro_x = 0.0;
    } else {
        data.gyro_x = (double)raw_gyro_x * GYRO_SCALE;
    }

    if (read_register(Y_GYRO_OUT, &raw_gyro_y) != 0) {
        fprintf(stderr, "Error reading gyro Y\n");
        data.gyro_y = 0.0;
    } else {
        data.gyro_y = (double)raw_gyro_y * GYRO_SCALE;
    }

    if (read_register(Z_GYRO_OUT, &raw_gyro_z) != 0) {
        fprintf(stderr, "Error reading gyro Z\n");
        data.gyro_z = 0.0;
    } else {
        data.gyro_z = (double)raw_gyro_z * GYRO_SCALE;
    }

    if (read_register(X_ACC_OUT, &raw_accel_x) != 0) {
        fprintf(stderr, "Error reading accel X\n");
        data.accel_x = 0.0;
    } else {
        data.accel_x = (double)raw_accel_x * ACCEL_SCALE;
    }

    if (read_register(Y_ACC_OUT, &raw_accel_y) != 0) {
        fprintf(stderr, "Error reading accel Y\n");
        data.accel_y = 0.0;
    } else {
        data.accel_y = (double)raw_accel_y * ACCEL_SCALE;
    }

    if (read_register(Z_ACC_OUT, &raw_accel_z) != 0) {
        fprintf(stderr, "Error reading accel Z\n");
        data.accel_z = 0.0;
    } else {
        data.accel_z = (double)raw_accel_z * ACCEL_SCALE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    data.timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    return data;
}

// Log data to file
void log_data(imu_data_t data) {
    fprintf(log_file, "%lf,%lf,%lf,%lf,%lf,%lf,%lf\n",
            data.timestamp,
            data.gyro_x,
            data.gyro_y,
            data.gyro_z,
            data.accel_x,
            data.accel_y,
            data.accel_z);
    fflush(log_file); // Ensure data is written immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("IMU data logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        imu_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(10000); // 10 ms delay (100 Hz sampling rate)
    }

    cleanup();
    return 0;
}

