        data.gyro_y = 0.0;
    } else {
        data.gyro_y = (double)raw_gyro_y * GYRO_SCALE;
    }

    if (read_register(Z_GYRO_OUT, &raw_gyro_z) != 0) {
        fprintf(stderr, "Error reading gyro Z\n");
        data.gyro_z = 0.0;
    } else {
        data.gyro_z = (double)raw_gyro_z * GYRO_SCALE;
    }

    if (read_register(X_ACC_OUT, &raw_accel_x) != 0) {
        fprintf(stderr, "Error reading accel X\n");
        data.accel_x = 0.0;
    } else {
        data.accel_x = (double)raw_accel_x * ACCEL_SCALE;
    }

    if (read_register(Y_ACC_OUT, &raw_accel_y) != 0) {
        fprintf(stderr, "Error reading accel Y\n");
        data.accel_y = 0.0;
    } else {
        data.accel_y = (double)raw_accel_y * ACCEL_SCALE;
    }

    if (read_register(Z_ACC_OUT, &raw_accel_z) != 0) {
        fprintf(stderr, "Error reading accel Z\n");
        data.accel_z = 0.0;
    } else {
        data.accel_z = (double)raw_accel_z * ACCEL_SCALE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    data.timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    return data;
}

// Log data to file
void log_data(imu_data_t data) {
    fprintf(log_file, "%lf,%lf,%lf,%lf,%lf,%lf,%lf\n",
            data.timestamp,
            data.gyro_x,
            data.gyro_y,
            data.gyro_z,
            data.accel_x,
            data.accel_y,
            data.accel_z);
    fflush(log_file); // Ensure data is written immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("IMU data logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        imu_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(10000); // 10 ms delay (100 Hz sampling rate)
    }

    cleanup();
    return 0;
}

