#define GPIO_PIN 17
#define GPIO_CHIP 4
#define DEBOUNCE_DELAY_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO line as input
    gpio_status = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (gpio_status != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %d\n", GPIO_PIN, gpio_status);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Self-parking sequence monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor value
        int sensor_value = gpioRead(GPIO_PIN);

        // Check for obstacle detection (LOW signal)
        if (sensor_value == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Log start of self-parking sequence
            printf("%s Self-parking sequence started\n", timestamp);

            // Simulate self-parking routine (e.g., moving a robotic arm)
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay

            // Log completion of self-parking sequence
            printf("%s Self-parking sequence completed\n", timestamp);
        }

        // Wait for 1 second
        gpioDelay(1000 * 1000); // 1 second delay
    }

    // Clean up GPIO resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

