#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Scale factor (0.02 deg/sec per LSB)
#define SCALE_FACTOR 0.02

// GPIO pin for Chip Select (CS)
#define CS_PIN 8

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_spi();
int initialize_gpio();
int read_register(uint8_t address, uint16_t *data);
gyro_data_t process_data(uint16_t x_raw, uint16_t y_raw, uint16_t z_raw);
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initializes the GPIO pin for Chip Select (CS)
int initialize_gpio() {
    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", CS_PIN);
        return -1;
    }
    gpioWrite(CS_PIN, 1); // Deactivate CS initially
    return 0;
}

// Reads data from a specific register
int read_register(uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer (address + read command)
    tx_buf[0] = address | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Activate CS
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deactivate CS

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract the received data
    *data = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

// Processes raw gyroscope data and applies the scale factor
gyro_data_t process_data(uint16_t x_raw, uint16_t y_raw, uint16_t z_raw) {
    gyro_data_t data;
    data.x = x_raw * SCALE_FACTOR;
    data.y = y_raw * SCALE_FACTOR;
    data.z = z_raw * SCALE_FACTOR;
    return data;
}

// Logs the gyroscope data to the console
void log_data(gyro_data_t data) {
    printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", data.x, data.y, data.z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("ADIS16266 Gyroscope Data Acquisition\n");

    // Main loop
    while (!terminate) {
        uint16_t x_raw, y_raw, z_raw;

        // Read gyroscope data
        if (read_register(XGYRO_OUT, &x_raw) != 0 ||
            read_register(YGYRO_OUT, &y_raw) != 0 ||
            read_register(ZGYRO_OUT, &z_raw) != 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            continue; // Skip to the next iteration
        }

        // Process the data
        gyro_data_t data = process_data(x_raw, y_raw, z_raw);

        // Log the data
        log_data(data);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

