#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_S 5
#define THRESHOLD 5

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main(int argc, char *argv[]) {
    int threshold = THRESHOLD; // Default threshold
    int count = 0;

    // Parse command-line argument
    if (argc > 1) {
        char *endptr;
        threshold = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || threshold < 0) {
            fprintf(stderr, "Error: Invalid threshold value. Using default threshold (%d).\n", THRESHOLD);
            threshold = THRESHOLD;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        for (int i = 0; i < (WINDOW_DURATION_S * 1000) / SAMPLE_INTERVAL_MS; ++i) {
            int level = gpioRead(GPIO_PIN);
            if (level == 1) {
                count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS);
        }

        // Check if the threshold is exceeded
        if (count > threshold) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s ALERT\n", timestamp);
