            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s OK\n", timestamp);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

