#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "access_log.txt"

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
int generate_random_code(char *code);
int read_user_input(char *input);
int validate_code(const char *user_code, const char *generated_code);
int log_access(const char *code);
void signal_handler(int signum);

// GPIO utility functions
int gpio_export(int pin) {
    int fd, ret;
    char buffer[64];

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d", pin);
    ret = write(fd, buffer, strlen(buffer));
    close(fd);
    if (ret < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int gpio_unexport(int pin) {
    int fd, ret;
    char buffer[64];

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d", pin);
    ret = write(fd, buffer, strlen(buffer));
    close(fd);
    if (ret < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    int fd, ret;
    char path[64];

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    ret = write(fd, direction, strlen(direction));
    close(fd);
    if (ret < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

int gpio_write(int pin, int value) {
    int fd, ret;
    char path[64];
    char buffer[2];

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d", value);
    ret = write(fd, buffer, strlen(buffer));
    close(fd);
    if (ret < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

// Security code generation function
int generate_random_code(char *code) {
    int i;
    for (i = 0; i < 6; i++) {
        code[i] = (rand() % 1000000) + 100000;
    }
    return 0;
}

// User input validation function
int read_user_input(char *input) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF) {
        if (c == '\r') c = getchar(); // Consume CR
        if (c == '\b') {
            // Backspace handling
            if (input != NULL && input[0] != '\0') {
                input[0] = '\0';
                return 0; // Clear input
            }
            input = NULL;
            return 0;
        }
        input[strlen(input) + 1] = c;
    }
    input[strlen(input) + 1] = '\0';
    return 0;
}

// Security code validation function
int validate_code(const char *user_code, const char *generated_code) {
    return strcmp(user_code, generated_code) == 0;
}

// Logging function
int log_access(const char *code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%s\n", timestamp, code);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        program_running = 0;
    }
}

int main() {
    int door_a_state, door_b_state;
    char generated_code[6], user_code[6];
    int ret;

    // Seed the random number generator
    srand(time(NULL));

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Export GPIO pins
    if (gpio_export(DOOR_A_PIN) < 0 || gpio_export(DOOR_B_PIN) < 0) {
        fclose(log_file);
        return 1;
    }

    // Set GPIO directions to output
    if (gpio_set_direction(DOOR_A_PIN, "out") < 0 || gpio_set_direction(DOOR_B_PIN, "out") < 0) {
        gpio_unexport(DOOR_A_PIN);
        gpio_unexport(DOOR_B_PIN);
        fclose(log_file);
        return 1;
    }

    // Initialize door states to locked (LOW)
    door_a_state = 0;
    door_b_state = 0;
    gpio_write(DOOR_A_PIN, door_a_state);
    gpio_write(DOOR_B_PIN, door_b_state);

    printf("Door access control system started. Press Enter to unlock Door A and B.\n");

    while (program_running) {
        // Generate a random security code
        if (generate_random_code(generated_code) < 0) {
            fprintf(stderr, "Error generating random code.\n");
            break;
        }

        printf("Generated security code: %s\n", generated_code);

        // Read user input
        if (read_user_input(user_code) < 0) {
            fprintf(stderr, "Error reading user input.\n");
            break;
        }

        // Validate the user input
        if (validate_code(user_code, generated_code) == 0) {
            printf("Correct code! Unlocking doors...\n");

            // Unlock doors for 5 seconds
            gpio_write(DOOR_A_PIN, 1); // Unlock Door A
            gpio_write(DOOR_B_PIN, 1); // Unlock Door B
            sleep(5);
            gpio_write(DOOR_A_PIN, 0); // Lock Door A
            gpio_write(DOOR_B_PIN, 0); // Lock Door B
            printf("Doors locked.\n");

            // Log the access
            if (log_access(generated_code) < 0) {
                fprintf(stderr, "Error logging access.\n");
            }
        } else {
            printf("Incorrect code. Access denied.\n");
        }
    }

    // Cleanup
    gpio_write(DOOR_A_PIN, 0);
    gpio_write(DOOR_B_PIN, 0);
    gpio_unexport(DOOR_A_PIN);
    gpio_unexport(DOOR_B_PIN);
    fclose(log_file);

    printf("Door access control system stopped.\n");

    return 0;
}

