#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MAX_CONVERSION_TIME 180 // milliseconds
#define LOG_FILE "light_log.txt"
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_bh1750(float *lux_value);
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    const char *log_file_name;
    int sleep_duration;
} config_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750 sensor
int read_bh1750(float *lux_value) {
    char config_cmd = CONTINUOUS_HIGH_RES_MODE;
    char buf[2];
    int bytes_read;

    // Send configuration command
    if (i2cWriteByte(i2c_handle, config_cmd) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion (up to MAX_CONVERSION_TIME)
    int start_time = time_time();
    while (time_time() - start_time < MAX_CONVERSION_TIME) {
        if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device\n");
            return -1;
        }
        // Check if the conversion is complete (status bit is 0)
        if (buf[0] == 0x00) {
            break; // Conversion complete
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    if (time_time() - start_time >= MAX_CONVERSION_TIME) {
        fprintf(stderr, "Timeout waiting for sensor data\n");
        return -1;
    }

    // Read the illuminance value
    bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading illuminance data: %d\n", bytes_read);
        return -1;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux_value = (float)raw_value / 1.2; // Convert to Lux

