FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_bh1750(float *lux_value);
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    const char *log_file_name;
    int sleep_duration;
} config_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750 sensor
int read_bh1750(float *lux_value) {
    char config_cmd = CONTINUOUS_HIGH_RES_MODE;
    char buf[2];
    int bytes_read;

    // Send configuration command
    if (i2cWriteByte(i2c_handle, config_cmd) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion (up to MAX_CONVERSION_TIME)
    int start_time = time_time();
    while (time_time() - start_time < MAX_CONVERSION_TIME) {
        if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device\n");
            return -1;
        }
        // Check if the conversion is complete (status bit is 0)
        if (buf[0] == 0x00) {
            break; // Conversion complete
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
