#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_PIN 18
#define PORT 12345
#define SECRET_KEY "MySecretKey"
#define MOTION_DETECTED_PREFIX "MOTION_DETECTED:"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_data(unsigned short *touch_data);
float calculate_frequency(unsigned short touch_data);
int authenticate_message(const char *message);
int play_tone(float frequency);
int log_frequency(float frequency);
void signal_handler(int signal);
void cleanup();

// Function to initialize the MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure Electrode Configuration (ECR) register
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Enable all 12 electrodes
        fprintf(stderr, "Error: Failed to configure ECR: %s\n", strerror(errno));
        return -1;
    }

    // Configure Touch and Release Thresholds (0x41 - 0x5A) - Example values
    for (int i = 0x41; i <= 0x5A; i++) {
        if (i2cWriteByteData(i2c_handle, i, 0x30) < 0) { // Example threshold
            fprintf(stderr, "Error: Failed to configure threshold: %s\n", strerror(errno));
            return -1;
        }
    }

    // Configure Filter Control Register (FCR) (0x5B)
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Enable filter
        fprintf(stderr, "Error: Failed to configure FCR: %s\n", strerror(errno));
        return -1;
    }

    // Configure Electrode Configuration (ECR) register again to enable electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to configure ECR: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read touch data from the MPR121
int read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data: %s\n", strerror(errno));
        return -1;
    }

    *touch_data = ((unsigned short)buf[1] << 8) | (unsigned short)buf[0];
    return 0;
}

// Function to calculate frequency based on touch data
float calculate_frequency(unsigned short touch_data) {
    // Simple example: frequency increases with the number of electrodes touched
    int touched_electrodes = 0;
    for (int i = 0; i < 12; i++) {
        if (touch_data & (1 << i)) {
            touched_electrodes++;
        }
    }

    // Map the number of touched electrodes to a frequency range
    float frequency = 440.0 + (touched_electrodes * 10.0); // Example mapping
    if (frequency > 2000.0) frequency = 2000.0; // Cap the frequency
    return frequency;
}

// Function to authenticate the message
int authenticate_message(const char *message) {
    if (strncmp(message, MOTION_DETECTED_PREFIX, strlen(MOTION_DETECTED_PREFIX)) == 0) {
        if (strstr(message, SECRET_KEY) != NULL) {
            printf("Authentication successful: %s\n", message);
            return 1;
        } else {
            fprintf(stderr, "Authentication failed: Secret key not found in message\n");
            return 0;
        }
    } else {
        fprintf(stderr, "Authentication failed: Incorrect prefix\n");
        return 0;
    }
}

// Function to play a tone using hardware PWM
int play_tone(float frequency) {
    if (frequency < 20.0 || frequency > 2000.0) {
        fprintf(stderr, "Error: Frequency out of range: %f\n", frequency);
        return -1;
    }

    gpioSetPWMfrequency(PWM_PIN, (int)frequency);
    gpioPWM(PWM_PIN, 128); // 50% duty cycle

    time_t start_time = time(NULL);
    while (time(NULL) - start_time < 5 && !terminate) {
        gpioDelay(100); // Check every 100ms
    }

    gpioPWM(PWM_PIN, 0); // Stop PWM
    return 0;
}

// Function to log the frequency to a file
int log_frequency(float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(PWM_PIN, 0); // Stop PWM
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (new_socket >= 0) {
        close(new_socket);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        cleanup();
        return 1;
    }

    // Configure PWM pin
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, 440); // Initial frequency
    gpioPWM(PWM_PIN, 0); // Ensure PWM is off initially

    // Open log file
    log_file = fopen("frequency_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        fprintf(stderr, "Error: Failed to create socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Bind socket to port 12345
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Error: Failed to bind socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Error: Failed to listen on socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Main loop
    while (!terminate) {
        // Accept connection
        int addrlen = sizeof(address);
        new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
        if (new_socket < 0) {
            fprintf(stderr, "Error: Failed to accept connection: %s\n", strerror(errno));
            continue; // Continue listening for other connections
        }

        // Receive message
        char buffer[1024] = {0};
        ssize_t bytes_received = recv(new_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            fprintf(stderr, "Error: Failed to receive message: %s\n", strerror(errno));
            close(new_socket);
            continue;
        }
        buffer[bytes_received] = '\0';

        // Authenticate message
        if (authenticate_message(buffer)) {
            // Read touch data
            unsigned short touch_data;
            if (read_touch_data(&touch_data) == 0) {
                // Calculate frequency
                float frequency = calculate_frequency(touch_data);

                // Log frequency
                log_frequency(frequency);

                // Play tone
                if (play_tone(frequency) != 0) {
                    fprintf(stderr, "Error: Failed to play tone\n");
                }
            } else {
                fprintf(stderr, "Error: Failed to read touch data\n");
            }
        } else {
            fprintf(stderr, "Authentication failed, not playing tone\n");
        }

        // Receive more messages
        while (!terminate && (bytes_received = recv(new_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
            buffer[bytes_received] = '\0';
            if (authenticate_message(buffer)) {
                // Read touch data
                unsigned short touch_data;
                if (read_touch_data(&touch_data) == 0) {
                    // Calculate frequency
                    float frequency = calculate_frequency(touch_data);

                    // Log frequency
                    log_frequency(frequency);

                    // Play tone
                    if (play_tone(frequency) != 0) {
                        fprintf(stderr, "Error: Failed to play tone\n");
                    }
                } else {
                    fprintf(stderr, "Error: Failed to read touch data\n");
                }
            } else {
                fprintf(stderr, "Authentication failed, not playing tone\n");
            }
        }

        if (bytes_received < 0) {
            fprintf(stderr, "Error: Failed to receive message: %s\n", strerror(errno));
        }

        close(new_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

