#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define CRA_REG_M 0x00
#define CRB_REG_M 0x01
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// GPIO pin for LED (BCM numbering)
#define LED_PIN 17

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_magnetometer();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_z_magnitude(int16_t z);
void set_led_brightness(float z_magnitude);
void signal_handler(int signal);
void log_error(const char *message);

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function to initialize the magnetometer
int initialize_magnetometer() {
    // Configure CRA_REG_M (0x00) for continuous conversion mode
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x18) < 0) { // 0x18 = 1100 0010
        log_error("Failed to write to CRA_REG_M");
        return -1;
    }

    // Configure CRB_REG_M (0x01) for +/- 1.3 Gauss full scale
    if (i2cWriteByteData(i2c_handle, CRB_REG_M, 0x20) < 0) { // 0x20 = 0010 0000
        log_error("Failed to write to CRB_REG_M");
        return -1;
    }

    // Configure MR_REG_M (0x02) for continuous conversion mode
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) { // 0x00 = 0000 0000
        log_error("Failed to write to MR_REG_M");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        log_error("Failed to read magnetometer data");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate Z-axis magnitude
float calculate_z_magnitude(int16_t z) {
    return (float)z;
}

// Function to set LED brightness using hardware PWM
void set_led_brightness(float z_magnitude) {
    // Map Z-axis magnitude (0-65535) to PWM duty cycle (0-1000000)
    int duty_cycle = (int)((z_magnitude / 65535.0) * 1000000.0);

    // Set PWM duty cycle
    gpioPWM(LED_PIN, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("magnetometer_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (initialize_magnetometer() < 0) {
        log_error("Magnetometer initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_PIN, PWM_FREQUENCY);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float z_magnitude;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Calculate Z-axis magnitude
            z_magnitude = calculate_z_magnitude(z);

            // Set LED brightness
            set_led_brightness(z_magnitude);

            // Log data
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[26];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

            fprintf(log_file, "[%s] X: %d, Y: %d, Z: %d, Z Magnitude: %.2f\n", timestamp, x, y, z, z_magnitude);
            fflush(log_file);
        } else {
            log_error("Failed to read magnetometer data");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

