#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L
int initialize_hmc5883l(int i2c_handle) {
    // Configure register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_A\n");
        return -1;
    }

    // Configure register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_MODE\n");
        return -1;
    }

    return 0;
}

// Function to read raw magnetometer data
magnetometer_data_t read_magnetometer_data(int i2c_handle) {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return 0s on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to calculate the running average of magnetometer data
void calculate_running_average(int *average_x, int *average_y, int *average_z, int *index, int *num_samples, magnetometer_data_t data) {
    static int sample_count = 0;
    static int last_index = 0;
    static int num_samples_initialized = 0;

    if (num_samples_initialized == 0) {
        *average_x = 0;
        *average_y = 0;
        *average_z = 0;
        *index = 0;
        *num_samples = 100;
        sample_count = 0;
        return;
    }

    sample_count++;

    if (sample_count >= *num_samples) {
        *index = (*index + 1) % *num_samples;
        *average_x = (*average_x * (*num_samples - 1)) + data.x;
        *average_y = (*average_y * (*num_samples - 1)) + data.y;
        *average_z = (*average_z * (*num_samples - 1)) + data.z;
        *num_samples = *num_samples + 1;
    } else {
        *index = (last_index + 1) % *num_samples;
        *average_x = (*average_x * (*num_samples - 1)) + data.x;
        *average_y = (*average_y * (*num_samples - 1)) + data.y;
        *average_z = (*average_z * (*num_samples - 1)) + data.z;
    }

    last_index = *index;
}

// Function to apply hard-iron offsets
magnetometer_data_t apply_hard_iron_offsets(magnetometer_data_t data, int average_x, int average_y, int average_z) {
    magnetometer_data_t offset_corrected_data;

    offset_corrected_data.x = data.x - average_x;
    offset_corrected_data.y = data.y - average_y;
    offset_corrected_data.z = data.z - average_z;

    return offset_corrected_data;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int average_x = 0, average_y = 0, average_z = 0;
    int index = 0;
    int num_samples = 100;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data(i2c_handle);

        // Calculate running average
        calculate_running_average(&average_x, &average_y, &average_z, &index, &num_samples, raw_data);

        // Apply hard-iron offsets
        magnetometer_data_t offset_corrected_data = apply_hard_iron_offsets(raw_data, average_x, average_y, average_z);

        // Print offset-corrected data
        printf("X: %d, Y: %d, Z: %d\n", offset_corrected_data.x, offset_corrected_data.y, offset_corrected_data.z);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

