magnetometer_data_t apply_hard_iron_offsets(magnetometer_data_t data, int average_x, int average_y, int average_z) {
    magnetometer_data_t offset_corrected_data;

    offset_corrected_data.x = data.x - average_x;
    offset_corrected_data.y = data.y - average_y;
    offset_corrected_data.z = data.z - average_z;

    return offset_corrected_data;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int average_x = 0, average_y = 0, average_z = 0;
    int index = 0;
    int num_samples = 100;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data(i2c_handle);

        // Calculate running average
        calculate_running_average(&average_x, &average_y, &average_z, &index, &num_samples, raw_data);

        // Apply hard-iron offsets
        magnetometer_data_t offset_corrected_data = apply_hard_iron_offsets(raw_data, average_x, average_y, average_z);

        // Print offset-corrected data
        printf("X: %d, Y: %d, Z: %d\n", offset_corrected_data.x, offset_corrected_data.y, offset_corrected_data.z);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

