#include <unistd.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define LSM303D_ID_REG 0x00
#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_CTRL_REG4_A 0x23
#define LSM303D_OUT_X_L_A 0x28

// GPIO pin for interrupt
#define INT_PIN 23

// Acceleration sensitivity (mg/LSB)
#define ACCEL_SENSITIVITY 0.061

// Interrupt threshold (mg)
#define INT_THRESHOLD 2000.0

// Circular buffer size
#define BUFFER_SIZE 64

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Circular buffer
accelerometer_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int verify_device_id();
int configure_accelerometer();
accelerometer_data_t read_acceleration();
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void dump_buffer();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0); // Bus 1, address 0x1D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to verify the device ID
int verify_device_id() {
    int id = i2cReadByteData(i2c_handle, LSM303D_ID_REG);
    if (id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", id);
        return -1;
    }
    if (id != 0x33) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", id);
        return -1;
    }
    printf("LSM303D device ID verified: 0x%02X\n", id);
    return 0;
}

// Function to configure the accelerometer
int configure_accelerometer() {
    // Enable accelerometer, 50 Hz data rate, +/- 2g range
    if (i2cWriteByteData(i2c_handle, LSM303D_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // Set interrupt threshold and duration
    if (i2cWriteByteData(i2c_handle, LSM303D_CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
accelerometer_data_t read_acceleration() {
    accelerometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LSM303D_OUT_X_L_A, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    // This function is called when the interrupt pin goes high
    // In this case, we just print a message to the console
    printf("Interrupt triggered!\n");
}

// Function to dump the circular buffer
void dump_buffer() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s ", timestamp);
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - BUFFER_SIZE + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("X: %6d, Y: %6d, Z: %6d ", buffer[index].x, buffer[index].y, buffer[index].z);
    }
    printf("\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure accelerometer
    if (configure_accelerometer() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set interrupt pin as input
    gpioSetMode(INT_PIN, PI_INPUT);
    gpioSetPullUpDown(INT_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set interrupt handler
    gpioSetISRFuncEx(INT_PIN, RISING_EDGE, 0, interrupt_handler, NULL);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        accelerometer_data_t accel_data = read_acceleration();

        // Store data in circular buffer
        buffer[buffer_index] = accel_data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Dump buffer on interrupt
        if (gpioRead(INT_PIN) == 1) {
            dump_buffer();
        }

        // Delay for 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Disable accelerometer
    i2cWriteByteData(i2c_handle, LSM303D_CTRL_REG1_A, 0x00); // Disable accelerometer

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

