#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a solenoid
int set_solenoid_state(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %d\n", gpio_pin, state, result);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    // Ensure both solenoids are initially off
    if (set_solenoid_state(SOLENOID_1_PIN, 0) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_solenoid_state(SOLENOID_2_PIN, 0) != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to alternate solenoid activation
    while (program_running) {
        // Activate solenoid 1
        if (set_solenoid_state(SOLENOID_1_PIN, 1) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        nanosleep((const struct timespec[]){{0, 500000000L}}, NULL); // 500ms

        // Deactivate solenoid 1 and activate solenoid 2
        if (set_solenoid_state(SOLENOID_1_PIN, 0) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        nanosleep((const struct timespec[]){{0, 500000000L}}, NULL); // 500ms

        // Deactivate solenoid 2 and activate solenoid 1
        if (set_solenoid_state(SOLENOID_2_PIN, 0) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        nanosleep((const struct timespec[]){{0, 500000000L}}, NULL); // 500ms
    }

    // Clean up and exit
    fprintf(stderr, "Cleaning up GPIO and exiting...\n");
    set_solenoid_state(SOLENOID_1_PIN, 0); // Ensure both solenoids are off
    set_solenoid_state(SOLENOID_2_PIN, 0);
    gpioTerminate();

    return 0;
}

