#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 27

// Define UART ports
#define UART_PORT1 "/dev/serial0"
#define UART_PORT2 "/dev/serial1"

// Define the expected code
const char *EXPECTED_CODE = "123456";

// Define the timeout duration (in seconds)
#define TIMEOUT_DURATION 5

// Global variables for UART file descriptors and GPIO handles
int uart_fd1 = -1;
int uart_fd2 = -1;
int gpio_handle1 = -1;
int gpio_handle2 = -1;

// Function prototypes
int initialize_uart(const char *port);
int read_uart_data(int fd, char *buffer, int max_len);
int validate_code(const char *code);
int control_relay(int gpio, int state);
int compare_codes(const char *code1, const char *code2);
void cleanup(int signal);
void log_error(const char *message);

// Signal handler function
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close UART ports
    if (uart_fd1 != -1) close(uart_fd1);
    if (uart_fd2 != -1) close(uart_fd2);

    // Set relays LOW (locked)
    control_relay(RELAY1_GPIO, 0);
    control_relay(RELAY2_GPIO, 0);

    // Close GPIO handles
    if (gpio_handle1 != -1) gpioTerminate();
    if (gpio_handle2 != -1) gpioTerminate();

    exit(0);
}

// Function to initialize UART port
int initialize_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    // Configure UART
    tty.c_cflag = B9600 | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                       // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                            // Non-canonical mode
    tty.c_cc[VMIN] = 0;                          // Read doesn't block
    tty.c_cc[VTIME] = 5;                         // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from UART port
int read_uart_data(int fd, char *buffer, int max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len - 1);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return (int)bytes_read;
    }
}

// Function to validate the received code
int validate_code(const char *code) {
    return (strcmp(code, EXPECTED_CODE) == 0);
}

// Function to control the relay
int control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to compare the received codes
int compare_codes(const char *code1, const char *code2) {
    return (strcmp(code1, code2) == 0);
}

// Function to log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize UART ports
    uart_fd1 = initialize_uart(UART_PORT1);
    if (uart_fd1 == -1) {
        gpioTerminate();
        return 1;
    }

    uart_fd2 = initialize_uart(UART_PORT2);
    if (uart_fd2 == -1) {
