#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define MOTION_DEBOUNCE_TIME 10 // seconds
#define RELAY_ON_TIME 1          // seconds
#define RELAY_OFF_TIME 1         // seconds
#define LOG_FILE "/var/log/motion_monitor.log"

// Global variables
static volatile int running = 1;
static int relay_fd = -1;
static int log_fd = -1;

// Function prototypes
int gpio_init(int pir_pin, int relay_pin);
int gpio_set_mode(int pin, int mode);
int gpio_read(int pin);
int gpio_write(int pin, int value);
int log_event(int priority, const char *message);
int relay_on(int relay_pin);
int relay_off(int relay_pin);
int motion_detected(int pir_pin);
int check_motion_debounce(int pir_pin, int last_motion_time);
int failsafe(int pir_pin);
void signal_handler(int signal);
int gpio_close(int pir_pin, int relay_pin);
int log_close(int log_fd);

// Function to initialize GPIO
int gpio_init(int pir_pin, int relay_pin) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(pir_pin, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set PIR pin mode");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(relay_pin, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay pin mode");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to set GPIO mode
int gpio_set_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode for pin %d", pin);
        return -1;
    }
    return 0;
}

// Function to read GPIO value
int gpio_read(int pin) {
    return gpioRead(pin);
}

// Function to write GPIO value
int gpio_write(int pin, int value) {
    if (gpioWrite(pin, value) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO value for pin %d", pin);
        return -1;
    }
    return 0;
}

// Function to log events
int log_event(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fd == -1) {
        syslog(LOG_ERR, "Log file not opened");
        return -1;
    }

    dprintf(log_fd, "%s: %s (Priority: %d)\n", timestamp, message, priority);
    fsync(log_fd);
    return 0;
}

// Function to turn relay on
int relay_on(int relay_pin) {
    if (gpio_write(relay_pin, 1) != 0) {
        syslog(LOG_ERR, "Failed to turn relay on");
        return -1;
    }
    return 0;
}

// Function to turn relay off
int relay_off(int relay_pin) {
    if (gpio_write(relay_pin, 0) != 0) {
        syslog(LOG_ERR, "Failed to turn relay off");
        return -1;
    }
    return 0;
}

// Function to check for motion detection
int motion_detected(int pir_pin) {
    return gpio_read(pir_pin);
}

// Function to check motion debounce
int check_motion_debounce(int pir_pin, int last_motion_time) {
    int current_time = time(NULL);
    if (difftime(current_time, last_motion_time) < MOTION_DEBOUNCE_TIME) {
        return 0; // Debounced
    }
    return 1; // Not debounced
}

// Function to trigger failsafe
int failsafe(int pir_pin) {
    syslog(LOG_WARNING, "Failsafe triggered: PIR signal HIGH for %d seconds", MOTION_DEBOUNCE_TIME);
    relay_off(RELAY_PIN);
    log_event(LOG_WARNING, "Failsafe triggered");
    log_event(LOG_EMERG, "System shutdown");
    running = 0; // Stop the main loop
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Function to close GPIO
int gpio_close(int pir_pin, int relay_pin) {
    if (relay_fd != -1) {
        close(relay_fd);
    }
    if (log_fd != -1) {
        log_close(log_fd);
    }
    gpioTerminate();
    return 0;
}

// Function to close log file
int log_close(int log_fd) {
    if (log_fd != -1) {
        close(log_fd);
    }
    return 0;
}

int main() {
    // Open syslog
    openlog("motion_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(PIR_PIN, RELAY_PIN) != 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        closelog();
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        syslog(LOG_ERR, "Failed to open log file");
        gpio_close(PIR_PIN, RELAY_PIN);
        closelog();
        return 1;
    }

    // Initialize last motion time
    time_t last_motion_time = time(NULL);

    // Main loop
    while (running) {
        int pir_value = motion_detected(PIR_PIN);
        time_t current_time = time(NULL);

        if (pir_value == 1) {
            if (!check_motion_debounce(PIR_PIN, last_motion_time)) {
                syslog(LOG_INFO, "Motion detected!");
                relay_on(RELAY_PIN);
                log_event(LOG_INFO, "Relay turned ON");
                sleep(RELAY_ON_TIME);
                relay_off(RELAY_PIN);
                log_event(LOG_INFO, "Relay turned OFF");
                last_motion_time = current_time;
            } else {
                failsafe(PIR_PIN);
            }
        } else {
            last_motion_time = current_time;
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Clean up
    gpio_close(PIR_PIN, RELAY_PIN);
    log_close(log_fd);
    closelog();

    return 0;
}

