// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the state machine states
enum {
    STATE_IDLE,
    STATE_RELAY1,
    STATE_RELAY2,
    STATE_RELAY3,
    STATE_RELAY4,
    STATE_PAUSE
};

// Define the state machine transitions
enum {
    TRANSITION_RELAY1_TO_RELAY2,
    TRANSITION_RELAY2_TO_RELAY3,
    TRANSITION_RELAY3_TO_RELAY4,
    TRANSITION_RELAY4_TO_IDLE,
    TRANSITION_IDLE_TO_RELAY1
};

// Define the state machine table
const enum {
    // Idle -> Relay 1
    {STATE_IDLE, TRANSITION_IDLE_TO_RELAY1, STATE_RELAY1},
    // Relay 1 -> Relay 2
    {STATE_RELAY1, TRANSITION_RELAY1_TO_RELAY2, STATE_RELAY2},
    // Relay 2 -> Relay 3
    {STATE_RELAY2, TRANSITION_RELAY2_TO_RELAY3, STATE_RELAY3},
