#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_CONFIG 0x1C

// Scaling factor for accelerometer data
#define ACCEL_SCALE 16384.0f // Sensitivity scale factor for +/- 2g range

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Structure to hold the circular buffer
typedef struct {
    accelerometer_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd;
circular_buffer_t buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_accelerometer_data(int fd, accelerometer_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, accelerometer_data_t data);
accelerometer_data_t get_latest_sample(circular_buffer_t *buffer);
int create_driver_interface(const char *interface_path);
void signal_handler(int signal);
void cleanup();

// I2C read function
int i2c_read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// I2C write function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Read accelerometer data function
int read_accelerometer_data(int fd, accelerometer_data_t *data) {
    int16_t x, y, z;

    x = (int16_t)((i2c_read_register(fd, ACCEL_XOUT_H) << 8) | i2c_read_register(fd, ACCEL_XOUT_H + 1));
    y = (int16_t)((i2c_read_register(fd, ACCEL_YOUT_H) << 8) | i2c_read_register(fd, ACCEL_YOUT_H + 1));
    z = (int16_t)((i2c_read_register(fd, ACCEL_ZOUT_H) << 8) | i2c_read_register(fd, ACCEL_ZOUT_H + 1));

    data->x = (int16_t)((i2c_read_register(fd, ACCEL_XOUT_H) << 8) | i2c_read_register(fd, ACCEL_XOUT_H + 1));
    data->y = (int16_t)((i2c_read_register(fd, ACCEL_YOUT_H) << 8) | i2c_read_register(fd, ACCEL_YOUT_H + 1));
    data->z = (int16_t)((i2c_read_register(fd, ACCEL_ZOUT_H) << 8) | i2c_read_register(fd, ACCEL_ZOUT_H + 1));

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, accelerometer_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Get the latest sample from the circular buffer
accelerometer_data_t get_latest_sample(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        accelerometer_data_t zero_data = {0, 0, 0};
        return zero_data;
    }
    int index = (buffer->tail + BUFFER_SIZE - 1) % BUFFER_SIZE;
    return buffer->data[index];
}

// Create the driver interface
int create_driver_interface(const char *interface_path) {
    FILE *fp = fopen(interface_path, "w");
    if (fp == NULL) {
        perror("Failed to open driver interface file");
        return -1;
    }

    fprintf(fp, "latest: int16_t,int16_t,int16_t\n");
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    close(i2c_fd);
    if (create_driver_interface("/sys/kernel/mpu6050_accel/latest") != 0) {
        fprintf(stderr, "Failed to create driver interface on exit.\n");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050 (wake up sensor)
    if (i2c_write_register(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050.\n");
        cleanup();
        return 1;
    }

    // Configure accelerometer range (+/- 2g)
    if (i2c_write_register(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure accelerometer range.\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;

    // Create driver interface
    if (create_driver_interface("/sys/kernel/mpu6050_accel/latest") != 0) {
        fprintf(stderr, "Failed to create driver interface.\n");
        cleanup();
        return 1;
    }

    // Main loop
    struct sigaction sa;
    struct itimerval timer;
    struct timespec ts;
    accelerometer_data_t data;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGALRM, &sa, NULL) == -1) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    timer.it_value.tv_sec = 0;
    timer.it_value.tv_usec = 10000; // 10ms
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = 10000; // 10ms

    // Set up signal handling for SIGALRM
    if (signal(SIGALRM, signal_handler) == SIG_ERR) {
        perror("signal");
        cleanup();
        return 1;
    }

    // Set up timer
    if (setitimer(ITIMER_REAL, &timer, NULL) == -1) {
        perror("setitimer");
        cleanup();
        return 1;
    }

    printf("MPU6050 data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (read_accelerometer_data(i2c_fd, &data) == 0) {
            add_to_buffer(&buffer, data);
            // In a distributed system, this is where you would send the data
            // to a remote server or store it in a database.
            // For this example, we just print the data.
            printf("X: %d, Y: %d, Z: %d\n", data.x, data.y, data.z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

