// Define the prime number intervals in seconds
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize a GPIO pin as output
int initialize_gpio(int gpio) {
    int result = gpioSetMode(gpio, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to turn a relay ON
int turn_relay_on(int gpio) {
    int result = gpioWrite(gpio, 1);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to turn a relay OFF
int turn_relay_off(int gpio) {
    int result = gpioWrite(gpio, 0);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to toggle a relay
int toggle_relay(int gpio) {
    int current_state = gpioRead(gpio);
    if (current_state != 0 && current_state != 1) {
        fprintf(stderr, "Error: Invalid GPIO state for GPIO %d\n", gpio);
        return -1;
    }
    int new_state = (current_state == 0) ? 1 : 0;
    int result = gpioWrite(gpio, new_state);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %d\n", gpio, new_state, result);
        return -1;
    }
    return 0;
}

// Function to toggle a relay after a specified interval
int toggle_relay_after_interval(int gpio, int interval) {
    struct timespec ts;
    ts.tv_sec = interval;
    ts.tv_nsec = 0; // No nanoseconds

    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    if (toggle_relay(gpio) != 0) {
        return -1;
    }

    // Wait for the interval to pass
    while (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        if (ts.tv_sec != interval) {
            fprintf(stderr, "Timeout waiting for interval %d\n", interval);
            return -1;
        }
    }

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio(RELAY1_GPIO) != 0 ||
        initialize_gpio(RELAY2_GPIO) != 0 ||
        initialize_gpio(RELAY3_GPIO) != 0 ||
        initialize_gpio(RELAY4_GPIO) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Toggle relays in sequence
        if (toggle_relay_after_interval(RELAY1_GPIO, INTERVAL1) != 0) {
            fprintf(stderr, "Error toggling relay 1\n");
        }
        if (toggle_relay_after_interval(RELAY2_GPIO, INTERVAL2) != 0) {
            fprintf(stderr, "Error toggling relay 2\n");
        }
        if (toggle_relay_after_interval(RELAY3_GPIO, INTERVAL3) != 0) {
            fprintf(stderr, "Error toggling relay 3\n");
        }
        if (toggle_relay_after_interval(RELAY4_GPIO, INTERVAL4) != 0) {
            fprintf(stderr, "Error toggling relay 4\n");
        }

        // Small delay to prevent busy-waiting
        usleep(10000); // 10ms
    }

    // Turn off all relays before exiting
    turn_relay_off(RELAY1_GPIO);
    turn_relay_off(RELAY2_GPIO);
    turn_relay_off(RELAY3_GPIO);
    turn_relay_off(RELAY4_GPIO);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

