#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define relay activation time in seconds
#define RELAY_ACTIVATION_TIME 3

// Global variables
static volatile int running = 1;
static volatile int relay_active = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay();
int log_event();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay
int activate_relay() {
    if (relay_active) {
        fprintf(stderr, "Relay already active, skipping activation.\n");
        return 1;
    }

    gpioWrite(RELAY_PIN, 1); // Activate relay
    relay_active = 1;
    printf("Relay activated.\n");
    return 0;
}

// Log event to file
int log_event() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: Relay activated\n", timestamp);
    fclose(fp);
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up GPIO and exiting...\n");
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound-activated relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sound sensor
        int sound_detected = read_sound_sensor();

        // Debounce
        gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to us

        if (sound_detected) {
            // Check if relay is already active
            if (!relay_active) {
                // Activate relay
                if (activate_relay() == 0) {
                    // Log event
                    if (log_event() != 0) {
                        fprintf(stderr, "Error logging event.\n");
                    }
                } else {
                    fprintf(stderr, "Error activating relay.\n");
                }
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(100 * 1000); // 100ms
    }

    cleanup();
    return 0;
}

