#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity scale factor for gyroscope
#define GYRO_SCALE 131.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_gyro_data(gyro_data_t *data);
float calculate_magnitude(gyro_data_t data);
void buffer_add(circular_buffer_t *buffer, gyro_data_t data);
int buffer_is_full(const circular_buffer_t *buffer);
void callback(int magnitude);
void signal_handler(int signal);

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1\n");
        return -1;
    }

    // Configure gyroscope sensitivity (optional, default is 250 dps)
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0) < 0) {
        fprintf(stderr, "Failed to write to GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Failed to read gyro data\n");
        return -1;
    }

    // Combine high and low bytes, and convert to degrees/second
    int16_t x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z = (int16_t)((buf[4] << 8) | buf[5]);

    data->x = (float)x / GYRO_SCALE;
    data->y = (float)y / GYRO_SCALE;
    data->z = (float)z / GYRO_SCALE;

    return 0;
}

// Calculate the magnitude of the angular velocity vector
float calculate_magnitude(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Add data to the circular buffer
void buffer_add(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Check if the circular buffer is full
int buffer_is_full(const circular_buffer_t *buffer) {
    return buffer->count == BUFFER_SIZE;
}

// Callback function to handle magnitude exceeding threshold
void callback(int magnitude) {
    printf("Magnitude exceeded threshold: %f\n", magnitude);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Exiting gracefully...\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    // Set up callback function
    gpioSetAlertFuncEx(0, callback, NULL);

    gyro_data_t gyro_data;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Add data to circular buffer
            buffer_add(&gyro_buffer, gyro_data);

            // Calculate magnitude
            float magnitude = calculate_magnitude(gyro_data);

            // Check if magnitude exceeds threshold
            if (magnitude > 50.0f) {
                // Invoke callback
                callback(magnitude);
            }
        } else {
            fprintf(stderr, "Error reading gyro data. Re-initializing...\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            if (init_i2c() < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                program_running = 0;
            }
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Failed to re-initialize MPU-6050. Exiting.\n");
                program_running = 0;
            }
        }

        // Delay
        gpioDelay(10); // 10 ms delay
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

