#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

// Define UART device and baud rate
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600

// Define GPIO pins for TXD and RXD
#define TXD_PIN 14 // GPIO14 (BCM)
#define RXD_PIN 15 // GPIO15 (BCM)

// Define MH-Z19B command sequence
const unsigned char command_sequence[] = {0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};

// Define CO2 error log file
#define CO2_ERROR_LOG "co2_error.log"

// Global variables
int uart_fd = -1;
FILE *co2_log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    long timestamp;
    float ppm;
    int error;
} sensor_data_t;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int send_command(int fd, const unsigned char *command, int command_len);
int receive_data(int fd, unsigned char *buffer, int buffer_len);
int parse_sensor_data(const unsigned char *data, int data_len, sensor_data_t *sensor_data);
int validate_checksum(const unsigned char *data, int data_len);
int log_data(const sensor_data_t *sensor_data);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                                // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Send command to the sensor
int send_command(int fd, const unsigned char *command, int command_len) {
    int bytes_written = write(fd, command, command_len);
    if (bytes_written != command_len) {
        fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Receive data from the sensor
int receive_data(int fd, unsigned char *buffer, int buffer_len) {
    ssize_t bytes_read = read(fd, buffer, buffer_len);
    if (bytes_read == -1) {
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1;
    } else if (bytes_read == 0) {
        // Timeout occurred
        return 0;
    }
    return bytes_read;
}

// Parse sensor data
int parse_sensor_data(const unsigned char *data, int data_len, sensor_data_t *sensor_data) {
    if (data_len != 9) {
        fprintf(stderr, "Error: Invalid data length: %d\n", data_len);
        return -1;
    }

    // Extract timestamp (microseconds)
    sensor_data->timestamp = (long)data[0] * 1000 + (long)data[1];

    // Extract ppm value
    sensor_data->ppm = (float)((long)data[2] * 256 + (long)data[3]);

    // Extract error flag
    sensor_data->error = (data[6] == 0) ? 0 : 1; // 0: no error, 1: error

    return 0;
}

// Validate checksum
int validate_checksum(const unsigned char *data, int data_len) {
    unsigned char checksum = 0;
    for (int i = 0; i < data_len - 1; i++) {
        checksum += data[i];
    }
    checksum = 0xFF - checksum + 1;

    if (checksum != data[data_len - 1]) {
        fprintf(stderr, "Error: Checksum mismatch\n");
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(const sensor_data_t *sensor_data) {
    char json_string[100];
    snprintf(json_string, sizeof(json_string), "{\"timestamp\":%ld,\"ppm\":%.2f,\"error\":%d}", sensor_data->timestamp, sensor_data->ppm, sensor_data->error);

    if (fprintf(co2_log_file, "%s\n", json_string) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(co2_log_file); // Ensure data is written to disk
    return 0;
}

// Log error to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    if (uart_fd != -1) {
        close(uart_fd);
    }

    if (co2_log_file != NULL) {
        fclose(co2_log_file);
    }

    if (error_log_file != NULL) {
        fclose(error_log_file);
    }

    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TXD_PIN, PI_OUTPUT);
    gpioSetMode(RXD_PIN, PI_INPUT);

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log files
    co2_log_file = fopen("co2_log.json", "a");
    if (co2_log_file == NULL) {
        perror("Error opening co2_log.json");
        cleanup();
        return 1;
    }

    error_log_file = fopen(CO2_ERROR_LOG, "a");
    if (error_log_file == NULL) {
        perror("Error opening co2_error.log");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char data[9];
        int bytes_read = 0;
        int retry_count = 0;
        int timeout_seconds = 1;

        // Send command
        if (send_command(uart_fd, command_sequence, sizeof(command_sequence)) != 0) {
            log_error("Failed to send command");
            sleep(5);
            continue;
        }

        // Receive data with retry and timeout
        while (bytes_read < 9 && retry_count < timeout_seconds * 100) {
            int bytes_available = 0;
            int timeout = 100; // 100ms timeout
            while (bytes_available < 1 && timeout > 0) {
                bytes_available = receive_data(uart_fd, data + bytes_read, 1);
                if (bytes_available == -1) {
                    log_error("Failed to receive data");
                    break;
                }
                timeout--;
                gpioDelay(1); // Small delay to avoid busy-waiting
            }

            if (bytes_available == 1) {
                bytes_read++;
            } else {
                log_error("Timeout receiving data");
                break;
            }
        }

        if (bytes_read != 9) {
            log_error("Failed to receive complete data");
            sleep(5);
            continue;
        }

        // Validate checksum
        if (validate_checksum(data, 9) != 0) {
            log_error("Checksum validation failed");
            sleep(5);
            continue;
        }

        // Parse sensor data
        sensor_data_t sensor_data;
        if (parse_sensor_data(data, 9, &sensor_data) != 0) {
            log_error("Failed to parse sensor data");
            sleep(5);
            continue;
        }

        // Log data
        if (log_data(&sensor_data) != 0) {
            log_error("Failed to log data");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

