#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for output
#define GPIO_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Heading deviation threshold
#define HEADING_THRESHOLD 10.0

// Circular buffer size
#define BUFFER_SIZE 100

// Hard-iron compensation offsets
#define X_OFFSET 100
#define Y_OFFSET -50

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer heading_buffer;

// Function prototypes
int initialize_i2c();
int configure_hmc5883l();
int read_hmc5883l(float *x, float *y, float *z);
float hard_iron_compensation(float x, float y);
void add_to_buffer(CircularBuffer *buffer, float value);
float get_latest_value(CircularBuffer *buffer);
bool check_deviation(float current_heading, float target_heading);
void set_gpio_output(bool high);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *buffer, float value) {
    buffer->buffer[buffer->head] = value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get the latest value from the circular buffer
float get_latest_value(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return NAN; // Return NaN if the buffer is empty
    }
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->buffer[index];
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_fd = wiringPiI2CSetup(HMC5883L_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Configure the HMC5883L
int configure_hmc5883l() {
    // Configuration register A: 8-average, 15 Hz, normal measurement
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_CONFIG_A, 0x70) == -1) {
        fprintf(stderr, "Error writing to config register A: %s\n", strerror(errno));
        return -1;
    }

    // Configuration register B: Gain = 1.3 Ga
