#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LUX_THRESHOLD_RED 50
#define LUX_THRESHOLD_GREEN 150
#define LUX_THRESHOLD_BLUE 300
#define LUX_THRESHOLD_ALL 300
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_lux();
void control_lamps(float lux);
void log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);

// Structure for GPIO pin configuration
typedef struct {
    int red_pin;
    int green_pin;
    int blue_pin;
} gpio_config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750
float read_lux() {
    unsigned char data[2];
    int result;

    for (int i = 0; i < I2C_RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, data, 2);
        if (result == 2) {
            unsigned int raw_value = (data[0] << 8) | data[1];
            return (float)raw_value / 1.2;
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", i + 1, result);
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read lux after %d retries.\n", I2C_RETRY_COUNT);
    return -1.0; // Indicate error
}

// Control RGB lamps based on lux value
void control_lamps(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < LUX_THRESHOLD_RED) {
        red_state = 1;
    } else if (lux < LUX_THRESHOLD_GREEN) {
        green_state = 1;
    } else if (lux < LUX_THRESHOLD_BLUE) {
        blue_state = 1;
    } else {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    gpioWrite(RED_GPIO, red_state);
    gpioWrite(GREEN_GPIO, green_state);
    gpioWrite(BLUE_GPIO, blue_state);
}

// Log data to file
void log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%d,%d,%d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RED_GPIO, PI_OUTPUT);
    gpioSetMode(GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(BLUE_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux >= 0) {
            control_lamps(lux);
            int red_state = gpioRead(RED_GPIO);
            int green_state = gpioRead(GREEN_GPIO);
            int blue_state = gpioRead(BLUE_GPIO);
            log_data(lux, red_state, green_state, blue_state);
        } else {
            fprintf(stderr, "Error reading lux value.\n");
        }

        gpioDelay(120000); // 120ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RED_GPIO, 0);
    gpioWrite(GREEN_GPIO, 0);
    gpioWrite(BLUE_GPIO, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

