#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A GPIO pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIO pins
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Distance range (10-100 cm)
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

// Proportional gain (0.5)
#define Kp 0.5

// Global variables for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and cleaning up...\n", signal);
}

// Function to set motor direction and speed
void set_motor_speed(int motor_a_distance, int motor_b_distance, int forward) {
    int in1, in2, in3, in4;

    // Motor A
    if (forward) {
        in1 = MOTOR_A_IN1;
        in2 = MOTOR_A_IN2;
    } else {
        in1 = MOTOR_A_IN1;
        in2 = MOTOR_A_IN2;
    }

    // Motor B
    if (forward) {
        in3 = MOTOR_B_IN3;
        in4 = MOTOR_B_IN4;
    } else {
        in3 = MOTOR_B_IN3;
        in4 = MOTOR_B_IN4;
    }

    // Set IN1 and IN3 high for forward, low for backward
    gpioWrite(in1, forward ? 1 : 0);
    gpioWrite(in3, forward ? 1 : 0);

    // Set IN2 and IN4 as PWM outputs
    gpioSetMode(in2, PI_OUTPUT);
    gpioSetMode(in4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(in2, PWM_FREQUENCY);
    gpioSetPWMfrequency(in4, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(in2, 255);
    gpioSetPWMrange(in4, 255);

    // Calculate PWM duty cycle based on distance
    int duty_cycle_a = (int)(Kp * (motor_a_distance - MIN_DISTANCE));
    int duty_cycle_b = (int)(Kp * (motor_b_distance - MIN_DISTANCE));

    // Clamp duty cycle to 0-255 range
    if (duty_cycle_a < 0) duty_cycle_a = 0;
    if (duty_cycle_a > 255) duty_cycle_a = 255;
    if (duty_cycle_b < 0) duty_cycle_b = 0;
    if (duty_cycle_b > 255) duty_cycle_b = 255;

    // Set PWM duty cycle
    gpioPWM(in2, duty_cycle_a);
    gpioPWM(in4, duty_cycle_b);
}

int main(int argc, char *argv[]) {
    int motor_a_distance, motor_b_distance;

    // Check command-line arguments
    if (argc != 3) {
