void set_motor_speed(int motor_a_distance, int motor_b_distance, int forward) {
    int in1, in2, in3, in4;

    // Motor A
    if (forward) {
        in1 = MOTOR_A_IN1;
        in2 = MOTOR_A_IN2;
    } else {
        in1 = MOTOR_A_IN1;
        in2 = MOTOR_A_IN2;
    }

