#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for stepper motor control
#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22

// Define GPIO pins for buttons
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define GPIO pin for DHT22 sensor
#define DHT22_PIN 4

// Define GPIO pin for PIR sensor
#define PIR_PIN 5

// Define the number of steps for a quarter turn
#define QUARTER_TURN_STEPS 512

// Define the inter-step delay in milliseconds
#define INTER_STEP_DELAY_MS 2

// Global variable to track program state for button debouncing
volatile int program_running = 1;

// Function prototypes
void cleanup_gpio();
void signal_handler(int signal);
void lock_door();
void unlock_door();
void rotate_quarter_turn();
void dht22_read(float *temperature, float *humidity);
void pir_callback(int gpio, int level, uint32_t tick);

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
    cleanup_gpio();
    exit(0);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    // De-energize all motor coils
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);

    // Release GPIO pins
    gpioSetMode(IN1, PI_INPUT);
    gpioSetMode(IN2, PI_INPUT);
    gpioSetMode(IN3, PI_INPUT);
    gpioSetMode(IN4, PI_INPUT);
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(DHT22_PIN, PI_INPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);

    gpioTerminate();
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    rotate_quarter_turn();
    printf("Door locked.\n");
}

// Function to unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    rotate_quarter_turn();
    printf("Door unlocked.\n");
}

// Function to rotate the stepper motor a quarter turn
void rotate_quarter_turn() {
    int steps = QUARTER_TURN_STEPS;
    int i, j;

    for (i = 0; i < 4; i++) {
        gpioWrite(IN1, 1);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);
        gpioDelay(INTER_STEP_DELAY_MS * 1000); // Convert ms to us

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 1);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 0);
        gpioDelay(INTER_STEP_DELAY_MS * 1000);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 1);
        gpioWrite(IN4, 0);
        gpioDelay(INTER_STEP_DELAY_MS * 1000);

        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioWrite(IN3, 0);
        gpioWrite(IN4, 1);
        gpioDelay(INTER_STEP_DELAY_MS * 1000);
    }
}

// Function to read temperature and humidity from DHT22 sensor
void dht22_read(float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int j = 0;

    // Set GPIO pin to output
    gpioSetMode(DHT22_PIN, PI_OUTPUT);
    gpioWrite(DHT22_PIN, PI_HIGH);
    gpioDelay(500); // Wait 500ms
    gpioWrite(DHT22_PIN, PI_LOW);
    gpioDelay(20); // Wait 20ms
    gpioWrite(DHT22_PIN, PI_HIGH);
    gpioSetMode(DHT22_PIN, PI_INPUT);

    // Read data
    for (int i = 0; i < 85; i++) {
        int counter = 0;
        while (gpioRead(DHT22_PIN) == laststate) {
            counter++;
            gpioDelay(1); // Delay 1us
            if (counter == 255) {
                break;
            }
        }
        laststate = gpioRead(DHT22_PIN);

        if (counter == 255) break;

        // Ignore first 3 transitions
        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    // Check checksum
    if ((j >= 40) && (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF))) {
        *humidity = (float)data[0] + (float)data[1] / 10.0;
        *temperature = (float)data[2] + (float)data[3] / 10.0;
        if (*temperature > 125) {
            *temperature = *temperature - 256;
        }
        *humidity = *humidity * 100;
    } else {
        fprintf(stderr, "DHT22 Checksum error\n");
    }
}

// Callback function for PIR sensor
void pir_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge detected
        printf("Motion detected!\n");
        unlock_door();
        gpioDelay(5000); // Wait 5 seconds before re-triggering
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(DHT22_PIN, PI_INPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Set up interrupt for PIR sensor
    gpioSetAlertFunc(PIR_PIN, pir_callback);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int lock_pressed = 0;
    int unlock_pressed = 0;

    printf("Smart Agriculture System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read DHT22 sensor
        dht22_read(&temperature, &humidity);
        printf("Temperature: %.1f\u00b0C, Humidity: %.1f%%\n", temperature, humidity);

        // Check for button presses
        if (gpioRead(LOCK_BUTTON) == 0) {
            if (!lock_pressed) {
                lock_pressed = 1;
                lock_door();
            }
        } else if (gpioRead(UNLOCK_BUTTON) == 0) {
            if (!unlock_pressed) {
                unlock_pressed = 1;
                unlock_door();
            }
        } else if (unlock_pressed) {
            unlock_pressed = 0;
        } else if (lock_pressed) {
            lock_pressed = 0;
        }

        gpioDelay(1000); // Delay 1 second
    }

    cleanup_gpio();
    return 0;
}

