#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define SERVO_PIN 18
#define PWM_PERIOD 1000000 // 1ms
#define PWM_RANGE 1000
#define LOG_FILE "solar_tracker.log"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void process_sensor_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
int set_servo_angle(int angle);
int log_data(float pitch, float roll, int servo_angle);
void signal_handler(int signal);

// Exponential backoff function
int i2c_retries(int fd, int delay_ms) {
    int retries = 0;
    int result = -1;
    int delay = delay_ms;

    while (retries < 5 && result != 0) {
        result = ioctl(fd, I2C_SLAVE, MPU6050_ADDR);
        if (result == -1) {
            perror("I2C_SLAVE ioctl failed");
            usleep(delay * 1000); // Convert ms to microseconds
            delay *= 2; // Exponential backoff
            retries++;
        }
    }
    return result;
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    // Wake up the MPU6050
    if (i2c_retries(fd, 10) != 0) {
        fprintf(stderr, "Failed to wake up MPU6050 after multiple retries.\n");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from MPU6050
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];
    int result = read(fd, buffer, 14);

    if (result != 14) {
        fprintf(stderr, "Failed to read 14 bytes from MPU6050: %s\n", strerror(errno));
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

// Process sensor data (accelerometer only)
void process_sensor_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll) {
    float ax = (float)accel_x;
    float ay = (float)accel_y;
    float az = (float)accel_z;

    *roll = atan2(ay, sqrt(ax * ax + az * az)) * 180 / M_PI;
    *pitch = atan2(-ax, sqrt(ay * ay + az * az)) * 180 / M_PI;
}

// Set servo angle using pigpio
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return -1;
    }

    int pulse_width = (int)(angle * PWM_RANGE / 180.0);
    gpioPWM(SERVO_PIN, pulse_width);
    return 0;
}

// Log data to file
int log_data(float pitch, float roll, int servo_angle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_angle);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

