    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int servo_angle;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_mpu6050_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Process sensor data
            process_sensor_data(accel_x, accel_y, accel_z, &pitch, &roll);

            // Set servo angle
            servo_angle = 90 - pitch; // Example: Adjust servo based on pitch
            if (set_servo_angle(servo_angle) != 0) {
