#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define fade duration (seconds)
#define FADE_DURATION 1800

// Structure to hold relay and schedule information
typedef struct {
    int relay_number;
    int on_off;
    int schedule_entry;
} RelayInfo;

// Global variables
static volatile int running = 1;
static RelayInfo relays[4];
static int num_relays = 0;

// Function prototypes
int read_schedule(const char *filename, RelayInfo *relays, int *num_relays);
int parse_schedule_entry(const char *line, RelayInfo *relay);
int set_relay_state(int relay_number, int state);
int perform_fade(int relay_number, int duration_seconds);
void signal_handler(int signal);

// Function to read the schedule file
int read_schedule(const char *filename, RelayInfo *relays, int *num_relays) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open schedule file %s\n", filename);
        return -1;
    }

    char line[256];
    *num_relays = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%d:%d:%d,%d,%d", &relays[*num_relays].relay_number, &relays[*num_relays].on_off, &relays[*num_relays].schedule_entry) == 3) {
            (*num_relays)++;
        } else {
            fprintf(stderr, "Error: Invalid schedule entry: %s", line);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

// Function to parse a schedule entry
int parse_schedule_entry(const char *line, RelayInfo *relay) {
    char *token;
    char *rest = line;
    int i = 0;

    // Skip leading whitespace
    while (isspace((unsigned char) *rest)) {
        rest++;
    }

    // Extract hour, minute, second
    token = strtok(rest, ":");
    if (token != NULL) {
        relay->schedule_entry = atoi(token);
    } else {
        fprintf(stderr, "Error: Invalid hour/minute/second format: %s", line);
        return -1;
    }

    // Extract relay number
    token = strtok(NULL, ";");
    if (token != NULL) {
        relay->relay_number = atoi(token);
    } else {
        fprintf(stderr, "Error: Invalid relay number format: %s", line);
        return -1;
    }

    // Extract on/off state
    token = strtok(NULL, ";");
    if (token != NULL) {
        relay->on_off = atoi(token);
    } else {
        fprintf(stderr, "Error: Invalid on/off format: %s", line);
        return -1;
    }

    return 0;
}

// Function to set the state of a relay
int set_relay_state(int relay_number, int state) {
    int pin = -1;
    if (relay_number == RELAY1_PIN) pin = RELAY1_PIN;
    else if (relay_number == RELAY2_PIN) pin = RELAY2_PIN;
    else if (relay_number == RELAY3_PIN) pin = RELAY3_PIN;
    else if (relay_number == RELAY4_PIN) pin = RELAY4_PIN;

    if (pin == -1) {
        fprintf(stderr, "Error: Invalid relay number: %d\n", relay_number);
        return -1;
    }

    gpioWrite(pin, state);
    return 0;
}

// Function to perform a fade
int perform_fade(int relay_number, int duration_seconds) {
    int duty_cycle;
    int i;
    int current_time = time_time();

    if (relay_number == RELAY1_PIN) duty_cycle = 0;
    else if (relay_number == RELAY2_PIN) duty_cycle = 50;
    else if (relay_number == RELAY3_PIN) duty_cycle = 75;
    else if (relay_number == RELAY4_PIN) duty_cycle = 100;

    for (i = 0; i < duration_seconds * 1000 / PWM_FREQUENCY; i++) {
        gpioPWM(relay_number, duty_cycle);
        gpioDelay(1000); // Delay for 1ms
        current_time = time_time();
        if (current_time - time_time() >= FADE_DURATION) break;
    }

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Turn off all relays
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize relays to off state
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Read the schedule file
    if (read_schedule("lighting_schedule.txt", relays, &num_relays) != 0) {
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        for (int i = 0; i < num_relays; i++) {
            if (relays[i].on_off == 1) {
                if (time_time() >= relays[i].schedule_entry) {
                    printf("Transition for relay %d at %d:%d:%d\n", relays[i].relay_number, relays[i].schedule_entry / 3600, (relays[i].schedule_entry % 3600) / 60, relays[i].schedule_entry % 60);
                    perform_fade(relays[i].relay_number, FADE_DURATION);
                    set_relay_state(relays[i].relay_number, 1); // Turn on the relay
                } else {
                    set_relay_state(relays[i].relay_number, 0); // Turn off the relay
                }
            }
        }
        gpioDelay(1000); // Check every second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

