#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum measurable distance (cm)
#define MAX_DISTANCE 400.0    // Maximum measurable distance (cm)
#define MIN_FREQUENCY 200.0   // Minimum frequency (Hz)
#define MAX_FREQUENCY 2000.0  // Maximum frequency (Hz)
#define TIMEOUT_US 50000       // Timeout for echo pulse (50ms)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
float measure_distance();
float map_distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to start (with timeout)
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to end (with timeout)
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 to get one-way distance

    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MAX_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MIN_FREQUENCY;
    } else {
        // Linear mapping
        float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
        return frequency;
    }
}

// Function to set buzzer frequency using PWM
void set_buzzer_frequency(float frequency) {
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
    gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
}

// Function to clean up GPIO and terminate pigpio
void cleanup() {
    gpioPWM(BUZZER_PIN, 0); // Stop PWM signal
    gpioTerminate();
}

