#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
    }
}

// Function to calculate the RGB values based on the proximity value
void calculate_rgb(float proximity_value, int *red, int *green, int *blue) {
    // Sine wave function for proximity value (0.0 to 1.0)
    float proximity_float = proximity_value * 3.14159; // Scale proximity to 0-2*pi

    // Calculate RGB values based on sine wave
    *red   = (int)(255 * sin(proximity_float / 2.0));   // Red
    *green = (int)(255 * sin(proximity_float / 4.0));   // Green
    *blue  = (int)(255 * sin(proximity_float / 6.0));   // Blue
}

