#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Hard iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Compass directions
const char *compass_directions[] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};
const int num_directions = sizeof(compass_directions) / sizeof(compass_directions[0]);

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int initialize_magnetometer();
magnetometer_data_t read_magnetometer_data();
void calibrate_magnetometer_data(magnetometer_data_t data);
float calculate_heading(magnetometer_data_t data);
char *determine_compass_direction(float heading);
int log_data(magnetometer_data_t data, char *direction);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to initialize the magnetometer
int initialize_magnetometer() {
    // Configure the magnetometer for continuous measurement mode 2 (100 Hz)
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x18) < 0) { // 0x18 = 01110000
        fprintf(stderr, "Error writing to CRA_REG_M\n");
        return -1;
    }

    // Set the gain (full scale) to +/- 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) { // 0x00 = 00000000
        fprintf(stderr, "Error writing to MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to calibrate magnetometer data
void calibrate_magnetometer_data(magnetometer_data_t data) {
    data.x -= X_OFFSET;
    data.y -= Y_OFFSET;
    data.z -= Z_OFFSET;
}

// Function to calculate heading in degrees
float calculate_heading(magnetometer_data_t data) {
    float x = (float)data.x;
    float y = (float)data.y;
    float z = (float)data.z;

    float heading = atan2(y, x) * 180 / M_PI;

    // Normalize to 0-360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Function to determine compass direction
char *determine_compass_direction(float heading) {
    float heading_rad = heading * (M_PI / 180.0);
    int index = (int)(heading_rad / 45.0);

    if (heading_rad >= 0 && heading_rad < 45.0) {
        return compass_directions[0]; // N
    } else if (heading_rad >= 45.0 && heading_rad < 90.0) {
        return compass_directions[1]; // NE
    } else if (heading_rad >= 90.0 && heading_rad < 135.0) {
        return compass_directions[2]; // E
    } else if (heading_rad >= 135.0 && heading_rad < 180.0) {
        return compass_directions[3]; // SE
    } else if (heading_rad >= 180.0 && heading_rad < 225.0) {
        return compass_directions[4]; // S
    } else if (heading_rad >= 225.0 && heading_rad < 270.0) {
        return compass_directions[5]; // SW
    } else if (heading_rad >= 270.0 && heading_rad < 315.0) {
        return compass_directions[6]; // W
    } else {
        return compass_directions[7]; // NW
    }
}

// Function to log data to a CSV file
int log_data(magnetometer_data_t data, char *direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, data.x, data.y, data.z, (int)direction);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (initialize_magnetometer() < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        magnetometer_data_t data = read_magnetometer_data();
        calibrate_magnetometer_data(data);

        float heading = calculate_heading(data);
        char *direction = determine_compass_direction(heading);

        log_data(data, direction);
        printf("Calibrated X: %d, Calibrated Y: %d, Calibrated Z: %d, Heading: %d, Direction: %s\n",
               data.x, data.y, data.z, (int)heading, direction);

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

