#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int last_touch_time = 0;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
void touch_callback(int gpio, int level, uint32_t tick);
int log_state(const char *timestamp, int relay_state);
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF

    return 0;
}

// Callback function for touch sensor events
void touch_callback(int gpio, int level, uint32_t tick) {
    int current_time = gpioTick();

    if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
        relay_state = !relay_state; // Toggle relay state
        gpioWrite(RELAY_PIN, relay_state);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        // Log the state change
        if (log_state(timestamp, relay_state) != 0) {
            fprintf(stderr, "Error logging state change\n");
        }

        last_touch_time = current_time;
    }
}

// Function to log the state change to a file
int log_state(const char *timestamp, int relay_state) {
    FILE *fp = fopen("relay_log.json", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Check if the file is empty, if so, add the opening bracket
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "[");
    } else {
