    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int moisture_level = read_moisture();
        printf("Moisture level: %d\n", moisture_level);
        control_irrigation(moisture_level);
        gpioDelay(10000000); // Wait 10 seconds (10000000 microseconds)
    }

    return 0;
}

