#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

// Define moisture thresholds
#define MOISTURE_THRESHOLD_LOW 50
#define MOISTURE_THRESHOLD_HIGH 60

// Define servo angles
#define VALVE_OPEN_ANGLE 90
#define NOZZLE_STEPS 5
#define NOZZLE_DELAY 2 // seconds
#define NOZZLE_HOLD 5 // seconds

// Define pulse widths (microseconds)
#define VALVE_PULSE_WIDTH 1500
#define NOZZLE_PULSE_WIDTHS {500, 1000, 1500, 2000, 2500}

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int set_servo_angle(int gpio, int angle);
int read_soil_moisture();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping servos and cleaning up...\n", signal);
    gpioServo(VALVE_GPIO, 0); // Stop valve servo
    gpioServo(NOZZLE_GPIO, 0); // Stop nozzle servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to set servo angle
int set_servo_angle(int gpio, int angle) {
    int pulse_width = 0;
    if (angle == 0) {
        pulse_width = 500;
    } else if (angle == 90) {
        pulse_width = 1500;
    } else if (angle == 180) {
        pulse_width = 2500;
    } else {
        pulse_width = 1000;
    }

    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo angle on GPIO %d: %d\n", gpio, result);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to read simulated soil moisture
int read_soil_moisture() {
    static int moisture = 20;
    moisture = (moisture + 20) % 100;
    return moisture;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(NOZZLE_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Automated Plant Watering System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read soil moisture
        int moisture = read_soil_moisture();

        // Check moisture thresholds
        if (moisture < MOISTURE_THRESHOLD_LOW) {
            printf("Moisture level: %d, below threshold. Starting watering cycle.\n", moisture);

            // Open valve
            if (set_servo_angle(VALVE_GPIO, VALVE_OPEN_ANGLE) != 0) {
                fprintf(stderr, "Error opening valve. Skipping watering cycle.\n");
            } else {
                // Sweep nozzle
                for (int i = 0; i < NOZZLE_STEPS; i++) {
                    int pulse_width = NOZZLE_PULSE_WIDTHS[i];
                    if (set_servo_angle(NOZZLE_GPIO, i * 45) != 0) {
                        fprintf(stderr, "Error setting nozzle angle %d. Skipping.\n", i);
                        continue; // Skip to the next angle
                    }
                    sleep(NOZZLE_DELAY);
                }

                // Hold spray
                if (set_servo_angle(NOZZLE_GPIO, 180) != 0) {
                    fprintf(stderr, "Error holding spray. Skipping.\n");
                } else {
                    sleep(NOZZLE_HOLD);
                }

                // Close valve
                if (set_servo_angle(VALVE_GPIO, 0) != 0) {
                    fprintf(stderr, "Error closing valve. Critical warning!\n");
                } else {
                    printf("Valve closed.\n");
                }
            }
        } else {
            printf("Moisture level: %d, above threshold. Skipping watering cycle.\n", moisture);
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(VALVE_GPIO, 0); // Stop valve servo
    gpioServo(NOZZLE_GPIO, 0); // Stop nozzle servo
    gpioTerminate(); // Terminate pigpio

    return 0;
}

