#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor for gyroscope
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int init_i2c();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0); // Open I2C bus 1, MPU6050 address
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
