#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define RELAY_GPIO 18
#define DISTANCE_THRESHOLD 50 // cm
#define POLL_INTERVAL 100 // ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_vl53l1x();
int read_distance(int *distance);
int control_relay(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // No specific initialization needed for VL53L1X in this example.
    // Refer to the datasheet for more advanced configurations.
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    char cmd[1] = {0x00}; // Example command to trigger a measurement
    char buffer[2]; // Buffer to store the distance data (2 bytes)
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Small delay for measurement

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1]; // Combine the two bytes into a 16-bit value
    return 0;
}

// Control the relay based on distance
int control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Set relay HIGH
    } else {
        gpioWrite(RELAY_GPIO, 0); // Set relay LOW
    }
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is LOW on exit
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

