#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the watering cycle duration in seconds
#define WATERING_CYCLE_DURATION 86400

// Define the relay activation duration in seconds
#define RELAY_ACTIVATION_DURATION 5

// Global variable to track the watering cycle start time
time_t watering_cycle_start_time = 0;

// Function prototypes
int initialize_gpio();
int set_relay_state(int gpio_pin, int state);
int activate_relay(int gpio_pin, int duration_seconds);
int log_watering_cycle();
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs with active-low semantics
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set initial state to HIGH (inactive)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Function to set the state of a relay (active-low)
int set_relay_state(int gpio_pin, int state) {
    if (gpio_pin != RELAY1_PIN && gpio_pin != RELAY2_PIN && gpio_pin != RELAY3_PIN && gpio_pin != RELAY4_PIN) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return 1; // Indicate failure
    }

    int result = gpioWrite(gpio_pin, !state); // Active-low, so invert the state
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d to state %d: %d\n", gpio_pin, state, result);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to activate a relay for a specified duration
int activate_relay(int gpio_pin, int duration_seconds) {
    if (gpio_pin != RELAY1_PIN && gpio_pin != RELAY2_PIN && gpio_pin != RELAY3_PIN && gpio_pin != RELAY4_PIN) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return 1; // Indicate failure
    }

    if (set_relay_state(gpio_pin, 0) != 0) {
        return 1; // Indicate failure
    }

    gpioDelay(duration_seconds * 1000000); // Delay in microseconds

    if (set_relay_state(gpio_pin, 1) != 0) {
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to log the watering cycle start time to a file
int log_watering_cycle() {
    FILE *fp = fopen("watering_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open watering_log.txt for writing\n");
        return 1; // Indicate failure
    }

    time_t t = watering_cycle_start_time;
    struct tm *tm_info = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(fp, "%s\n", s) < 0) {
        fprintf(stderr, "Failed to write to watering_log.txt\n");
        fclose(fp);
        return 1; // Indicate failure
    }

    fclose(fp);
    return 0; // Indicate success
}

// Function to cleanup GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    printf("Cleaning up GPIO and exiting...\n");
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    gpioTerminate();
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Signal received (%d). Cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Log the initial watering cycle start time
    if (log_watering_cycle() != 0) {
        cleanup_gpio();
        return 1; // Exit if logging fails
    }

    printf("Watering system started. Cycle duration: %d seconds\n", WATERING_CYCLE_DURATION);

    // Main loop
    while (1) {
        // Activate relays sequentially
        if (activate_relay(RELAY1_PIN, RELAY_ACTIVATION_DURATION) != 0) {
            fprintf(stderr, "Failed to activate relay 1\n");
        }
        if (activate_relay(RELAY2_PIN, RELAY_ACTIVATION_DURATION) != 0) {
            fprintf(stderr, "Failed to activate relay 2\n");
        }
        if (activate_relay(RELAY3_PIN, RELAY_ACTIVATION_DURATION) != 0) {
            fprintf(stderr, "Failed to activate relay 3\n");
        }
        if (activate_relay(RELAY4_PIN, RELAY_ACTIVATION_DURATION) != 0) {
            fprintf(stderr, "Failed to activate relay 4\n");
        }

        // Check if the watering cycle duration has elapsed
        if (watering_cycle_start_time == 0) {
            if (time(NULL) - watering_cycle_start_time >= WATERING_CYCLE_DURATION) {
                if (log_watering_cycle() != 0) {
                    fprintf(stderr, "Failed to log watering cycle\n");
                }
                watering_cycle_start_time = time(NULL);
            }
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    return 0; // This line will never be reached due to the infinite loop
}

