#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>
#include <stdbool.h>

// MPU-9250 Registers
#define MPU9250_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define CONFIG 0x1A

// SPI Configuration
#define SPI_BUS "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MSB_FIRST

// GPIO Configuration
#define GYRO_CS_PIN 8 // GPIO8 (BCM)
#define GYRO_CS_LINE_OFFSET 8 // GPIO line offset for GYRO_CS_PIN

// Retry settings
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
static int spi_fd = -1;
static int gyro_cs_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *bus, int speed, int mode, int bits_per_word, int msb_first);
int gyro_init(int gyro_cs_fd);
int read_gyro_data(int gyro_cs_fd, int16_t *x_rate, int16_t *y_rate, int16_t *z_rate);
int log_data(FILE *fp, struct timespec ts, int16_t x_rate, int16_t y_rate, int16_t z_rate);
void signal_handler(int sig);
void cleanup();

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
    int16_t z_rate;
} gyro_data_t;

// Function to initialize the SPI device
int spi_init(const char *bus, int speed, int mode, int bits_per_word, int msb_first) {
    int fd = spiOpen(bus, speed, mode);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to initialize the gyroscope
int gyro_init(int gyro_cs_fd) {
    // Wake up the MPU-9250 (clear sleep bit)
    char data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;
    if (spiWrite(gyro_cs_fd, data, 2) != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }

    // Set sample rate divider
    data[0] = SMPLRT_DIV;
    data[1] = 0x07; // Sample rate = 1kHz / (1 + 7) = 125 Hz
    if (spiWrite(gyro_cs_fd, data, 2) != 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV register\n");
        return -1;
    }

    // Configure DLPF (Digital Low Pass Filter)
    data[0] = CONFIG;
    data[1] = 0x00; // Set DLPF_CFG to 0 for 256 Hz bandwidth
    if (spiWrite(gyro_cs_fd, data, 2) != 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int gyro_cs_fd, int16_t *x_rate, int16_t *y_rate, int16_t *z_rate) {
    char tx_buf[7];
    char rx_buf[7];

    // Read X, Y, and Z rates (6 bytes)
    tx_buf[0] = GYRO_XOUT_H;
    memset(rx_buf, 0, sizeof(rx_buf));

    if (spiXfer(gyro_cs_fd, tx_buf, rx_buf, 7) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x_rate = (int16_t)((rx_buf[2] << 8) | rx_buf[1]);
    *y_rate = (int16_t)((rx_buf[4] << 8) | rx_buf[3]);
    *z_rate = (int16_t)((rx_buf[6] << 8) | rx_buf[5]);

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, struct timespec ts, int16_t x_rate, int16_t y_rate, int16_t z_rate) {
    if (fprintf(fp, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, x_rate, y_rate, z_rate) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }
    if (gyro_cs_fd != -1) {
        gpioSetMode(gyro_cs_fd, PI_INPUT); // Set back to input
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO line for CS
    gyro_cs_fd = gpioSetMode(GYRO_CS_PIN, PI_OUTPUT);
    if (gyro_cs_fd < 0) {
        fprintf(stderr, "Error setting GPIO mode for CS pin\n");
        cleanup();
        return 1;
    }

    // Open SPI device
    spi_fd = spi_init(SPI_BUS, SPI_SPEED, SPI_MODE, SPI_BITS_PER_WORD, SPI_MSB_FIRST);
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }

    // Initialize gyroscope
    if (gyro_init(gyro_cs_fd) < 0) {
        cleanup();
        return 1;
    }

