int log_data(FILE *fp, struct timespec ts, int16_t x_rate, int16_t y_rate, int16_t z_rate) {
    if (fprintf(fp, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, x_rate, y_rate, z_rate) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }
    if (gyro_cs_fd != -1) {
        gpioSetMode(gyro_cs_fd, PI_INPUT); // Set back to input
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

