    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO line for CS
    gyro_cs_fd = gpioSetMode(GYRO_CS_PIN, PI_OUTPUT);
    if (gyro_cs_fd < 0) {
        fprintf(stderr, "Error setting GPIO mode for CS pin\n");
        cleanup();
