    while (!terminate) {
        // Read gyroscope data with retries
        if (read_gyro_data(gyro_cs_fd, &gyro_data.x_rate, &gyro_data.y_rate, &gyro_data.z_rate) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Log data
