                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            fprintf(stderr, "Gyroscope read failed, retrying...\n");
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                break;
            }
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
