#define LED_PIN 17

// Data Structure for Gyroscope Data
typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular Buffer Structure
typedef struct {
    gyro_data_t buffer[64];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global Variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int init_mpu6050();
int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
int check_threshold(gyro_data_t data);
void blink_led(int pin, int duration_ms);
void print_buffer(circular_buffer_t *buffer);
void signal_handler(int signal);

// Function to initialize the MPU-6050
int init_mpu6050() {
    char buf[2];

    // Wake up the MPU-6050 (set sleep bit to 0)
    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00;
    if (spiWrite(spi_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Configure gyroscope range to ±250°/s
    buf[0] = GYRO_CONFIG;
    buf[1] = 0x00; // Full scale range = ±250°/s
    if (spiWrite(spi_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Could not configure gyroscope\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(gyro_data_t *data) {
    char buf[7];
    int16_t x, y, z;

    // Read gyroscope data (X, Y, Z axes)
    buf[0] = GYRO_XOUT_H;
    if (spiXfer(spi_handle, buf, buf, 7) != 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    x = (int16_t)((buf[2] << 8) | buf[1]);
    y = (int16_t)((buf[4] << 8) | buf[3]);
    z = (int16_t)((buf[6] << 8) | buf[5]);

    // Store the data in the struct
    data->x = x;
    data->y = y;
    data->z = z;

    // Get timestamp
    clock_gettime(CLOCK_REALTIME, &data->timestamp);

    return 0;
}

