#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define AMBIENT_LIGHT_REG 0x22
#define PROXIMITY_REG 0x24
#define LED_GPIO 17
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_register(int fd, uint8_t reg);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity);
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
void control_led(int gpio, int state);
void signal_handler(int sig);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    uint16_t ambient_light;
    uint16_t proximity;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, SI1145_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &sensor_data.ambient_light, &sensor_data.proximity) == 0) {
            if (log_data(log_file, sensor_data.ambient_light, sensor_data.proximity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
            control_led(LED_GPIO, sensor_data.proximity > 100);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }
        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read a single register
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// Write a single register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Read ambient light and proximity data
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    *ambient_light = read_register(fd, AMBIENT_LIGHT_REG);
    if (*ambient_light < 0) return -1;
    *proximity = read_register(fd, PROXIMITY_REG);
    if (*proximity < 0) return -1;
    return 0;
}

// Log data to file
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,AmbientLight:%u,Proximity:%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Control LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

