#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXRS290 Register Addresses
#define X_RATE_REG 0x00
#define Y_RATE_REG 0x02

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// GPIO Pin for Chip Enable (CE0)
#define CE_PIN 8

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize_spi();
int read_register(uint8_t address, uint8_t dummy, uint8_t *data);
int write_register(uint8_t address, uint8_t data);
int read_gyro_data(int16_t *x_rate, int16_t *y_rate);
void log_data(int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read a register from the ADXRS290
int read_register(uint8_t address, uint8_t dummy, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = address | 0x80; // Set read bit (MSB)
    tx_buf[1] = dummy;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error during SPI transfer for register 0x%02X\n", address);
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

// Function to write a register in the ADXRS290
int write_register(uint8_t address, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = address & 0x7F; // Clear read bit (MSB)
    tx_buf[1] = data;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error during SPI transfer for write to register 0x%02X\n", address);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from both axes
int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    uint8_t x_rate_data, y_rate_data;

    if (read_register(X_RATE_REG, 0x00, &x_rate_data) != 0) {
        fprintf(stderr, "Error reading X rate data\n");
        return -1;
    }
    if (read_register(Y_RATE_REG, 0x00, &y_rate_data) != 0) {
        fprintf(stderr, "Error reading Y rate data\n");
        return -1;
    }

    *x_rate = (int16_t)x_rate_data;
