#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17

// Define constants
#define ALERT_DURATION_MS 2000
#define ALERT_THRESHOLD_MS 500
#define DEBOUNCE_DELAY_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int open_log_file();
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);
void trigger_alert();
void log_event();
void cleanup();
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    uint32_t last_tick;
} SensorStates;

SensorStates sensor_states = {0, 0, 0};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Seismic event detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Check if both sensors are HIGH for the threshold duration
        if (sensor_states.sensor1_state == 1 && sensor_states.sensor2_state == 1) {
            if (gpioTick() - sensor_states.last_tick >= ALERT_THRESHOLD_MS * 1000) {
                trigger_alert();
                sensor_states.last_tick = gpioTick();
            }
        } else {
            sensor_states.last_tick = 0; // Reset debounce if sensor states change
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors (optional, depends on sensor wiring)
    // gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    // gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    return 0;
}

// Open the log file
int open_log_file() {
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }
    return 0;
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick1 = 0;
    if (tick - last_tick1 > DEBOUNCE_DELAY_MS * 1000) {
        sensor_states.sensor1_state = level;
        last_tick1 = tick;
        if (sensor_states.sensor1_state == 1) {
            log_event();
        }
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick2 = 0;
    if (tick - last_tick2 > DEBOUNCE_DELAY_MS * 1000) {
        sensor_states.sensor2_state = level;
        last_tick2 = tick;
        if (sensor_states.sensor2_state == 1) {
            log_event();
        }
    }
}

// Trigger the alert
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1); // Set ALERT_PIN HIGH
    gpioDelay(ALERT_DURATION_MS * 1000); // Wait for ALERT_DURATION_MS milliseconds
    gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
}

// Log the seismic event
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
    fflush(log_file); // Ensure the data is written to the file immediately
    printf("%s - Seismic event detected!\n", timestamp);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_PIN, 0); // Ensure ALERT_PIN is LOW
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d).  Shutting down...\n", signal);
    running = 0;
}

