#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define CE0 8
#define SCLK 11
#define MOSI 10
#define MISO 9
#define LED_PIN 17

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define ADXRS290 register addresses
#define XGYRO_OUT 0x00

// Define threshold for angular rate
#define THRESHOLD 20.0

// Define circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    struct timespec timestamp;
    float angular_rate;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int spi_handle;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_gyro_data(float *angular_rate);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
int check_threshold(float angular_rate, float threshold);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(CE0, PI_OUTPUT);
    gpioSetMode(SCLK, PI_OUTPUT);
    gpioSetMode(MOSI, PI_OUTPUT);
    gpioSetMode(MISO, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    gpioWrite(CE0, 1); // Disable chip select initially
    gpioWrite(LED_PIN, 0); // Turn off LED

    return 0;
}

// Function to initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(float *angular_rate) {
    uint8_t tx_buffer[2];
    uint8_t rx_buffer[2];
    int16_t raw_data;
    int status;

    // Set MSB of register address to 1 for read operation
    tx_buffer[0] = XGYRO_OUT | 0x80; // Read bit set
    tx_buffer[1] = 0x00; // Dummy byte

    gpioWrite(CE0, 0); // Enable chip select
    status = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    gpioWrite(CE0, 1); // Disable chip select

    if (status != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", status);
        return -1;
    }

    // Combine the two bytes to form the 16-bit raw data
    raw_data = (rx_buffer[0] << 8) | rx_buffer[1];

    // Convert raw data to angular rate (degrees per second)
    *angular_rate = (float)raw_data * 0.03125; // Sensitivity: 0.03125 dps/LSB

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to check if the angular rate exceeds the threshold
int check_threshold(float angular_rate, float threshold) {
    return (angular_rate > threshold) ? 1 : 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    float angular_rate;
    struct timespec ts;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10 ms

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&angular_rate) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
                // Create gyro_data_t struct
                gyro_data_t data = {ts, angular_rate};

                // Add data to circular buffer
                add_to_buffer(&gyro_buffer, data);

                // Check threshold and control LED
                int threshold_exceeded = check_threshold(angular_rate, THRESHOLD);
                gpioWrite(LED_PIN, threshold_exceeded);

                // Print angular rate and timestamp
                printf("Timestamp: %ld.%09ld, Angular Rate: %.2f deg/s\n", ts.tv_sec, ts.tv_nsec, angular_rate);
            } else {
                fprintf(stderr, "Failed to get timestamp\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Sleep for 10 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

