volatile sig_atomic_t program_running = 1;

int main(int argc, char *argv[]) {
    // Check for command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Validate the total duration
    if (validate_duration((int)atol(argv[1])) != 0) {
        return 1;
    }

