    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to control the sunset simulation
    while (program_running) {
        // Fade the first lamp
        fade_lamp(LAMP1_GPIO, total_duration);

        // Fade the second lamp
        fade_lamp(LAMP2_GPIO, total_duration);

        // Fade the third lamp
        fade_lamp(LAMP3_GPIO, total_duration);

        // Wait for a short period before repeating the cycle
        sleep(5);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

// Function to validate the total duration
int validate_duration(int duration) {
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Invalid total duration.  Must be between 1 and 3600 seconds.\n");
        return 1;
    }
    return 0;
}

// Function to initialize the pigpio library and set up GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency to 100 Hz
    gpioSetPWMfrequency(LAMP1_GPIO, 100);
    gpioSetPWMfrequency(LAMP2_GPIO, 100);
    gpioSetPWMfrequency(LAMP3_GPIO, 100);

    return 0;
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio, int duration) {
    int i;
    int steps = duration * 10; // Number of steps to fade over the duration
    int delay_ms = duration * 1000 / steps; // Delay between steps in milliseconds

    for (i = 255; i >= 0; i -= 5) { // Fade from 255 to 0 in steps of 5
        gpioPWM(gpio, i);
        printf("Lamp on GPIO %d: PWM value %d\n", gpio, i);
        gpioDelay(delay_ms);
    }
    gpioPWM(gpio, 0); // Turn off the lamp
    printf("Lamp on GPIO %d: Off\n", gpio);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    // Turn off all lamps
    gpioWrite(LAMP1_GPIO, 0);
    gpioWrite(LAMP2_GPIO, 0);
    gpioWrite(LAMP3_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();
    printf("GPIO resources released.\n");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d).  Shutting down gracefully...\n", signal);
    program_running = 0;
}

