void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
        program_running = 0; // Set flag to exit main loop

        // De-energize all relays
        set_relay_state(RED_RELAY, RELAY_OFF);
        set_relay_state(YELLOW_RELAY, RELAY_OFF);
        set_relay_state(GREEN_RELAY, RELAY_OFF);
