#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define ELE0_TOUCH_STATUS_REG 0x00
#define ELE0_TOUCH_THRESHOLD 0x0F
#define ELE0_RELEASE_THRESHOLD 0x0A
#define GPIO_RELAY 17
#define DEBOUNCE_DELAY_MS 100
#define RELAY_ON_TIME_MS 500
#define LOG_FILE "touch_relay.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int initialize_gpio();
int initialize_mpr121();
int read_touch_status(uint16_t *touch_status);
int debounce_touch(int electrode, int state);
int toggle_relay();
int log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// GPIO initialization function
int initialize_gpio() {
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode");
        return -1;
    }
    gpioWrite(GPIO_RELAY, 0); // Initialize relay to LOW
    return 0;
}

// MPR121 initialization function
int initialize_mpr121() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x00) < 0) {
        log_error("Failed to set MPR121 to stop mode");
        return -1;
    }
    gpioDelay(1); // Small delay after writing to the MPR121

    // Electrode 0 touch and release thresholds
    if (i2cWriteByteData(i2c_handle, 0x41, ELE0_TOUCH_THRESHOLD) < 0) {
        log_error("Failed to write touch threshold");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x42, ELE0_RELEASE_THRESHOLD) < 0) {
        log_error("Failed to write release threshold");
        return -1;
    }

    // Electrode 0 enable
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        log_error("Failed to enable electrode 0");
        return -1;
    }

    // Start mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        log_error("Failed to set MPR121 to start mode");
        return -1;
    }
    gpioDelay(1); // Small delay after writing to the MPR121

    return 0;
}

// Touch status reading function
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, ELE0_TOUCH_STATUS_REG, buf, 2) != 2) {
        log_error("Failed to read touch status");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Debounce function
int debounce_touch(int electrode, int state) {
    static int last_state = 0;
    static struct timespec last_debounce_time;
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    double time_diff = (current_time.tv_sec - last_debounce_time.tv_sec) * 1000.0;
    time_diff += (current_time.tv_nsec - last_debounce_time.tv_nsec) / 1000000.0;

    if (state != last_state) {
        if (time_diff >= DEBOUNCE_DELAY_MS) {
            last_state = state;
            last_debounce_time = current_time;
            return 1; // Debounced
        }
    }
    return 0; // Not debounced
}

// Relay toggling function
int toggle_relay() {
    int current_state = gpioRead(GPIO_RELAY);
    gpioWrite(GPIO_RELAY, !current_state);
    return 0;
}

// Error logging function
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return -1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        i2cClose(i2c_handle);
        gpioWrite(GPIO_RELAY, 0); // Reset relay
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    uint16_t touch_status;
    int last_touch_state = 0;

    printf("Touch relay control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            int current_touch_state = (touch_status >> 1) & 1; // Extract electrode 0 state

            if (debounce_touch(0, current_touch_state)) {
                if (current_touch_state != last_touch_state) {
                    toggle_relay();
                    last_touch_state = current_touch_state;
                }
            }
        } else {
            log_error("Failed to read touch status, retrying...");
            gpioDelay(10); // Small delay before retrying
        }

        gpioDelay(10); // 10ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

