#define DEBOUNCE_READS 3
#define DEBOUNCE_DELAY_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_flame_sensor();
int debounce(int sensor_value, int reads, int delay_ms);
void log_flame_event();
void activate_alarm();
void deactivate_alarm();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Deactivate alarm
    deactivate_alarm();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to debounce the flame sensor readings
int debounce(int sensor_value, int reads, int delay_ms) {
    int low_count = 0;
    for (int i = 0; i < reads; i++) {
        int sensor_reading = read_flame_sensor();
        if (sensor_reading < 0) {
            return -1; // Propagate error
        }
        if (sensor_reading == sensor_value) {
            low_count++;
        }
        gpioDelay(delay_ms * 1000); // Convert ms to microseconds
    }
    return (low_count == reads) ? 0 : -1; // Return 0 if all reads are LOW, -1 otherwise
}

// Function to log the flame event to a file
void log_flame_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Flame Detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the alarm (buzzer and LED)
void activate_alarm() {
    gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    gpioWrite(LED_PIN, 1);    // Turn on LED
}

// Function to deactivate the alarm (buzzer and LED)
void deactivate_alarm() {
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioWrite(LED_PIN, 0);    // Turn off LED
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        int debounced_value = debounce(sensor_value, DEBOUNCE_READS, DEBOUNCE_DELAY_MS);

        if (debounced_value == 0) {
            log_flame_event();
            activate_alarm();
        } else if (debounced_value > 0) {
            deactivate_alarm();
        }

        gpioDelay(10000); // Check every 10ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_alarm();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

