#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration (milliseconds)
#define DISPENSE_DURATION 1000

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int dispense_solenoids(int duration_ms);
int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Shutting down...\n");
        gpioWrite(SOLENOID_1_PIN, 0); // Deactivate solenoid 1
        gpioWrite(SOLENOID_2_PIN, 0); // Deactivate solenoid 2
        gpioTerminate(); // Terminate pigpio
        program_running = 0; // Set flag to exit main loop
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    // Initialize solenoids to OFF state
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    return 0; // Indicate success
}

// Function to dispense solenoids
int dispense_solenoids(int duration_ms) {
    if (duration_ms <= 0) {
        fprintf(stderr, "Invalid dispense duration: %d ms\n", duration_ms);
        return 1; // Indicate failure
    }

    // Activate solenoid 1
    gpioWrite(SOLENOID_1_PIN, 1);
    gpioDelay(duration_ms / 2); // Half of the duration for solenoid 1
    gpioWrite(SOLENOID_1_PIN, 0);

    // Activate solenoid 2
    gpioWrite(SOLENOID_2_PIN, 1);
    gpioDelay(duration_ms / 2); // Half of the duration for solenoid 2
    gpioWrite(SOLENOID_2_PIN, 0);

    return 0; // Indicate success
}

// Function to log dispense events
int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Solenoid 1: %d, Solenoid 2: %d, Duration: %d ms\n", s, solenoid1_pin, solenoid2_pin, duration_ms);
    fclose(fp);

    return 0; // Indicate success
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (dispense_solenoids(DISPENSE_DURATION) != 0) {
            fprintf(stderr, "Error during dispense!\n");
        }
        if (log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION) != 0) {
            fprintf(stderr, "Error logging dispense event!\n");
        }
        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();

    printf("Dispensing system stopped.\n");
    return 0;
}

