#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENA 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENB 25

// Enable pins
#define ENA 24
#define ENB 25

// PID parameters
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Obstacle avoidance threshold
#define OBSTACLE_THRESHOLD 20.0

// PWM frequency
#define PWM_FREQUENCY 1000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void set_motor_speed(int motor_a_speed, int motor_b_speed);
float calculate_pid(float tilt_error, float previous_error, float integral, float dt);
float simulate_ultrasonic_sensor();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void obstacle_avoidance(float distance);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set motor control pins as outputs
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Set enable pins high to enable PWM
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    // Stop motors
    set_motor_speed(0, 0);

    // Disable PWM
    gpioWrite(ENA, 0);
    gpioWrite(ENB, 0);

    gpioTerminate();
}

// Set motor speeds
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    if (motor_a_speed > 255) motor_a_speed = 255;
    if (motor_a_speed < -255) motor_a_speed = -255;
