#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>
#include <errno.h>
#include <stdbool.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define ALSA macro
#define ALSA_AVAILABLE

// Define default scaling factor
#define DEFAULT_SCALING_FACTOR 1.0

// Define period size
#define PERIOD_SIZE 1024

// Define buffer overrun threshold
#define BUFFER_OVERFLOW_THRESHOLD 100

// Define ALSA device name
#define ALSA_DEVICE "default"

// Define ALSA sample format
#define ALSA_FORMAT SND_PCM_FORMAT_S16_LE

// Define ALSA sample rate
#define ALSA_SAMPLE_RATE 8000

// Define ALSA channels
#define ALSA_CHANNELS 1

// Define ALSA bits per sample
#define ALSA_BITS 16

// Define ALSA interleaved flag
#define ALSA_INTERLEAVED 0

// Global variables
snd_pcm_t *pcm_handle;
bool running = true;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle);
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int frames);
double calculate_rms(short *buffer, int frames);
void map_amplitude_to_color(double rms, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signum);
void cleanup();

// Function to initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening ALSA device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, ALSA_FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, ALSA_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &alsa_sample_rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_prepare(*pcm_handle)) < 0) {
        fprintf(stderr, "Error preparing PCM: %s\n", snd_strerror(err));
        return -1;
    }

    return 0;
}

// Function to capture audio from ALSA
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int frames) {
    int err;
    if ((err = snd_pcm_readi(pcm_handle, buffer, frames)) != frames) {
        fprintf(stderr, "Error reading from PCM: %s\n", snd_strerror(err));
        return -1;
    }
    return 0;
}

// Function to calculate RMS amplitude
double calculate_rms(short *buffer, int frames) {
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / frames);
}

// Function to map RMS amplitude to RGB color
void map_amplitude_to_color(double rms, int *red, int *green, int *blue) {
    // Non-linear mapping (logarithmic)
    double normalized_rms = rms / 1000.0; // Scale down for better sensitivity
    double red_value = (normalized_rms * 255.0) * (1.0 - (normalized_rms / 1000.0)); // Invert and scale
    double green_value = (normalized_rms * 255.0) * (1.0 - (normalized_rms / 1000.0) * 0.5); // Green is less intense
    double blue_value = (normalized_rms * 255.0) * (normalized_rms / 1000.0); // Blue is least intense

    // Clamp values to 0-255 range
    if (red_value < 0) red_value = 0;
    if (red_value > 255) red_value = 255;
    if (green_value < 0) green_value = 0;
    if (green_value > 255) green_value = 255;
    if (blue_value < 0) blue_value = 0;
    if (blue_value > 255) blue_value = 255;

    *red = (int)red_value;
    *green = (int)green_value;
    *blue = (int)blue_value;
}

// Function to set LED color using software PWM
void set_led_color(int red, int green, int blue) {
    // Software PWM implementation
    // This is a simplified version.  A more accurate PWM would use a timer.
    // For now, we just set the GPIO levels based on the color values.
    // This is not ideal for real-world PWM applications but serves as a demonstration.

    // Map RGB values (0-255) to GPIO levels (0-255)
    int red_level = (int)(((double)red / 255.0) * 255.0);
    int green_level = (int)(((double)green / 255.0) * 255.0);
    int blue_level = (int)(((double)blue / 255.0) * 255.0);

    // Set GPIO levels
    gpioWrite(RED_PIN, (red_level > 127) ? 1 : 0); // On/off
    gpioWrite(GREEN_PIN, (green_level > 127) ? 1 : 0); // On/off
    gpioWrite(BLUE_PIN, (blue_level > 127) ? 1 : 0); // On/off
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = false;
    printf("Caught signal %d, exiting...\n", signum);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int frames;
    short *buffer;
    int red, green, blue;
    double rms;
    int opt;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize ALSA
    if (init_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        cleanup();
        return 1;
    }

    // Check if a scaling factor was provided as a command-line argument
    if (argc > 1) {
        opt = atoi(argv[1]);
        if (opt > 0) {
            DEFAULT_SCALING_FACTOR = opt;
        } else {
            fprintf(stderr, "Invalid scaling factor. Using default value 1.0\n");
        }
    }

    printf("Audio capture and mood light started. Press Ctrl+C to exit.\n");

    while (running) {
        // Capture audio
        if (capture_audio(pcm_handle, buffer, PERIOD_SIZE) == 0) {
            // Calculate RMS amplitude
            rms = calculate_rms(buffer, PERIOD_SIZE);

            // Map amplitude to color
            map_amplitude_to_color(rms, &red, &green, &blue);

            // Set LED color
            set_led_color(red, green, blue);

            // Print status message
            printf("RMS: %.2f, R: %d, G: %d, B: %d\n", rms, red, green, blue);
        } else {
            fprintf(stderr, "Error capturing audio\n");
        }

        // Sleep for 10ms (100Hz sampling rate)
        usleep(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

