#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_ID 0x12
#define TCS34725_STATUS 0x93
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Enable register values
#define TCS34725_ENABLE_AIEN 0x10  // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN 0x08   // Wait enable - writing 1 activates the wait timer
#define TCS34725_ENABLE_AEN 0x02   // ALS Enable
#define TCS34725_ENABLE_PON 0x01   // Power on

// Integration time values
#define TCS34725_INTEGRATIONTIME_154MS 0xFF // 154ms

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold color data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} color_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
color_data_t read_color_data();
char* format_data(color_data_t data);
int write_to_csv(char* data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the TCS34725 sensor
int init_sensor() {
    // Check the ID register
    int id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read ID register: %d\n", id);
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and ALS
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        fprintf(stderr, "Failed to write to ENABLE register (PON)\n");
        return -1;
    }
    gpioDelay(3); // Wait for power-on (datasheet recommends 2.4ms)

    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Failed to write to ENABLE register (PON | AEN)\n");
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_154MS) < 0) {
        fprintf(stderr, "Failed to write to ATIME register\n");
        return -1;
    }

    return 0;
}

// Read color data from the sensor
color_data_t read_color_data() {
    color_data_t data;
    int status;

    status = i2cReadByteData(i2c_handle, TCS34725_CONTROL);
    if (status < 0) {
        fprintf(stderr, "Failed to read CONTROL register: %d\n", status);
        data.clear = 0; data.red = 0; data.green = 0; data.blue = 0;
        return data;
    }

    status = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    if (status < 0) {
        fprintf(stderr, "Failed to read CDATA register: %d\n", status);
        data.clear = 0; data.red = 0; data.green = 0; data.blue = 0;
        return data;
    }
    data.clear = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    if (status < 0) {
        fprintf(stderr, "Failed to read RDATA register: %d\n", status);
        data.red = 0; data.green = 0; data.blue = 0;
        return data;
    }
    data.red = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    if (status < 0) {
        fprintf(stderr, "Failed to read GDATA register: %d\n", status);
        data.green = 0; data.blue = 0;
        return data;
    }
    data.green = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_BDATA);
    if (status < 0) {
        fprintf(stderr, "Failed to read BDATA register: %d\n", status);
        data.blue = 0;
        return data;
    }
    data.blue = (uint16_t)status;

    return data;
}

// Format data into a CSV string
char* format_data(color_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0
    static char csv_string[100]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(csv_string, sizeof(csv_string), "%s,%u,%u,%u,%u\n", timestamp, data.clear, data.red, data.green, data.blue);
    return csv_string;
}

// Write data to CSV file
int write_to_csv(char* data) {
    if (fp == NULL) {
        fprintf(stderr, "CSV file not opened\n");
        return -1;
    }

    if (fputs(data, fp) == EOF) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }

    fflush(fp); // Ensure data is written immediately
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize sensor
    if (init_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Clear,Red,Green,Blue\n");
    }
    fflush(fp);

    // Main loop
    while (!terminate) {
        color_data_t color_data = read_color_data();
        char* csv_data = format_data(color_data);

        if (write_to_csv(csv_data) < 0) {
            fprintf(stderr, "Error writing data to CSV\n");
        }

        gpioDelay(500); // Sample every 500ms
    }

    // Cleanup
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

