#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define sunrise and sunset durations (in minutes)
#define SUNRISE_DURATION 60
#define SUNSET_DURATION 60

// Define daytime duration (in minutes)
#define DAYTIME_DURATION 360

// Define nighttime duration (in minutes)
#define NIGHTTIME_DURATION 864 - SUNRISE_DURATION - SUNSET_DURATION - DAYTIME_DURATION

// Define PWM frequency (in Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-1000)
#define PWM_RANGE 1000

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void set_relay_state(int relay_pin, int state);
void sunrise_phase();
void daytime_phase();
void sunset_phase();
void nighttime_phase();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
        program_running = 0;

        // Turn off all relays
        set_relay_state(RELAY1_PIN, 0);
        set_relay_state(RELAY2_PIN, 0);
        set_relay_state(RELAY3_PIN, 0);
        set_relay_state(RELAY4_PIN, 0);

        // Terminate pigpio library
        gpioTerminate();

        exit(0);
    }
}

// Function to set the state of a relay
void set_relay_state(int relay_pin, int state) {
    gpioWrite(relay_pin, state);
}

// Function to simulate sunrise
void sunrise_phase() {
    time_t start_time = time(NULL);
    time_t current_time;
    int duty_cycle = 0;
    int i;

    while (time(NULL) - start_time < SUNRISE_DURATION && program_running) {
        current_time = time(NULL);

        // Calculate the elapsed time in minutes
        float elapsed_time = (float)(current_time - start_time) / 60.0;

        // Map the elapsed time to the duty cycle (0-1000)
        duty_cycle = (int)(elapsed_time * PWM_RANGE);

        // Set the relay states (active-low)
        set_relay_state(RELAY1_PIN, (duty_cycle > 500) ? 1 : 0);
        set_relay_state(RELAY2_PIN, (duty_cycle > 500) ? 1 : 0);
        set_relay_state(RELAY3_PIN, (duty_cycle > 500) ? 1 : 0);
        set_relay_state(RELAY4_PIN, (duty_cycle > 500) ? 1 : 0);

        // Sleep for a short interval to control the PWM frequency
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay in microseconds
    }
}

// Function to simulate daytime
void daytime_phase() {
    time_t start_time = time(NULL);
    time_t current_time;
    int i;

    while (time(NULL) - start_time < DAYTIME_DURATION && program_running) {
        current_time = time(NULL);

        // Sleep for a long interval to simulate daytime
        gpioDelay(60000000); // Delay in microseconds (60 seconds)
    }
}

// Function to simulate sunset
void sunset_phase() {
    time_t start_time = time(NULL);
    time_t current_time;
    int duty_cycle = 1000;
    int i;

    while (time(NULL) - start_time < SUNSET_DURATION && program_running) {
        current_time = time(NULL);

        // Calculate the elapsed time in minutes
        float elapsed_time = (float)(current_time - start_time) / 60.0;

        // Map the elapsed time to the duty cycle (1000-0)
        duty_cycle = 1000 - (int)(elapsed_time * 10); // Decrease duty cycle

