#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_S 5
#define LOG_FILE "motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a motion event to the log file
void log_motion_event(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to capture video using raspivid
int capture_video() {
    char filename[50];
    char timestamp[25];
    time_t rawtime;
    struct tm *timeinfo;

    // Get the current timestamp
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 25, "%Y%m%d_%H%M%S", timeinfo);
    sprintf(filename, VIDEO_DIR "%s.h264", timestamp);

    // Construct the raspivid command
    char command[200];
    sprintf(command, "raspivid -o %s -t %d", filename, VIDEO_DURATION_S);

    // Execute the raspivid command
    int status = system(command);

    if (status == 0) {
        printf("Video captured successfully: %s\n", filename);
        return 0; // Success
    } else {
        fprintf(stderr, "Error: raspivid command failed with status %d\n", status);
        return -1; // Failure
    }
}

// Function to handle the SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register the SIGINT handler
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read the sensor value
        int sensor_value = gpioRead(GPIO_PIN);

        // Check for motion event (active-low)
        if (sensor_value == 0) {
            // Debounce the input
            gpioDelay(DEBOUNCE_MS * 1000); // Convert ms to microseconds

            // Re-read the sensor value after the debounce delay
            int debounced_value = gpioRead(GPIO_PIN);

            if (debounced_value == 0) {
                // Get the current timestamp
                char *timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    printf("Motion detected at: %s\n", timestamp);

                    // Log the motion event
                    log_motion_event(timestamp);

                    // Capture video
                    if (capture_video() != 0) {
                        fprintf(stderr, "Error: Video capture failed.\n");
                    }

                    // Free the allocated memory for the timestamp
                    free(timestamp);

                    // Wait for a short period to avoid capturing multiple videos for the same event
                    gpioDelay(1000 * 1000); // 1 second
                } else {
                    fprintf(stderr, "Error: Failed to get timestamp.\n");
                }
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(100 * 1000); // 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

