#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>

// MPU-6050 I2C address (AD0 low)
#define MPU6050_ADDRESS 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity scale factor for +/- 250 deg/s range
#define GYRO_SENSITIVITY 131.0f

// Global variables
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050(int fd);
int read_gyro_data(int fd, float *x, float *y, float *z);
void log_data(FILE *fp, long long timestamp, float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050(int fd) {
    int retries = 3;
    while (retries > 0) {
        // Wake up the MPU-6050 (clear sleep bit)
        if (wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0) < 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050. Retrying...\n");
            retries--;
            delay(100); // Wait before retrying
            continue;
        }

        // Configure gyroscope sensitivity (+/- 250 deg/s)
        if (wiringPiI2CWriteReg8(fd, GYRO_CONFIG, 0) < 0) {
            fprintf(stderr, "Error: Could not configure gyroscope. Retrying...\n");
            retries--;
            delay(100); // Wait before retrying
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "Error: Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Initialization failed
}

// Read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    int retries = 3;

    while (retries > 0) {
        // Read raw gyroscope data
        raw_x = (int16_t)((wiringPiI2CReadReg8(fd, GYRO_XOUT_H) << 8) | wiringPiI2CReadReg8(fd, GYRO_XOUT_L));
        raw_y = (int16_t)((wiringPiI2CReadReg8(fd, GYRO_YOUT_H) << 8) | wiringPiI2CReadReg8(fd, GYRO_YOUT_L));
        raw_z = (int16_t)((wiringPiI2CReadReg8(fd, GYRO_ZOUT_H) << 8) | wiringPiI2CReadReg8(fd, GYRO_ZOUT_L));

        // Check for I2C read errors
        if (raw_x == -1 || raw_y == -1 || raw_z == -1) {
            fprintf(stderr, "Error: I2C read error. Retrying...\n");
            retries--;
            delay(10); // Wait before retrying
            continue;
        }

        // Convert raw data to degrees per second
        *x = (float)raw_x / GYRO_SENSITIVITY;
        *y = (float)raw_y / GYRO_SENSITIVITY;
        *z = (float)raw_z / GYRO_SENSITIVITY;

        return 0; // Data read successfully
    }

    fprintf(stderr, "Error: Failed to read gyroscope data after multiple retries.\n");
    return -1; // Data read failed
}

// Log data to file
void log_data(FILE *fp, long long timestamp, float x, float y, float z) {
    fprintf(fp, "%lld,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi.\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPU6050_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C communication.\n");
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "Error: Failed to initialize MPU-6050.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }
    rewind(log_file);

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float x, y, z;
    struct timespec ts;
    long long timestamp;

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                timestamp = (long long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
            } else {
                fprintf(stderr, "Error: Failed to get timestamp.\n");
                timestamp = 0; // Use 0 as a default value
            }

            // Log data
            log_data(log_file, timestamp, x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data.\n");
        }

        // Delay for 10 milliseconds
        delay(10);
    }

    // Close log file
    fclose(log_file);

    return 0;
}

