// Define GPIO pins for the relays
#define RELAY_ZONE_1 4
#define RELAY_ZONE_2 17
#define RELAY_ZONE_3 27
#define RELAY_ZONE_4 22

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    program_running = 0;

    // Deactivate all relays
    gpioWrite(RELAY_ZONE_1, 1);
    gpioWrite(RELAY_ZONE_2, 1);
    gpioWrite(RELAY_ZONE_3, 1);
    gpioWrite(RELAY_ZONE_4, 1);

    // Close the log file
    FILE *log_file = fopen("irrigation_log.txt", "a");
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to set the state of a relay
void set_relay_state(int zone, int state) {
    int pin;
    switch (zone) {
        case 1:
            pin = RELAY_ZONE_1;
            break;
        case 2:
            pin = RELAY_ZONE_2;
            break;
        case 3:
            pin = RELAY_ZONE_3;
            break;
        case 4:
            pin = RELAY_ZONE_4;
            break;
        default:
            fprintf(stderr, "Invalid relay zone: %d\n", zone);
            return;
    }

    gpioWrite(pin, state);
}

// Function to log data to a file
void log_data(int moisture, int relay1_state, int relay2_state, int relay3_state, int relay4_state) {
    FILE *log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
