    gpioSetMode(RELAY_ZONE_1, PI_OUTPUT);
    gpioSetMode(RELAY_ZONE_2, PI_OUTPUT);
    gpioSetMode(RELAY_ZONE_3, PI_OUTPUT);
    gpioSetMode(RELAY_ZONE_4, PI_OUTPUT);

    // Seed the random number generator
    srand(time(NULL));

    // Main loop
    while (program_running) {
        // Generate random moisture value
        int moisture = rand() % 101;

        // Determine relay states based on moisture value
        int relay1_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay2_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay3_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay4_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;

        // Set relay states
        set_relay_state(1, relay1_state);
        set_relay_state(2, relay2_state);
        set_relay_state(3, relay3_state);
        set_relay_state(4, relay4_state);

        // Log the data
        log_data(moisture, relay1_state, relay2_state, relay3_state, relay4_state);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_ZONE_1, 1);
    gpioWrite(RELAY_ZONE_2, 1);
    gpioWrite(RELAY_ZONE_3, 1);
    gpioWrite(RELAY_ZONE_4, 1);
    gpioTerminate();

    return 0;
}

