#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE 4000.0 // 4 meters in cm
#define TIMEOUT_US 100000      // 100ms timeout in microseconds
#define MAX_PULSE_WIDTH 23000 // Maximum pulse width in microseconds (4m * 2)

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;
static volatile int echo_received = 0;
static volatile int echo_timeout = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick, void *userdata);
double calculate_distance(unsigned int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
void *sensor_thread(void *arg);
void echo_timeout_handler();

// Interrupt handler for ECHO pin
void echo_callback(int gpio, int level, unsigned int tick, void *userdata)
{
    if (level == 1) {
        pthread_mutex_lock(&mutex);
        start_tick = tick;
        echo_received = 1;
        pthread_mutex_unlock(&mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&mutex);
        end_tick = tick;
        echo_received = 1;
        pthread_mutex_unlock(&mutex);
    } else {
        pthread_mutex_lock(&mutex);
        echo_timeout = 1;
        pthread_mutex_unlock(&mutex);
    }
}

// Function to trigger the ultrasonic pulse
void trigger_pulse()
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIG_PIN, 0);
}

// Function to calculate distance in centimeters
double calculate_distance(unsigned int pulse_width)
{
    if (pulse_width > MAX_PULSE_WIDTH) {
        return -1.0; // Indicate error
    }
    return (pulse_width * 0.0343) / 2.0;
}

// Function to log the distance to a file
void log_distance(double distance)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    unsigned long long timestamp_ns = (unsigned long long)ts.tv_sec * 1000000000ULL + ts.tv_nsec;

    pthread_mutex_lock(&mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%llu,%.2f\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    }
    pthread_mutex_unlock(&mutex);
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Thread function for the sensor loop
void *sensor_thread(void *arg)
{
    while (running) {
        trigger_pulse();
        gpioDelay(200); // Wait 200ms between triggers

        pthread_mutex_lock(&mutex);
        if (log_file != NULL) {
            double distance = calculate_distance(end_tick - start_tick);
            if (distance >= 0) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Error: Invalid pulse width: %u\n", end_tick - start_tick);
            }
            start_tick = 0;
            end_tick = 0;
        }
        pthread_mutex_unlock(&mutex);

        if (echo_timeout) {
            echo_timeout_handler();
            echo_timeout = 0;
        }
    }
    return NULL;
}

// Timeout handler function
void echo_timeout_handler()
{
    fprintf(stderr, "Timeout error: Echo signal not received within %d us\n", TIMEOUT_US);
    pthread_mutex_lock(&mutex);
    if (log_file != NULL) {
        fprintf(log_file, "Timeout error: Echo signal not received within %d us\n", TIMEOUT_US);
        fflush(log_file);
    }
    pthread_mutex_unlock(&mutex);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Create sensor thread
    pthread_t sensor_thread_id;
    if (pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create sensor thread!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Wait for the sensor thread to finish (which it won't until a signal is received)
    pthread_join(sensor_thread_id, NULL);

    // Cleanup
    pthread_mutex_destroy(&mutex);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

