#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Default I2C address of the LIS3DH accelerometer
#define DEFAULT_I2C_ADDRESS 0x18

// Default free-fall threshold (0.2 g)
#define DEFAULT_FREE_FALL_THRESHOLD 0.2

// Default impact threshold (1.5 g)
#define DEFAULT_IMPACT_THRESHOLD 1.5

// Buzzer GPIO pin (BCM numbering)
#define BUZZER_PIN 17

// I2C bus number (typically 1 on Raspberry Pi)
#define I2C_BUS 1

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
float free_fall_threshold = DEFAULT_FREE_FALL_THRESHOLD;
float impact_threshold = DEFAULT_IMPACT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int init_lis3dh();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
int detect_free_fall(float magnitude);
int detect_impact(float magnitude);
void activate_buzzer();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize I2C interface
int init_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LIS3DH accelerometer
int init_lis3dh() {
    // Enable accelerometer and set data rate (100 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to g units (assuming +/- 2g full-scale range)
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Detect free-fall
int detect_free_fall(float magnitude) {
    return (magnitude < free_fall_threshold);
}

// Detect impact
int detect_impact(float magnitude) {
    return (magnitude > impact_threshold);
}

// Activate buzzer for 1 second
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(1000000);       // Wait for 1 second (1000000 microseconds)
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:f:i:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'f':
                free_fall_threshold = strtof(optarg, NULL);
                break;
            case 'i':
                impact_threshold = strtof(optarg, NULL);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-f free_fall_threshold] [-i impact_threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (detect_free_fall(magnitude)) {
                printf("Free-fall detected! Magnitude: %.2f g\n", magnitude);
            } else if (detect_impact(magnitude)) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                activate_buzzer();
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        gpioDelay(10000); // Delay for 10 ms (10000 microseconds)
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

