#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Motor 1 (X-axis) GPIO pins
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Motor 2 (Y-axis) GPIO pins
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Stepper motor steps per revolution (28BYJ-48)
#define STEPS_PER_REV 2048

// Gear ratio (1/64)
#define GEAR_RATIO 64.0

// Step delay (microseconds)
#define STEP_DELAY 1000

// Square side length (millimeters)
#define SQUARE_SIDE 50.0

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void motor1_step(int step);
void motor2_step(int step);
void move_motor1(int steps);
void move_motor2(int steps);
void move_square();
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, stopping motors and cleaning up...\n");
        program_running = 0;
        cleanup();
        exit(0);
    }
}

// Motor 1 step function
void motor1_step(int step) {
    gpioWrite(MOTOR1_IN1, (step & 1) ? 1 : 0);
    gpioWrite(MOTOR1_IN2, (step & 2) ? 1 : 0);
    gpioWrite(MOTOR1_IN3, (step & 4) ? 1 : 0);
    gpioWrite(MOTOR1_IN4, (step & 8) ? 1 : 0);
}

// Motor 2 step function
void motor2_step(int step) {
    gpioWrite(MOTOR2_IN1, (step & 1) ? 1 : 0);
    gpioWrite(MOTOR2_IN2, (step & 2) ? 1 : 0);
    gpioWrite(MOTOR2_IN3, (step & 4) ? 1 : 0);
    gpioWrite(MOTOR2_IN4, (step & 8) ? 1 : 0);
}

