#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Default I2C address and threshold
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0

// LIS3DH Registers
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
float threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int configure_lis3dh(int handle);
int read_acceleration(int handle, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize I2C
int init_i2c(int address) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return i2c_handle;
}

// Function to configure the LIS3DH
int configure_lis3dh(int handle) {
    // Configure CTRL1 register (ODR = 100 Hz, FS = ±2g, Low Power mode)
    if (i2cWriteByteData(handle, LIS3DH_REG_CTRL1, 0x77) < 0) { //0b01110111
        fprintf(stderr, "Failed to write to CTRL1 register\n");
        return -1;
    }

    // Configure CTRL4 register (Full scale = ±2g, High resolution)
    if (i2cWriteByteData(handle, LIS3DH_REG_CTRL4, 0x88) < 0) { //0b10001100
        fprintf(stderr, "Failed to write to CTRL4 register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH
int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, LIS3DH_REG_OUT_X_L, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to g units (assuming +/- 2g range and 12-bit resolution)
    *x = (float)raw_x / 16384.0f; // 2^15 = 32768, but we're using 12-bit
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", s, x, y, z);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                if (i2c_address != 0x18 && i2c_address != 0x19) {
                    fprintf(stderr, "Invalid I2C address. Using default 0x18.\n");
                    i2c_address = DEFAULT_I2C_ADDRESS;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0) {
                    fprintf(stderr, "Invalid threshold. Using default 2.0 g.\n");
                    threshold = DEFAULT_THRESHOLD;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c(i2c_address) < 0) {
        return 1;
    }

    // Configure LIS3DH
    if (configure_lis3dh(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    accelerometer_data_t accel_data;
    while (!terminate) {
        if (read_acceleration(i2c_handle, &accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Check for high acceleration
            if (fabs(accel_data.x) > threshold || fabs(accel_data.y) > threshold || fabs(accel_data.z) > threshold) {
                log_data(accel_data.x, accel_data.y, accel_data.z);
                system("sudo shutdown -h now");
                break; // Exit loop after shutdown command
            }
        } else {
            // Log error to file
            FILE *fp = fopen("/var/log/acceleration_errors.log", "a");
            if (fp != NULL) {
                time_t t = time(NULL);
                struct tm *tm = localtime(&t);
                char s[64];
                strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
                fprintf(fp, "%s, Error reading acceleration data\n", s);
                fclose(fp);
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

