#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_LED 22

// Define circular buffer size
#define BUFFER_SIZE 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Circular buffer
SensorReadings buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void update_buffer(int left, int center, int right);
int check_center_sensor(int *buffer, int buffer_size);
void activate_alert();
void move_forward();
void turn_left();
void turn_right();
void stop();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(ALERT_LED, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to update the circular buffer
void update_buffer(int left, int center, int right) {
    buffer[buffer_index].left = left;
    buffer[buffer_index].center = center;
    buffer[buffer_index].right = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check if the center sensor consistently detects no line
int check_center_sensor(int *buffer, int buffer_size) {
    int count = 0;
    for (int i = 0; i < buffer_size; i++) {
        if (buffer[i].center == 1) {
            count++;
        }
    }
    return count;
}

// Function to activate the alert LED/buzzer
void activate_alert() {
    gpioWrite(ALERT_LED, 1); // Turn on LED
    gpioDelay(2000);          // Wait for 2 seconds
    gpioWrite(ALERT_LED, 0); // Turn off LED
}

// Placeholder function for moving forward
void move_forward() {
    // In a real implementation, this would control the motors to move forward
    printf("Moving forward (placeholder)\n");
}

// Placeholder function for turning left
void turn_left() {
    // In a real implementation, this would control the motors to turn left
    printf("Turning left (placeholder)\n");
}

// Placeholder function for turning right
void turn_right() {
    // In a real implementation, this would control the motors to turn right
    printf("Turning right (placeholder)\n");
}

// Placeholder function for stopping
void stop() {
    // In a real implementation, this would stop the motors
    printf("Stopping (placeholder)\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs or output
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_LED, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR);
        int center = read_sensor(CENTER_SENSOR);
        int right = read_sensor(RIGHT_SENSOR);

        // Update the circular buffer
        update_buffer(left, center, right);

        // Check if the center sensor consistently detects no line
        if (check_center_sensor(buffer, BUFFER_SIZE)) {
            activate_alert();
        } else {
            // Move forward if center sensor detects a line
            if (center == 0) {
                move_forward();
            } else {
                // Turn left if left sensor detects a line
                if (left == 0) {
                    turn_left();
                } else {
                    // Turn right if right sensor detects a line
                    if (right == 0) {
                        turn_right();
                    } else {
                        // Stop if no line is detected by all sensors
                        stop();
                    }
                }
            }
        }

        // Delay for 10 milliseconds
        gpioDelay(10);
    }

    // Clean up and exit
    gpioWrite(ALERT_LED, 0); // Turn off LED
    gpioTerminate();          // Terminate pigpio
    return 0;
}

