#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define RELAY_GPIO 17
#define MAGNETIC_THRESHOLD 5.0 // mT
#define SAMPLE_INTERVAL 100 // ms
#define MAX_RETRIES 50
#define RETRY_DELAY 10 // ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_magnetic_field(float *magnetic_field);
int control_relay(int state);
int log_event(const char *event_type, float magnetic_field, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float magnetic_field;
    int relay_state;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize relay GPIO
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially off

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read magnetic field
        if (read_magnetic_field(&sensor_data.magnetic_field) == 0) {
            // Check if magnetic field exceeds threshold
            if (sensor_data.magnetic_field > MAGNETIC_THRESHOLD) {
                // Activate relay
                if (control_relay(1) == 0) {
                    sensor_data.relay_state = 1;
                } else {
                    fprintf(stderr, "Failed to activate relay\n");
                }
            } else {
                // Deactivate relay
                if (control_relay(0) == 0) {
                    sensor_data.relay_state = 0;
                } else {
                    fprintf(stderr, "Failed to deactivate relay\n");
                }
            }

            // Log event
            log_event("magnetic_field", sensor_data.magnetic_field, sensor_data.relay_state);
        } else {
            fprintf(stderr, "Failed to read magnetic field\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read magnetic field from Si7210
int read_magnetic_field(float *magnetic_field) {
    char buf[2];
    int16_t raw_data;
    int retries = 0;

    // Read two bytes from register 0x01 (example, adjust as needed)
    if (i2cReadI2CBlockData(i2c_handle, 0x01, buf, 2) != 2) {
        fprintf(stderr, "Failed to read magnetic field data\n");
        return 1;
    }

    // Combine the bytes to form a 16-bit value
    raw_data = (buf[0] << 8) | buf[1];

    // Convert raw data to mT (adjust scaling as needed based on Si7210 datasheet)
    *magnetic_field = (float)raw_data * 0.01; // Example scaling

    return 0;
}

// Control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write to relay GPIO\n");
        return 1;
    }
    return 0;
}

// Log events to file
int log_event(const char *event_type, float magnetic_field, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s - %s - Magnetic Field: %.2f mT, Relay State: %s\n",
            timestamp, event_type, magnetic_field, (relay_state == 1) ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();
}

