#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define BUFFER_SIZE 1024

// Global variables for signal handling
int server_fd = -1;
int client_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int setup_gpio();
int setup_socket();
int handle_client(int client_fd);
int parse_command(char *command);
int control_relay(int state);
int log_event(const char *message);
void signal_handler(int signum);

int main() {
    // Initialize syslog
    openlog("relay_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (setup_gpio() != 0) {
        syslog(LOG_ERR, "Failed to setup GPIO. Exiting.");
        closelog();
        return 1;
    }

    // Setup socket
    if (setup_socket() != 0) {
        syslog(LOG_ERR, "Failed to setup socket. Exiting.");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file. Exiting.");
        gpioTerminate();
        close(server_fd);
        close(client_fd);
        closelog();
        return 1;
    }

    // Main loop
    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            syslog(LOG_ERR, "Accept failed. Continuing.");
            continue; // Continue listening for new connections
        }

        syslog(LOG_INFO, "Connection accepted from %s:%d", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));

        handle_client(client_fd);

        close(client_fd);
    }

    return 0;
}

// Function to initialize GPIO
int setup_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Function to setup the socket
int setup_socket() {
    struct sockaddr_in server_addr;

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        syslog(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Bind failed");
        close(server_fd);
        return -1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        syslog(LOG_ERR, "Listen failed");
        close(server_fd);
        return -1;
    }

    syslog(LOG_INFO, "Server listening on port %d", PORT);
    return 0;
}

// Function to handle client connection
int handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    // Receive data from client
    bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Receive failed");
        return -1;
    } else if (bytes_received == 0) {
        syslog(LOG_INFO, "Client disconnected");
        return 0;
    }

    // Process the received command
    parse_command(buffer);

    // Close the client socket
    close(client_fd);
    return 0;
}

// Function to parse the command
int parse_command(char *command) {
    // Remove trailing whitespace
    size_t len = strlen(command);
    if (len > 0 && command[len - 1] == ' ') {
        command[len - 1] = '\0';
    }

    // Check if the command is "ON" or "OFF"
    if (strcmp(command, "ON") == 0 || strcmp(command, "off") == 0) {
        return 0; // Valid command
    } else {
        syslog(LOG_WARNING, "Invalid command: %s", command);
        return -1; // Invalid command
    }
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", GPIO_PIN);
        return -1;
    }
    return 0;
}

// Function to log events
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal %d received, shutting down...", signum);

    // Turn off the relay
    control_relay(0);

    // Close sockets
    if (client_fd != -1) {
        close(client_fd);
    }
    if (server_fd != -1) {
        close(server_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    closelog();
    exit(0);
}

