#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define FLOW_THRESHOLD 5.0
#define RELAY_GPIO 18
#define POLLING_INTERVAL_MS 100

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int bus, int addr);
int start_measurement(int i2c_handle);
int read_sensor_data(int i2c_handle, uint8_t *data, int count);
float calculate_flow_rate(uint8_t *data);
int validate_crc(uint8_t *data, int len);
int control_relay(int gpio_pin, int state);
int log_flow_rates(float flow1, float flow2);
void signal_handler(int signal);

// CRC-8 calculation function (pure function)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Function to start measurement on the sensor
int start_measurement(int i2c_handle) {
    uint8_t start_cmd[2] = {0x36, 0x08};
    int result = i2cWriteDevice(i2c_handle, (char *)start_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle, uint8_t *data, int count) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, count);
    if (bytes_read != count) {
        fprintf(stderr, "Error reading sensor data: %d bytes read (expected %d)\n", bytes_read, count);
        return -1;
    }
    return 0;
}

// Function to calculate flow rate from raw data
float calculate_flow_rate(uint8_t *data) {
    // Extract raw flow rate (2 bytes) and CRC (1 byte)
    int16_t raw_flow = (data[0] << 8) | data[1];
    uint8_t crc = data[2];

    // Validate CRC
    if (validate_crc(data, 3) != crc) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1.0; // Indicate error
    }

