    // Assuming a scaling factor of 0.01 ml/min per raw unit
    float flow_rate = (float)raw_flow * 0.01;
    return flow_rate;
}

// Function to validate CRC
int validate_crc(uint8_t *data, int len) {
    uint8_t crc_calculated = crc8(data, len);
    return (crc_calculated != data[len]);
}

