    printf("Received signal %d, shutting down...\n", signal);
    terminate = 1;

    // De-energize the relay
    control_relay(RELAY_GPIO, 0);

    // Close I2C handles
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Call pigpio cleanup function
    gpioTerminate();

    exit(0);
}

