#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define ENA_PIN 22
#define IN1_PIN 23
#define IN2_PIN 24

// Define constants
#define RAIN_THRESHOLD 3
#define RAIN_DEBOUNCE_TIME 600 // milliseconds
#define MOTOR_DURATION 5000 // milliseconds
#define POLL_INTERVAL 200 // milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;
int rain_detected_count = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int start);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("ERROR: pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins as output or input
    gpioSetMode(ENA_PIN, PI_OUTPUT);
    gpioSetMode(IN1_PIN, PI_OUTPUT);
    gpioSetMode(IN2_PIN, PI_OUTPUT);
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);

    // Enable pull-up resistor on the rain sensor pin
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
int control_motor(int start) {
    if (gpioWrite(ENA_PIN, PI_HIGH) != 0) {
        log_event("ERROR: Failed to enable motor");
        return -1;
    }

    if (gpioWrite(IN1_PIN, PI_HIGH) != 0) {
        log_event("ERROR: Failed to set IN1 high");
        return -1;
    }

    if (gpioWrite(IN2_PIN, PI_LOW) != 0) {
        log_event("ERROR: Failed to set IN2 low");
        return -1;
    }

    if (start) {
        if (gpioDelay(MOTOR_DURATION * 1000) != 0) {
            log_event("ERROR: Failed to delay motor run time");
            return -1;
        }
    } else {
        if (gpioWrite(ENA_PIN, PI_LOW) != 0) {
            log_event("ERROR: Failed to disable motor");
            return -1;
        }
        if (gpioWrite(IN1_PIN, PI_LOW) != 0) {
            log_event("ERROR: Failed to set IN1 low");
            return -1;
        }
        if (gpioWrite(IN2_PIN, PI_LOW) != 0) {
            log_event("ERROR: Failed to set IN2 low");
            return -1;
        }
    }

    return 0;
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);

    syslog(LOG_INFO, "%s", log_message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("INFO: Received signal, shutting down...");
}

// Cleanup function to release resources
void cleanup() {
    log_event("INFO: Cleaning up resources...");
    gpioWrite(ENA_PIN, PI_LOW);
    gpioWrite(IN1_PIN, PI_LOW);
    gpioWrite(IN2_PIN, PI_LOW);
    gpioTerminate();
    closelog();
}

int main() {
    // Open syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    log_event("INFO: Rain window control system started");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected == 0) { // Rain detected (LOW signal)
            rain_detected_count++;
            if (rain_detected_count >= RAIN_THRESHOLD) {
                log_event("INFO: Rain detected, closing window");
                if (control_motor(1) == 0) {
                    log_event("INFO: Motor started");
                    sleep(RAIN_DEBOUNCE_TIME);
                    if (read_rain_sensor() == 1) { // Check if rain stopped
                        log_event("INFO: Rain stopped, window closing complete");
                        rain_detected_count = 0; // Reset counter
                    }
                } else {
                    log_event("ERROR: Failed to start motor");
                }
            }
        } else { // No rain detected (HIGH signal)
            rain_detected_count = 0; // Reset counter
        }

        gpioDelay(POLL_INTERVAL * 1000); // Poll every POLL_INTERVAL milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

