                    lock_door();
                    gpioDelay(DEBOUNCE_DELAY);
                    stop_servo();
                }
            }
        }

        // Small delay to reduce CPU usage
        gpioDelay(1000); // 1ms
    }

    // Stop the servo before exiting
    stop_servo();

