#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define LOG_FILE "security_log.txt"

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int activate_relay();
int deactivate_relay();
int log_event(const char *event_type, double duration);
void signal_handler(int signal);

int main() {
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0; // Store the last state of the PIR sensor
    time_t start_time = 0; // Time when the relay was activated
    double duration = 0.0; // Duration the relay was active

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = read_pir_sensor();

        if (current_state == 1 && last_state == 0) {
            // Rising edge detected
            if (activate_relay() == 0) {
                start_time = time(NULL);
                duration = 60.0; // Set initial duration
            } else {
                fprintf(stderr, "Failed to activate relay.\n");
            }
        } else if (current_state == 0 && last_state == 1) {
            // Falling edge detected
            if (deactivate_relay() != 0) {
                fprintf(stderr, "Failed to deactivate relay.\n");
            }
            duration = 0.0; // Reset duration
        }

        last_state = current_state;
        gpioDelay(100); // Poll every 100ms
    }

    printf("Exiting gracefully.\n");
    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF state
    deactivate_relay();

    return 0;
}

int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

int activate_relay() {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate relay.\n");
        return 1;
    }
    return 0;
}

int deactivate_relay() {
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate relay.\n");
        return 1;
    }
    return 0;
}

int log_event(const char *event_type, double duration) {
    time_t now = time(NULL);
    struct tm *tstruct;
    char buf[80];
    double seconds_to_log = (duration > 60.0) ? 60.0 : duration; // Limit to 60 seconds

    tstruct = localtime(&now);
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }

    if (fprintf(log_file, "%s - %s - Duration: %.2f seconds\n", buf, event_type, seconds_to_log) < 0) {
        fprintf(stderr, "Failed to write to log file.\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;

    // Turn off the relay
    deactivate_relay();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

