#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_MS 200

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int mpr121_read_touch_status(int i2c_handle);
void relay_control(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configuration values
    uint8_t baseline_filter_config = 0x0B; // MHD=0x0B, NHD=0x0B, NCL=0x0B, FDL=0x0B
    uint8_t ffe_config = 0x0A; // FFI=0x0A, SFI=0x0A, CDT=0x0A
    uint8_t touch_config = 0x0C; // Enable 12 electrodes, Electrode 0 only
    uint8_t auto_config = 0x0F; // Auto config range

    // Write baseline filter configuration
    if (i2cWriteByteData(i2c_handle, 0x5B, baseline_filter_config) < 0) {
        fprintf(stderr, "Error: Failed to write baseline filter config\n");
        return -1;
    }

    // Write FFE configuration
    if (i2cWriteByteData(i2c_handle, 0x5C, ffe_config) < 0) {
        fprintf(stderr, "Error: Failed to write FFE config\n");
        return -1;
    }

    // Write touch configuration
    if (i2cWriteByteData(i2c_handle, 0x5D, touch_config) < 0) {
        fprintf(stderr, "Error: Failed to write touch config\n");
        return -1;
    }

    // Write auto config
    if (i2cWriteByteData(i2c_handle, 0x5E, auto_config) < 0) {
        fprintf(stderr, "Error: Failed to write auto config\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int i2c_handle) {
    int touch_status = i2cReadByteData(i2c_handle, 0x00);
    if (touch_status < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    return touch_status;
}

// Function to control the relay
void relay_control(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize relay to OFF state
    relay_control(RELAY_GPIO, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int touch_status = mpr121_read_touch_status(i2c_handle);
        if (touch_status >= 0) {
            if (touch_status & 0x01) { // Check if electrode 0 is touched
                relay_control(RELAY_GPIO, 1); // Turn relay ON
                gpioDelay(DEBOUNCE_MS * 1000); // Debounce
                relay_control(RELAY_GPIO, 0); // Turn relay OFF
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }
        gpioDelay(50 * 1000); // Check every 50ms
    }

    // Cleanup
    relay_control(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("MPR121 touch sensor relay control stopped.\n");
    return 0;
}

