            if (touch_status & 0x01) { // Check if electrode 0 is touched
                relay_control(RELAY_GPIO, 1); // Turn relay ON
                gpioDelay(DEBOUNCE_MS * 1000); // Debounce
                relay_control(RELAY_GPIO, 0); // Turn relay OFF
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }
        gpioDelay(50 * 1000); // Check every 50ms
    }

    // Cleanup
    relay_control(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("MPR121 touch sensor relay control stopped.\n");
    return 0;
}

