#define SERVO_RANGE (SERVO_MAX_PULSE - SERVO_MIN_PULSE)

// Define servo frequency (Hz)
#define SERVO_FREQUENCY 50

// Define PIR sensor read interval (milliseconds)
#define PIR_READ_INTERVAL 100

// Define log file path
#define LOG_FILE "security.log"

// Global variables
int server_fd, new_socket;
