int set_servo_angle(int angle);
int read_pir_sensor();
void cleanup();

// Logging function
void log_event(int priority, const char *format, ...)
{
    va_list args;
    va_start(args, format);
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s ", buf);
        vfprintf(log_file, format, args);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not initialized. Message: %s\n", format);
    }
    va_end(args);
}

// Error logging function
void log_error(const char *message)
{
    log_event(LOG_ERR, "%s", message);
}

// Warning logging function
void log_warning(const char *message)
{
    log_event(LOG_WARNING, "%s", message);
}

// Signal handler function
void signal_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        log_event(LOG_INFO, "Received signal %d, shutting down...", signum);
        terminate = 1;
    }
}

// GPIO initialization function
int init_gpio()
{
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN); // Pull-down resistor

    log_event(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Socket initialization function
int init_socket()
{
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_error("Socket creation failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_error("Setsockopt failed");
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_error("Bind failed");
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_error("Listen failed");
        return -1;
    }
    log_event(LOG_INFO, "Socket listening on port %d", PORT);
    return 0;
}

// Command parsing function
int parse_command(const char *command, int *angle)
{
    if (strncmp(command, "set_servo_angle ", 16) == 0) {
        if (sscanf(command + 16, "%d", angle) == 1) {
            if (*angle >= 0 && *angle <= 180) {
                return 0; // Success
            } else {
                log_error("Invalid angle. Angle must be between 0 and 180.");
                return -1; // Failure
            }
        } else {
            log_error("Invalid format. Angle must be an integer.");
            return -1; // Failure
        }
    } else {
        log_error("Invalid command");
        return -1; // Failure
    }
}

// Servo control function
int set_servo_angle(int angle)
{
    if (angle < 0 || angle > 180) {
        log_error("Invalid angle. Angle must be between 0 and 180.");
        return -1;
    }

    // Calculate pulse width
    int pulse_width = (int)(((float)angle / 180.0) * SERVO_RANGE);

    // Calculate on-time and off-time
    int on_time = (int)(((float)SERVO_RANGE / SERVO_FREQUENCY) * (pulse_width / SERVO_RANGE));
    int off_time = (int)(((float)SERVO_RANGE / SERVO_FREQUENCY) * ((1.0 - (pulse_width / SERVO_RANGE)) / SERVO_FREQUENCY));

