    return 0;
}

// PIR sensor reading function
int read_pir_sensor()
{
    int pir_value = gpioRead(PIR_PIN);
    if (pir_value < 0) {
        log_error("Failed to read PIR sensor value");
        return -1;
    }
    return pir_value;
}

// Cleanup function
void cleanup()
{
    log_event(LOG_INFO, "Cleaning up...");

