{
    char buffer[1024] = {0};
    int valread;
    int angle;
    int pir_result;

    // Receive command
    valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        log_error("Receive failed");
        close(client_socket);
