        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO23 as output for grow light control
    gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read lux value from BH1750 sensor
float read_bh1750() {
    int retries = 0;
    int result;
    unsigned char buf[2];

    while (retries < RETRY_COUNT) {
        // Send start measurement command (High Resolution Mode)
        if (i2cWriteByte(i2c_handle, 0x10) != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Wait for measurement (at least 180ms)
        gpioDelay(200000); // 200ms

        // Read 2 bytes of data
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Convert data to lux value
        unsigned int raw_value = (buf[0] << 8) | buf[1];
        float lux = (float)raw_value / 1.2;

        return lux;
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", RETRY_COUNT);
    return -1.0; // Indicate error
}

// Function to control the grow light based on lux value
void control_grow_light(float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(GROW_LIGHT_GPIO, 1); // Activate grow light
    } else {
        gpioWrite(GROW_LIGHT_GPIO, 0); // Deactivate grow light
    }
}

// Function to log data to file
void log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GROW_LIGHT_GPIO, 0); // Ensure grow light is off
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        return 1;
    }

    fprintf(stderr, "System initialized. Starting main loop...\n");

    // Main loop
    while (!terminate) {
        float lux = read_bh1750();

        if (lux >= 0) {
            log_data(lux);
            control_grow_light(lux);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Exiting.\n");
    return 0;
}

