#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Define constants
#define NUM_READINGS 5
#define SCALE_FACTOR 1.0 // Default scale factor
#define WEIGHT_THRESHOLD 1000.0 // Default weight threshold
#define SOLENOID_ACTIVATION_DURATION 200 // Solenoid activation duration in milliseconds
#define MAX_RETRIES 3

// Global variables
volatile sig_atomic_t program_running = 1;
double tare_value = 0.0;
double scale_factor = SCALE_FACTOR;
int weight_threshold = WEIGHT_THRESHOLD;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value, double tare_value, double scale_factor);
void activate_solenoid();
void deactivate_solenoid();
void tare_load_cell();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    program_running = 0;
}

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Wait for DOUT to go LOW
        int timeout = 1000; // Timeout after 1 second
        while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
            gpioDelay(1); // Wait 1 ms
            timeout--;
        }

        if (timeout == 0) {
            syslog(LOG_ERR, "HX711: Timeout waiting for DOUT to go LOW (attempt %d).", retries + 1);
            retries++;
            gpioDelay(10); // Small delay before retrying
            continue;
        }

        // Read 24 bits of data
        for (int i = 0; i < 24; i++) {
            gpioWrite(HX711_SCK, 1);
            gpioDelay(1); // Small delay
            data = data << 1;
            if (gpioRead(HX711_DOUT)) {
                data++;
            }
            gpioWrite(HX711_SCK, 0);
            gpioDelay(1); // Small delay
        }

        // Select Channel A gain 128
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay

        // Convert to two's complement
        if (data & 0x800000) {
            data |= 0xFF000000;
        }

        return data;
    }

    syslog(LOG_ERR, "HX711: Failed to read data after %d retries.", MAX_RETRIES);
    return -1; // Indicate error
}

// Function to calculate weight in grams
double calculate_weight(int raw_value, double tare_value, double scale_factor) {
    return (double)raw_value / scale_factor - tare_value;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Set HIGH
    gpioDelay(SOLENOID_ACTIVATION_DURATION); // Wait for specified duration
    deactivate_solenoid(); // Set LOW after activation
}

// Function to deactivate the solenoid lock
void deactivate_solenoid() {
    gpioWrite(SOLENOID_PIN, 0); // Set LOW
}

// Function to perform tare operation
void tare_load_cell() {
    int raw_value;
    double sum = 0.0;
    int num_readings = NUM_READINGS;

    syslog(LOG_INFO, "Starting tare operation...");

    while (num_readings > 0) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            syslog(LOG_ERR, "Tare: Failed to read HX711 data.");
            break;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
        num_readings--;
    }

    if (num_readings > 0) {
        tare_value = sum / num_readings;
        syslog(LOG_INFO, "Tare value: %.2f", tare_value);
    } else {
        syslog(LOG_ERR, "Tare: Failed to read enough data.");
    }
}

// Function to cleanup GPIO and close syslog
void cleanup() {
    syslog(LOG_INFO, "Cleaning up and exiting...");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog
}

int main(int argc, char *argv[]) {
    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Set solenoid pin LOW initially
    deactivate_solenoid();

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                weight_threshold = atof(optarg);
                break;
            case 's':
                scale_factor = atof(optarg);
                break;
            case 'd':
                duration_ms = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale_factor] [-d duration_ms]\n", argv[0]);
                syslog(LOG_ERR, "Invalid command-line argument: %s", optarg);
                return 1;
        }
    }

    // Perform tare operation
    tare_load_cell();

    // Main loop
    while (program_running) {
        double weight_sum = 0.0;
        int num_readings = NUM_READINGS;
        int raw_value;

        syslog(LOG_INFO, "Starting weight measurement...");

        while (num_readings > 0) {
            raw_value = read_hx711();
            if (raw_value == -1) {
                syslog(LOG_ERR, "Weight measurement: Failed to read HX711 data.");
                break;
            }
            weight_sum += calculate_weight(raw_value, tare_value, scale_factor);
            gpioDelay(10); // Small delay between readings
            num_readings--;
        }

        if (num_readings > 0) {
            double average_weight = weight_sum / num_readings;
            syslog(LOG_INFO, "Weight: %.2f grams", average_weight);
        } else {
            syslog(LOG_ERR, "Weight measurement: Failed to read enough data.");
        }

        if (average_weight > weight_threshold) {
            syslog(LOG_INFO, "Weight threshold exceeded. Activating solenoid.");
            activate_solenoid();
        }

        gpioDelay(duration_ms * 1000); // Delay for specified duration
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

