#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <getopt.h>
#include <pigpio.h>

// Default values
#define DEFAULT_MQTT_BROKER "localhost"
#define DEFAULT_MQTT_PORT 1883
#define DEFAULT_MQTT_CLIENT_ID "relay_controller_1"
#define DEFAULT_MQTT_KEEPALIVE 60
#define DEFAULT_GPIO_PIN 17
#define MQTT_TOPIC "home/lights/control"
#define GPIO_INIT_DELAY 1 // seconds

// Global variables
static volatile int running = 1;
static int gpio_pin = DEFAULT_GPIO_PIN;
static char *mqtt_broker = DEFAULT_MQTT_BROKER;
static int mqtt_port = DEFAULT_MQTT_PORT;
static char *mqtt_client_id = DEFAULT_MQTT_CLIENT_ID;
static int mqtt_keepalive = DEFAULT_MQTT_KEEPALIVE;
static char *mqtt_topic = MQTT_TOPIC;
static int gpio_initialized = 0;
static int mqtt_client_id_length = strlen(mqtt_client_id);

// Function prototypes
void signal_handler(int sig);
int initialize_gpio(int pin);
int connect_mqtt(char *broker, int port, char *client_id, int keepalive);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void on_error(struct mosquitto *mosq, void *userdata, int result);
void cleanup();
void log_message(int priority, const char *message);

// Signal handler
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Initialize GPIO
int initialize_gpio(int pin) {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpio_initialized = 1;

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0); // Initialize LOW
    log_message(LOG_INFO, "GPIO initialized on pin %d", pin);
    return 0;
}

// Connect to MQTT broker
int connect_mqtt(char *broker, int port, char *client_id, int keepalive) {
    int rc;
    struct mosquitto *mosq = NULL;

    mosquitto_lib_init();
    mosq = mosquitto_new(client_id, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Out of memory.");
        return -1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_error_callback_set(mosq, on_error);

    mosquitto_connect_data_t data;
    data.broker = broker;
    data.port = port;
    data.keepalive = keepalive;
    data.cleansession = 1;

    rc = mosquitto_connect(mosq, &data, NULL);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_subscribe(mosq, NULL, mqtt_topic, 0);

    return 0;
}

// MQTT connect callback
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "Connected to MQTT broker");
    } else {
        log_message(LOG_ERR, "Connect failed: %s", mosquitto_strerror(result));
    }
}

// MQTT disconnect callback
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_message(LOG_WARNING, "Disconnected unexpectedly: %s", mosquitto_strerror(rc));
    } else {
        log_message(LOG_INFO, "Disconnected cleanly");
    }
}

// MQTT message callback
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Received message on topic '%s': %s", message->topic, payload);
        log_message(LOG_INFO, log_message_buffer);

        if (strcmp(payload, "ON") == 0) {
            gpioWrite(gpio_pin, 1); // Relay ON
            log_message(LOG_INFO, "Relay ON");
        } else if (strcmp(payload, "OFF") == 0) {
            gpioWrite(gpio_pin, 0); // Relay OFF
            log_message(LOG_INFO, "Relay OFF");
        } else {
            log_message(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        log_message(LOG_ERR, "Empty message received");
    }
}

// MQTT error callback
void on_error(struct mosquitto *mosq, void *userdata, int result) {
    log_message(LOG_ERR, "MQTT error: %s", mosquitto_strerror(result));
}

// Cleanup function
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");

    if (mqtt_client_id_length > 0) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }

    if (gpio_initialized) {
        gpioWrite(gpio_pin, 0); // Ensure LOW on exit
        gpioTerminate();
    }

    closelog();
}

// Log message to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main(int argc, char *argv[]) {
    int opt;
    char *broker = DEFAULT_MQTT_BROKER;
    int port = DEFAULT_MQTT_PORT;
    int keepalive = DEFAULT_MQTT_KEEPALIVE;
    int rc;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "b:p:k:t:g:")) != -1) {
        switch (opt) {
            case 'b':
                broker = optarg;
                break;
            case 'p':
                port = atoi(optarg);
                break;
            case 'k':
                keepalive = atoi(optarg);
                break;
            case 't':
                mqtt_topic = optarg;
                break;
            case 'g':
                gpio_pin = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-b broker] [-p port] [-k keepalive] [-t topic] [-g gpio_pin]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(gpio_pin) != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    // Delay to allow GPIO to initialize
    sleep(GPIO_INIT_DELAY);

    // Connect to MQTT broker
    if (connect_mqtt(broker, port, mqtt_client_id, keepalive) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1); // -1 timeout means loop forever
        if (rc != MOSQ_ERR_SUCCESS) {
            log_message(LOG_WARNING, "MQTT loop error: %s", mosquitto_strerror(rc));
            sleep(5); // Wait before retrying
            if (connect_mqtt(broker, port, mqtt_client_id, keepalive) != 0) {
                log_message(LOG_ERR, "Failed to reconnect to MQTT broker");
                running = 0; // Exit loop if reconnection fails
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

