// Define GPIO pins for the servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define pulse width range (500-2500 us)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to set the pulse width for a servo
void set_servo_pulse(int gpio, int pulse_width_us) {
    if (gpioPWM(gpio, pulse_width_us) != 0) {
        fprintf(stderr, "Error setting PWM for GPIO %d\n", gpio);
    }
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set up the GPIO pins as outputs
int setup_gpio_output() {
    if (gpioSetMode(SERVO1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", SERVO1_PIN);
        return -1;
    }
    if (gpioSetMode(SERVO2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", SERVO2_PIN);
        return -1;
    }
    if (gpioSetMode(SERVO3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", SERVO3_PIN);
        return -1;
    }
    if (gpioSetMode(SERVO4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", SERVO4_PIN);
        return -1;
    }
    if (gpioSetMode(SERVO5_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", SERVO5_PIN);
        return -1;
    }
    return 0;
}

// Function to set up the PWM frequency
int setup_pwm_frequency() {
    if (gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", SERVO1_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(SERVO2_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", SERVO2_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", SERVO3_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(SERVO4_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", SERVO4_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(SERVO5_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", SERVO5_PIN);
        return -1;
    }
    return 0;
}

// Function to set up the GPIO pins and PWM frequency
int setup_gpio() {
    if (setup_gpio_output() != 0) {
        return -1;
    }
    if (setup_pwm_frequency() != 0) {
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Set up GPIO pins and PWM frequency
    if (setup_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Define servo positions
    int servo_positions[] = {1000, 1500, 2000, 500, 2500};
    int num_servos = sizeof(servo_positions) / sizeof(servo_positions[0]);

    // Iterate through the servo positions
    for (int i = 0; i < num_servos; i++) {
        // Set the pulse width for each servo
        set_servo_pulse(SERVO1_PIN, servo_positions[i]);
        set_servo_pulse(SERVO2_PIN, servo_positions[i]);
        set_servo_pulse(SERVO3_PIN, servo_positions[i]);
        set_servo_pulse(SERVO4_PIN, servo_positions[i]);
        set_servo_pulse(SERVO5_PIN, servo_positions[i]);

        // Wait for 3 seconds
        sleep(3);
    }

    // Stop PWM and terminate pigpio
    gpioTerminate();

    return 0;
}

