#include <signal.h>
#include <pigpio.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>
#include <math.h>

// Motor A GPIOs
#define MOTOR_A_PWM   17
#define MOTOR_A_DIR   18

// Motor B GPIOs
#define MOTOR_B_PWM   22
#define MOTOR_B_DIR   23

// Encoder A GPIOs
#define ENCODER_A_A   4
#define ENCODER_A_B   5

// Encoder B GPIOs
#define ENCODER_B_A   6
#define ENCODER_B_B   12

// Encoder Ticks per Revolution
#define ENCODER_TICKS 64

// Encoder Stall Detection Time (seconds)
#define STALL_TIMEOUT 2

// Global Variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
volatile int encoder_a_stalled = 0;
volatile int encoder_b_stalled = 0;
volatile int encoder_a_direction = 1; // 1 for forward, -1 for backward
volatile int encoder_b_direction = 1; // 1 for forward, -1 for backward
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
volatile int encoder_a_stall_start_time = 0;
volatile int encoder_b_stall_start_time = 0;

// Target RPM (RPM)
#define TARGET_RPM 50

// PI Controller Gains
#define KP 1.0
#define KI 0.1

// PWM Frequency (Hz)
#define PWM_FREQUENCY 10000

// Encoder Ticks per second
#define ENCODER_TICKS_PER_SECOND (PWM_FREQUENCY * ENCODER_TICKS)

// Mutex for protecting encoder tick counters
pthread_mutex_t encoder_mutex;

// Global flag for program termination
volatile sig_atomic_t program_running = 1;

// Function Prototypes
void motor_a_forward(int speed);
void motor_a_backward(int speed);
void motor_a_stop();
void motor_b_forward(int speed);
void motor_b_backward(int speed);
void motor_b_stop();
void encoder_isr_a(int gpio, int level, uint32_t tick, void *user);
void encoder_isr_b(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks);
double calculate_error(double setpoint, double actual);
double calculate_proportional(double error);
double calculate_integral(double error, double *integral);
void set_motor_speed(double pwm_a, double pwm_b);
void *encoder_thread(void *arg);
void signal_handler(int signal);

// Motor Control Functions
void motor_a_forward(int speed) {
    gpioWrite(MOTOR_A_DIR, 1); // Forward
    gpioPWM(MOTOR_A_PWM, speed);
}

void motor_a_backward(int speed) {
    gpioWrite(MOTOR_A_DIR, 0); // Backward
    gpioPWM(MOTOR_A_PWM, speed);
}

void motor_a_stop() {
    gpioWrite(MOTOR_A_DIR, 0); // Stop
    gpioPWM(MOTOR_A_PWM, 0);
}

void motor_b_forward(int speed) {
    gpioWrite(MOTOR_B_DIR, 1); // Forward
    gpioPWM(MOTOR_B_PWM, speed);
}

void motor_b_backward(int speed) {
    gpioWrite(MOTOR_B_DIR, 0); // Backward
    gpioPWM(MOTOR_B_PWM, speed);
}

void motor_b_stop() {
    gpioWrite(MOTOR_B_DIR, 0); // Stop
    gpioPWM(MOTOR_B_PWM, 0);
}

// Encoder Interrupt Service Routines (ISRs)
void encoder_isr_a(int gpio, int level, uint32_t tick, void *user) {
    pthread_mutex_lock(&encoder_mutex);
    if (level == PI_HIGH) {
        encoder_a_count++;
    } else if (level == PI_LOW) {
        encoder_a_count--;
    }
    pthread_mutex_unlock(&encoder_mutex);
}

void encoder_isr_b(int gpio, int level, uint32_t tick, void *user) {
    pthread_mutex_lock(&encoder_mutex);
    if (level == PI_HIGH) {
        encoder_b_count++;
    } else if (level == PI_LOW) {
        encoder_b_count--;
    }
    pthread_mutex_unlock(&encoder_mutex);
}

// RPM Calculation Function
double calculate_rpm(int ticks) {
    return (double)ticks / ENCODER_TICKS_PER_SECOND * 60.0;
}

// PI Controller Functions
double calculate_error(double setpoint, double actual) {
    return setpoint - actual;
}

double calculate_proportional(double error) {
    return KP * error;
}

double calculate_integral(double error, double *integral) {
    *integral += KI * error;
    return *integral;
}

// Motor Speed Setting Function
void set_motor_speed(double pwm_a, double pwm_b) {
    if (pwm_a > 255) pwm_a = 255;
    if (pwm_a < 0) pwm_a = 0;
    if (pwm_b > 255) pwm_b = 255;
    if (pwm_b < 0) pwm_b = 0;

    gpioPWM(MOTOR_A_PWM, (int)pwm_a);
    gpioPWM(MOTOR_B_PWM, (int)pwm_b);
}

// Encoder Thread Function
void *encoder_thread(void *arg) {
    while (program_running) {
        // Consume interrupts
        gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_isr_a, NULL);
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_isr_a, NULL);
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_isr_b, NULL);
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_isr_b, NULL);

        // Calculate RPM
        double rpm_a = calculate_rpm(encoder_a_count);
        double rpm_b = calculate_rpm(encoder_b_count);

        // Calculate Error
        double error = TARGET_RPM - rpm_a;

        // PI Control
        double proportional = calculate_proportional(error);
        double integral = calculate_integral(error, &integral_a);
        double pwm_a = proportional + integral;

        // Clamp PWM
        if (pwm_a > 255) pwm_a = 255;
        if (pwm_a < 0) pwm_a = 0;

        // Set Motor Speed
        set_motor_speed(pwm_a, pwm_b);

        // Update Encoder Counts
        encoder_a_count = 0;
        encoder_b_count = 0;

        // Print RPM and PWM
        printf("Motor A RPM: %.2f, Motor B RPM: %.2f, PWM A: %d, PWM B: %d\n", rpm_a, rpm_b, pwm_a, pwm_b);

        // Stall Detection
        if (encoder_a_stalled) {
            time_t now = time(NULL);
            if (difftime(now, encoder_a_stall_start_time) > STALL_TIMEOUT) {
                printf("WARNING: Encoder A Stall Detected!\n");
                encoder_a_stalled = 0;
            }
        }
        if (encoder_b_stalled) {
            time_t now = time(NULL);
            if (difftime(now, encoder_b_stall_start_time) > STALL_TIMEOUT) {
                printf("WARNING: Encoder B Stall Detected!\n");
                encoder_b_stalled = 0;
            }
        }

        // Sleep for 100ms
        gpioDelay(100000); // 100ms
    }
    return NULL;
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    program_running = 0;
    motor_a_stop();
    motor_b_stop();
    gpioTerminate();
    pthread_mutex_destroy(&encoder_mutex);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&encoder_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
