    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_PWM, 255);
    gpioSetPWMrange(MOTOR_B_PWM, 255);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Create encoder thread
    pthread_t encoder_thread_id;
    if (pthread_create(&encoder_thread_id, NULL, encoder_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder thread\n");
        gpioTerminate();
        pthread_mutex_destroy(&encoder_mutex);
