#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define LED_GPIO 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define Hysteresis 10
#define POLL_INTERVAL 5 // seconds
#define RELAY_DELAY 180 // milliseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
int read_bh1750(float *lux);
void control_led(int lux);
void log_data(float lux, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750(float *lux) {
    char config_mode = 0x10; // Continuous high resolution mode
    char buf[2];
    int result;

    // Send configuration command
    result = i2cWriteByte(i2c_handle, config_mode);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        log_data(-1, -1); // Log error
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(RELAY_DELAY);

    // Read two bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        log_data(-1, -1); // Log error
        return -1;
    }

    // Convert data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control the LED strip based on light level
void control_led(int lux) {
    static int relay_state = 0; // 0 = OFF, 1 = ON
    static int last_relay_state = 0;
    static int hysteresis_counter = 0;

    if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        relay_state = 1;
        hysteresis_counter = 0; // Reset hysteresis counter
    } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
        relay_state = 0;
        hysteresis_counter = 0; // Reset hysteresis counter
    } else if (lux > LUX_THRESHOLD_DAWN + Hysteresis && relay_state == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        relay_state = 1;
        hysteresis_counter = 0; // Reset hysteresis counter
    } else if (lux < LUX_THRESHOLD_DUSK - Hysteresis && relay_state == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
        relay_state = 0;
        hysteresis_counter = 0; // Reset hysteresis counter
    } else {
        hysteresis_counter++;
        if (hysteresis_counter >= Hysteresis) {
            gpioWrite(LED_GPIO, 1); // Turn LED on
            relay_state = 1;
            hysteresis_counter = 0; // Reset hysteresis counter
        }
    }

    if (relay_state != last_relay_state) {
        log_data(lux, relay_state);
        last_relay_state = relay_state;
    }
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C, GPIO, and logging
    if (init_i2c() != 0 || init_gpio() != 0 || init_logging() != 0) {
        gpioTerminate();
        return 1;
    }

    float lux;
    int relay_state;

    printf("Chicken coop monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            control_led(lux);
        } else {
            fprintf(stderr, "Failed to read light sensor data.\n");
            log_data(-1, -1); // Log error
        }

        gpioDelay(POLL_INTERVAL * 1000); // Delay for POLL_INTERVAL seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();
    fclose(log_file);

    printf("Chicken coop monitoring stopped.\n");
    return 0;
}

