#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Relay activation delay in milliseconds
#define RELAY_DELAY 500

// Global variable to track the relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
int log_relay_state(int state);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    return 0; // Indicate success
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error writing to relay pin\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to log the relay state with an ISO 8601 timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(stderr, "%s Relay: %s\n", timestamp, state == 1 ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error writing to stderr\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

