// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIME_MS 1000
#define LOG_FILE "water_flow.log"

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
float calculate_lpm(int pulse_count);
void control_solenoid(float lpm);
void log_data(float lpm, int solenoid_state);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine for the flow sensor
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) { // Rising edge
        pulse_count++;
    }
}

// Function to calculate LPM from pulse count
float calculate_lpm(int pulse_count) {
    return (float)pulse_count / PULSES_PER_LITER * 60.0; // LPM
}

// Function to control the solenoid valve
void control_solenoid(float lpm) {
    if (lpm > LPM_THRESHOLD_HIGH) {
        gpioWrite(SOLENOID_GPIO, 0); // Close the valve
        printf("Closing solenoid valve (LPM: %.2f > %.2f)\n", lpm, LPM_THRESHOLD_HIGH);
    } else if (lpm < LPM_THRESHOLD_LOW) {
        gpioWrite(SOLENOID_GPIO, 1); // Open the valve
        printf("Opening solenoid valve (LPM: %.2f < %.2f)\n", lpm, LPM_THRESHOLD_LOW);
    }
}

// Function to log data to a file
void log_data(float lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Could not write to log file.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(SOLENOID_GPIO, 1); // Open the valve on shutdown
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&mutex);
    gpioTerminate();
    exit(0);
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);
    gpioWrite(SOLENOID_GPIO, 1); // Initialize solenoid to open

    // Set up interrupt on rising edge of the flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    gpioWrite(SOLENOID_GPIO, 1); // Ensure valve is open on exit
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&mutex);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Lock the mutex before accessing the pulse count
        pthread_mutex_lock(&mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count after reading
        pthread_mutex_unlock(&mutex);

        float lpm = calculate_lpm(current_pulse_count);
        control_solenoid(lpm);
        log_data(lpm, gpioRead(SOLENOID_GPIO));

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    cleanup();
    return 0;
}

