#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Configuration file path
#define CONFIG_FILE "config.ini"

// Default values
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_SENSOR_GPIO 23
#define DEFAULT_SERVO_GPIO 18
#define DEFAULT_TIMEOUT_MS 1000

// Global variables (minimize usage)
static int server_port = DEFAULT_SERVER_PORT;
static char server_ip[INET_ADDRSTRLEN] = DEFAULT_SERVER_IP;
static int sensor_gpio = DEFAULT_SENSOR_GPIO;
static int servo_gpio = DEFAULT_SERVO_GPIO;
static int timeout_ms = DEFAULT_TIMEOUT_MS;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static int socket_desc;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Structure to hold dispensing event data
typedef struct {
    time_t timestamp;
    double target_weight;
    double actual_weight;
    char error_message[256];
} dispensing_event_t;

// Function prototypes
int load_configuration();
int initialize_gpio();
int initialize_socket();
int handle_client(int client_socket);
int dispense_ingredient(double target_weight);
double read_weight();
int set_servo_angle(double angle);
int log_event(const char *event_type, double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signum);
void cleanup();

// HX711 communication functions
int hx711_init(int data_pin, int clock_pin, int timeout_ms);
int hx711_read_raw(int data_pin, int clock_pin, int timeout_ms);
double hx711_calibrate(int known_weight);
double hx711_read_weight(int data_pin, int clock_pin, int timeout_ms);

// Function to load configuration from file
int load_configuration() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s. Using default values.\n", CONFIG_FILE);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, INET_ADDRSTRLEN - 1);
                server_ip[INET_ADDRSTRLEN - 1] = '\0'; // Ensure null termination
            } else if (strcmp(key, "sensor_gpio") == 0) {
                sensor_gpio = atoi(value);
            } else if (strcmp(key, "servo_gpio") == 0) {
                servo_gpio = atoi(value);
            } else if (strcmp(key, "timeout_ms") == 0) {
                timeout_ms = atoi(value);
            } else if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            }
        }
    }

    fclose(fp);
    printf("Configuration loaded: port=%d, ip=%s, sensor_gpio=%d, servo_gpio=%d, timeout=%d, calibration_factor=%.2f\n",
           server_port, server_ip, sensor_gpio, servo_gpio, timeout_ms, calibration_factor);
    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(sensor_gpio, PI_INPUT);
    gpioSetMode(servo_gpio, PI_OUTPUT);

    return 0;
}

// Function to initialize the socket
int initialize_socket() {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((socket_desc = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port 12345
    if (setsockopt(socket_desc, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(server_port);

    // Forcefully attaching socket to the port 12345
    if (bind(socket_desc, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        return -1;
    }
    if (listen(socket_desc, 3) < 0) {
        perror("listen");
        return -1;
    }
    printf("Listening on port %d...\n", server_port);
    return 0;
}

// Function to handle client connection
int handle_client(int client_socket) {
    char buffer[1024] = {0};
    int read_size;

    // Receive message from client
    while ((read_size = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[read_size] = '\0';
        printf("Received: %s\n", buffer);

        // Parse the received message
        double target_weight;
        if (sscanf(buffer, "TARGET_WEIGHT=%lf", &target_weight) == 1) {
            printf("Target weight: %lf grams\n", target_weight);

            // Dispense the ingredient
            double actual_weight = dispense_ingredient(target_weight);
            printf("Actual weight: %lf grams\n", actual_weight);

            // Log the dispensing event
            log_event("dispensing", target_weight, actual_weight, NULL);
        } else {
            fprintf(stderr, "Error: Invalid message format\n");
            log_event("error", 0.0, 0.0, "Invalid message format");
        }
    }

    if (read_size == 0) {
        printf("Client disconnected\n");
    } else if (read_size == -1) {
        perror("recv failed");
        log_event("error", 0.0, 0.0, "recv failed");
    }

    close(client_socket);
    return 0;
}

// Function to dispense the ingredient
double dispense_ingredient(double target_weight) {
    double actual_weight = read_weight();
    if (actual_weight < 0) {
        return actual_weight; // Return error value
    }

    // Calculate pulse width based on target weight
    double pulse_width = (target_weight - actual_weight) * 1000.0 + 1000.0; // Map to 1000-2000 us

    // Set servo angle
    if (set_servo_angle(pulse_width / 1000.0) != 0) {
        return actual_weight; // Return error value
    }

    // Wait for 1 second
    gpioDelay(1000); // Delay in milliseconds

    // Read weight again after stabilization
    actual_weight = read_weight();
    if (actual_weight < 0) {
        return actual_weight; // Return error value
    }

    return actual_weight;
}

// Function to read weight from HX711
double read_weight() {
    int data = hx711_read_raw(sensor_gpio, servo_gpio, timeout_ms);
    if (data < 0) {
        return -1.0; // Indicate error
    }

    // Convert raw data to weight (example calibration)
    double weight = (double)data * calibration_factor; // Replace with actual calibration formula
    return weight;
}

// Function to read raw data from HX711
int hx711_read_raw(int data_pin, int clock_pin, int timeout_ms) {
    int data = 0;
    int attempts = 0;

    // Wait for the HX711 to be ready
    while (gpioRead(data_pin) == 1) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        attempts++;
        if (attempts > timeout_ms) {
            fprintf(stderr, "Error: HX711 timeout\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // 1 us clock pulse
        data = data << 1;
        if (gpioRead(data_pin)) {
            data++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1); // 1 us clock pulse
    }

    // Apply the 25th clock pulse for gain selection (default gain = 128)
    gpioWrite(clock_pin, 1);
    gpioDelay(1); // 1 us clock pulse
    gpioWrite(clock_pin, 0);
    gpioDelay(1); // 1 us clock pulse

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate the HX711
double hx711_calibrate(int known_weight) {
    // Placeholder for calibration logic
    // Replace with actual calibration procedure
    // This example assumes a simple linear relationship
    return known_weight / 1000.0; // Example calibration factor
}

// Function to read weight after stabilization
double hx711_read_weight(int data_pin, int clock_pin, int timeout_ms) {
    int data = hx711_read_raw(data_pin, clock_pin, timeout_ms);
    if (data < 0) {
        return -1.0; // Indicate error
    }
    return (double)data * calibration_factor; // Apply calibration factor
}

// Function to set servo angle
int set_servo_angle(double angle) {
    if (angle < 1000.0 || angle > 2000.0) {
        fprintf(stderr, "Error: Angle out of range (1000-2000)\n");
        return -1;
    }

    // Convert angle to pulse width (SG90 servo)
    int pulse_width_us = (int)(angle * 1000.0 + 1000.0); // Map to 1000-2000 us

    gpioServo(servo_gpio, pulse_width_us);
    return 0;
}

// Function to log dispensing events
int log_event(const char *event_type, double target_weight, double actual_weight, const char *error_message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %s, %.2f, %.2f, %s\n", timestamp, event_type, target_weight, actual_weight, error_message);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (socket_desc > 0) {
        close(socket_desc);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
