    log_file = fopen("dispensing_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Starting dispensing service...\n");

    // Main loop
    while (!terminate) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_socket = accept(socket_desc, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            perror("accept failed");
            continue; // Continue listening for new connections
        }

        printf("Connection accepted\n");
        handle_client(client_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

