#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_MS 50

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    gpioWrite(RELAY_GPIO, 1); // Turn relay OFF
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log the relay state change with timestamp
void log_relay_state(int state) {
    char timestamp[20];
    get_timestamp(timestamp);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEBOUNCE_MS;

    // Check for command-line argument for debounce interval
    if (argc > 1) {
        debounce_ms = atoi(argv[1]);
        if (debounce_ms <= 0) {
            fprintf(stderr, "Error: Debounce interval must be a positive integer.\n");
            return 1;
        }
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_GPIO, 1);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 1; // Assume no touch initially (HIGH)
    int current_touch_state = 1; // Assume no touch initially (HIGH)
    int last_debounce_time = 0;

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_touch_state = gpioRead(TOUCH_SENSOR_GPIO);

        if (current_touch_state == 0 && last_touch_state == 1) {
            // Rising edge detected
            gpioWrite(RELAY_GPIO, 0); // Turn relay ON
            log_relay_state(0);
            gpioDelay(debounce_ms * 1000); // Debounce
        } else if (current_touch_state == 1 && last_touch_state == 0) {
            // Falling edge detected (optional, but can be used for other logic)
            gpioWrite(RELAY_GPIO, 1); // Turn relay OFF
            log_relay_state(1);
            gpioDelay(debounce_ms * 1000); // Debounce
        }

        last_touch_state = current_touch_state;
        last_debounce_time = gpioTick();
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_GPIO, 1); // Turn relay OFF
    gpioTerminate(); // Release GPIO resources

    return 0;
}

