#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD (1000000 / PWM_FREQUENCY) // microseconds
#define MIN_PULSE_WIDTH 500 // us
#define MAX_PULSE_WIDTH 2500 // us
#define STEP_SIZE 10 // degrees
#define MIN_ANGLE 0
#define MAX_ANGLE 180

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
}

int main() {
    int angle;
    int pulse_width;
    int current_angle = 90;
    int previous_angle = 90;
    int angle_step = STEP_SIZE;
    int current_pulse_width = 1500; // Initial pulse width for 90 degrees
    int previous_pulse_width = 1500;
    int current_direction = 1; // 1 for increment, -1 for decrement
    int raw_input;
    struct termios old_termios, new_termios;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Save terminal settings
    if (tcgetattr(STDIN_FILENO, &old_termios) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return 1;
    }

    // Set raw input
    new_termios.c_lflag &= ~(ICANON | ECHO);
    new_termios.c_cc[VMIN] = 0;  // Read at least 0 characters
    new_termios.c_cc[VTIME] = 5; // Wait for 0.5 seconds
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Servo control started. Press '+' to increase, '-' to decrease, 'q' to quit.\n");

    while (program_running) {
        // Read keyboard input
        raw_input = getchar();

        if (raw_input == '+') {
            current_direction = 1;
            angle += STEP_SIZE;
            if (angle > MAX_ANGLE) {
                angle = MAX_ANGLE;
                current_direction = -1;
            }
        } else if (raw_input == '-') {
            current_direction = -1;
            angle -= STEP_SIZE;
            if (angle < MIN_ANGLE) {
                angle = MIN_ANGLE;
                current_direction = 1;
            }
        } else if (raw_input == 'q') {
            program_running = 0;
        } else if (raw_input == '\n') {
            // Handle newline character (already processed by getchar)
            continue;
        } else {
            // Ignore other characters
            continue;
        }

        // Calculate pulse width based on angle
        pulse_width = current_pulse_width + (current_angle - previous_angle) * (current_pulse_width - previous_pulse_width) / 90;

        // Clamp pulse width
        if (pulse_width < MIN_PULSE_WIDTH) {
            pulse_width = MIN_PULSE_WIDTH;
        } else if (pulse_width > MAX_PULSE_WIDTH) {
            pulse_width = MAX_PULSE_WIDTH;
        }

        // Set servo position
        if (gpioPWM(SERVO_PIN, pulse_width) != 0) {
            fprintf(stderr, "Error setting PWM: %d\n", pulse_width);
            program_running = 0; // Stop on error
        }

        // Update previous angle and pulse width
        previous_angle = current_angle;
        previous_pulse_width = pulse_width;

        // Print angle
        printf("Angle: %d\n", current_angle);
    }

    // Stop PWM pulses
    gpioPWM(SERVO_PIN, 0);

    // Restore terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &old_termios);

    // Terminate pigpio
    gpioTerminate();

    printf("Servo control stopped.\n");
    return 0;
}

