#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_INTERVAL_SEC 5
#define NUM_PULSES 1000 // Number of pulses to count for RPM calculation

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulses);
void log_rpm(double rpm);
void signal_handler(int signal);
int setup();
void cleanup();

// Structure to pass data to the thread
typedef struct {
    int gpio_pin;
    int *pulse_count;
    pthread_mutex_t *mutex;
} thread_data_t;

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;

    if (diff > DEBOUNCE_MS * 1000) { // Convert ms to microseconds
        pthread_mutex_lock(&(*thread_data_t*)user_data->mutex);
        (*thread_data_t*)user_data->pulse_count++;
        pthread_mutex_unlock(&(*thread_data_t*)user_data->mutex);
        last_tick = tick;
    }
}

// Function to calculate RPM
double calculate_rpm(int pulses) {
    double rpm = (double)pulses / NUM_PULSES * 60.0;
    return rpm;
}

// Function to log RPM to file
void log_rpm(double rpm) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", buf, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Setup function to initialize GPIO and logging
int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    // Open log file
    log_file = fopen("motor_rpm.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main() {
    thread_data_t thread_data;
    thread_data.gpio_pin = GPIO_PIN;
    thread_data.pulse_count = &pulse_count;
    thread_data.mutex = &pulse_mutex;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    // Create the thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, pulse_counter, &thread_data) != 0) {
        fprintf(stderr, "Error creating thread!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        sleep(LOG_INTERVAL_SEC);

        // Calculate RPM
        double rpm = calculate_rpm(pulse_count);

        // Log RPM
        log_rpm(rpm);

        // Reset pulse count
        pulse_count = 0;
    }

    // Wait for the thread to finish
    pthread_join(thread_id, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

// Thread function to count pulses
void *pulse_counter(void *arg) {
    thread_data_t *data = (thread_data_t *)arg;
    int *pulse_count_ptr = data->pulse_count;
    while (running) {
        // Do nothing, just wait for interrupts
        sleep(1); // Sleep for 1 second to reduce CPU usage
    }
    return NULL;
}

