#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Relay activation time in seconds
#define RELAY_ACTIVATION_TIME 5

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_touch_sensor();
void control_relay(int state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the relay
void control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error writing to relay pin %d\n", RELAY_PIN);
        cleanup();
        exit(1);
    }
    relay_state = state;
}

// Cleanup function
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    control_relay(0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected) {
            // Debounce
            gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds

            // Re-read after debounce
            if (read_touch_sensor() == 1) {
                // Toggle relay state
                control_relay(!relay_state);

                // Check if relay should be deactivated after activation time
                if (relay_state == 1) {
                    gpioDelay(RELAY_ACTIVATION_TIME * 1000); // Convert seconds to microseconds
                    control_relay(0);
                }
            }
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    cleanup();
    return 0;
}

