// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define PWM frequency
#define PWM_FREQUENCY 1000 // Hz

// Define proportional gain
#define KP 1.0

// Define target flow rate (L/min)
float target_flow_rate;

// Define log file name
#define LOG_FILE "flow_log.csv"

// Global variables
FILE *log_file;
volatile int pulse_count = 0;
volatile int running = 1;

// Function prototypes
int initialize_gpio();
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
float calculate_duty_cycle(float flow_rate);
void set_valve_position(int duty_cycle);
void log_data(float flow_rate, int duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Enable valve
    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PWM_PIN, 255);

    return 0;
}

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pulse_count++;
}

// Function to calculate duty cycle based on flow rate
float calculate_duty_cycle(float flow_rate) {
    float error = flow_rate - target_flow_rate;
    float duty_cycle = KP * error;

    // Clamp duty cycle to 0-255 range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to set valve position using PWM
void set_valve_position(int duty_cycle) {
    gpioPWM(VALVE_PWM_PIN, duty_cycle);
}

// Function to log data to CSV file
void log_data(float flow_rate, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    // Disable valve
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioPWM(VALVE_PWM_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_L/min>\n", argv[0]);
        return 1;
    }

    // Parse target flow rate
    char *endptr;
    target_flow_rate = strtof(argv[1], &endptr);
    if (*endptr != '\0') {
        fprintf(stderr, "Invalid target flow rate: %s\n", argv[1]);
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register interrupt handler for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read pulse count
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count

        // Calculate flow rate (L/min) - Example conversion (adjust as needed)
        float flow_rate = (float)current_pulse_count * 0.01; // Example scaling factor

        // Calculate duty cycle
        int duty_cycle = (int)calculate_duty_cycle(flow_rate);

        // Set valve position
        set_valve_position(duty_cycle);

        // Log data
        log_data(flow_rate, duty_cycle);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

