void cleanup_gpio();

// Structure to pass data to the encoder thread
typedef struct {
    int ena_pin;
    int in1_pin;
    int in2_pin;
    int a_pin;
    int b_pin;
} motor_config_t;

// Thread function for encoder 1
void *encoder1_thread(void *arg) {
    motor_config_t *config = (motor_config_t *)arg;
    int ena_pin = config->ena_pin;
    int in1_pin = config->in1_pin;
    int in2_pin = config->in2_pin;
    int a_pin = config->a_pin;
    int b_pin = config->b_pin;

    gpioSetISRFuncEx(a_pin, BOTH_EDGES, 0, encoder1_isr, NULL);
    gpioSetISRFuncEx(b_pin, BOTH_EDGES, 0, encoder1_isr, NULL);

    while (running) {
        gpioDelay(1000); // Sleep for 1ms to reduce CPU usage
    }

    pthread_exit(NULL);
}

// Thread function for encoder 2
void *encoder2_thread(void *arg) {
    motor_config_t *config = (motor_config_t *)arg;
    int enb_pin = config->enb_pin;
    int in3_pin = config->in3_pin;
    int in4_pin = config->in4_pin;
    int a_pin = config->a_pin;
    int b_pin = config->b_pin;

    gpioSetISRFuncEx(a_pin, BOTH_EDGES, 0, encoder2_isr, NULL);
    gpioSetISRFuncEx(b_pin, BOTH_EDGES, 0, encoder2_isr, NULL);

    while (running) {
        gpioDelay(1000); // Sleep for 1ms to reduce CPU usage
    }

    pthread_exit(NULL);
}

// Interrupt Service Routines (ISRs)
void encoder1_isr(int gpio, int level, uint32_t tick, void *user_data) {
    static int last_level = 0;
    int current_level = level;

    if (current_level != last_level) {
        if (current_level == 1) {
            encoder1_count++;
        } else if (current_level == 0) {
            encoder1_count--;
        }
        last_level = current_level;
    }
}

void encoder2_isr(int gpio, int level, uint32_t tick, void *user_data) {
    static int last_level = 0;
    int current_level = level;

    if (current_level != last_level) {
        if (current_level == 1) {
            encoder2_count++;
        } else if (current_level == 0) {
            encoder2_count--;
        }
        last_level = current_level;
    }
}

// PID Control Function
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error, double dt) {
    double error = setpoint - actual_value;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Logging Function
void log_data(double motor1_speed, double motor2_speed, double pid1_output, double pid2_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, motor1_speed, motor2_speed, pid1_output, pid2_output);
    fflush(log_file);
}

// Motor Control Functions
void motor1_forward(double duty_cycle) {
    gpioWrite(MOTOR1_IN1, 1);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, duty_cycle);
}

void motor1_backward(double duty_cycle) {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 1);
    gpioPWM(MOTOR1_ENA, duty_cycle);
}

void motor1_stop() {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, 0);
}

void motor2_forward(double duty_cycle) {
    gpioWrite(MOTOR2_IN3, 1);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, duty_cycle);
}

void motor2_backward(double duty_cycle) {
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 1);
    gpioPWM(MOTOR2_ENB, duty_cycle);
}

void motor2_stop() {
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, 0);
}

// Setup GPIO
void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    // Motor 1
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR1_A, PI_INPUT);
    gpioSetMode(MOTOR1_B, PI_INPUT);
    gpioSetPullUpDown(MOTOR1_A, PI_PUD_UP);
    gpioSetPullUpDown(MOTOR1_B, PI_PUD_UP);

    // Motor 2
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(MOTOR2_A, PI_INPUT);
    gpioSetMode(MOTOR2_B, PI_INPUT);
    gpioSetPullUpDown(MOTOR2_A, PI_PUD_UP);
    gpioSetPullUpDown(MOTOR2_B, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Initialize mutexes
    if (pthread_mutex_init(&encoder_mutex1, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed for encoder 1\n");
        gpioTerminate();
        exit(1);
    }
    if (pthread_mutex_init(&mutex2, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed for encoder 2\n");
        pthread_mutex_destroy(&encoder_mutex1);
        gpioTerminate();
        exit(1);
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&encoder_mutex1);
        pthread_mutex_destroy(&mutex2);
        gpioTerminate();
        exit(1);
    }
    fprintf(log_file, "Timestamp,Motor1_Speed,Motor2_Speed,PID1_Output,PID2_Output\n");
    fflush(log_file);
}

// Cleanup GPIO
void cleanup_gpio() {
    motor1_stop();
    motor2_stop();
    gpioTerminate();
    fclose(log_file);
    pthread_mutex_destroy(&encoder_mutex1);
    pthread_mutex_destroy(&mutex2);
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    running = 0;
    motor1_stop();
    motor2_stop();
    cleanup_gpio();
    exit(0);
}

int main() {
    motor_config_t motor1_config = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR1_A, MOTOR1_B};
    motor_config_t motor2_config = {MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4, MOTOR2_A, MOTOR2_B};

    setup_gpio();

    pthread_t encoder1_thread_id, encoder2_thread_id;
    if (pthread_create(&encoder1_thread_id, NULL, encoder1_thread, &motor1_config) != 0) {
        fprintf(stderr, "Error creating encoder 1 thread\n");
        cleanup_gpio();
        return 1;
    }
    if (pthread_create(&encoder2_thread_id, NULL, encoder2_thread, &motor2_config) != 0) {
        fprintf(stderr, "Error creating encoder 2 thread\n");
        cleanup_gpio();
        return 1;
    }

    double motor1_speed = 0.0;
    double motor2_speed = 0.0;
    double pid1_output = 0.0;
    double pid2_output = 0.0;
    double dt = 0.01; // 100ms sample time

    while (running) {
        // Read encoder counts
        pthread_mutex_lock(&encoder_mutex1);
        int current_count = encoder1_count;
        encoder1_count = 0; // Reset for next sample
        pthread_mutex_unlock(&encoder_mutex1);

        pthread_mutex_lock(&mutex2);
        int current_count = encoder2_count;
        encoder2_count = 0; // Reset for next sample
        pthread_mutex_unlock(&mutex2);

        // Calculate motor speeds (RPM)
        motor1_speed = (double)current_count * 60000.0 / dt; // Assuming 360 pulses per revolution
        motor2_speed = (double)current_count * 60000.0 / dt; // Assuming 360 pulses per revolution

        // PID Control
        pid1_output = pid_control(motor1_speed, TARGET_SPEED, &motor1_speed_integral, &motor1_speed_previous_error, dt);
        pid2_output = pid_control(motor2_speed, TARGET_SPEED, &motor2_speed_integral, &motor2_speed_previous_error, dt);

        // Motor Control
        motor1_forward(pid1_output);
        motor2_forward(pid2_output);

        // Logging
        log_data(motor1_speed, motor2_speed, pid1_output, pid2_output);

        gpioDelay(1000); // 1ms delay
    }

    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);

    cleanup_gpio();

    return 0;
}

