#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define POLL_INTERVAL_MS 50
#define LOG_FILE "relay_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(int touched);
void log_relay_state(int touched);
void signal_handler(int signal);

// Structure for MPR121 configuration
typedef struct {
    uint8_t touch_threshold;
    uint8_t release_threshold;
} mpr121_config_t;

// Function to write a register on the MPR121
int mpr121_write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a register on the MPR121
int mpr121_read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to initialize the MPR121
int mpr121_init() {
    // Soft reset
    if (mpr121_write_register(i2c_handle, 0x80, 0x63) != 0) return -1;
    gpioDelay(100); // Wait for reset

    // Configure Electrode Configuration (ECR) register
    if (mpr121_write_register(i2c_handle, 0x5E, 0x3F) != 0) return -1; // Enable all 12 electrodes

    // Configure Filter Configuration (FCR) register
    if (mpr121_write_register(i2c_handle, 0x5B, 0x01) != 0) return -1; // Filter configuration

    // Configure Touch Threshold (TT) register
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_register(i2c_handle, 0x41 + 2 * i, 0x30) != 0) return -1; // Touch threshold
    }

    // Configure Release Threshold (RT) register
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_register(i2c_handle, 0x42 + 2 * i, 0x10) != 0) return -1; // Release threshold
    }

    // Enable Run Mode (ECR, bit 0)
    if (mpr121_write_register(i2c_handle, 0x5E, 0x3F) != 0) return -1; // Enable all 12 electrodes

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    uint8_t buf[2];
    if (i2cWriteDevice(i2c_handle, (char[]){0x00, 0x00}, 2) != 2) {
        fprintf(stderr, "Error writing to MPR121 for read\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading touch status from MPR121\n");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to control the relay based on the touch status
void control_relay(int touched) {
    if (touched) {
        gpioWrite(RELAY_GPIO, 1); // HIGH
    } else {
        gpioWrite(RELAY_GPIO, 0); // LOW
    }
}

// Function to log the relay state to a file
void log_relay_state(int touched) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Relay state: %s\n", timestamp, touched ? "HIGH" : "LOW");
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for relay control
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint16_t touch_status;

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            int touched = (touch_status > 0);
            control_relay(touched);
            log_relay_state(touched);
        } else {
            fprintf(stderr, "Error reading touch status, retrying...\n");
        }
        gpioDelay(POLL_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

