// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_valve(int valve_number, int duration_ms);
void log_event(int valve_number, int duration_ms);
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    // Initialize valves to closed state (relay OFF)
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);

    return 0; // Indicate success
}

// Function to activate a valve for a specified duration
void activate_valve(int valve_number, int duration_ms) {
    int gpio_pin;

    if (valve_number == 1) {
        gpio_pin = VALVE1_GPIO;
    } else if (valve_number == 2) {
        gpio_pin = VALVE2_GPIO;
    } else {
        fprintf(stderr, "Invalid valve number: %d\n", valve_number);
        return;
    }

    gpioWrite(gpio_pin, 1); // Activate the relay (open the valve)
    gpioDelay(duration_ms * 1000); // Delay for the specified duration (in microseconds)
    gpioWrite(gpio_pin, 0); // Deactivate the relay (close the valve)
}

// Function to log an event to the log file
void log_event(int valve_number, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s Valve %d activated for %d ms\n", timestamp, valve_number, duration_ms);
    fclose(fp);
}

// Function to cleanup the GPIO pins
void cleanup_gpio() {
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);
    gpioTerminate();
    printf("GPIO cleanup complete. Exiting.\n");
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received (%d). Cleaning up and exiting.\n", signal);
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Water distribution schedule started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        activate_valve(1, 500); // Valve 1 for 500ms
        log_event(1, 500);
        gpioDelay(5000000); // Pause for 5 seconds (5000000 microseconds)

        activate_valve(2, 1000); // Valve 2 for 1000ms
        log_event(2, 1000);
        gpioDelay(10000000); // Pause for 10 seconds (10000000 microseconds)
    }

    return 0;
}

