#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define TOUCH_THRESHOLD 0x30
#define RELEASE_THRESHOLD 0x10
#define ELE0_FILTER 0x20
#define ELE0_CHARGE 0x10
#define ELE0_CURRENT 0x08
#define ELE0_ENABLE 0x04
#define ELE0_CONFIG 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int mpr121_set_electrode_config(int i2c_handle, uint16_t touch_threshold, uint16_t release_threshold, uint16_t filter, uint16_t charge, uint16_t current, uint16_t enable);
int mpr121_start_run(int i2c_handle);
int mpr121_read_touch_status(int i2c_handle);
int mpr121_toggle_relay(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode.\n");
        return -1;
    }

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), TOUCH_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), RELEASE_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    // Configure filter, charge time, and electrode current
    if (i2cWriteByteData(i2c_handle, 0x5C, ELE0_FILTER) < 0) {
        fprintf(stderr, "Error: Failed to set filter for all electrodes.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, ELE0_CHARGE) < 0) {
        fprintf(stderr, "Error: Failed to set charge time for all electrodes.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5E, ELE0_CURRENT) < 0) {
        fprintf(stderr, "Error: Failed to set electrode current for all electrodes.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, ELE0_ENABLE) < 0) {
        fprintf(stderr, "Error: Failed to enable all electrodes.\n");
        return -1;
    }

    // Set the MPR121 to run mode
    if (mpr121_start_run(i2c_handle) < 0) {
        fprintf(stderr, "Error: Failed to start MPR121 run mode.\n");
        return -1;
    }

    return 0;
}

// Function to set the configuration of a single electrode
int mpr121_set_electrode_config(int i2c_handle, uint16_t touch_threshold, uint16_t release_threshold, uint16_t filter, uint16_t charge, uint16_t current, uint16_t enable) {
    char buf[2];
    buf[0] = 0x41 + (0 * 2); // Address of the first byte for electrode 0
    buf[1] = touch_threshold;

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], &touch_threshold, 1) < 0) {
        fprintf(stderr, "Error: Failed to write touch threshold for electrode 0.\n");
        return -1;
    }

    buf[0] = 0x42 + (0 * 2); // Address of the second byte for electrode 0
    buf[1] = release_threshold;

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], &release_threshold, 1) < 0) {
        fprintf(stderr, "Error: Failed to write release threshold for electrode 0.\n");
        return -1;
    }

    buf[0] = 0x5C; // Address of the filter register
    buf[1] = filter;

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], &filter, 1) < 0) {
        fprintf(stderr, "Error: Failed to write filter for electrode 0.\n");
        return -1;
    }

    buf[0] = 0x5D; // Address of the charge register
    buf[1] = charge;

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], &charge, 1) < 0) {
        fprintf(stderr, "Error: Failed to write charge time for electrode 0.\n");
        return -1;
    }

    buf[0] = 0x5E; // Address of the current register
    buf[1] = current;

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], &current, 1) < 0) {
        fprintf(stderr, "Error: Failed to write current for electrode 0.\n");
        return -1;
    }

    buf[0] = 0x5F; // Address of the enable register
    buf[1] = enable;

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], &enable, 1) < 0) {
        fprintf(stderr, "Error: Failed to enable electrode 0.\n");
        return -1;
    }

    return 0;
}

// Function to start the MPR121 in run mode
int mpr121_start_run(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to run mode.\n");
        return -1;
    }
    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int i2c_handle) {
    char buf[2];
    buf[0] = 0x00; // Address of the first byte for touch status
    if (i2cReadI2CBlockData(i2c_handle, buf[0], buf, 2) < 0) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }
    return ((int)buf[1] << 8) | (int)buf[0];
}

// Function to toggle the relay connected to GPIO17
int mpr121_toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    gpioWrite(gpio_pin, !current_state);
    return current_state;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read touch status
        int touch_status = mpr121_read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status.\n");
            break; // Exit loop on error
        }

        // Toggle relay if any electrode is touched
        int relay_state = mpr121_toggle_relay(RELAY_GPIO);
        printf("Relay state: %d\n", relay_state);

        // Delay
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

