#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_DURATION_S 2
#define POLLING_INTERVAL_MS 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
int log_event(const char *event_type);
void rate_limit();
void cleanup();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int pir_pin;
    int relay_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Function to implement rate limiting
void rate_limit() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: Rate limiting activated.\n", timestamp);
    fflush(log_file);
    sleep(RATE_LIMIT_DURATION_S);
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to perform cleanup before exiting
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    fprintf(log_file, "Program started\n");
    fflush(log_file);

    // Main loop
    while (!terminate) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            // Motion detected
            if (control_relay(1) == 0) {
                log_event("Door unlocked");
                rate_limit();
            } else {
                fprintf(stderr, "Error controlling relay!\n");
            }
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

