void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, shutting down gracefully...\n");
        shutdown = 1;
    }
}

// Function to generate a random PWM duty cycle for a motor
int generate_random_duty_cycle(int motor_index) {
    if (motor_index < 0 || motor_index >= NUM_MOTORS) {
        fprintf(stderr, "Error: Invalid motor index: %d\n", motor_index);
        return -1; // Indicate an error
    }

    // Seed the random number generator with the current time
    unsigned int seed = time(NULL);
    srand(seed);

    // Generate a random duty cycle between MIN_DUTY_CYCLE and MAX_DUTY_CYCLE
    return (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
}

