    if (play_pattern(duty_cycles, durations, NUM_MOTORS * 15) != 0) {
        fprintf(stderr, "Error: Failed to play haptic feedback pattern\n");
        gpioTerminate(); // Terminate pigpio before exiting
        return 1;
    }

    // Stop both motors
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

