#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0
#define WEIGHT_THRESHOLD 10.0 // kg
#define READ_TIMEOUT 0.5 // seconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double scale_factor = DEFAULT_SCALE;
static double offset = DEFAULT_OFFSET;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value, double scale_factor, double offset);
int control_solenoid(double weight);
int load_calibration_data();
int save_calibration_data();
double startup_calibration();
void log_data(int raw_value, double weight);
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int i;
    int data = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for the HX711 to be ready
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
        if (timeout_counter > READ_TIMEOUT * 1000) { // Timeout after READ_TIMEOUT seconds
            fprintf(stderr, "Error: HX711 timeout\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    // Apply the 25th clock pulse for gain selection (default gain = 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value, double scale_factor, double offset) {
    return (double)(raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
int control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
        printf("Solenoid activated (Weight: %.2f kg)\n", weight);
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
        printf("Solenoid deactivated (Weight: %.2f kg)\n", weight);
    }
    return 0;
}

// Function to load calibration data from file
int load_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s. Using default values.\n", CALIBRATION_FILE);
        return -1; // Indicate failure to load calibration
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Error: Invalid calibration data in %s. Using default values.\n", CALIBRATION_FILE);
        fclose(fp);
        return -1; // Indicate failure to load calibration
    }

    fclose(fp);
    printf("Calibration data loaded: scale_factor = %.2f, offset = %.2f\n", scale_factor, offset);
    return 0; // Indicate success
}

// Function to save calibration data to file
int save_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s for writing.\n", CALIBRATION_FILE);
        return -1; // Indicate failure to save calibration
    }

    fprintf(fp, "%lf %lf", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved: scale_factor = %.2f, offset = %.2f\n", scale_factor, offset);
    return 0; // Indicate success
}

// Function to perform startup calibration
double startup_calibration() {
    double sum = 0.0;
    int num_readings = 0;
    printf("Starting calibration...\n");
    while (num_readings < 100) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error during calibration: HX711 timeout\n");
            return -1; // Indicate calibration failure
        }
        sum += calculate_weight(raw_value, scale_factor, offset);
        gpioDelay(10); // Small delay between readings
        num_readings++;
    }
    return sum / num_readings;
}

// Function to log data to file
void log_data(int raw_value, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Raw: %d, Weight: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, raw_value, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Load calibration data
    if (load_calibration_data() != 0) {
        printf("Using default calibration values: scale_factor = %.2f, offset = %.2f\n", DEFAULT_SCALE, DEFAULT_OFFSET);
    }

    // Perform startup calibration
    if (startup_calibration() == -1) {
        fprintf(stderr, "Error: Startup calibration failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value, scale_factor, offset);
            control_solenoid(weight);
            log_data(raw_value, weight);
        } else {
            fprintf(stderr, "Error: HX711 read failed. Skipping this iteration.\n");
        }

        gpioDelay(500); // Read every 500ms
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

