// Define GPIO pins
#define DT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 17

// Define weight threshold
#define WEIGHT_THRESHOLD 100.0

// Define lock activation duration
#define LOCK_DURATION 5.0

// Define HX711 timeout (seconds)
#define HX711_TIMEOUT 5

// Define data file name
#define DATA_FILE "stock_events.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
float convert_to_weight(int raw_value);
void activate_lock();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(DT_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);

    // Wait for DT to go low
    int timeout = 0;
    while (gpioRead(DT_PIN) == 1 && timeout < HX711_TIMEOUT) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= HX711_TIMEOUT) {
        log_event("HX711 timeout waiting for DT to go low.");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(DT_PIN)) {
            data++;
        }
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1);
    }

    // Apply the 25th clock pulse for gain selection (default gain = 128)
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to convert raw value to weight in grams
float convert_to_weight(int raw_value) {
    // Calibration factor (adjust based on your setup)
    float calibration_factor = 0.01; // Example: 0.01 grams per unit
    return (float)raw_value * calibration_factor;
}

// Function to activate the solenoid lock
void activate_lock() {
    gpioWrite(LOCK_PIN, 1); // Activate the lock
    log_event("Solenoid lock activated.");
    gpioDelay(LOCK_DURATION * 1000); // Wait for the specified duration
    gpioWrite(LOCK_PIN, 0); // Deactivate the lock
    log_event("Solenoid lock deactivated.");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

int main() {
    int raw_value;
    float weight;
    int lock_active = 0; // Flag to track lock activation status

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(DATA_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started.");

    // Main loop
    while (running) {
        // Read data from HX711
        raw_value = read_hx711();
        if (raw_value == -1) {
            log_event("Error reading from HX711.");
        } else {
            // Convert raw value to weight
            weight = convert_to_weight(raw_value);

            // Log weight reading
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Weight: %.2f g", weight);
            log_event(log_message);

            // Check weight threshold and activate lock if necessary
            if (weight < WEIGHT_THRESHOLD && !lock_active) {
                activate_lock();
                lock_active = 1; // Set lock activation flag
            } else if (weight >= WEIGHT_THRESHOLD && lock_active) {
                lock_active = 0; // Reset lock activation flag
            }
        }

        // Wait for one second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup
    log_event("Program exiting.");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

