#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define SOLENOID_LOCK_DURATION 5 // seconds
#define SOLENOID_RELEASE_DELAY 1 // seconds
#define TIMEOUT_THRESHOLD 100 // milliseconds

// Global variables
static volatile int running = 1;
static volatile int data_high_count = 0;
static volatile int data_low_count = 0;
static volatile int data_ready = 0;
static double calibration_factor = 0.0;
static FILE *calibration_file = NULL;
static FILE *security_log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_calibration_factor();
int read_hx711();
double convert_to_weight(int raw_value);
void control_solenoid(int lock);
void log_security_event(double weight);
void signal_handler(int signal);
void timeout_handler();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the calibration factor from the calibration file
int read_calibration_factor() {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file: %s\n", CALIBRATION_FILE);
        return 1;
    }

    if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor from file\n");
        fclose(calibration_file);
        return 1;
    }

    fclose(calibration_file);
    printf("Calibration factor: %lf\n", calibration_factor);
    return 0;
}

// Function to read data from the HX711
int read_hx711() {
    data_low_count = 0;
    data_high_count = 0;
    data_ready = 0;

    gpioWrite(HX711_CLOCK_PIN, 0); // Ensure clock is low initially

    // Wait for the data line to go high
    while (gpioRead(HX711_DATA_PIN) == 0 && running) {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (!running) return -1; // Exit if signal received

    data_high_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && running) {
        gpioDelay(1);
        data_high_count++;
    }

    // Wait for the data line to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && running) {
        gpioDelay(1);
    }

    if (!running) return -1; // Exit if signal received

    data_low_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 0 && running) {
        gpioDelay(1);
        data_low_count++;
    }

    if (!running) return -1; // Exit if signal received

    if (data_high_count > TIMEOUT_THRESHOLD || data_low_count > TIMEOUT_THRESHOLD) {
        fprintf(stderr, "Timeout occurred while reading HX711 data\n");
        return -1; // Indicate timeout
    }

    return 1; // Indicate data is ready
}

// Function to convert raw data to weight
double convert_to_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Function to control the solenoid lock
void control_solenoid(int lock) {
    gpioWrite(SOLENOID_PIN, lock);
    if (lock) {
        gpioDelay(SOLENOID_LOCK_DURATION * 1000000); // Delay in microseconds
        gpioDelay(SOLENOID_RELEASE_DELAY * 1000000); // Delay in microseconds
    } else {
        gpioDelay(100000); // Small delay to ensure release
    }
}

// Function to log security events
void log_security_event(double weight) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(security_log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fflush(security_log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioWrite(SOLENOID_PIN, 0); // Unlock solenoid
    gpioTerminate(); // Terminate pigpio
    if (calibration_file != NULL) fclose(calibration_file);
    if (security_log_file != NULL) fclose(security_log_file);
    exit(0);
}

// Timeout handler
void timeout_handler() {
    fprintf(stderr, "Timeout occurred, exiting...\n");
    running = 0;
    gpioWrite(SOLENOID_PIN, 0); // Unlock solenoid
    gpioTerminate(); // Terminate pigpio
    if (calibration_file != NULL) fclose(calibration_file);
    if (security_log_file != NULL) fclose(security_log_file);
    exit(1);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Read calibration factor
    if (read_calibration_factor() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open security log file
    security_log_file = fopen(SECURITY_LOG_FILE, "a");
    if (security_log_file == NULL) {
        fprintf(stderr, "Error opening security log file: %s\n", SECURITY_LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Starting weight monitoring...\n");

    while (running) {
        if (read_hx711() == 1) {
            int raw_value = gpioRead(HX711_DATA_PIN); // Read the data line
            if (raw_value == 1) {
                data_ready = 1;
            }
        } else {
            data_ready = 0;
        }

        if (data_ready) {
            int raw_value = gpioRead(HX711_DATA_PIN);
            if (raw_value == 1) {
                data_ready = 1;
            } else {
                data_ready = 0;
            }

            if (data_ready) {
                int signed_value = 0;
                for (int i = 0; i < 24; i++) {
                    if (read_hx711() == 1) {
                        data_ready = 1;
                    } else {
                        data_ready = 0;
                    }
                    if (data_ready) {
                        gpioWrite(HX711_CLOCK_PIN, 1);
                        gpioDelay(1);
