int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error writing to relay pin\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to log events to a file
int log_event(int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s Relay state: %s\n", timestamp, relay_state == "ON" ? "ON" : "OFF");
    fclose(fp);
    return 0; // Indicate success
}

