    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();
        if (sensor_value == -1) {
            // Error reading sensor, but continue running
            gpioDelay(100); // Small delay to avoid spamming errors
            continue;
        }

        // Active-low sensor: LOW indicates obstacle
        int relay_state = (sensor_value == 0) ? "ON" : "OFF";

        if (control_relay(relay_state) != 0) {
