        if (log_event(relay_state) != 0) {
            fprintf(stderr, "Error logging event, but continuing...\n");
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup GPIO resources
    gpioTerminate();
    printf("Relay control program stopped.\n");

