#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to read the watering duration from the configuration file
int read_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open configuration file %s.\n", filename);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read from configuration file %s.\n", filename);
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "duration=%d", duration) != 1) {
        fprintf(stderr, "Error: Invalid format in configuration file %s. Expected 'duration=<seconds>'.\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to initialize the GPIO line
int initialize_gpio(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Could not set GPIO %d as output.\n", gpio_pin);
        return -1;
    }
    if (gpioWrite(gpio_pin, 0) != 0) { // Initialize to LOW (valve off)
        fprintf(stderr, "Error: Could not write to GPIO %d initially.\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to activate the valve
int activate_valve(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error: Could not write to GPIO %d to activate valve.\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to deactivate the valve
int deactivate_valve(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: Could not write to GPIO %d to deactivate valve.\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to wait for the specified duration
int wait_duration(int duration) {
    if (duration <= 0 || duration > MAX_DURATION) {
        fprintf(stderr, "Error: Invalid duration value. Must be between 1 and 3600 seconds.\n");
        return -1;
    }
    return 0;
}

// Function to log messages to stdout
void log_message(const char *message) {
    printf("%s\n", message);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Read the watering duration from the configuration file
    int duration;
    if (read_duration(CONFIG_FILE, &duration) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize the GPIO line
    if (initialize_gpio(VALVE_GPIO) != 0) {
        gpioTerminate();
        return 1;
    }

    // Activate the valve
    if (activate_valve(VALVE_GPIO) != 0) {
        gpioTerminate();
        return 1;
    }

    // Wait for the specified duration
    if (wait_duration(duration) != 0) {
        deactivate_valve(VALVE_GPIO);
        gpioTerminate();
        return 1;
    }

    // Deactivate the valve
    if (deactivate_valve(VALVE_GPIO) != 0) {
        gpioTerminate();
        return 1;
    }

    // Log the valve state changes
    log_message("Valve activated.");
    sleep(duration);
    log_message("Valve deactivated.");

    // Clean up and exit
    deactivate_valve(VALVE_GPIO);
    gpioTerminate();
    log_message("Program terminated.");
    return 0;
}

