    gpioSetMode(MOTOR_PWM_RIGHT, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_BACKWARD, PI_OUTPUT);

