    gpioSetPWMrange(MOTOR_PWM_LEFT, PWM_RANGE);
    gpioSetPWMrange(MOTOR_PWM_RIGHT, PWM_RANGE);
    gpioSetPWMrange(MOTOR_PWM_FORWARD, PWM_RANGE);
