        set_motor_speed(MOTOR_PWM_LEFT, left_speed);
        set_motor_speed(MOTOR_PWM_RIGHT, right_speed);

        // Log data
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        // Delay for 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Stop motors
    set_motor_speed(MOTOR_PWM_LEFT, 0);
    set_motor_speed(MOTOR_PWM_RIGHT, 0);
    set_motor_speed(MOTOR_PWM_FORWARD, 0);
    set_motor_speed(MOTOR_PWM_BACKWARD, 0);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

