#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width limits
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define servo pulse width for lock position (0 degrees)
#define LOCK_PULSE_WIDTH 1000

// Define servo pulse width for unlock position (180 degrees)
#define UNLOCK_PULSE_WIDTH 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nSIGINT received, cleaning up and exiting...\n");
        gpioServo(SERVO_PIN, 0); // Stop the servo
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to set the servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d). Must be between %d and %d.\n", pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1; // Indicate an error
    }

    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width to %d. pigpio error code: %d\n", pulse_width, result);
        return -1; // Indicate an error
    }
    return 0; // Indicate success
}

// Function to lock the door
int lock_door(int gpio) {
    printf("Locking door...\n");
    if (set_servo_pulse_width(gpio, LOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error: Failed to lock the door.\n");
        return -1;
    }
    return 0;
}

// Function to unlock the door
