#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define motor activation times (in milliseconds)
#define MOTOR1_ON_TIME 200
#define MOTOR2_ON_TIME 300

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, stopping motors and exiting...\n");
}

// Function to activate a motor for a specified duration
void activate_motor(int gpio, int duration_ms) {
    if (gpioWrite(gpio, 1) != 0) { // Activate the motor
        fprintf(stderr, "Error: Failed to activate motor on GPIO %d\n", gpio);
        return;
    }
    gpioDelay(duration_ms * 1000); // Delay for the specified duration
    if (gpioWrite(gpio, 0) != 0) { // Deactivate the motor
        fprintf(stderr, "Error: Failed to deactivate motor on GPIO %d\n", gpio);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Activate motor 1
        activate_motor(MOTOR1_GPIO, MOTOR1_ON_TIME);

        // Activate motor 2
        activate_motor(MOTOR2_GPIO, MOTOR2_ON_TIME);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

