#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ parameters
#define ZMQ_PORT 5555
#define ZMQ_TOPIC "SOUND_ALERTS"

// Define alarm duration (in seconds)
#define ALARM_DURATION 1

// Global variables
static volatile int running = 1;
static int zmq_socket = -1;
static int zmq_context = -1;

// Function prototypes
int initialize_gpio();
int initialize_zmq();
void cleanup_gpio();
void cleanup_zmq();
void signal_handler(int signal);
int publish_sound_alert();
int subscribe_and_activate_alarm();

// Function to initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to initialize ZeroMQ
int initialize_zmq() {
    zmq_socket = zmq_socket(zmq_context, ZMQ_REQ);
    if (zmq_socket < 0) {
        fprintf(stderr, "Error creating ZeroMQ socket\n");
        return -1;
    }

    if (zmq_connect(zmq_socket, "tcp://*:5555") < 0) {
        fprintf(stderr, "Error connecting to ZeroMQ server\n");
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioWrite(ALARM_LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

// Function to cleanup ZeroMQ
void cleanup_zmq() {
    if (zmq_socket >= 0) {
        zmq_close(zmq_socket);
    }
    if (zmq_context >= 0) {
        zmq_term(zmq_context);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to publish sound alert
int publish_sound_alert() {
    int rc = zmq_send(zmq_socket, "SOUND_ALERT", strlen("SOUND_ALERT"), 0);
    if (rc == -1) {
        fprintf(stderr, "Error sending message\n");
        return -1;
    }
    return 0;
}

// Function to subscribe to ZeroMQ topic and activate alarm
int subscribe_and_activate_alarm() {
    char buffer[256];
    int rc = zmq_recv(zmq_socket, buffer, sizeof(buffer) - 1, 0);
    if (rc == -1) {
        fprintf(stderr, "Error receiving message\n");
        return -1;
    }

    printf("Received alert: %s\n", buffer);

    gpioWrite(ALARM_LED_PIN, 1); // Turn on LED
    gpioDelay(ALARM_DURATION * 1000000); // Wait for alarm duration (in microseconds)
    gpioWrite(ALARM_LED_PIN, 0); // Turn off LED
    return 0;
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor or alarm_node\n");
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        printf("Sound sensor mode started...\n");
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        printf("Alarm node mode started...\n");
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize ZeroMQ
    if (initialize_zmq() != 0) {
        cleanup_gpio();
        return 1;
    }

    // Main loop
    if (strcmp(argv[1], "sound_sensor") == 0) {
        while (running) {
            if (publish_sound_alert() != 0) {
                break;
            }
            gpioDelay(10000); // 10ms delay
        }
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        while (running) {
            if (subscribe_and_activate_alarm() != 0) {
                break;
            }
            gpioDelay(10000); // 10ms delay
        }
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        cleanup_gpio();
        cleanup_zmq();
        return 1;
    }

    // Cleanup
    cleanup_gpio();
    cleanup_zmq();

    printf("Exiting.\n");
    return 0;
}

