#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4
#define MAX_LUX 1000.0
#define MIN_LUX 0.0
#define MAX_RETRIES 3

// Sensor addresses
const int sensor_addresses[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fds[NUM_SENSORS];
int udp_socket;

// Function prototypes
float read_bh1750fvi(int fd, int address);
void broadcast_data(float lux_values[], int num_sensors);
void signal_handler(int signal);
int setup_i2c(int address);
int setup_udp_socket();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Function to set up I2C communication
int setup_i2c(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from BH1750FVI sensor
float read_bh1750fvi(int fd, int address) {
    unsigned char buf[2];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        // Send start conversion command (high resolution mode)
        unsigned char start_cmd[] = {0x10};
        if (write(fd, start_cmd, 1) != 1) {
            perror("Error writing to I2C device");
            return NAN;
        }

        usleep(180000); // Wait 180ms

        // Read two bytes of data
        bytes_read = read(fd, buf, 2);
        if (bytes_read != 2) {
            perror("Error reading from I2C device");
            return NAN;
        }

        // Convert data to lux value
        unsigned int raw_value = (buf[0] << 8) | buf[1];
        float lux = (float)raw_value / 1.2;

        if (lux < MIN_LUX || lux > MAX_LUX) {
            fprintf(stderr, "Warning: Sensor %d returned invalid lux value: %.2f\n", address, lux);
        }

        return lux;
    }

    fprintf(stderr, "Error: Max retries reached for sensor %d\n", address);
    return NAN; // Return NaN if all retries failed
}

// Function to set up UDP socket
int setup_udp_socket() {
    int sockfd;
    struct sockaddr_in addr;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }

    // Set multicast TTL
    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("setsockopt TTL failed");
        close(sockfd);
        return -1;
    }

    // Set destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Bind socket (optional for sending)
    if (bind(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind failed");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Function to broadcast data
void broadcast_data(float lux_values[], int num_sensors) {
    char buffer[256];
    int offset = 0;
    int i;

    for (i = 0; i < num_sensors; i++) {
        offset += snprintf(buffer + offset, sizeof(buffer) - offset, "%d", i + 1);
        offset += snprintf(buffer + offset, sizeof(buffer) - offset, ",%.2f", lux_values[i]);
        if (i < num_sensors - 1) {
            offset += snprintf(buffer + offset, sizeof(buffer) - offset, ";");
        }
    }

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto failed");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C sensors
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = setup_i2c(sensor_addresses[i]);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to initialize sensor %d\n", i);
            // Continue with other sensors, setting the lux value to NaN
        }
    }

    // Initialize UDP socket
    udp_socket = setup_udp_socket();
    if (udp_socket < 0) {
        fprintf(stderr, "Failed to initialize UDP socket\n");
        // Continue without UDP broadcasting
    }

    // Main loop
    while (!terminate) {
        float lux_values[NUM_SENSORS];

        // Read data from each sensor
        for (int i = 0; i < NUM_SENSORS; i++) {
            lux_values[i] = read_bh1750fvi(i2c_fds[i], sensor_addresses[i]);
            if (isnan(lux_values[i])) {
                fprintf(stderr, "Failed to read data from sensor %d, setting to NaN\n", i);
                lux_values[i] = NAN; // Set to NaN if reading failed
            }
        }

        // Broadcast data
        broadcast_data(lux_values, NUM_SENSORS);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
        }
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }

    printf("Exiting.\n");
    return 0;
}

