#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define START_CONDITION 0x00
#define FLOW_DATA_MSB 0x00
#define FLOW_DATA_LSB 0x01
#define FLOW_DATA_SIZE 2
#define FLOW_VALUE_MASK 0x3FFF
#define SLPM_SCALE_FACTOR 0.01
#define LOG_FILE "aircraft_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *raw_flow);
float convert_to_slpm(uint16_t raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    uint16_t raw_flow;
    float flow_rate_slpm;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AWM7300V_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(uint16_t *raw_flow) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, FLOW_DATA_MSB, (char *)raw_flow, FLOW_DATA_SIZE);
        if (result == FLOW_DATA_SIZE) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(100); // 100ms delay
            retries++;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure after retries
}

// Function to convert raw flow data to SLPM
float convert_to_slpm(uint16_t raw_flow) {
    return (float)raw_flow * SLPM_SCALE_FACTOR;
}

// Function to log flow rate to a file
int log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fclose(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_flow;
        float flow_rate_slpm;

        // Read sensor data
        if (read_sensor_data(&raw_flow) == 0) {
            // Convert to SLPM
            flow_rate_slpm = convert_to_slpm(raw_flow);

            // Log flow rate
            if (log_flow_rate(flow_rate_slpm) != 0) {
                fprintf(stderr, "Error logging flow rate.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

