#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x4C
#define DEFAULT_SAMPLING_INTERVAL 1 // seconds
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define BACKOFF_DELAY_US 10000 // 10 ms
#define SENSOR_ABSENT_THRESHOLD 0.1 // g

// D7S Register Addresses (Example - Refer to D7S datasheet for actual values)
#define REG_X_AXIS_LSB 0x28
#define REG_X_AXIS_MSB 0x29
#define REG_Y_AXIS_LSB 0x2A
#define REG_Y_AXIS_MSB 0x2B
#define REG_Z_AXIS_LSB 0x2C
#define REG_Z_AXIS_MSB 0x2D

// Global variables
int i2c_handle;
FILE *error_log_file;
FILE *data_log_file;
int i2c_address = DEFAULT_I2C_ADDRESS;
int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
char *output_filename = DEFAULT_OUTPUT_FILENAME;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    double x_g;
    double y_g;
    double z_g;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int address);
int read_sensor_data(int i2c_handle, sensor_data_t *data);
int log_data(FILE *data_file, sensor_data_t data);
int log_error(FILE *error_file, const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    char buf[6];
    int16_t x_raw, y_raw, z_raw;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cReadI2CBlockData(i2c_handle, REG_X_AXIS_LSB, buf, 6) == 6) {
            x_raw = (int16_t)((buf[1] << 8) | buf[0]);
            y_raw = (int16_t)((buf[3] << 8) | buf[2]);
            z_raw = (int16_t)((buf[5] << 8) | buf[4]);

            // Convert raw values to g (adjust scale factor as needed)
            data->x_g = (double)x_raw / 1000.0; // Example scale factor
            data->y_g = (double)y_raw / 1000.0;
            data->z_g = (double)z_raw / 1000.0;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading sensor data (attempt %d): %d\n", retries + 1, i2c_handle);
            log_error(error_log_file, "Error reading sensor data");
            retries++;
            gpioDelay(BACKOFF_DELAY_US);
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    log_error(error_log_file, "Failed to read sensor data after multiple retries.");
    return -1; // Failure
}

// Function to log data to CSV file
int log_data(FILE *data_file, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(data_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x_g, data.y_g, data.z_g);
    fflush(data_file); // Ensure data is written immediately
    return 0;
}

// Function to log errors to file
int log_error(FILE *error_file, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_file, "%s - %s\n", timestamp, message);
    fflush(error_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close files and I2C
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    if (data_log_file != NULL) {
        fclose(data_log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
