        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

