#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_socket = -1;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (udp_socket != -1) {
            close(udp_socket);
        }
        exit(0);
    }
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to configure the BH1750 sensor
int configure_sensor() {
    unsigned char config_data[1] = {CONTINUOUS_HIGH_RES_MODE};
    if (write(i2c_fd, config_data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read raw data from the BH1750 sensor
int read_sensor(unsigned short *raw_value) {
    unsigned char buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert raw value to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send data via UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char lux_str[20];
    snprintf(lux_str, sizeof(lux_str), "%.2f", lux_value);

    if (sendto(udp_socket, lux_str, strlen(lux_str), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP multicast");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Configure sensor
    if (configure_sensor() < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }

    // Set TTL for multicast
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(udp_socket);
        udp_socket = -1;
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }

    unsigned short raw_value;
    float lux_value;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor(&raw_value) < 0) {
            fprintf(stderr, "Error reading sensor, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        // Convert to lux
        lux_value = convert_to_lux(raw_value);

        // Send data via UDP multicast
        if (send_udp_multicast(lux_value) < 0) {
            fprintf(stderr, "Error sending data, retrying in 1 second...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

