#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define UART port and baud rate
#define UART_PORT "/dev/ttyS0"
#define BAUD_RATE 921600

// Define magic word
#define MAGIC_WORD {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07}

// Define TLV types (example values, adjust based on AWR1642 documentation)
#define TLV_TYPE_RANGE 1
#define TLV_TYPE_VELOCITY 2

// Define data structure for radar data
typedef struct {
    long object_index;
    float range_m;
    float velocity_mps;
} RadarData;

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_uart();
int read_uart_data(char *buffer, int max_len);
int synchronize_magic_word(const char *buffer, int len);
int extract_tlv_data(const char *buffer, int len, RadarData *data);
int validate_tlv_payload(const RadarData *data);
int write_data_to_csv(const RadarData *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_PORT, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Read data from UART
int read_uart_data(char *buffer, int max_len) {
    int bytes_read = serRead(uart_handle, buffer, max_len);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Synchronize on magic word
int synchronize_magic_word(const char *buffer, int len) {
    if (len < 8) return 0; // Not enough data to check magic word

    for (int i = 0; i < 7; i++) {
        if (buffer[i] != (unsigned char)(MAGIC_WORD[i] >> 8)) {
            return 0; // Magic word not found
        }
        if (buffer[i+1] != (unsigned char)(MAGIC_WORD[i] & 0xFF)) {
            return 0; // Magic word not found
        }
    }
    return 1; // Magic word found
}

// Extract TLV data
int extract_tlv_data(const char *buffer, int len, RadarData *data) {
    int offset = 0;
    while (offset < len - 8) {
        // Find the start of the next TLV
        int type = *((unsigned char *)(buffer + offset + 1));
        int length = *((unsigned char *)(buffer + offset + 2));

        if (offset + 4 + length > len) {
            fprintf(stderr, "Malformed TLV: Length exceeds buffer size\n");
            return -1;
        }

        if (type == 0) { // Assuming type 0 is range
            data->object_index = *((long *)(buffer + offset + 3));
            data->range_m = *((float *)(buffer + offset + 7));
        } else if (type == 1) { // Assuming type 1 is velocity
            data->object_index = *((long *)(buffer + offset + 3));
            data->velocity_mps = *((float *)(buffer + offset + 7));
        } else {
            fprintf(stderr, "Unknown TLV type: %d\n", type);
            return -1;
        }

        offset += 4 + length;
    }
    return 0;
}

// Validate TLV payload
int validate_tlv_payload(const RadarData *data) {
    if (data->range_m < 0 || data->range_m > 100) { // Example range validation
        fprintf(stderr, "Invalid range value: %f\n", data->range_m);
        return -1;
    }
    if (data->velocity_mps < -50 || data->velocity_mps > 50) { // Example velocity validation
        fprintf(stderr, "Invalid velocity value: %f\n", data->velocity_mps);
        return -1;
    }
    return 0;
}

// Write data to CSV file
int write_data_to_csv(const RadarData *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%ld,%f,%f\n", timestamp, data->object_index, data->range_m, data->velocity_mps);
    fflush(csv_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }

    char buffer[2048]; // Adjust buffer size as needed
    RadarData radar_data;

    // Main loop
    while (!terminate) {
        int bytes_read = read_uart_data(buffer, sizeof(buffer));
        if (bytes_read > 0) {
            if (synchronize_magic_word(buffer, bytes_read)) {
                if (extract_tlv_data(buffer, bytes_read, &radar_data) == 0) {
                    if (validate_tlv_payload(&radar_data) == 0) {
                        write_data_to_csv(&radar_data);
                    }
                }
            }
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Cleanup
    serClose(uart_handle);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

