#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define TIMEOUT_USEC 0
#define MAX_LINE_LENGTH 256

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int uart_fd = -1;

// Structure to hold UART configuration
typedef struct {
    struct termios tty;
} uart_config_t;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the UART
int init_uart(uart_config_t *config) {
    int fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART: %s\n", strerror(errno));
        return -1;
    }

    if (tcgetattr(fd, config->tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    config->tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    config->tty.c_iflag = IGNPAR;                           // Ignore parity errors
    config->tty.c_oflag = 0;
    config->tty.c_lflag = 0; // Non-canonical mode
    config->tty.c_cc[VMIN] = 0;  // Read doesn't block
    config->tty.c_cc[VTIME] = 5; // 0.5 second timeout

    if (tcsetattr(fd, TCSANOW, &config->tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART with timeout
int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // Timeout
        }
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1; // Error
    } else {
        buffer[bytes_read] = '\0';
        return bytes_read;
    }
}

// Function to parse the log data
int parse_log_data(const char *line, float *timestamp, float *range) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the string for strtok
    if (line_copy == NULL) {
        fprintf(stderr, "Error duplicating string: %s\n", strerror(errno));
        return -1;
    }

    token = strtok(line_copy, ",");
    if (token == NULL) {
        fprintf(stderr, "Error parsing timestamp: %s\n", strerror(errno));
        free(line_copy);
        return -1;
    }
    *timestamp = strtof(token, NULL);

    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error parsing range: %s\n", strerror(errno));
        free(line_copy);
        return -1;
    }
    *range = strtof(token, NULL);

    free(line_copy);
    return 0;
}

// Function to print the log data
void print_log_data(float timestamp, float range) {
    time_t rawtime = (time_t)timestamp;
    struct tm *timeinfo = localtime(&rawtime);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    uart_config_t uart_config;
    char log_buffer[MAX_LINE_LENGTH];
    float timestamp, range;
    fd_set readfds;
    struct timeval timeout;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (init_uart(&uart_config) == -1) {
        return EXIT_FAILURE;
    }
    uart_fd = uart_config.fd;

    // Main loop
    while (!terminate) {
        // Clear the input buffer
        memset(log_buffer, 0, sizeof(log_buffer));

        // Read data from UART with timeout
        int bytes_read = read_uart_data(uart_fd, log_buffer, sizeof(log_buffer) - 1);
        if (bytes_read > 0) {
            // Append the read data to the log buffer
            char *end = log_buffer + bytes_read;
            while (end > log_buffer && *end == '\n') {
                end--;
            }
            if (end > log_buffer) {
                *end = '\0'; // Null-terminate at the newline
            } else {
                // No newline found, treat as incomplete line
                bytes_read = 0; // Reset bytes read
                continue;
            }

            // Parse the log data
            if (parse_log_data(log_buffer, &timestamp, &range) == 0) {
                // Print the log data
                print_log_data(timestamp, range);
            } else {
                fprintf(stderr, "Error parsing log data: %s\n", strerror(errno));
            }
        } else if (bytes_read == -1) {
            // Timeout occurred
            fprintf(stderr, "Timeout occurred, no data received.\n");
        } else {
            // No data received
            fprintf(stderr, "No data received.\n");
        }

        // Reset the select timeout
        timeout.tv_sec = TIMEOUT_SEC;
        timeout.tv_usec = TIMEOUT_USEC;
    }

    // Close the UART
    close(uart_fd);
    fprintf(stderr, "UART closed.\n");

    return EXIT_SUCCESS;
}

