#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device and baud rate
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variable for UART file descriptor
int uart_fd = -1;

// Function prototypes
int initialize_gpio();
int initialize_uart();
void cleanup_gpio();
void cleanup_uart();
void signal_handler(int signal);
void log_sensor_data(int left, int middle, int right);

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} SensorData;

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to initialize the UART port
int initialize_uart() {
    uart_fd = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for no flags
    if (uart_fd < 0) {
        fprintf(stderr, "Failed to open UART device: %s\n", UART_DEVICE);
        return -1;
    }
    return 0;
}

// Function to cleanup the pigpio library
void cleanup_gpio() {
    gpioTerminate();
}

// Function to cleanup the UART port
void cleanup_uart() {
    if (uart_fd != -1) {
        serClose(uart_fd);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    cleanup_uart();
    exit(0);
}

// Function to log sensor data with timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup_gpio();
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        SensorData sensor_data;

        // Read sensor data
        sensor_data.left = gpioRead(LEFT_SENSOR_PIN);
        sensor_data.middle = gpioRead(MIDDLE_SENSOR_PIN);
        sensor_data.right = gpioRead(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(sensor_data.left, sensor_data.middle, sensor_data.right);

        // Check for emergency stop condition
        if (sensor_data.left == 0 && sensor_data.middle == 0 && sensor_data.right == 0) {
            if (uart_fd != -1) {
                if (serWrite(uart_fd, "EMERGENCY STOP!\n", strlen("EMERGENCY STOP!\n")) < 0) {
                    fprintf(stderr, "Error writing to UART\n");
                }
            } else {
                fprintf(stderr, "UART not initialized, cannot send emergency stop\n");
            }
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

